/* 注译分片 2: {键: 条目} — 懒加载后并入 window.POEM_NOTES */
window.POEM_NOTES_2={"采莲子·一|皇甫松":{"s":"首两句「菡萏香连十顷陂，小姑贪戏采莲迟」写十顷荷塘荷花飘香、小姑娘贪玩采莲采晚了，以「贪戏」写姑娘的天真；后两句「晚来弄水船头湿，更脱红裙裹鸭儿」是名句——傍晚玩水把船头弄湿了，又脱下红裙子裹小鸭儿，以「脱红裙裹鸭儿」的细节写姑娘的天真活泼，画面生动、情趣盎然，语言朴素而富有生活气息，是花间词中别具一格的作品。","b":"皇甫松（唐五代词人）这首《采莲子》写采莲姑娘的天真活泼，是花间词中富有生活气息的作品。","n":["采莲子：乐府曲调名，写采莲生活（此为皇甫松所作，唐五代词人）","菡萏：荷花。音hàndàn","十顷陂：十顷的池塘。陂音bēi，池塘","小姑：年轻的姑娘","贪戏采莲迟：贪玩采莲采得晚了","弄水船头湿：玩水把船头弄湿了","更脱红裙裹鸭儿：又脱下红裙子裹小鸭儿"]},"寻陆鸿渐不遇|皎然":{"s":"首联「移家虽带郭，野径入桑麻」写陆羽的新家虽近城郭，但野径通入桑麻，环境清幽；颔联「近种篱边菊，秋来未着花」写篱边种菊、秋来未开，以菊花写陆羽的高洁；颈联「扣门无犬吠，欲去问西家」写敲门无狗叫、欲去问邻居，写不遇的过程；尾联「报道山中去，归时每日斜」是名句——邻居回答说陆羽到山中去了，每天回来时太阳都西斜了，以邻居的回答写陆羽的闲适与爱山，不遇中见其人，意境清远，是寻访诗的佳作。","b":"皎然（唐代诗僧）寻访好友陆羽不遇时所作，写陆羽的隐居生活与寻访不遇的惆怅，是寻访诗的名篇。","n":["陆鸿渐：陆羽，字鸿渐，茶圣，皎然的好友","移家虽带郭：搬家虽然靠近城郭。带郭，靠近城郭","野径入桑麻：野外的小路通入桑麻地","近种篱边菊：近来在篱笆边种了菊花","秋来未着花：秋天来了还没开花","扣门无犬吠：敲门没有狗叫","欲去问西家：想要离去又问西边的邻居","报道山中去：（邻居）回答说（陆羽）到山中去了","归时每日斜：回来时每天太阳都西斜了"],"m":"报道山中去，归时每日斜。","r":"按「移家野径—篱边种菊—扣门问西家—山中去日斜归」背；以邻居回答侧面写陆羽是核心。"},"汴河怀古二首·一|皮日休":{"s":"首两句「万艘龙舸绿丝间，载到扬州尽不还」写隋炀帝乘万艘龙船南巡、一去不返，以「尽不还」写隋亡的结局；后两句「应是天教开汴水，一千余里地无山」是名句——应该是上天让开凿汴河，一千多里地没有山，以「天教开汴水」的反语写运河开凿的历史必然性，以「地无山」写运河的地理条件，表面赞美实则讽刺，构思独特，是咏史诗中的别致之作。（同题第二首「尽道隋亡为此河，至今千里赖通波」更为传诵。）","b":"皮日休（晚唐诗人）这首《汴河怀古》写隋炀帝开凿大运河的历史功过，以独特视角评价隋炀帝，是咏史诗的名篇。","n":["汴河：通济渠，隋炀帝开凿的大运河一段","万艘龙舸：万艘龙船（舸，大船）。舸音gě","绿丝间：在绿柳之间","载到扬州尽不还：运到扬州都不回来了（指隋炀帝南巡江都不返）","应是天教开汴水：应该是上天让开凿汴河","一千余里地无山：一千多里地没有山（指运河开凿的地势平坦）"],"m":"应是天教开汴水，一千余里地无山。","r":"四句按「万艘龙舸—载到扬州—天教开汴水—千里无山」背；反语与独特视角是核心。"},"终南望余雪|祖咏":{"s":"首两句「终南阴岭秀，积雪浮云端」写终南山北岭的秀丽、积雪好像浮在云端，以「浮云端」写山之高、雪之厚；后两句「林表明霁色，城中增暮寒」是名句——树林顶端呈现初晴的光色、城中增添了傍晚的寒意，以「林表」的明丽与「城中」的寒冷对比，以望雪而生寒，写尽雪后初晴的清冷，全诗意境清新、语言精炼，是咏雪诗的名篇，「意尽而止」成为诗坛佳话。","b":"祖咏（盛唐诗人）这首《终南望余雪》写从长安望终南山雪后的景色，是咏雪诗的名篇，据说这是应试诗，祖咏只写了四句就交卷，说「意尽」。","n":["终南：终南山，在今陕西西安南","阴岭：北面的山岭（山北为阴）","秀：秀丽","积雪浮云端：积雪好像浮在云端","林表明霁色：树林顶端呈现出雨后初晴的光色。霁色，雨后初晴的景色","城中增暮寒：城中增添了傍晚的寒意"],"m":"林表明霁色，城中增暮寒。","r":"四句按「终南阴岭—积雪云端—林表霁色—城中暮寒」背；「霁」读jì；望雪生寒是核心。"},"自遣|罗隐":{"s":"首两句「得即高歌失即休，多愁多恨亦悠悠」写得意高歌、失意罢休，多愁多恨也悠悠然，表面旷达实则愤激；后两句「今朝有酒今朝醉，明日愁来明日愁」是名句——今天有酒今天醉、明天有愁明天愁，以「今朝」「明日」的重复写及时行乐的颓废，以旷达写失意，以颓废写愤激，语言明快而情感深沉，是晚唐诗歌的代表作，「今朝有酒今朝醉」成为流传千古的成语。","b":"罗隐（晚唐诗人）这首《自遣》写失意后的旷达与愤激，「今朝有酒今朝醉」成为千古名句，是晚唐颓废气的典型体现。","n":["自遣：自我排遣","得即高歌失即休：得意时就高歌、失意时就罢休","多愁多恨亦悠悠：多愁多恨也悠悠然（不放在心上）","今朝有酒今朝醉：今天有酒今天就喝醉","明日愁来明日愁：明天有愁明天再愁"],"m":"今朝有酒今朝醉，明日愁来明日愁。","r":"四句按「得失高歌—多愁悠悠—今朝酒醉—明日愁来」背；旷达外表下的愤激是核心。"},"正月十五夜|苏味道":{"s":"首联「火树银花合，星桥铁锁开」写元宵夜灯火辉煌、开禁夜行，「火树银花」成为千古成语；颔联「暗尘随马去，明月逐人来」写游人骑马、尘土飞扬、明月相随，以「随」「逐」写元宵的热闹；颈联「游伎皆秾李，行歌尽落梅」写歌伎美丽、边走边唱，以秾李喻美女；尾联「金吾不禁夜，玉漏莫相催」写不禁夜行、希望漏壶不要催促，以「莫相催」写对元宵夜的留恋，全诗对仗工稳、色彩明丽，是初唐律诗的成熟之作，写尽盛唐元宵的繁华。","b":"苏味道（初唐诗人，「文章四友」之一）这首《正月十五夜》写长安元宵夜的繁华热闹，是写元宵节的千古名篇，「火树银花」成为成语。","n":["正月十五夜：元宵节","火树银花合：灯光焰火连成一片（火树银花，形容灯火辉煌）","星桥铁锁开：桥上的铁锁打开（指元宵夜开禁，允许百姓夜行）","暗尘随马去：暗中的尘土随马而去","明月逐人来：明月追逐着人而来","游伎皆秾李：游赏的歌伎都如秾李般美丽。秾李，艳丽的李花，喻美女","行歌尽落梅：边走边唱的都是《梅花落》曲调","金吾不禁夜：金吾（禁军官名）不禁止夜行（指元宵开宵禁）","玉漏莫相催：玉漏（玉制的漏壶，计时器）不要催促（希望夜长一些）"],"m":"火树银花合，星桥铁锁开。","r":"按「火树银花—暗尘明月—游伎行歌—金吾玉漏」背；「火树银花」是成语；对仗工稳是特点。"},"送友人|薛涛":{"s":"首两句「水国蒹葭夜有霜，月寒山色共苍苍」写水乡秋夜、芦苇有霜、月寒山色苍茫，以《诗经》「蒹葭苍苍」的意境写送别环境的清冷；后两句「谁言千里自今夕，离梦杳如关塞长」是名句——谁说千里之别从今夜开始，离别后的梦遥远得像关塞一样长，以「谁言」的反问写离情的深切、以「关塞长」比喻离梦的遥远，想象奇特，情感深沉，是薛涛诗中的佳作，也是女诗人送别诗的名篇。","b":"薛涛（唐代女诗人）这首《送友人》写送别友人时的景色与离情，是女诗人送别诗的名篇。","n":["薛涛：唐代女诗人，曾居成都浣花溪，制「薛涛笺」","水国：水乡","蒹葭：芦苇。音jiānjiā","苍苍：茂盛的样子","月寒山色共苍苍：月色寒冷、山色与芦苇一样苍茫","谁言千里自今夕：谁说千里之别从今夜开始","离梦杳如关塞长：离别后的梦遥远得像关塞一样长。杳，遥远"],"m":"谁言千里自今夕，离梦杳如关塞长。","r":"四句按「水国蒹葭—月寒山色—谁言千里—离梦关塞」背；「蒹葭」读jiānjiā；化用《诗经》蒹葭意境是核心。"},"蝉|虞世南":{"s":"首两句「垂緌饮清露，流响出疏桐」写蝉的形态（垂緌）、食性（饮清露）、鸣声（流响）、栖息（疏桐），以「清露」「疏桐」写蝉的高洁；后两句「居高声自远，非是藉秋风」是千古名句——因为站在高处声音自然传得远，不是凭借秋风的力量，以蝉喻人，写品格高洁的人自然声名远播，不需要凭借外力，托物言志，立意高远，是初唐咏物诗的典范，「居高声自远」成为千古名句。","b":"虞世南（初唐诗人，「凌烟阁二十四功臣」之一）这首《蝉》托物言志，以蝉的高洁喻人的品格，是咏蝉诗的千古名篇，与骆宾王《在狱咏蝉》、李商隐《蝉》并称「咏蝉三绝」。","n":["垂緌：蝉的头部伸出的触须（像帽带下垂）。緌音ruí","饮清露：饮用清露（古人认为蝉饮露为生）","流响出疏桐：长鸣声从稀疏的梧桐树中传出","居高声自远：因为站在高处声音自然传得远","非是藉秋风：不是凭借秋风的力量。藉音jiè，凭借"],"m":"居高声自远，非是藉秋风。","r":"四句按「垂緌饮露—流响疏桐—居高声远—非藉秋风」背；「緌」读ruí、「藉」读jiè；托物言志是核心。"},"哥舒歌|西鄙人":{"s":"首两句「北斗七星高，哥舒夜带刀」以北斗七星高悬起兴，写哥舒翰夜里带刀守边，以「北斗高」喻哥舒翰的威望高；后两句「至今窥牧马，不敢过临洮」是名句——至今吐蕃只敢偷看牧马，不敢越过临洮，以「不敢过」写哥舒翰守边的功绩，以吐蕃的胆怯反衬哥舒翰的威名，语言朴素如民歌，气势雄浑，是唐代边塞民歌的代表作，也是歌颂守边名将的名篇。","b":"西鄙人（西部边地的人，佚名）这首《哥舒歌》是唐代民歌，歌颂名将哥舒翰守边的功绩，语言朴素、气势雄浑，是唐代边塞民歌的代表作。","n":["哥舒歌：歌颂哥舒翰的民歌（哥舒翰，唐代名将，曾任陇右节度使，守边有功）","北斗七星高：北斗七星高高挂在天上","哥舒夜带刀：哥舒翰夜里带着刀（守边）","至今窥牧马：至今（吐蕃）偷看牧马（指不敢轻举妄动）","不敢过临洮：不敢越过临洮（临洮，今甘肃岷县，唐代边防要地）"],"m":"至今窥牧马，不敢过临洮。","r":"四句按「北斗七星高—哥舒夜带刀—窥牧马—不敢过临洮」背；以吐蕃胆怯反衬哥舒翰威名是核心。"},"剑客|贾岛":{"s":"首两句「十年磨一剑，霜刃未曾试」写十年磨一剑、刀刃锋利却未曾试过，以「十年」写磨砺之久、以「霜刃」写剑之锋利，以剑喻才，写自己十年苦读、才华未展；后两句「今日把似君，谁为不平事」是名句——今天把剑拿给你看，谁有不平的事我来伸张，以「把似君」写渴望施展、以「不平事」写抱负，托物言志，语言朴素而意气豪迈，是贾岛诗中少有的豪放之作，也是咏剑诗的名篇。","b":"贾岛（中唐诗人，「苦吟诗人」）这首《剑客》以剑喻才，写自己十年磨砺、渴望施展抱负的心情，是咏物言志的名篇。","n":["剑客：剑客（一作「述剑」）","十年磨一剑：用十年时间磨一把剑（写剑的珍贵与磨砺之久）","霜刃未曾试：霜雪般锋利的刀刃还没有试过。霜刃，形容刀刃锋利如霜","今日把似君：今天把它拿给你看。把似，拿给","谁为不平事：谁有不平的事（我来为他伸张正义）"],"m":"十年磨一剑，霜刃未曾试。","r":"四句按「十年磨剑—霜刃未试—今日把似君—谁为不平事」背；以剑喻才是核心。"},"题李凝幽居|贾岛":{"s":"首联「闲居少邻并，草径入荒园」写李凝幽居的偏僻——少邻居、草径通荒园，环境清幽；颔联「鸟宿池边树，僧敲月下门」是千古名句——鸟儿栖息在池边树上、僧人在月光下敲门，以「敲」字写夜的静，以动衬静，「推敲」的典故流传千古；颈联「过桥分野色，移石动云根」写走过桥原野景色分开、移动石头云脚也动，以「分」「动」写景色的变化；尾联「暂去还来此，幽期不负言」写暂时离去还会再来、不食归隐之约，表达对隐居生活的向往，全诗意境清幽、炼字精当，是贾岛苦吟诗的代表作。","b":"贾岛拜访友人李凝的幽居时所作，「鸟宿池边树，僧敲月下门」是「推敲」典故的出处，是苦吟诗的典范。","n":["李凝：贾岛的友人，隐士","幽居：隐居的地方","少邻并：很少有邻居","草径入荒园：长满草的小路通入荒芜的园子","鸟宿池边树：鸟儿栖息在池边的树上","僧敲月下门：僧人在月光下敲门（「推敲」典故的出处）","过桥分野色：走过桥去，原野的景色分开","移石动云根：移动石头，云脚也动了（古人认为云「触石而出」，故称石为云根）","暂去还来此：暂时离去还会再来这里","幽期不负言：归隐的约定不食言"],"m":"鸟宿池边树，僧敲月下门。","r":"按「闲居荒园—鸟宿僧敲—过桥移石—暂去还来」背；「推敲」典故是核心；以动衬静是手法。"},"忆江上吴处士|贾岛":{"s":"首联「闽国扬帆去，蟾蜍亏复团」写友人扬帆去闽地、月亮缺了又圆，以月的圆缺写时间之久、思念之深；颔联「秋风生渭水，落叶满长安」是千古名句——秋风从渭水刮起、落叶飘满长安，以「生」「满」写秋意的浓重，以苍凉的秋景写离情，意境雄浑；颈联「此地聚会夕，当时雷雨寒」回忆当时聚会的夜晚、雷雨交加，以回忆写友情；尾联「兰桡殊未返，消息海云端」写友人还没回来、消息在海云那一边，以「海云端」写距离的遥远，全诗意境苍凉、情感深沉，是贾岛五律的名篇。","b":"贾岛这首诗写思念去闽地的友人吴处士，以秋风落叶写离情，是贾岛诗中的名篇，「秋风生渭水，落叶满长安」为千古名句。","n":["吴处士：姓吴的处士（处士，有才德而隐居不仕的人）","闽国扬帆去：扬帆去闽国（今福建）","蟾蜍亏复团：月亮缺了又圆（蟾蜍，代指月亮，古代传说月中有蟾蜍）","秋风生渭水：秋风从渭水刮起","落叶满长安：落叶飘满长安","此地聚会夕：在这里聚会的夜晚","当时雷雨寒：当时雷雨交加、天气寒冷","兰桡殊未返：木兰舟还没有回来（指吴处士还没回来）。兰桡，木兰做的船桨，代指船","消息海云端：消息在海云的那一边（指遥远）"],"m":"秋风生渭水，落叶满长安。","r":"按「闽国扬帆—蟾蜍亏团—秋风落叶—聚会雷雨—兰桡未返」背；「蟾蜍」代月；「秋风生渭水，落叶满长安」是名句。"},"雪晴晚望|贾岛":{"s":"首联「倚杖望晴雪，溪云几万重」写拄杖眺望晴雪、溪上云几万重，以「几万重」写云之多；颔联「樵人归白屋，寒日下危峰」写樵夫归白屋、寒日落危峰，以「归」「下」写傍晚的动态，画面清冷；颈联「野火烧冈草，断烟生石松」写野火烧冈草、断烟生石松，以「烧」「生」写景色的生机；尾联「却回山寺路，闻打暮天钟」写返回山寺路上、听到暮钟，以「暮钟」写山寺的清幽，全诗画面清冷、意境幽远，是贾岛山水诗的佳作。","b":"贾岛这首诗写雪后初晴傍晚眺望山寺所见的景色，以清冷的画面写隐居的意境，是贾岛山水诗的名篇。","n":["雪晴晚望：雪后初晴傍晚眺望","倚杖望晴雪：拄着拐杖眺望雪后初晴的景色","溪云几万重：溪上的云有几万重","樵人归白屋：樵夫回到白屋（白屋，不施彩漆的屋子，指贫家）","寒日下危峰：寒冷的太阳落下高耸的山峰","野火烧冈草：野火烧着山冈上的草","断烟生石松：断续的烟从石松间升起","却回山寺路：返回山寺的路上","闻打暮天钟：听到傍晚的钟声"],"m":"樵人归白屋，寒日下危峰。","r":"按「倚杖望雪—溪云万重—樵人寒日—野火断烟—回山寺闻钟」背；清冷画面是特点。"},"宿山寺|贾岛":{"s":"首联「众岫耸寒色，精庐向此分」写群峰耸寒色、佛寺对着这里分开，以「寒色」写山的清冷；颔联「流星透疏木，走月逆行云」是名句——流星透过疏木、月亮与云反向而行，以「透」「逆」写夜景的生动，想象奇特；颈联「绝顶人来少，高松鹤不群」写绝顶人少、高松鹤不群，以「人少」「鹤不群」写山寺的清幽与高洁；尾联「一僧年八十，世事未曾闻」写八十老僧、不问世事，以老僧的超脱写山寺的境界，全诗意境清幽、想象奇特，是贾岛五律的佳作。","b":"贾岛这首诗写夜宿山寺所见的清幽景色与老僧的超脱，是贾岛山水诗的名篇。","n":["众岫耸寒色：群峰耸立着寒冷的景色。岫音xiù，山峰","精庐向此分：精舍（佛寺）对着这里分开","流星透疏木：流星透过稀疏的树木","走月逆行云：月亮行走、与云反向而行（写云行月移）","绝顶人来少：绝顶上来的人少","高松鹤不群：高松上的鹤不合群（喻高洁）","一僧年八十：一个僧人八十岁了","世事未曾闻：世间的事从未听说过"],"m":"流星透疏木，走月逆行云。","r":"按「众岫精庐—流星走月—绝顶高松—老僧世事」背；「岫」读xiù；「走月逆行云」想象奇特。"},"暮过山村|贾岛":{"s":"首联「数里闻寒水，山家少四邻」写几里外闻寒水、山家少四邻，以「寒水」「少四邻」写山村的偏僻；颔联「怪禽啼旷野，落日恐行人」是名句——怪鸟在旷野啼叫、落日让行人害怕，以「怪禽」「落日」写环境的荒凉与行人的恐惧，画面阴森；颈联「初月未终夕，边烽不过秦」写新月未全黑、烽火未过秦，以「边烽不过秦」写这里的安宁；尾联「萧条桑柘外，烟火渐相亲」写萧条桑柘外、炊烟渐亲切，以「烟火渐相亲」写由恐惧转为温暖，全诗由荒凉到温暖、由恐惧到亲切，情感转折自然，是贾岛五律的佳作。","b":"贾岛这首诗写傍晚经过山村的所见所感，由荒凉到温暖，是贾岛山水诗的名篇。","n":["暮过山村：傍晚经过山村","数里闻寒水：几里外就听到寒冷的水声","山家少四邻：山里人家很少有四邻（写偏僻）","怪禽啼旷野：怪鸟在旷野啼叫","落日恐行人：落日让行人害怕","初月未终夕：新月还没到晚上（指天还没全黑）","边烽不过秦：烽火没有越过秦地（指这里没有战火）。秦，今陕西一带","萧条桑柘外：萧条的桑树柘树外。柘音zhè，桑树的一种","烟火渐相亲：炊烟渐渐让人感到亲切"],"m":"怪禽啼旷野，落日恐行人。","r":"按「闻寒水少四邻—怪禽落日—初月边烽—桑柘烟火」背；由荒凉转温暖的情感转折是核心。"},"题诗后|贾岛":{"s":"首两句「二句三年得，一吟双泪流」写两句诗三年才得到、一吟诵就双泪直流，以「三年」写苦吟之久、以「双泪流」写得诗之喜，是苦吟诗人的真实写照；后两句「知音如不赏，归卧故山秋」写知音如果不欣赏就归隐故山，以「归卧」写对知音的渴望，全诗语言朴素、情感真挚，是贾岛苦吟诗风的自白，「二句三年得，一吟双泪流」成为千古名句，也是了解中唐苦吟诗派的重要作品。","b":"贾岛这首《题诗后》写自己苦吟的艰辛，「二句三年得，一吟双泪流」是苦吟诗人的自白，是了解贾岛诗风的名篇。","n":["题诗后：题完诗后（贾岛苦吟，作诗后写此诗）","二句三年得：两句诗三年才得到","一吟双泪流：一吟诵就双泪直流","知音如不赏：知音如果不欣赏","归卧故山秋：就回到故山秋卧（指归隐）"],"m":"二句三年得，一吟双泪流。","r":"四句按「二句三年—一吟双泪—知音不赏—归卧故山」背；苦吟精神是核心。"},"柏林寺南望|郎士元":{"s":"首两句「溪上遥闻精舍钟，泊舟微径度深松」写溪上遥闻寺钟、停船穿松寻寺，以「遥闻」「度深松」写游兴与山的幽深；后两句「青山霁后云犹在，画出东南四五峰」是名句——青山雨后初晴云还在、东南方的四五座山峰像画出来的一样，以「画出」写山的明丽如画，以「四五峰」写山的错落，语言清新、意境明丽，是中唐写景七绝的佳作。","b":"郎士元（中唐诗人）这首诗写雨后初晴望柏林寺南的青山，以「画出」写山的明丽，是写景小诗的名篇。","n":["柏林寺：在今河北赵县（一说在今陕西西安）","溪上遥闻精舍钟：在溪上远远听到佛寺的钟声。精舍，佛寺","泊舟微径度深松：停船沿小路穿过深松","青山霁后云犹在：青山雨后初晴云还在。霁，雨后初晴","画出东南四五峰：画出了东南方的四五座山峰"],"m":"青山霁后云犹在，画出东南四五峰。","r":"四句按「遥闻寺钟—泊舟度松—青山霁后—画出群峰」背；「画出」是炼字；以画喻山是核心。"},"淮上与友人别|郑谷":{"s":"首两句「扬子江头杨柳春，杨花愁杀渡江人」写扬子江头杨柳青青、柳絮飘飞愁煞渡江人，以杨柳、杨花写离情（古人折柳送别）；后两句「数声风笛离亭晚，君向潇湘我向秦」是千古名句——几声风笛、离亭傍晚，你去潇湘我去秦，以「风笛」「离亭」写离别的氛围、以「君向潇湘我向秦」写两人各奔东西，以朴素的语言写深挚的离情，「君向潇湘我向秦」成为千古名句，是晚唐送别诗的代表作。","b":"郑谷（晚唐诗人）这首诗写在淮水边与友人分别，一人去潇湘一人去秦，是送别诗的千古名篇。","n":["淮上：淮水边","扬子江头：长江渡口（扬子江，长江下游）","杨柳春：杨柳青青的春天","杨花愁杀渡江人：柳絮飘飞愁煞渡江的人","风笛：风中的笛声","离亭：送别亭","君向潇湘我向秦：你去潇湘（湖南）我去秦（陕西）"],"m":"数声风笛离亭晚，君向潇湘我向秦。","r":"四句按「扬子江头—杨花愁杀—风笛离亭—君向潇湘我向秦」背；折柳送别的文化背景是核心；「君向潇湘我向秦」是名句。"},"谷口书斋寄杨补阙|钱起":{"s":"首联「泉壑带茅茨，云霞生薜帷」写泉水山谷环绕茅屋、云霞从薜帷生起，环境清幽；颔联「竹怜新雨后，山爱夕阳时」是名句——竹子在新雨后更可爱、山在夕阳时更可爱，以「怜」「爱」写对竹与山的喜爱，以「新雨」「夕阳」写景色的明丽；颈联「闲鹭栖常早，秋花落更迟」写闲鹭早栖、秋花迟落，以动植写书斋的闲适；尾联「家童扫萝迳，昨与故人期」写家童扫小路、昨天与故人约定，以「扫萝迳」写期待友人来访，全诗意境清幽、对仗工稳，是大历十才子山水诗的代表作。","b":"钱起（中唐诗人，「大历十才子」之首）这首诗写谷口书斋的清幽景色，邀请友人杨补阙来访，是山水田园诗的名篇。","n":["谷口：谷口（在今陕西泾阳，汉代隐士郑子真隐居处）","书斋：书房","杨补阙：姓杨的补阙（补阙，官名，掌讽谏）","泉壑带茅茨：泉水山谷环绕着茅屋。茅茨，茅屋","云霞生薜帷：云霞从薜荔帷帐中生起。薜帷，薜荔做的帷帐","竹怜新雨后：竹子在新雨后更可爱。怜，爱","山爱夕阳时：山在夕阳时更可爱","闲鹭栖常早：悠闲的白鹭常常栖息得早","秋花落更迟：秋天的花落得更迟","家童扫萝迳：家童扫藤萝掩映的小路。迳同「径」","昨与故人期：昨天与故人（指杨补阙）约定了"],"m":"竹怜新雨后，山爱夕阳时。","r":"按「泉壑茅茨—云霞薜帷—新雨夕阳—闲鹭秋花—扫径期故人」背；「怜」「爱」是炼字；清幽意境是核心。"},"别离|陆龟蒙":{"s":"首联「丈夫非无泪，不洒离别间」写大丈夫不是没有泪、只是不洒在离别间，以「非无泪」「不洒」写大丈夫的克制；颔联「杖剑对尊酒，耻为游子颜」写持剑对酒、耻于做游子愁颜，以「杖剑」写豪情；颈联「蝮蛇一螫手，壮士即解腕」是名句——蝮蛇咬手、壮士断腕，用「壮士解腕」的典故写大丈夫的果断与以大局为重；尾联「所志在功名，离别何足叹」写志向在功名、离别不足叹，以反问写豪情，全诗刚健豪迈、一反送别诗的伤感传统，是晚唐送别诗中的别调。","b":"陆龟蒙（晚唐诗人，「皮陆」之一）这首《别离》写大丈夫以功名自任、不以离别为意的豪情，是送别诗中的豪放之作。","n":["杖剑：拿着剑。杖同「仗」","尊酒：一杯酒。尊同「樽」","耻为游子颜：耻于做出游子的愁颜","蝮蛇一螫手：蝮蛇一旦咬了手。螫音shì，毒虫刺人","壮士即解腕：壮士就砍断手腕（「蝮蛇螫手，壮士解腕」典故，指为大局牺牲局部）","所志在功名：志向在功名","离别何足叹：离别哪里值得叹息"],"m":"蝮蛇一螫手，壮士即解腕。","r":"四句按「丈夫有泪—杖剑对酒—蝮蛇螫手—功名何叹」背；「杖」同仗、「尊」同樽、「螫」读shì；壮士解腕典故是核心。"},"新沙|陆龟蒙":{"s":"首两句「渤澥声中涨小堤，官家知后海鸥知」写渤海中涨出新沙洲、官家比海鸥还先知道，以「官家知后海鸥知」的夸张讽刺官家征税之快、之细，连海鸥都不如；后两句「蓬莱有路教人到，应亦年年税紫芝」是名句——如果蓬莱有路让人到，也应该年年征收紫芝税，以「蓬莱税紫芝」的想象讽刺官家征税无孔不入，连仙境都不放过，想象奇特、讽刺辛辣，是晚唐讽刺诗的代表作。","b":"陆龟蒙这首《新沙》讽刺官家征税无孔不入，连新涨的沙洲都不放过，是晚唐讽刺诗的名篇。","n":["新沙：新涨出的沙洲","渤澥声中涨小堤：渤海的涛声中涨出了小堤。渤澥，渤海的别称。澥音xiè","官家知后海鸥知：官家知道后海鸥才知道（讽刺官家征税之快，连海鸥都不如）","蓬莱有路教人到：如果蓬莱有路让人到","应亦年年税紫芝：也应该年年征收紫芝税（紫芝，灵芝，传说中的仙草）"],"m":"蓬莱有路教人到，应亦年年税紫芝。","r":"四句按「渤澥涨堤—官家海鸥—蓬莱有路—年年税紫芝」背；「澥」读xiè；夸张与想象是讽刺手法。"},"感遇诗三十八首·一|陈子昂":{"s":"首四句「微月生西海，幽阳始代升。圆光正东满，阴魂已朝凝」写新月从西海升起、日月交替、月满月落，以日月运行写宇宙的规律；后四句「太极生天地，三元更废兴。至精谅斯在，三五谁能征」写太极生天地、三元更替兴衰，最精微的道理确实在这里，三皇五帝谁能验证呢，以哲理写对宇宙人生的思考，语言古朴、意境深远，是陈子昂感遇诗的代表作，体现了其追慕汉魏风骨、反对齐梁绮靡的诗学主张。","b":"陈子昂（初唐诗人，唐诗革新的先驱）《感遇》三十八首之一，以日月运行、太极生天地的哲理写对宇宙人生的思考，是其感遇诗的代表作。","n":["感遇诗三十八首：陈子昂的组诗，共三十八首，此为其一","微月生西海：新月从西海升起","幽阳始代升：幽暗的太阳开始替代升起（指日月交替）","圆光正东满：圆月正从东方满盈","阴魂已朝凝：阴魂已在早晨凝聚（指月落）","太极生天地：太极生天地（太极，古代哲学概念，指天地未分前的混沌之气）","三元更废兴：天、地、人三元更替兴衰。三元，天、地、人","至精谅斯在：最精微的道理确实在这里。谅，确实","三五谁能征：三皇五帝谁能验证呢。三五，三皇五帝；征，验证"],"m":"太极生天地，三元更废兴。","r":"按「微月幽阳—圆光阴魂—太极三元—至精三五」背；哲理思考是核心；汉魏风骨是风格特点。"},"陇西行四首·一|陈陶":{"s":"首两句「汉主东封报太平，无人金阙议边兵」写汉皇东封泰山夸耀太平、金殿上无人议论边事，以「东封」「无人议边兵」讽刺帝王粉饰太平、不关心边防；后两句「纵饶夺得林胡塞，碛地桑麻种不生」是名句——纵然夺得林胡塞，沙漠地里桑麻种不活，以「碛地桑麻种不生」写夺得了沙漠也无用，讽刺穷兵黩武、劳民伤财，语言朴素而讽刺深刻，是晚唐咏史讽刺诗的佳作。","b":"陈陶（晚唐诗人）《陇西行》四首之一，讽刺帝王夸耀太平、无人关心边事、夺得了沙漠也无用，是咏史讽刺诗。（同题第二首「誓扫匈奴不顾身，五千貂锦丧胡尘。可怜无定河边骨，犹是春闺梦里人」更为传诵。）","n":["陇西行：乐府旧题，写边塞征战（陈陶，晚唐诗人）","汉主东封报太平：汉皇东封泰山报告太平（指帝王封禅，夸耀太平）","无人金阙议边兵：金殿上无人议论边防战事。金阙，宫殿","纵饶夺得林胡塞：纵然夺得林胡塞（林胡，古代北方民族，此指边地）","碛地桑麻种不生：沙漠地里桑麻种不活。碛音qì，沙漠"],"m":"纵饶夺得林胡塞，碛地桑麻种不生。","r":"四句按「汉主东封—无人议边—纵饶夺得—碛地不生」背；「碛」读qì；讽刺粉饰太平与穷兵黩武是核心。"},"台城|韦庄":{"s":"首两句「江雨霏霏江草齐，六朝如梦鸟空啼」写江上细雨蒙蒙、江草整齐，六朝像梦一样、鸟儿空自啼叫，以「霏霏」「如梦」写六朝的虚幻与荒凉；后两句「无情最是台城柳，依旧烟笼十里堤」是千古名句——最无情的是台城的柳树，依旧烟雾笼罩十里长堤，以柳的「无情」「依旧」写人的有情、历史的变迁，以乐景写哀，借古讽今，意境苍凉，是晚唐咏史怀古诗的代表作，「无情最是台城柳」成为千古名句。","b":"韦庄（晚唐诗人，「花间派」代表）这首《台城》写六朝故都的荒凉，借古讽今，是晚唐咏史怀古诗的千古名篇。","n":["台城：六朝时的宫城，在今南京玄武湖边","江雨霏霏江草齐：江上细雨蒙蒙、江草整齐。霏霏，细雨蒙蒙的样子","六朝如梦鸟空啼：六朝像梦一样、鸟儿空自啼叫。六朝，吴、东晋、宋、齐、梁、陈，皆建都南京","无情最是台城柳：最无情的是台城的柳树","依旧烟笼十里堤：依旧烟雾笼罩着十里长堤"],"m":"无情最是台城柳，依旧烟笼十里堤。","r":"四句按「江雨江草—六朝如梦—台城柳—烟笼十里堤」背；以柳的无情反衬人的有情是核心；借古讽今是手法。"},"菩萨蛮·人人尽说江南好|韦庄":{"s":"上片「人人尽说江南好，游人只合江南老。春水碧于天，画船听雨眠」写人人都说江南好、游人只合江南老，春水比天碧绿、画船听雨入眠，以「春水碧于天」写江南水的明丽、以「画船听雨眠」写江南生活的闲适；下片「垆边人似月，皓腕凝霜雪。未老莫还乡，还乡须断肠」写垆边女子貌美、皓腕如霜雪，以「未老莫还乡，还乡须断肠」写对故乡的思念与不敢还乡的痛苦（韦庄故乡在战乱中），以乐景写哀，江南越美、思乡越痛，情感深沉，是花间词的代表作，「春水碧于天，画船听雨眠」成为千古名句。","b":"韦庄《菩萨蛮》五首之二（库文标为「人人尽说江南好」），写江南的美好与游子的思乡，是花间词的千古名篇，与白居易《忆江南》齐名。","n":["菩萨蛮：词牌名","人人尽说江南好：人人都说江南好","游人只合江南老：游人只应该在江南终老。只合，只应该","春水碧于天：春水比天还碧绿","画船听雨眠：在画船上听着雨声入眠","垆边人似月：酒垆边的女子像月亮一样美丽。垆，酒垆","皓腕凝霜雪：洁白的手腕像凝结的霜雪","未老莫还乡：没老不要还乡","还乡须断肠：还乡一定会断肠（指故乡战乱，回去会伤心）"],"m":"春水碧于天，画船听雨眠。","r":"按「人人说江南好—游人合老—春水画船—垆边人—未老莫还乡」背；以乐景写哀是核心；「只合」是只应该。"},"淮上喜会梁川故人|韦应物":{"s":"首联「江汉曾为客，相逢每醉还」写曾经在江汉做客、相逢每次醉归，回忆昔日的交游；颔联「浮云一别后，流水十年间」是名句——像浮云一样分别后、流水一样十年过去了，以「浮云」「流水」比喻离别与时间，以「十年」写时间之久，对仗工稳、意境苍凉；颈联「欢笑情如旧，萧疏鬓已斑」写欢笑情意如旧、鬓发已斑，以「情如旧」与「鬓已斑」对比，写岁月无情；尾联「何因北归去，淮上对秋山」写什么原因北归、在淮水边对秋山，以景结情，余味悠然，全诗情感深沉、对仗工稳，是韦应物五律的代表作。","b":"韦应物（中唐诗人）这首诗写在淮上与梁川故人久别重逢，写友情与岁月的感慨，是中唐五律的名篇。","n":["淮上：淮水边","梁川故人：梁川（今陕西南郑一带）的老朋友","江汉曾为客：曾经在江汉一带做客","相逢每醉还：相逢每次都醉着回去","浮云一别后：像浮云一样分别后","流水十年间：流水一样十年过去了","欢笑情如旧：欢笑的情意如旧","萧疏鬓已斑：稀疏的鬓发已经斑白。萧疏，稀疏","何因北归去：什么原因北归呢","淮上对秋山：在淮水边对着秋山"],"m":"浮云一别后，流水十年间。","r":"按「江汉为客—相逢醉还—浮云流水—欢笑鬓斑—何因北归」背；「浮云」「流水」比喻是核心；以景结情是手法。"},"初发扬子寄元大校书|韦应物":{"s":"首联「凄凄去亲爱，泛泛入烟雾」写凄凄离别亲爱、船驶入烟雾，以「凄凄」「泛泛」写离情与船行；颔联「归棹洛阳人，残钟广陵树」写回洛阳的人、残钟从广陵树间传来，以「归棹」「残钟」写离别的场景；颈联「今朝此为别，何处还相遇」写今天分别、何处再相遇，以反问写离别的惆怅；尾联「世事波上舟，沿洄安得住」是名句——世事像波浪上的船、顺流逆流怎么停得住，以「波上舟」比喻世事无常，以反问写对人生的感慨，全诗情感深沉、比喻贴切，是韦应物送别诗的代表作。","b":"韦应物这首诗写从扬子津出发、送别友人元大，写离情与世事无常的感慨，是送别诗的名篇。","n":["初发扬子：从扬子津（长江渡口）出发","元大校书：元大（排行大）校书郎（官名）","凄凄去亲爱：凄凄地离别亲爱之人","泛泛入烟雾：船泛泛地驶入烟雾中","归棹洛阳人：回洛阳的人（指元大，元大要回洛阳）。棹，船桨，代指船","残钟广陵树：残钟从广陵（扬州）的树间传来","今朝此为别：今天在这里分别","何处还相遇：什么地方还能相遇","世事波上舟：世事像波浪上的船","沿洄安得住：顺流逆流怎么能停得住呢。沿洄，顺流与逆流"],"m":"世事波上舟，沿洄安得住。","r":"按「凄凄泛泛—归棹残钟—今朝何处—世事波舟」背；「沿洄」是顺流逆流；世事如舟的比喻是核心。"},"寄全椒山中道士|韦应物":{"s":"首联「今朝郡斋冷，忽念山中客」写今天官署冷、忽然想念山中道士，以「冷」写心境、以「忽念」写思念；颔联「涧底束荆薪，归来煮白石」想象道士在涧底捆柴、回来煮白石，以「束荆薪」「煮白石」写道士的清苦与高洁；颈联「欲持一瓢酒，远慰风雨夕」写想拿一瓢酒、远远慰藉风雨之夜，以「一瓢酒」写情意的真；尾联「落叶满空山，何处寻行迹」是名句——落叶满空山、到哪里寻踪迹，以「落叶满空山」写山的空寂、以「何处寻」写寻而不得的惆怅，以景结情，意境清远，是韦应物五古的代表作，「落叶满空山，何处寻行迹」成为千古名句。","b":"韦应物任滁州刺史时，想念全椒山中道士，想送酒去却寻不到，是寄赠诗的千古名篇。","n":["全椒：今安徽全椒","山中道士：山中的道士","郡斋：州郡的官署（韦应物时任滁州刺史）","涧底束荆薪：在涧底捆柴。荆薪，柴草","归来煮白石：回来煮白石（道家传说仙人煮白石为粮，此指道士的清苦生活）","欲持一瓢酒：想拿一瓢酒","远慰风雨夕：远远地慰藉风雨之夜","落叶满空山：落叶满了空山","何处寻行迹：到哪里寻找踪迹呢"],"m":"欲持一瓢酒，远慰风雨夕。落叶满空山，何处寻行迹。","r":"按「郡斋冷念客—束薪煮石—持酒慰夕—落叶空山」背；「煮白石」是道家典故；以景结情是核心。"},"赋得暮雨送李胄|韦应物":{"s":"首联「楚江微雨里，建业暮钟时」写楚江微雨、建业暮钟，以「微雨」「暮钟」写送别的环境；颔联「漠漠帆来重，冥冥鸟去迟」是名句——茫茫中船帆沉重、昏暗中鸟飞迟缓，以「帆重」「鸟迟」写雨的细密，以「漠漠」「冥冥」写雨的迷蒙，对仗工稳、意境苍凉；颈联「海门深不见，浦树远含滋」写海门深不见、浦树远含滋，以「深不见」「远含滋」写远景的迷蒙；尾联「相送情无限，沾襟比散丝」写相送情无限、泪比雨丝多，以「散丝」比喻雨丝与泪丝，情景交融，全诗意境苍凉、情感深沉，是韦应物送别诗的代表作。","b":"韦应物这首诗写在暮雨中送别友人李胄，以雨写离情，是送别诗的名篇。","n":["赋得暮雨送李胄：以暮雨为题送李胄（赋得，指定题目赋诗）","楚江微雨里：楚江（长江）在微雨里","建业暮钟时：建业（南京）傍晚敲钟时","漠漠帆来重：茫茫中船帆来的沉重（因雨湿）。漠漠，迷蒙的样子","冥冥鸟去迟：昏暗中鸟飞去迟缓。冥冥，昏暗的样子","海门深不见：海门（长江入海处）深得看不见","浦树远含滋：水边的树远远含着湿润。滋，湿润","相送情无限：相送情意无限","沾襟比散丝：沾湿衣襟的泪比雨丝还多。散丝，比喻细雨"],"m":"漠漠帆来重，冥冥鸟去迟。","r":"按「楚江微雨—建业暮钟—漠漠冥冥—海门浦树—沾襟散丝」背；「漠漠」「冥冥」是叠字；以雨写情是核心。"},"长安遇冯著|韦应物":{"s":"首联「客从东方来，衣上灞陵雨」写客人从东方来、衣上带灞陵雨，以「灞陵雨」写行程的辛苦；颔联「问客何为来，采山因买斧」写问客人为什么来、答进山隐居买斧，以问答写冯著的失意与隐居之志；颈联「冥冥花正开，飏飏燕新乳」是名句——昏暗中花正开、飞舞中燕新乳，以「花正开」「燕新乳」写春景的生机，以乐景衬哀情；尾联「昨别今已春，鬓丝生几缕」写昨天分别今天已春、鬓边生了几缕白发，以「鬓丝」写岁月无情，全诗语言朴素、情感深沉，是韦应物赠答诗的代表作。","b":"韦应物这首诗写与友人冯著重逢，写冯著的失意与岁月的感慨，是赠答诗的名篇。","n":["冯著：韦应物的友人，曾隐居","客从东方来：客人从东方来","衣上灞陵雨：衣服上带着灞陵的雨（灞陵，在长安东，汉文帝陵墓，古人送别处）","问客何为来：问客人为什么来","采山因买斧：进山（隐居）因此买斧（指来买隐居的工具）","冥冥花正开：昏暗中花正开","飏飏燕新乳：飞舞中燕子刚喂雏。飏飏，飞舞的样子。飏音yáng","昨别今已春：昨天分别今天已是春天","鬓丝生几缕：鬓边生了几缕白发"],"m":"冥冥花正开，飏飏燕新乳。","r":"按「客从东来—衣上灞雨—问客何为—采山买斧—花燕—昨别鬓丝」背；「飏」读yáng；以乐景衬哀情是核心。"},"夕次盱眙县|韦应物":{"s":"首联「落帆逗淮镇，停舫临孤驿」写落帆停淮镇、停船靠孤驿，以「孤驿」写旅夜的孤寂；颔联「浩浩风起波，冥冥日沈夕」写浩浩风起波、冥冥日西沉，以「浩浩」「冥冥」写环境的苍茫；颈联「人归山郭暗，雁下芦洲白」是名句——人归山郭昏暗、雁下芦洲白，以「人归」「雁下」写傍晚的动态，以「暗」「白」写色彩的对比，画面苍凉；尾联「独夜忆秦关，听钟未眠客」写独夜忆秦关、听钟未眠，以「未眠」写思乡之深，全诗意境苍凉、情感深沉，是韦应物羁旅诗的代表作。","b":"韦应物这首诗写傍晚停宿盱眙县，写旅夜的孤寂与思乡，是羁旅诗的名篇。","n":["夕次盱眙县：傍晚停宿在盱眙县（今江苏盱眙）。次，停宿","落帆逗淮镇：落下船帆停在淮水边的镇子。逗，停留","停舫临孤驿：停船靠着孤驿。舫，船","浩浩风起波：浩浩的风掀起波浪","冥冥日沈夕：昏暗中太阳西沉。沈同「沉」","人归山郭暗：人归山郭昏暗","雁下芦洲白：雁下到白色的芦洲","独夜忆秦关：孤独的夜里忆念秦关（长安）","听钟未眠客：听着钟声的未眠客人"],"m":"人归山郭暗，雁下芦洲白。","r":"按「落帆停舫—风波日沉—人归雁下—独夜听钟」背；「沈」同沉；以景写情是核心。"},"滁州西涧|韦应物":{"s":"首两句「独怜幽草涧边生，上有黄鹂深树鸣」写独爱涧边幽草、上有黄鹂深树鸣，以「幽草」「黄鹂」写涧边的清幽，以「独怜」写诗人的偏爱；后两句「春潮带雨晚来急，野渡无人舟自横」是千古名句——春潮带雨傍晚来得急、野渡无人船自横，以「急」写雨的急、以「自横」写船的自在，以动衬静，画面清幽，意境深远，全诗语言朴素、意境清远，是韦应物七绝的代表作，「野渡无人舟自横」成为千古名句，也是中国山水画的常见题材。","b":"韦应物任滁州刺史时所作，写滁州西涧的清幽景色，是山水小诗的千古名篇，「野渡无人舟自横」成为千古名句。","n":["滁州西涧：滁州（今安徽滁州）城西的涧水","独怜幽草涧边生：独独喜爱涧边生长的幽草。怜，爱","上有黄鹂深树鸣：上面有黄鹂在深树中鸣叫","春潮带雨晚来急：春潮带着雨傍晚来得急","野渡无人舟自横：荒野的渡口无人、船自横在那里"],"m":"春潮带雨晚来急，野渡无人舟自横。","r":"四句按「独怜幽草—黄鹂深树—春潮带雨—野渡舟横」背；「怜」是爱；以动衬静是核心；「舟自横」是诗眼。"},"闻雁|韦应物":{"s":"首两句「故园眇何处，归思方悠哉」写故乡遥远在哪里、归思正悠长，以「眇」写故乡的遥远、以「悠哉」写归思的悠长；后两句「淮南秋雨夜，高斋闻雁来」是名句——淮南的秋雨之夜、在高斋中听到大雁飞来，以「秋雨夜」写环境的清冷、以「闻雁」写思乡的触发（大雁南飞引发游子思乡），以景结情，意境清远，全诗语言朴素、情感深沉，是韦应物五绝的代表作。","b":"韦应物任滁州刺史时所作，写秋雨夜闻雁思乡，是思乡小诗的名篇。","n":["闻雁：听到大雁的叫声","故园眇何处：故乡遥远在哪里。眇同「渺」，遥远","归思方悠哉：归思正悠长。悠哉，悠长的样子","淮南秋雨夜：淮南的秋雨之夜","高斋闻雁来：在高斋中听到大雁飞来"],"m":"淮南秋雨夜，高斋闻雁来。","r":"四句按「故园眇—归思悠—淮南秋雨—高斋闻雁」背；「眇」同渺；闻雁思乡是文化意象。"},"晚春|韩愈":{"s":"首两句「谁收春色将归去，慢绿妖红半不存」写谁收了春色将归去、绿叶红花大半不存，以「谁收」的拟人写春归、以「半不存」写晚春的凋零；后两句「榆荚祗能随柳絮，等闲撩乱走空园」是名句——榆荚只能随着柳絮、随便在空园里撩乱飞舞，以「祗能」「等闲」写榆荚柳絮的无奈与顽皮，以拟人写晚春的生机，语言明快、想象奇特，是韩愈七绝中的清新之作。","b":"韩愈这首《晚春》写晚春景色，以拟人手法写榆荚柳絮的飞舞，是写景小诗的名篇。（韩愈《晚春》另一首「草树知春不久归，百般红紫斗芳菲。杨花榆荚无才思，惟解漫天作雪飞」更为传诵。）","n":["晚春：晚春","谁收春色将归去：谁收了春色将要归去","慢绿妖红半不存：慢绿（绿叶）妖红（红花）大半不存在了","榆荚祗能随柳絮：榆荚只能随着柳絮（飘飞）。祗同「只」；榆荚，榆树的果实，形似钱，又称榆钱","等闲撩乱走空园：随便地在空园里撩乱飞舞。等闲，随便；撩乱，纷乱"],"m":"榆荚祗能随柳絮，等闲撩乱走空园。","r":"四句按「谁收春色—慢绿妖红—榆荚柳絮—撩乱空园」背；「祗」同只；拟人手法是核心。"},"左迁至蓝关示侄孙湘|韩愈":{"s":"首联「一封朝奏九重天，夕贬潮州路八千」以「朝奏」「夕贬」的对比写获罪之快、贬谪之远，悲愤激烈；颔联「欲为圣朝除弊事，肯将衰朽惜残年」直抒胸臆，写自己为朝廷除弊、不惜残年的忠愤；颈联「云横秦岭家何在，雪拥蓝关马不前」是千古名句——云横秦岭、家在何处，雪拥蓝关、马不肯前，以景写情，家亡国愁交织，苍凉悲壮；尾联「知汝远来应有意，好收吾骨瘴江边」写侄孙远来、正好在瘴江边收我的尸骨，以沉痛语作结，忠愤之气凛然，是韩愈七律的压卷之作。","b":"韩愈元和十四年（819）因上《论佛骨表》谏迎佛骨，触怒宪宗，被贬潮州，行至蓝关遇侄孙韩湘，写下这首诗，是韩诗的千古名篇。","n":["左迁：贬官（古人以右为尊，左迁即降职）","蓝关：蓝田关，在今陕西蓝田东南","侄孙湘：侄孙韩湘","一封朝奏九重天：早上一封奏章上达皇帝。九重天，指皇帝","夕贬潮州路八千：傍晚就被贬到八千里外的潮州","弊事：有害的事（指迎佛骨）","肯将衰朽惜残年：哪肯因衰老顾惜残年","瘴江：有瘴气的江水（指潮州一带）"],"m":"云横秦岭家何在，雪拥蓝关马不前。","r":"按「朝奏夕贬—除弊惜年—云横雪拥—收骨瘴江」背；「左迁」是贬官；忠愤是全诗基调。"},"早春呈水部张十八员外二首·一|韩愈":{"s":"首两句「天街小雨润如酥，草色遥看近却无」写京城小雨滋润如酥、草色远看有近看无，以「润如酥」写春雨的细腻、以「遥看近却无」写早春草的朦胧，观察入微；后两句「最是一年春好处，绝胜烟柳满皇都」写早春正是一年春好处、远胜过晚春烟柳满皇都，以对比写早春的可爱，全诗语言清新、观察细腻，是写早春的千古名篇，「草色遥看近却无」成为名句。","b":"韩愈这首小诗写早春景色，以「草色遥看近却无」写早春草的朦胧，是写早春的千古名篇。","n":["早春呈水部张十八员外：早春呈给水部员外郎张籍（张籍排行十八）","天街：京城的街道","润如酥：滋润如酥油（形容春雨的细腻）","草色遥看近却无：草色远看有、近看却无（写早春草刚发芽的状态）","最是一年春好处：正是一年中春天最好的地方","绝胜烟柳满皇都：远远胜过烟柳笼罩的皇都（晚春景色）"],"m":"天街小雨润如酥，草色遥看近却无。","r":"四句按「小雨润酥—草色有无—春好处—绝胜烟柳」背；「遥看近却无」是观察入微的名句。"},"师说|韩愈":{"s":"全文围绕「师道」展开：第一段提出中心论点——古之学者必有师，师者传道受业解惑，道之所存师之所存；第二段以对比批判当时耻于从师的风气——古之圣人从师而问、今之众人耻学于师，爱其子择师而教、于其身则耻师，巫医乐师百工不耻相师、士大夫群聚笑之，三层对比层层深入；第三段以孔子从师为例，提出「弟子不必不如师，师不必贤于弟子，闻道有先后，术业有专攻」的进步观点；第四段说明写作缘由——嘉许李蟠能行古道。全文论证严密、对比鲜明、气势充沛，是论说文的典范。","b":"韩愈这篇《师说》是针对当时士大夫耻于从师的风气而作，提出「道之所存，师之所存」「弟子不必不如师，师不必贤于弟子」等进步观点，是中国古代论说文的千古名篇。","n":["学者：求学的人","传道受业解惑：传授道理、教授学业、解答疑惑。受同「授」","庸知：哪里知道。庸，岂、哪里","无贵无贱：无论贵贱","句读：句子的停顿。读音dòu","小学而大遗：小的方面学习、大的方面遗漏","不齿：不屑一提","郯子：春秋时郯国国君，孔子曾向他问官名","苌弘：周敬王大夫，孔子曾向他问乐。苌音cháng","师襄：春秋鲁国乐官，孔子曾向他学琴","老聃：老子，孔子曾向他问礼。聃音dān","术业有专攻：学问技艺各有专门研究","贻：赠送。音yí"],"m":"师者，所以传道受业解惑也。是故无贵无贱，无长无少，道之所存，师之所存也。","r":"按「提出论点—批判风气（三层对比）—孔子例证—写作缘由」背；「受」同授、「读」读dòu、「贻」读yí；核心观点是「道之所存，师之所存」。"},"马说|韩愈":{"s":"全文以「伯乐—千里马」的比喻贯穿：第一段提出「世有伯乐，然后有千里马，千里马常有而伯乐不常有」，点明识才者的重要；第二段写千里马因食不饱、力不足而才美不外见，揭示人才被埋没的原因——「食马者不知其能千里而食也」；第三段写「策之不以其道，食之不能尽其材，鸣之而不能通其意」，却执策而临之曰「天下无马」，以「其真无马邪？其真不知马也」的反问作结，辛辣讽刺统治者不识人才。全文托物寓意、层层深入、语言精炼，是寓言式论说文的典范。","b":"韩愈这篇《马说》以千里马喻人才，以伯乐喻识才者，批判当时统治者不识人才、摧残人才的社会现象，是中国古代寓言式论说文的千古名篇。","n":["伯乐：春秋时善相马的人（孙阳）","祗辱于奴隶人之手：只是在奴仆手中受屈辱。祗同「只」","骈死于槽枥之间：并排死在马厩里。骈，两马并驾；槽枥，马槽。枥音lì","一食或尽粟一石：吃一顿有时能吃完一石粮食。石音dàn，容量单位","食马者：喂马的人。食音sì，喂养","才美不外见：才能和优点不能表现出来。见同「现」","策之不以其道：鞭打它不按正确方法。策，马鞭，此指鞭打","执策而临之：拿着鞭子面对着它","其真无马邪：难道真的没有千里马吗。邪同「耶」，语气词"],"m":"世有伯乐，然后有千里马。千里马常有，而伯乐不常有。","r":"按「提出论点—埋没原因—辛辣讽刺」背；「祗」同只、「食」读sì、「见」同现、「邪」同耶；核心是「千里马常有，伯乐不常有」。"},"进学解|韩愈":{"s":"全文采用辞赋的「主客问答」形式：第一段国子先生教诲学生——业精于勤荒于嬉、行成于思毁于随，当今圣贤相逢、选拔公平，诸生只需业精行成；第二段学生反驳——先生口不绝吟、手不停披、焚膏继晷，可谓勤矣；觝排异端、攘斥佛老，可谓劳矣；沉浸醲郁、含英咀华，文章闳中肆外，可谓能矣；然而公不见信、私不见助，跋前踬后、动辄得咎，冬暖儿号寒、年丰妻啼饥，头童齿豁，先生自己尚且如此，还教别人？第三段先生以工匠用材、医师用药为喻，说明人各有宜、量才录用，孟轲荀卿尚且不遇，自己如今「投闲置散，乃分之宜」，以自解作结，实则愤懑更深。全文辞藻华美、用典丰富、抑扬顿挫，是辞赋式论说文的典范。","b":"韩愈元和七年（812）任国子博士时所作，借国子先生与学生的对话，抒发自己才高而不被重用的愤懑，是中国古代辞赋式论说文的千古名篇，「业精于勤荒于嬉，行成于思毁于随」成为千古名句。","n":["进学解：关于增进学业的辨析（韩愈任国子博士时所作）","国子先生：韩愈自称（时任国子博士）","业精于勤荒于嬉：学业精进在于勤奋、荒废在于嬉戏","行成于思毁于随：品行成就在于思考、败坏在于因循","治具毕张：法令制度全部施行。治具，法令","爬罗剔抉：搜罗挑选（指选拔人才）","刮垢磨光：刮去污垢、磨出光泽（指培养人才）","焚膏油以继晷：点油灯继续日光（指夜以继日）。晷音guǐ，日光","兀兀：劳苦的样子","觝排异端：排斥异端邪说。觝同「抵」","补苴罅漏：弥补裂缝和漏洞。苴音jū，铺垫；罅音xià，裂缝","佶屈聱牙：文句曲折拗口。佶音jí、聱音áo","跋前踬后：进退两难。踬音zhì","头童齿豁：头顶秃了、牙齿缺了。童，秃；豁，缺","杗：大梁。音máng","桷：方椽子。音jué","欂栌：斗拱。音bólú","卓荦：卓越。荦音luò","訾：诋毁。音zǐ","豨苓：猪苓，泻药。豨音xī"],"m":"业精于勤，荒于嬉；行成于思，毁于随。","r":"按「先生教诲—学生反驳（勤/劳/能/遇）—先生自解」背；生僻字多：晷guǐ、苴jū、罅xià、佶jí、聱áo、踬zhì、杗máng、桷jué、欂栌bólú、荦luò、豨xī；核心名句是「业精于勤荒于嬉，行成于思毁于随」。"},"同题仙游观|韩翃":{"s":"首联「仙台下见五城楼，风物凄凄宿雨收」写仙台下见五城楼、宿雨初收风物凄凄，以「五城楼」写道观如仙境；颔联「山色遥连秦树晚，砧声近报汉宫秋」写山色遥连秦树、砧声近报汉宫秋，以「秦树」「汉宫」写历史的沧桑；颈联「疏松影落空坛静，细草香闲小洞幽」写疏松影落空坛、细草香闲小洞，以「空坛静」「小洞幽」写道观的清幽；尾联「何用别寻方外去，人间亦自有丹丘」写何必另寻方外、人间自有丹丘，以「丹丘」喻此地如仙境，全诗意境清幽、对仗工稳，是大历十才子山水诗的代表作。","b":"韩翃（中唐诗人，「大历十才子」之一）这首诗写游仙游观的景色，以道观的清幽写仙境的意境，是大历十才子山水诗的名篇。","n":["仙游观：在今河南嵩山","五城楼：传说中神仙的五城十二楼","宿雨收：昨夜的雨停了","秦树：秦地的树","砧声：捣衣声","汉宫：汉代宫殿，此指唐宫","空坛：空的祭坛","方外：世俗之外","丹丘：神仙居住的地方（昼夜常明）"],"m":"何用别寻方外去，人间亦自有丹丘。","r":"按「仙台宿雨—山色砧声—疏松细草—人间丹丘」背；「丹丘」是仙境；以道观比仙境是核心。"},"寒食|韩翃":{"s":"首两句「春城无处不飞花，寒食东风御柳斜」写京城寒食节——无处不飞花、东风吹斜御柳，以「飞花」「御柳」写京城春景的明丽，画面生动；后两句「日暮汉宫传蜡烛，轻烟散入五侯家」写傍晚皇宫传送蜡烛、轻烟散入五侯家，以「传蜡烛」「五侯家」暗讽权贵近臣得皇帝特赐、特权独享，以汉喻唐，含蓄讽刺，全诗语言明丽、寓意深刻，是中唐七绝的名篇，「春城无处不飞花」成为千古名句。","b":"韩翃这首《寒食》写京城寒食节的景色，以「汉宫传蜡烛」暗讽权贵得宠，是中唐七绝的千古名篇，据说唐德宗因这首诗赏识韩翃。","n":["寒食：寒食节，在清明前一二日，禁火吃冷食","春城无处不飞花：春天的京城无处不飘着柳絮（飞花，指柳絮）","御柳：皇宫中的柳树","汉宫传蜡烛：汉宫（指唐宫）传送蜡烛（寒食禁火，但皇帝特赐蜡烛给近臣）","五侯：指东汉桓帝时同日封侯的五个宦官，此指权贵近臣"],"m":"春城无处不飞花，寒食东风御柳斜。","r":"四句按「春城飞花—寒食御柳—汉宫传烛—轻烟五侯」背；「飞花」指柳絮；以汉喻唐、暗讽权贵是核心。"},"宿石邑山中|韩翃":{"s":"首两句「浮云不共此山齐，山霭苍苍望转迷」写浮云不能与此山齐、山霭苍苍望转迷，以「浮云不共齐」写山之高、以「望转迷」写山之深；后两句「晓月暂飞高树里，秋河隔在数峰西」是名句——晓月暂时飞进高树里、银河隔在数峰西，以「晓月」「秋河」写山中夜景的清幽，以「暂飞」「隔在」写山的高峻，画面清新、意境幽远，是大历十才子山水诗的佳作。","b":"韩翃这首诗写夜宿石邑山中所见的景色，以山的高峻写意境的清幽，是大历十才子山水诗的名篇。","n":["石邑山：在今河北获鹿东南","浮云不共此山齐：浮云不能与此山一样高（写山之高）","山霭苍苍：山中的云气苍茫。霭，云气","望转迷：望过去更加迷茫","晓月暂飞高树里：晓月暂时飞进高树里（写月被树遮）","秋河隔在数峰西：银河隔在数座山峰的西边。秋河，秋天的银河"],"m":"晓月暂飞高树里，秋河隔在数峰西。","r":"四句按「浮云不共齐—山霭望转迷—晓月高树—秋河数峰」背；以山高写境幽是核心。"},"过山农家|顾况":{"s":"这首六言诗四句四个画面：「板桥人渡泉声」写走过板桥听泉声，「茆檐日午鸡鸣」写茅檐正午鸡鸣，以声写山村的宁静；「莫嗔焙茶烟暗」写不要嗔怪焙茶烟熏暗了屋，「却喜晒谷天晴」写却高兴晒谷天晴，以「莫嗔」「却喜」写山农的生活与心情，一嗔一喜，生活气息浓郁，全诗六言句式整齐、画面生动，是六言诗中的佳作。","b":"顾况（中唐诗人）这首六言诗写过山农家所见的情景，以焙茶、晒谷写农家生活，是六言诗的名篇。","n":["过山农家：经过山农的家（六言诗）","板桥人渡泉声：人走过板桥时听到泉声","茆檐日午鸡鸣：茅草屋檐下正午鸡鸣。茆同「茅」","莫嗔焙茶烟暗：不要嗔怪焙茶的烟熏暗了屋子。嗔音chēn，责怪；焙音bèi，微火烘烤","却喜晒谷天晴：却高兴晒谷的天气晴朗"],"m":"莫嗔焙茶烟暗，却喜晒谷天晴。","r":"四句六言，按「板桥泉声—茆檐鸡鸣—莫嗔焙茶—却喜晒谷」背；「茆」同茅、「嗔」读chēn、「焙」读bèi；生活气息是核心。"},"宫词|顾况":{"s":"首两句「长乐宫连上苑春，玉楼金殿艳歌新」写长乐宫连上苑春、玉楼金殿艳歌新，以宫殿的华丽与歌舞的热闹反衬宫女的孤独；后两句「君门一入无由出，唯有宫莺得见人」是名句——宫门一入就出不来、只有宫莺能见到外面的人，以「宫莺得见人」反衬宫女不能见人，以鸟的自由反衬人的不自由，含蓄深沉，是宫怨诗的佳作。","b":"顾况这首《宫词》写宫女一入宫门便失去自由，只有宫莺能见到外面的人，是宫怨诗的名篇。","n":["长乐宫：汉代宫殿，此指唐宫","上苑：皇家园林","玉楼金殿：华丽的楼阁宫殿","艳歌新：新的艳丽歌声","君门一入无由出：宫门一进去就没有理由出来","宫莺：宫中的黄莺"],"m":"君门一入无由出，唯有宫莺得见人。","r":"四句按「长乐上苑—玉楼艳歌—君门无由出—宫莺得见人」背；以宫莺反衬宫女是核心。"},"楚江怀古三首·一|马戴":{"s":"首联「露气寒光集，微阳下楚丘」写露气寒光聚集、微阳落下楚丘，以「寒光」「微阳」写秋夜的清冷；颔联「猿啼洞庭树，人在木兰舟」是名句——猿在洞庭树上啼、人在木兰舟中，以「猿啼」写环境的凄清、以「人在舟」写游子的孤独，对仗工稳、意境苍凉；颈联「广泽生明月，苍山夹乱流」写广泽生明月、苍山夹乱流，以「明月」「乱流」写夜景的壮阔；尾联「云中君不降，竟夕自悲秋」写云神不降、整夜悲秋，以「悲秋」点题，全诗意境苍凉、对仗工稳，是晚唐五律的名篇。","b":"马戴这首诗写在楚江边、洞庭湖畔的秋夜景色，怀古伤今，是晚唐五律的名篇。","n":["楚江怀古：在楚江边怀古（马戴，晚唐诗人）","露气寒光集：露气与寒光聚集","微阳下楚丘：微弱的夕阳落下楚地的山丘","洞庭树：洞庭湖边的树","木兰舟：木兰木做的船（船的美称）","广泽：广阔的水泽（指洞庭湖）","乱流：杂乱的水流","云中君：云神（《楚辞·九歌》有《云中君》）","竟夕：整夜"],"m":"猿啼洞庭树，人在木兰舟。","r":"按「露气微阳—猿啼人舟—广泽苍山—云中君悲秋」背；「猿啼洞庭树，人在木兰舟」是名句；以景写情是核心。"},"灞上秋居|马戴":{"s":"首联「灞原风雨定，晚见雁行频」写灞原风雨初定、傍晚见雁阵频飞，以「雁行频」写秋意与思乡；颔联「落叶他乡树，寒灯独夜人」是名句——他乡树上的落叶、寒灯前孤独的人，以「落叶」「寒灯」写环境的凄清、以「他乡」「独夜」写游子的孤独，对仗工稳、意境苍凉；颈联「空园白露滴，孤壁野僧邻」写空园白露滴、孤壁与野僧邻，以「空园」「孤壁」写居处的荒凉；尾联「寄卧郊扉久，何门致此身」写久居郊外、什么门路能出仕，以反问写失意，全诗意境苍凉、情感深沉，是晚唐五律的名篇。","b":"马戴这首诗写在灞上秋居的孤独与失意，是晚唐五律的名篇。","n":["灞上：灞陵（在长安东）","灞原风雨定：灞原上的风雨停了","雁行频：雁阵频繁飞过","落叶他乡树：他乡树上的落叶","寒灯独夜人：寒灯前孤独的夜行人","空园白露滴：空园里白露滴落","孤壁野僧邻：孤壁旁与野僧为邻","郊扉：郊外的门（指自己的居处）","何门致此身：什么门路能让我出仕呢"],"m":"落叶他乡树，寒灯独夜人。","r":"按「风雨雁行—落叶寒灯—空园孤壁—郊扉何门」背；「落叶他乡树，寒灯独夜人」是名句；以景写情是核心。"},"送李少府贬峡中王少府贬长沙|高适":{"s":"首联「嗟君此别意何如，驻马衔杯问谪居」写感叹分别、停马饮酒问谪居，以「嗟」「问」写离情；颔联「巫峡啼猿数行泪，衡阳归雁几封书」是名句——巫峡猿啼使人落泪、衡阳归雁带来书信，以「巫峡」「衡阳」分别对应两位友人的贬所，对仗工稳、用典贴切；颈联「青枫江上秋天远，白帝城边古木疏」写青枫江秋远、白帝城古木疏，继续写两地景色；尾联「圣代即今多雨露，暂时分手莫踌躇」写当今圣明恩泽广、暂时分别不要犹豫，以宽慰作结，全诗情感真挚、对仗工稳，是盛唐送别七律的名篇。","b":"高适（盛唐边塞诗人）这首诗送两位友人分别被贬峡中和长沙，写离情与对友人的宽慰，是盛唐送别七律的名篇。","n":["李少府贬峡中：李姓县尉被贬到峡中（三峡一带）","王少府贬长沙：王姓县尉被贬到长沙","嗟君此别意何如：感叹你们这次分别心情如何","驻马衔杯问谪居：停马饮酒问贬谪之地","巫峡啼猿数行泪：巫峡猿啼使人落泪","衡阳归雁几封书：衡阳归雁带来几封书信","青枫江：青枫江（在长沙）","白帝城：在今重庆奉节（三峡入口）","圣代：圣明的时代","雨露：皇帝的恩泽","踌躇：犹豫不前"],"m":"巫峡啼猿数行泪，衡阳归雁几封书。","r":"按「嗟别问居—巫峡衡阳—青枫白帝—圣代莫踌躇」背；「巫峡啼猿」「衡阳归雁」分别对应两地；以宽慰作结是特点。"},"题菊花|黄巢":{"s":"首两句「飒飒西风满院栽，蘂寒香冷蝶难来」写秋风萧瑟满院菊花、花蕊寒冷香气清冷蝴蝶难来，以「西风」「寒香」写菊花的孤寂；后两句「他年我若为青帝，报与桃花一处开」是名句——将来我如果做了掌管春天的青帝，就让菊花与桃花一起开放，以「青帝」的想象写改变命运的雄心，以「桃花一处开」写对平等的渴望，托物言志、气势豪迈，是黄巢诗的代表作，也预示了他后来的起义。","b":"黄巢这首《题菊花》以菊花自比，写菊花在寒风中开放、蝴蝶难来，表达改变命运的雄心，是咏物言志的名篇。","n":["题菊花：题咏菊花（黄巢，唐末农民起义领袖）","飒飒西风：秋风萧瑟","蘂寒香冷蝶难来：花蕊寒冷香气清冷蝴蝶难来。蘂同「蕊」","他年我若为青帝：将来我如果做了青帝（青帝，神话中掌管春天的神）","报与桃花一处开：就让菊花与桃花一起开放"],"m":"他年我若为青帝，报与桃花一处开。","r":"四句按「飒飒西风—蘂寒香冷—我为青帝—报与桃花开」背；「蘂」同蕊；托物言志、改变命运的雄心是核心。"},"不第后赋菊|黄巢":{"s":"首两句「待到秋来九月八，我花开后百花杀」写等到九月初八、菊花开后百花凋谢，以「我花开」「百花杀」写菊花的压倒一切；后两句「冲天香阵透长安，满城尽带黄金甲」是千古名句——冲天的香气阵列浸透长安、满城都像披着黄金铠甲，以「冲天」「透长安」写气势的磅礴、以「黄金甲」写菊花的壮丽，想象奇特、气势豪迈，托物言志，预示了黄巢后来领导农民起义、攻入长安的雄心，是咏物诗中的千古名篇。","b":"黄巢科举落第后所作，以菊花的盛开写自己的雄心壮志，「满城尽带黄金甲」成为千古名句，是咏物言志的千古名篇。","n":["不第后赋菊：科举落第后咏菊（黄巢）","待到秋来九月八：等到秋天九月初八（九月九重阳节前一天）","我花开后百花杀：菊花开后百花都凋谢了（我花，指菊花）","冲天香阵透长安：冲天的香气阵列浸透长安","满城尽带黄金甲：满城都像披着黄金铠甲（指菊花盛开如黄金甲）"],"m":"冲天香阵透长安，满城尽带黄金甲。","r":"四句按「待到九月八—我花百花杀—冲天香阵—满城黄金甲」背；「黄金甲」比喻菊花；气势豪迈是核心。"},"谒金门·风乍起|冯延巳":{"s":"上片「风乍起，吹皱一池春水。闲引鸳鸯香径里，手挼红杏蕊」写风忽然吹起、吹皱一池春水，以「吹皱春水」比喻少妇心绪的不宁；闲来逗引鸳鸯、手揉红杏蕊，以「闲引」「手挼」写少妇的百无聊赖；下片「斗鸭阑干独倚，碧玉搔头斜坠。终日望君君不至，举头闻鹊喜」写独倚斗鸭栏杆、碧玉簪斜坠，以「独倚」「斜坠」写少妇的慵懒与孤独；终日望君君不至、抬头闻鹊喜，以「闻鹊喜」写在失望中又生希望，情感细腻，「风乍起，吹皱一池春水」成为千古名句。","b":"冯延巳（五代南唐词人，官至宰相）这首《谒金门》写闺中少妇思念丈夫的心情，「风乍起，吹皱一池春水」成为千古名句，是花间词的名篇。","n":["谒金门：词牌名","风乍起：风忽然吹起","吹皱一池春水：吹皱了一池春水（名句，中主李璟曾戏问冯延巳「吹皱一池春水，干卿何事」）","闲引鸳鸯：闲来逗引鸳鸯","香径：充满花香的小路","手挼红杏蕊：手揉搓红杏花蕊。挼音ruó，揉搓","斗鸭阑干：斗鸭的栏杆（古代有斗鸭的游戏）","碧玉搔头：碧玉做的簪子。搔头，簪子","斜坠：斜斜地坠落","举头闻鹊喜：抬头听到喜鹊叫而欢喜（喜鹊叫预示喜事）"],"m":"风乍起，吹皱一池春水。","r":"按「风乍起—吹皱春水—闲引鸳鸯—手挼红杏—独倚斜坠—望君闻鹊」背；「挼」读ruó；以吹皱春水比喻心绪不宁是核心。"},"鹊踏枝·谁道闲情抛掷久|冯延巳":{"s":"上片「谁道闲情抛掷久？每到春来，惆怅还依旧。日日花前常病酒，不辞镜里朱颜瘦」写谁说闲情抛掉了、每到春来惆怅依旧，天天花前醉酒、不辞朱颜消瘦，以「病酒」「朱颜瘦」写闲情的深；下片「河畔青芜堤上柳，为问新愁，何事年年有？独立小桥风满袖，平林新月人归后」写河畔青草堤上柳、试问新愁为何年年有，独立小桥风满袖、平林新月人归后，以「独立小桥」「风满袖」写孤独，以「平林新月」「人归后」写环境的清冷，意境深远，「独立小桥风满袖，平林新月人归后」成为千古名句，对后世影响深远。","b":"冯延巳这首《鹊踏枝》写闲情惆怅的缠绵，以「独立小桥风满袖」写孤独，是花间词向士大夫词过渡的名篇，对晏殊、欧阳修影响很大。","n":["鹊踏枝：词牌名，即《蝶恋花》","谁道闲情抛掷久：谁说闲情已经抛掉很久了","惆怅还依旧：惆怅还是依旧","日日花前常病酒：天天在花前常常醉酒。病酒，醉酒","不辞镜里朱颜瘦：不推辞镜里红颜消瘦","河畔青芜堤上柳：河畔青草、堤上柳树。青芜，青草","为问新愁：试问新愁","何事年年有：为什么年年都有","独立小桥风满袖：独自站在小桥上风吹满袖","平林新月人归后：平林上新月升起、人归去后"],"m":"独立小桥风满袖，平林新月人归后。","r":"按「闲情抛掷—惆怅依旧—花前病酒—朱颜瘦—青芜堤柳—新愁年年—独立小桥—平林新月」背；以景结情是核心；「独立小桥风满袖」是名句。"},"相见欢·林花谢了春红|李煜":{"s":"上片「林花谢了春红，太匆匆。无奈朝来寒雨晚来风」写林花凋谢了春红、太匆匆，无奈朝来寒雨晚来风，以「林花谢」写美好事物的消逝、以「朝来寒雨晚来风」写摧残的频繁，既是写花也是写自己的亡国之痛；下片「胭脂泪，相留醉，几时重。自是人生长恨水长东」写胭脂般的泪水、相互挽留沉醉、何时再重逢，以「胭脂泪」写美人的悲泣、以「几时重」写重逢的无望，最后以「人生长恨水长东」的比喻作结——人生的长恨就像水永远向东流一样不可挽回，意境深远、情感沉痛，是李煜词的千古名篇。","b":"李煜（南唐后主）亡国后所作，以林花凋谢写人生长恨，是李煜词的千古名篇，「人生长恨水长东」成为千古名句。","n":["相见欢：词牌名","林花谢了春红：林间的花凋谢了春天的红色","太匆匆：太匆匆忙忙了","无奈朝来寒雨晚来风：无奈早上寒雨晚上风","胭脂泪：胭脂般的泪水（指女子的泪，或指落花带雨如泪）","相留醉：相互挽留沉醉","几时重：什么时候再重逢","自是人生长恨水长东：人生本来就是长恨如水长向东流"],"m":"林花谢了春红，太匆匆。无奈朝来寒雨晚来风。自是人生长恨水长东。","r":"按「林花谢—太匆匆—寒雨晚风—胭脂泪—相留醉—几时重—人生长恨水长东」背；以花喻人、以水喻恨是核心；「人生长恨水长东」是名句。"},"破阵子·四十年来家国|李煜":{"s":"上片「四十年来家国，三千里地山河。凤阁龙楼连霄汉，玉树琼枝作烟萝，几曾识干戈」写南唐四十年家国、三千里山河，凤阁龙楼连云霄、玉树琼枝如烟雾，几曾认识战争，以繁华的回忆与「几曾识干戈」的无知对比，写亡国的原因；下片「一旦归为臣虏，沈腰潘鬓消磨。最是仓皇辞庙日，教坊犹奏别离歌，垂泪对宫娥」写一旦做了俘虏、沈腰潘鬓消磨，最是仓皇辞庙那天、教坊还奏别离歌、垂泪对宫娥，以「仓皇辞庙」「教坊奏歌」「垂泪宫娥」三个细节写亡国的惨痛，以乐景写哀，情感沉痛，是李煜词的千古名篇。","b":"李煜亡国被俘后所作，回忆南唐的繁华与亡国的惨痛，以「最是仓皇辞庙日，教坊犹奏别离歌，垂泪对宫娥」写亡国之痛，是李煜词的千古名篇。","n":["破阵子：词牌名","四十年来家国：南唐建国四十年（南唐937-975，约四十年）","三千里地山河：三千里地的山河","凤阁龙楼连霄汉：凤阁龙楼连接云霄。凤阁龙楼，指宫殿","玉树琼枝作烟萝：玉树琼枝像烟萝一样（指宫廷园林的珍奇花木）。烟萝，烟雾中的女萝","几曾识干戈：哪里认识战争。干戈，兵器，代指战争","一旦归为臣虏：一旦做了俘虏","沈腰潘鬓消磨：沈腰（沈约腰瘦）潘鬓（潘岳鬓白）都消磨了。沈同「沉」","仓皇辞庙：仓皇辞别宗庙","教坊犹奏别离歌：教坊还在奏别离歌。教坊，宫廷音乐机构","垂泪对宫娥：流着泪面对宫女"],"m":"最是仓皇辞庙日，教坊犹奏别离歌，垂泪对宫娥。","r":"按「四十年家国—三千里山河—凤阁龙楼—几曾识干戈—一旦臣虏—沈腰潘鬓—仓皇辞庙—教坊奏歌—垂泪宫娥」背；「沈」同沉；以繁华回忆与亡国惨痛对比是核心。"},"摊破浣溪沙·菡萏香销翠叶残|李璟":{"s":"上片「菡萏香销翠叶残，西风愁起绿波间。还与韶光共憔悴，不堪看」写荷花香销叶残、西风在绿波间起愁，与韶光一同憔悴、不堪看，以「菡萏香销」写秋景的萧瑟、以「韶光憔悴」写人的憔悴；下片「细雨梦回鸡塞远，小楼吹彻玉笙寒。多少泪珠何限恨，倚阑干」写细雨中梦醒、边塞遥远，小楼上吹遍玉笙、笙声凄寒，多少泪珠无限恨、倚着栏杆，以「梦回鸡塞」写思念之深、以「玉笙寒」写心境的凄寒，「细雨梦回鸡塞远，小楼吹彻玉笙寒」成为千古名句，意境凄清、情感深沉，是南唐词的名篇。","b":"李璟（南唐中主，李煜之父）这首词写思妇思念征夫的愁情，「细雨梦回鸡塞远，小楼吹彻玉笙寒」成为千古名句，是南唐词的名篇。","n":["摊破浣溪沙：词牌名（浣溪沙的变体）","菡萏香销翠叶残：荷花的香气消散、翠绿的荷叶残败。菡萏音hàndàn，荷花","西风愁起绿波间：西风在绿波间吹起愁意","还与韶光共憔悴：还与美好的时光一同憔悴。韶光，美好的时光","不堪看：不忍心看","细雨梦回鸡塞远：细雨中梦醒、鸡塞（鸡鹿塞，在今内蒙古，此指边塞）遥远","小楼吹彻玉笙寒：小楼上吹遍玉笙、笙声凄寒","多少泪珠何限恨：多少泪珠、无限怨恨","倚阑干：倚着栏杆"],"m":"细雨梦回鸡塞远，小楼吹彻玉笙寒。","r":"按「菡萏香销—西风愁起—韶光憔悴—不堪看—细雨梦回—鸡塞远—小楼吹彻—玉笙寒—泪珠倚阑」背；「菡萏」读hàndàn；以景写情是核心。"},"73821:长相思|万俟咏":{"s":"上片「一声声。一更更。窗外芭蕉窗里灯。此时无限情」写雨声一声接一声、夜一更接一更，窗外芭蕉窗里灯，此时无限情，以「一声声」「一更更」的叠字写雨的绵密与夜的漫长；下片「梦难成。恨难平。不道愁人不喜听。空阶滴到明」写梦难成、恨难平，不管愁人不喜欢听，雨在空阶滴到天明，以「滴到明」写雨的整夜不停与愁人的彻夜难眠，全词以雨声贯穿，叠字运用巧妙，意境凄清，是写雨的名篇。","b":"万俟咏（北宋末南宋初词人）这首《长相思》写雨夜的愁思，以雨声贯穿全词，是写雨的名篇。","n":["长相思：词牌名","一声声：一声接一声（指雨声）","一更更：一更接一更（指夜的漫长）","窗外芭蕉窗里灯：窗外的芭蕉、窗里的灯","此时无限情：此时有无限的情思","梦难成：梦难以做成","恨难平：怨恨难以平息","不道愁人不喜听：不管愁人不喜欢听","空阶滴到明：空荡的台阶上（雨）滴到天明"],"m":"窗外芭蕉窗里灯，此时无限情。","r":"按「一声声—一更更—芭蕉灯—无限情—梦难成—恨难平—不喜听—滴到明」背；叠字与雨声贯穿是核心。"},"卜算子|严蕊":{"s":"上片「不是爱风尘，似被前身误。花落花开自有时，总是东君主」写不是喜爱风尘、似乎被前世耽误，花落花开自有时、总是由春神主宰，以「不是爱风尘」的辩白写自己的无奈、以「东君主」写命运的不由自主；下片「去也终须去。住也如何住。若得山花插满头，莫问奴归处」写离去终究要离去、留下又怎么留，如果能归隐山花插满头、不要问我的归宿，以「山花插满头」写对自由的向往、以「莫问奴归处」写对尊严的坚持，全词语言朴素、情感真挚，是宋词中少有的妓女自白，「不是爱风尘，似被前身误」成为名句。","b":"严蕊（南宋天台营妓，有才学）这首《卜算子》是她被朱熹陷害入狱后，在岳霖面前自陈身世之作，写自己的不幸与对自由的渴望，是宋词中少有的妓女自白词。","n":["卜算子：词牌名","不是爱风尘：不是喜爱风尘（风尘，指妓女生活）","似被前身误：似乎是被前世耽误了","花落花开自有时：花落花开自然有时节","总是东君主：总是由东君（春神）主宰","去也终须去：离去终究要离去","住也如何住：留下又怎么能留下","若得山花插满头：如果能（归隐）把山花插满头","莫问奴归处：不要问我的归宿"],"m":"不是爱风尘，似被前身误。若得山花插满头，莫问奴归处。","r":"按「不是爱风尘—前身误—花开花落—东君主—去终须去—住如何住—山花满头—莫问归处」背；妓女自白与对自由的渴望是核心。"},"64118:贺新郎|刘克庄":{"s":"上片「国脉微如缕。问长缨、何时入手，缚将戎主。未必人间无好汉，谁与宽些尺度。试看取、当年韩五。岂有谷城公付授，也不干、曾遇骊山母。谈笑起，两河路」写国家命脉微弱如线，问长缨何时入手捆绑敌酋，未必人间无好汉、谁能放宽用人标准，看当年韩世忠，岂是有名师传授、遇过仙母，谈笑间在两河路起兵，以韩世忠为例呼吁用人；下片「少时棋柝曾联句。叹而今、登楼揽镜，事机频误。闻说北风吹面急，边上冲梯屡舞。君莫道、投鞭虚语。自古一贤能制难，有金汤、便可无张许。快投笔，莫题柱」写少年时曾联句，叹如今登楼揽镜、事机频误，听说北风急、边上云梯屡舞，莫道投鞭是虚语，自古一贤能制难，有金城汤池就可以没有张巡许远吗，快投笔从戎、莫追求功名，全词忧国忧民、呼吁抗金，气势豪迈，是南宋爱国词的名篇。","b":"刘克庄（南宋后期词人，「江湖派」领袖）这首《贺新郎》写国家危亡、呼吁用人抗金，是南宋爱国词的名篇。","n":["贺新郎：词牌名","国脉微如缕：国家的命脉微弱如线","长缨：长绳（用终军「请缨」典故，指克敌立功）","缚将戎主：捆绑敌酋","宽些尺度：放宽些标准（指用人）","韩五：韩世忠（排行五，南宋抗金名将）","谷城公：黄石公（张良的老师，此指名师）","骊山母：骊山老母（传说中的女仙）","两河路：黄河两岸的路（指中原抗金前线）","棋柝：棋盘和打更的梆子（指少年时的游戏与联句）","登楼揽镜：登楼揽镜（指忧国伤时、揽镜自照）","冲梯：冲锋的云梯","投鞭：投鞭断流（前秦苻坚「投鞭于江，足断其流」，此指敌人兵力强大）","金汤：金城汤池（比喻坚固的城池）","张许：张巡、许远（安史之乱中死守睢阳的名将）","投笔：投笔从戎（班超典故）","题柱：题柱（司马相如题升仙桥柱，指追求功名）"],"m":"国脉微如缕。问长缨、何时入手，缚将戎主。","r":"按「国脉微缕—长缨缚戎—宽尺度—韩五例—少时联句—而今事误—北风冲梯—一贤制难—投笔莫题柱」背；用典多（终军请缨、韩世忠、黄石公、投鞭断流、张巡许远、投笔从戎、题柱）；爱国主题是核心。"},"玉楼春|刘克庄":{"s":"上片「年年跃马长安市。客舍似家家似寄。青钱换酒日无何，红烛呼庐宵不寐」写年年在长安跃马、客舍似家家似寄，青钱换酒整天无事、红烛呼卢通宵不睡，以「跃马」「换酒」「呼卢」写早年的游乐与放荡；下片「易挑锦妇机中字。难得玉人心下事。男儿西北有神州，莫滴水西桥畔泪」写容易得到锦妇的回文、难得美人的心意，男儿西北有中原、不要为儿女私情流泪，以「西北有神州」的呼吁转折，从个人游乐转向爱国情怀，「男儿西北有神州，莫滴水西桥畔泪」成为名句，全词先抑后扬、气势豪迈，是南宋爱国词的名篇。","b":"刘克庄这首《玉楼春》写自己早年在京城的游乐生活，结尾以「男儿西北有神州，莫滴水西桥畔泪」呼吁爱国，是南宋爱国词的名篇。","n":["玉楼春：词牌名","跃马长安市：在长安市跃马（指在京城游乐）","客舍似家家似寄：客舍像家、家像寄居的地方（指常年在外）","青钱换酒日无何：用青钱换酒、整天无所事事。日无何，整天无事","红烛呼庐宵不寐：红烛下呼卢（赌博）通宵不睡。呼卢，赌博时的呼叫","锦妇机中字：锦妇（苏蕙）织在锦上的字（苏蕙织回文锦寄丈夫窦滔的典故）","玉人心下事：美人心中的事","西北有神州：西北有中原（指沦陷的中原）","水西桥畔泪：水西桥边的泪（指为儿女私情流泪）"],"m":"男儿西北有神州，莫滴水西桥畔泪。","r":"按「跃马长安—客舍家寄—青钱换酒—红烛呼卢—锦妇机字—玉人心事—西北神州—莫滴桥泪」背；用典（苏蕙回文）；先抑后扬、爱国呼吁是核心。"},"61884:沁园春|刘过":{"s":"上片「斗酒彘肩，风雨渡江，岂不快哉。被香山居士，约林和靖，与东坡老，驾勒吾回。坡谓西湖，正如西子，浓抹淡妆临镜台。二公者，皆掉头不顾，只管衔杯」写斗酒彘肩、风雨渡江岂不快哉，却被白居易约林逋、苏轼拉马回去，苏轼说西湖正如西施、浓抹淡妆临镜台，二公掉头不顾只管喝酒，想象三位古人对话；下片「白云天竺飞来。图画里、峥嵘楼观开。爱东西双涧，纵横水绕，两峰南北，高下云堆。逋曰不然，暗香浮动，争似孤山先探梅。须晴去，访稼轩未晚，且此俳徊」写白云天竺飞来、图画里楼观峥嵘，爱东西双涧水绕、两峰南北云堆，林逋说不然、暗香浮动怎比孤山探梅，等天晴去访辛弃疾也不晚、且在此徘徊，全词想象三位古人对话、各言西湖之美，构思奇特、用典丰富，是宋词中别具一格的名篇。","b":"刘过（南宋词人，辛弃疾的朋友）这首《沁园春》是他去拜访辛弃疾的路上，想象白居易、林逋、苏轼三位西湖诗人拉他回去赏西湖，构思奇特，是宋词中别具一格的名篇。","n":["沁园春：词牌名","斗酒彘肩：一斗酒、一只猪肘（樊哙在鸿门宴上的故事，此指豪情）","风雨渡江：风雨中渡江","香山居士：白居易（号香山居士）","林和靖：林逋（字和靖，北宋隐士，隐居西湖孤山）","东坡老：苏轼（号东坡居士）","驾勒吾回：拉着马让我回去","西湖正如西子：西湖正像西施（苏轼「欲把西湖比西子」）","浓抹淡妆临镜台：浓抹淡妆对着镜台（苏轼「淡妆浓抹总相宜」）","天竺飞来：天竺山飞来（飞来峰，在西湖灵隐寺前）","东西双涧：东西两条山涧","两峰南北：南北两高峰","暗香浮动：暗香浮动（林逋「疏影横斜水清浅，暗香浮动月黄昏」）","孤山先探梅：先到孤山探梅","稼轩：辛弃疾（号稼轩）","俳徊：徘徊。俳同「徘」"],"m":"坡谓西湖，正如西子，浓抹淡妆临镜台。","r":"按「斗酒渡江—三公约回—坡谓西子—二公衔杯—天竺飞来—双涧两峰—逋曰探梅—访稼轩徘徊」背；「俳」同徘；想象古人对话是核心特色。"},"唐多令|刘过":{"s":"上片「芦叶满汀洲。塞沙带浅流。二十年、重过南楼。柳下系舟犹未稳，能几日、又中秋」写芦叶满汀洲、塞沙带浅流，二十年后重过南楼，柳下系船未稳、能几日又中秋，以「二十年」「又中秋」写时间的流逝；下片「黄鹤断矶头。故人今不在。旧江山，浑是新愁。欲买桂花同载酒，终不似、少年游」写黄鹤矶头、故人不在，旧江山全是新愁，想买桂花载酒、终不像少年游，以「故人不在」「旧江山新愁」写物是人非、家国之痛，以「终不似少年游」写青春不再的感慨，全词情感深沉、意境苍凉，「欲买桂花同载酒，终不似、少年游」成为千古名句。","b":"刘过这首《唐多令》写二十年后重过武昌南楼，物是人非、江山易主的愁情，「终不似、少年游」成为名句，是南宋婉约词的名篇。","n":["唐多令：词牌名","芦叶满汀洲：芦叶满了水边平地","塞沙带浅流：边塞的沙地带着浅流","二十年、重过南楼：二十年后重过南楼（南楼，在武昌，刘过曾与友人游此）","柳下系舟犹未稳：柳下系船还没稳","能几日、又中秋：能过几天又到中秋","黄鹤断矶头：黄鹤矶的尽头（黄鹤矶，在武昌黄鹤楼旁）","故人今不在：老朋友如今不在了","旧江山，浑是新愁：旧江山全是新愁","欲买桂花同载酒：想买桂花一同载酒","终不似、少年游：终究不像少年时的游乐"],"m":"欲买桂花同载酒，终不似、少年游。","r":"按「芦叶汀洲—塞沙浅流—二十年南楼—系舟未稳—又中秋—黄鹤矶—故人不在—旧江山新愁—买花载酒—不似少年游」背；物是人非与家国之痛是核心。"},"双双燕|史达祖":{"s":"上片「过春社了，度帘幕中间，去年尘冷。差池欲住，试入旧巢相并。还相雕梁藻井。又软语、商量不定。飘然快拂花梢，翠尾分开红影」写春社过后、燕子穿过帘幕、去年巢穴尘冷，差池欲住、试入旧巢相并，相看雕梁藻井、软语商量不定，飘然快拂花梢、翠尾分开红影，以细腻的笔触写燕子归巢的全过程；下片「芳径。芹泥雨润。爱贴地争飞，竞夸轻俊。红楼归晚，看足柳昏花暝。应自栖香正稳。便忘了、天涯芳信。愁损翠黛双蛾，日日画阑独凭」写芳径芹泥雨润、贴地争飞竞夸轻俊，红楼归晚、看足柳昏花暝，栖香正稳、忘了天涯芳信，愁损翠黛双蛾、日日画阑独凭，以燕子的双飞快乐反衬思妇的孤独，全词咏物而不滞于物，以燕写人，是咏物词的千古名篇。","b":"史达祖（南宋词人，「婉约派」代表）这首《双双燕》是咏燕词的千古名篇，以燕子的归巢、筑巢、双飞写闺中思妇的孤独，是咏物词的典范。","n":["双双燕：词牌名（史达祖自度曲）","春社：春社日（祭祀土地神的日子，燕子春社来、秋社去）","度帘幕中间：穿过帘幕中间","去年尘冷：去年的巢穴尘土冰冷","差池：燕子羽毛参差不齐的样子（《诗经》「燕燕于飞，差池其羽」）","雕梁藻井：雕花的梁、画有花纹的天花板。藻井，天花板上的装饰","软语商量：柔声商量","花梢：花的顶端","翠尾分开红影：翠绿的尾羽分开红色的花影","芹泥雨润：芹菜地的泥土被雨滋润（燕子衔芹泥筑巢）","贴地争飞：贴着地面争飞","红楼归晚：回到红楼晚了","柳昏花暝：柳树昏暗、花影朦胧。暝音míng，昏暗","栖香正稳：在香巢中安稳栖息","天涯芳信：远方的书信（古人认为燕子能传信）","愁损翠黛双蛾：愁坏了画眉的双眉。翠黛，画眉的颜料；蛾，蛾眉","画阑独凭：独自靠着画栏"],"m":"还相雕梁藻井。又软语、商量不定。飘然快拂花梢，翠尾分开红影。","r":"按「春社度帘—去年尘冷—差池欲住—旧巢相并—相雕梁—软语商量—拂花梢—翠尾红影—芳径芹泥—贴地争飞—红楼归晚—柳昏花暝—栖香忘信—愁损独凭」背；「暝」读míng；以燕衬人、咏物写情是核心。"},"73579:水调歌头|叶梦得":{"s":"上片「秋色渐将晚，霜信报黄花。小窗低户深映，微路绕敧斜。为问山翁何事，坐看流年轻度，拚却鬓双华。徙倚望沧海，天净水明霞」写秋色渐晚、霜信报黄花，小窗低户深映、小路绕倾斜，问山翁何事、坐看流年轻度、不顾双鬓花白，徘徊望沧海、天净水明霞，写归隐生活的清幽与对流年虚度的感慨；下片「念平昔，空飘荡，遍天涯。归来三径重扫，松竹本吾家。却恨悲风时起，冉冉云间新雁，边马怨胡笳。谁似东山老，谈笑静胡沙」写念平生空飘荡遍天涯，归来三径重扫、松竹本吾家，却恨悲风起、云间新雁、边马怨胡笳，谁像谢安那样谈笑间平定胡沙，以「东山老」的典故呼吁抗金，全词由归隐到忧国，意境开阔，是南宋爱国词的名篇。","b":"叶梦得（南宋词人）这首《水调歌头》写晚年归隐的生活与对国事的忧虑，以「谁似东山老，谈笑静胡沙」呼吁抗金，是南宋爱国词的名篇。","n":["水调歌头：词牌名","霜信报黄花：霜的信息报给菊花（指霜降菊开）","敧斜：倾斜。敧音qī","山翁：山翁（指自己，或指隐士）","流年轻度：轻易度过流年","拚却鬓双华：不顾双鬓花白。拚音pàn，不顾","徙倚：徘徊。徙音xǐ","沧海：大海","三径：三条小路（用蒋诩「三径」典故，指归隐后的家园）","冉冉：慢慢的样子","边马怨胡笳：边地的马怨恨胡笳声。胡笳，北方少数民族乐器","东山老：谢安（隐居东山，此指有才能的隐士）","谈笑静胡沙：谈笑间平定胡人（胡沙，指北方少数民族的侵扰）"],"m":"谁似东山老，谈笑静胡沙。","r":"按「秋色霜信—小窗微路—山翁流年—鬓华—徙倚沧海—天净霞—念平昔—空飘荡—三径松竹—悲风新雁—边马胡笳—东山静胡沙」背；「敧」读qī、「拚」读pàn、「徙」读xǐ；用典（三径、东山谢安）；由归隐到忧国是核心。"},"夜书所见|叶绍翁":{"s":"首两句「萧萧梧叶送寒声，江上秋风动客情」写萧萧梧叶送寒声、江上秋风动客情，以「梧叶」「秋风」写秋意、以「客情」写游子的思乡；后两句「知有儿童挑促织，夜深篱落一灯明」是名句——知道有儿童在挑蟋蟀、夜深篱笆边一盏灯明，以儿童挑促织的欢乐反衬游子的孤独，以乐景写哀，「夜深篱落一灯明」的画面温馨而乡愁更深，全诗语言朴素、意境深远，是南宋七绝的名篇。","b":"叶绍翁（南宋诗人）这首小诗写秋夜所见，以儿童挑促织的乐景反衬游子的孤独，是南宋七绝的名篇。","n":["夜书所见：夜晚写下所见","萧萧梧叶送寒声：萧萧的梧桐叶送来寒冷的声音","江上秋风动客情：江上的秋风触动了游子的情思","知有儿童挑促织：知道有儿童在挑促织（蟋蟀）。促织，蟋蟀","夜深篱落一灯明：夜深了篱笆边一盏灯明"],"m":"知有儿童挑促织，夜深篱落一灯明。","r":"四句按「梧叶寒声—秋风客情—儿童挑促织—篱落一灯明」背；以乐景写哀、儿童反衬游子是核心。"},"孙权劝学|司马光":{"s":"全文分两层：第一层写孙权劝学——孙权对吕蒙说「卿今当涂掌事，不可不学」，吕蒙以军中多务推辞，孙权说「孤岂欲卿治经为博士邪！但当涉猎，见往事耳」，并以自己「常读书，自以为大有所益」现身说法，吕蒙乃始就学；第二层写吕蒙就学后的变化——鲁肃过寻阳，与蒙论议，大惊曰「卿今者才略，非复吴下阿蒙」，吕蒙曰「士别三日，即更刮目相待，大兄何见事之晚乎」，肃遂拜蒙母、结友而别。全文以对话为主，语言精炼，「吴下阿蒙」「士别三日，刮目相待」成为千古成语，是叙事散文的典范。","b":"司马光《资治通鉴》中的这篇《孙权劝学》写孙权劝吕蒙学习、吕蒙就学后才略大进的故事，「士别三日，即更刮目相待」「吴下阿蒙」成为成语，是中国古代叙事散文的名篇。","n":["孙权劝学：孙权劝吕蒙学习（选自《资治通鉴》）","当涂掌事：当权管事。当涂，当道、当权","辞以军中多务：以军中事务多推辞","治经为博士：研究经典做博士（专掌经学传授的学官）","但当涉猎：只应当广泛浏览。涉猎，广泛浏览","见往事耳：了解历史罢了","孰若孤：谁比得上我。孤，古代王侯的自称","及鲁肃过寻阳：等到鲁肃经过寻阳","才略：才干和谋略","非复吴下阿蒙：不再是吴下的阿蒙了（阿蒙，吕蒙的昵称）","士别三日：读书人分别三天","即更刮目相待：就应当另眼相看。刮目，擦眼睛，指另眼相看","大兄何见事之晚乎：长兄怎么认清事物这么晚呢","拜蒙母：拜见吕蒙的母亲","结友而别：结为朋友才分别"],"m":"士别三日，即更刮目相待，大兄何见事之晚乎！","r":"按「孙权劝学—吕蒙推辞—孙权现身说法—吕蒙就学—鲁肃大惊—吕蒙对答—结友而别」背；核心成语是「吴下阿蒙」「士别三日，刮目相待」；以对话写人是核心。"},"75074:采桑子|吕本中":{"s":"全词以「江楼月」为喻，正反两面写：上片「恨君不似江楼月，南北东西。只有相随无别离」写恨你不像江楼月——月亮南北东西都在、只有相随没有别离，以月的「相随无别离」反衬人的别离；下片「恨君却似江楼月，暂满还亏。暂满还亏。待得团团是几时」写恨你却像江楼月——暂时圆满又亏缺，等到团圆是什么时候，以月的「暂满还亏」比喻人的聚少离多，全词以月为喻，一正一反，构思巧妙，「恨君不似」「恨君却似」的对比写尽思妇的矛盾心理，是宋词中的名篇。","b":"吕本中（南宋词人）这首《采桑子》以江楼月为喻，写思妇对丈夫的思念，构思巧妙，是宋词中的名篇。","n":["采桑子：词牌名","恨君不似江楼月：遗憾你不像江楼上的月亮","南北东西：（月亮）南北东西（都在）","只有相随无别离：只有相随没有别离","恨君却似江楼月：遗憾你却像江楼上的月亮","暂满还亏：暂时圆满又亏缺","待得团团是几时：等到团圆是什么时候"],"m":"恨君不似江楼月，南北东西。只有相随无别离。恨君却似江楼月，暂满还亏。","r":"按「恨君不似月—南北东西—相随无别离—恨君却似月—暂满还亏—待得团团几时」背；以月为喻、一正一反是核心特色。"},"南歌子|吕本中":{"s":"上片「驿路侵斜月，溪桥度晓霜。短篱残菊一枝黄。正是乱山深处、过重阳」写驿路斜月、溪桥晓霜，短篱残菊一枝黄，正是乱山深处过重阳，以「斜月」「晓霜」「残菊」写旅途的凄清、以「乱山深处过重阳」写游子的孤独；下片「旅枕元无梦，寒更每自长。只言江左好风光。不道中原归思、转凄凉」写旅枕无梦、寒更长，只说江左风光好，不说中原归思转凄凉，以「中原归思」写家国之痛，全词由个人旅思转向家国之痛，意境苍凉，是南宋爱国词的名篇。","b":"吕本中这首《南歌子》写在乱山深处过重阳的旅思，以「中原归思」写家国之痛，是南宋爱国词的名篇。","n":["南歌子：词牌名","驿路侵斜月：驿路沐浴在斜月中","溪桥度晓霜：走过溪桥上的晓霜","短篱残菊一枝黄：短篱笆边一枝残菊黄","乱山深处、过重阳：在乱山深处过重阳节","旅枕元无梦：旅枕上本来无梦。元同「原」","寒更每自长：寒夜的更声每次都显得长","只言江左好风光：只说江左（江南）风光好","不道中原归思、转凄凉：不说中原的归思转而凄凉"],"m":"只言江左好风光，不道中原归思、转凄凉。","r":"按「驿路斜月—溪桥晓霜—残菊黄—乱山过重阳—旅枕无梦—寒更长—江左风光—中原归思凄凉」背；「元」同原；由个人旅思到家国之痛是核心。"},"65287:齐天乐|吴文英":{"s":"上片「三千年事残鸦外，无言倦凭秋树。逝水移川，高陵变谷，那识当时神禹。幽云怪雨。翠萍湿空梁，夜深飞去。雁起青天，数行书似旧藏处」写三千年往事在残鸦外、无言倦凭秋树，逝水移川、高陵变谷、哪识当时大禹，幽云怪雨、翠萍湿空梁、夜深飞去，雁起青天、几行字似旧藏处，以大禹治水的历史与禹庙的神秘写怀古；下片「寂寥西窗久坐，故人悭会遇，同翦灯语。积藓残碑，零圭断璧，重拂人间尘土。霜红罢舞。漫山色青青，雾朝烟暮。岸锁春船，画旗喧赛鼓」写寂寥西窗久坐、故人少会、同剪灯语，积藓残碑、零圭断璧、重拂尘土，霜红罢舞、山色青青、雾朝烟暮，岸锁春船、画旗喧赛鼓，以友人相聚与禹庙文物写今昔之感，全词用典丰富、意象密丽，是吴文英词的代表作。","b":"吴文英（南宋词人，「梦窗词」代表，格律派）这首《齐天乐》写与友人游禹庙、怀古伤今，是吴文英词的名篇，以密丽深涩的风格著称。","n":["齐天乐：词牌名","三千年事残鸦外：三千年的往事在残鸦之外（指历史久远）","无言倦凭秋树：无言疲倦地靠着秋树","逝水移川：流逝的水改变了河道","高陵变谷：高山变成了深谷（指世事变迁）","神禹：大禹（治水的大禹）","幽云怪雨：幽暗的云、怪异的雨","翠萍湿空梁：翠绿的浮萍沾湿了空梁（传说禹庙梁上有龙，能致云雨）","夜深飞去：夜深时飞去","雁起青天：大雁从青天飞起","数行书似旧藏处：几行字像旧藏书的地方（雁阵如字）","西窗久坐：西窗久坐","故人悭会遇：故人少相会。悭音qiān，少","同翦灯语：一同剪灯夜话。翦同「剪」","积藓残碑：积满苔藓的残碑","零圭断璧：零碎的圭、断裂的璧（指残缺的文物）。圭音guī","重拂人间尘土：重新拂去人间的尘土","霜红罢舞：霜红的叶子停止飞舞","漫山色青青：空有山色青青","岸锁春船：岸边锁着春船","画旗喧赛鼓：画旗喧闹、赛鼓声响（赛神的鼓）"],"m":"逝水移川，高陵变谷，那识当时神禹。","r":"按「三千年事—倦凭秋树—逝水高陵—神禹—幽云怪雨—翠萍空梁—雁起青天—西窗久坐—故人翦灯—残碑断璧—霜红罢舞—山色青青—岸锁春船—画旗赛鼓」背；「悭」读qiān、「翦」同剪、「圭」读guī；用典（大禹治水、禹庙龙梁）；密丽深涩是吴文英风格。"},"65333:风入松|吴文英":{"s":"上片「听风听雨过清明。愁草瘗花铭。楼前绿暗分携路，一丝柳、一寸柔情。料峭春寒中酒，交加晓梦啼莺」写听风听雨过清明、愁写葬花铭，楼前绿暗分别路、一丝柳一寸柔情，料峭春寒中酒、晓梦啼莺，以「清明」「葬花」「分携」写离别与思念；下片「西园日日扫林亭。依旧赏新晴。黄蜂频扑秋千索，有当时、纤手香凝。惆怅双鸳不到，幽阶一夜苔生」写西园日日扫林亭、依旧赏新晴，黄蜂频频扑秋千绳、有当时纤手的香气凝聚，惆怅双鸳不到、幽阶一夜苔生，以「黄蜂扑秋千索」的想象写思念之深——秋千索上似乎还留着情人纤手的香气，连黄蜂都被吸引，想象奇特、情感深挚，「黄蜂频扑秋千索，有当时、纤手香凝」成为名句，全词意境凄清、想象奇特，是吴文英词的名篇。","b":"吴文英这首《风入松》写清明时节思念情人，以「黄蜂频扑秋千索，有当时、纤手香凝」的想象写思念之深，是吴文英词的名篇。","n":["风入松：词牌名","听风听雨过清明：听风听雨过了清明节","愁草瘗花铭：愁闷中写葬花铭。瘗音yì，埋葬；铭，文体","楼前绿暗分携路：楼前绿荫浓密的分别路。分携，分别","一丝柳、一寸柔情：一丝柳、一寸柔情","料峭春寒中酒：微寒的春寒中醉酒。料峭，微寒","交加晓梦啼莺：交错的晓梦中黄莺啼叫","西园日日扫林亭：西园天天扫林亭","依旧赏新晴：依旧欣赏新晴","黄蜂频扑秋千索：黄蜂频频扑向秋千绳","有当时、纤手香凝：有当时纤手的香气凝聚","惆怅双鸳不到：惆怅鸳鸯（指情人的鞋）不到","幽阶一夜苔生：幽静的台阶一夜长满青苔"],"m":"黄蜂频扑秋千索，有当时、纤手香凝。","r":"按「听风听雨—清明—瘗花铭—绿暗分携—一丝柳一寸情—春寒中酒—晓梦啼莺—西园扫亭—赏新晴—黄蜂扑索—纤手香凝—双鸳不到—幽阶苔生」背；「瘗」读yì；黄蜂扑索的想象是核心特色。"},"65417:八声甘州|吴文英":{"s":"上片「渺空烟四远，是何年、青天坠长星。幻苍崖云树，名娃金屋，残霸宫城。箭径酸风射眼，腻水染花腥。时靸双鸳响，廊叶秋声」写空烟四远、何年青天坠长星，幻化出苍崖云树、名娃金屋、残霸宫城，箭径酸风刺眼、腻水染花腥，时靸双鸳响、廊叶秋声，以吴王夫差与西施的遗迹写历史的沧桑；下片「宫里吴王沈醉，倩五湖倦客，独钓醒醒。问苍波无语，华发奈山青。水涵空、阑干高处，送乱鸦、斜日落渔汀。连呼酒，上琴台去，秋与云平」写宫里吴王沉醉、请五湖倦客范蠡独钓醒醒，问苍波无语、华发奈山青，水涵空阑干高处、送乱鸦斜日落渔汀，连呼酒上琴台、秋与云平，以吴王的沉醉与范蠡的清醒对比，以「秋与云平」的开阔意境作结，全词怀古伤今、意境开阔，是吴文英词的千古名篇。","b":"吴文英这首《八声甘州》是游苏州灵岩山（吴王夫差与西施的遗迹）时所作，借吴越兴亡的历史写怀古伤今，是吴文英词的千古名篇。","n":["八声甘州：词牌名","渺空烟四远：渺茫的空烟向四方远去","青天坠长星：青天坠下长星（指灵岩山如长星坠地）","幻苍崖云树：幻化出苍崖云树","名娃金屋：名娃（西施）的金屋","残霸宫城：残霸（吴王夫差）的宫城","箭径酸风射眼：箭径（采香径）的酸风刺眼。酸风，刺眼的风","腻水染花腥：腻水（宫女梳洗的水）染花带腥","时靸双鸳响：不时传来拖鞋的声音。靸音sǎ，拖鞋；双鸳，鸳鸯鞋","廊叶秋声：廊下的叶声（响屧廊，吴王宫中的廊，西施穿木屐走过会响）","宫里吴王沈醉：宫里吴王沉醉","倩五湖倦客：请五湖倦客（范蠡，助越灭吴后泛舟五湖）。倩音qìng，请","独钓醒醒：独自垂钓、清醒着","问苍波无语：问苍波无语","华发奈山青：白发无奈山青","水涵空：水包含天空","阑干高处：栏杆高处","送乱鸦、斜日落渔汀：送乱鸦、斜日落在渔汀。汀音tīng，水边平地","连呼酒：连连呼酒","上琴台去：上琴台去（琴台，在灵岩山，西施弹琴处）","秋与云平：秋意与云平"],"m":"宫里吴王沈醉，倩五湖倦客，独钓醒醒。","r":"按「空烟四远—青天坠星—苍崖云树—名娃金屋—残霸宫城—箭径酸风—腻水花腥—靸双鸳响—廊叶秋声—吴王沉醉—范蠡独钓—苍波无语—华发山青—水涵空—送乱鸦—呼酒琴台—秋与云平」背；「靸」读sǎ、「倩」读qìng、「汀」读tīng、「沈」同沉；用典（吴王夫差、西施、范蠡、响屧廊、采香径、琴台）；怀古伤今是核心。"},"唐多令|吴文英":{"s":"上片「何处合成愁。离人心上秋。纵芭蕉、不雨也飕飕。都道晚凉天气好，有明月、怕登楼」写愁字怎么合成、离人的心上有秋（拆字「愁=秋+心」），纵然芭蕉不下雨也飕飕响，都说晚凉天气好、有明月怕登楼，以拆字手法写离愁、以「怕登楼」写思乡；下片「年事梦中休。花空烟水流。燕辞归、客尚淹留。垂柳不萦裙带住，漫长是、系行舟」写年事梦中休、花空烟水流，燕辞归客尚淹留，垂柳不缠住情人的裙带、却总是系住行舟，以「垂柳不萦裙带、却系行舟」的对比写离愁，全词构思巧妙、语言明快，「何处合成愁，离人心上秋」成为名句，是吴文英词中别具一格的作品。","b":"吴文英这首《唐多令》写离愁，以「何处合成愁，离人心上秋」的拆字手法开篇，是吴文英词中少有的疏朗明快之作。","n":["唐多令：词牌名","何处合成愁：愁字怎么合成（「愁」=「秋」+「心」）","离人心上秋：离人的心上有秋（拆字：愁=秋+心）","纵芭蕉、不雨也飕飕：纵然芭蕉不下雨也飕飕响。飕飕，风声","都道晚凉天气好：都说晚凉天气好","有明月、怕登楼：有明月、怕登楼","年事梦中休：年事在梦中结束","花空烟水流：花空了、烟水流逝","燕辞归、客尚淹留：燕子辞别归去、客子还滞留。淹留，滞留","垂柳不萦裙带住：垂柳不缠住裙带（指情人）。萦音yíng，缠绕","漫长是、系行舟：总是系住行舟"],"m":"何处合成愁。离人心上秋。","r":"按「何处合成愁—人心上秋—芭蕉飕飕—晚凉天好—有明月怕登楼—年事梦休—花空水流—燕辞客留—垂柳不萦裙—长系行舟」背；「萦」读yíng；拆字手法（愁=秋+心）是核心特色。"},"74227:鹧鸪天|周紫芝":{"s":"上片「一点残红欲尽时。乍凉秋气满屏帏。梧桐叶上三更雨，叶叶声声是别离」写残灯将尽、秋气满屏帏，梧桐叶上三更雨、叶叶声声是别离，以「三更雨」「叶叶声声」写离愁的绵密；下片「调宝瑟，拨金猊。那时同唱鹧鸪词。如今风雨西楼夜，不听清歌也泪垂」写调宝瑟、拨金猊，那时同唱鹧鸪词，如今风雨西楼夜、不听清歌也泪垂，以「那时同唱」与「如今泪垂」对比，写物是人非的感慨，全词意境凄清、情感深沉，「梧桐叶上三更雨，叶叶声声是别离」成为名句。","b":"周紫芝（南宋词人）这首《鹧鸪天》写秋夜思念情人，以「梧桐叶上三更雨，叶叶声声是别离」写离愁，是宋词中的名篇。","n":["鹧鸪天：词牌名","一点残红欲尽时：一点残灯将尽时","乍凉秋气满屏帏：刚凉的秋气充满屏帏。屏帏，屏风和帷帐","梧桐叶上三更雨：梧桐叶上三更的雨","叶叶声声是别离：每叶每声都是别离","调宝瑟：调弄宝瑟","拨金猊：拨弄金猊（金狮形的香炉）。猊音ní","那时同唱鹧鸪词：那时一同唱鹧鸪词","如今风雨西楼夜：如今风雨西楼的夜晚","不听清歌也泪垂：不听清歌也流泪"],"m":"梧桐叶上三更雨，叶叶声声是别离。","r":"按「残红欲尽—秋气屏帏—梧桐三更雨—叶叶是别离—调宝瑟—拨金猊—同唱鹧鸪—风雨西楼—不听清歌也泪垂」背；「猊」读ní；以雨写愁、今昔对比是核心。"},"72739:满庭芳|周邦彦":{"s":"上片「风老莺雏，雨肥梅子，午阴嘉树清圆。地卑山近，衣润费垆烟。人静乌鸢自乐，小桥外、新绿溅溅。凭栏久，黄芦苦竹，拟泛九江船」写风老莺雏、雨肥梅子、午阴嘉树清圆，地卑山近、衣润费炉烟，人静乌鸢自乐、小桥外新绿溅溅，凭栏久、黄芦苦竹、拟泛九江船，以江南夏景写羁旅之愁；下片「年年。如社燕，飘流瀚海，来寄修椽。且莫思身外，长近尊前。憔悴江南倦客，不堪听、急管繁弦。歌筵畔，先安簟枕，容我醉时眠」写年年如社燕、飘流瀚海、来寄修椽，且莫思身外、长近尊前，憔悴江南倦客、不堪听急管繁弦，歌筵畔先安簟枕、容我醉时眠，以社燕自比、以醉眠排遣，全词意境清丽、情感深沉，「风老莺雏，雨肥梅子」成为名句，是周邦彦词的名篇。","b":"周邦彦（北宋词人，「婉约派」集大成者，格律派创始人）这首《满庭芳》写在溧水（今江苏溧水）任上的羁旅之愁，以「且莫思身外，长近尊前」写自我排遣，是周邦彦词的名篇。","n":["满庭芳：词牌名","风老莺雏：春风使莺雏长大","雨肥梅子：雨使梅子肥美","午阴嘉树清圆：正午的树荫下嘉树清圆","地卑山近：地势低、靠近山","衣润费垆烟：衣服湿润费炉烟（烤衣服）。垆同「炉」","人静乌鸢自乐：人静时乌鸦鸢鸟自乐。鸢音yuān","新绿溅溅：新绿的水溅溅响。溅溅音jiānjiān，水流声","黄芦苦竹：黄芦和苦竹（白居易《琵琶行》「黄芦苦竹绕宅生」）","拟泛九江船：打算泛九江的船","社燕：春社时来的燕子","飘流瀚海：飘流到瀚海（北方大沙漠，此指遥远）","来寄修椽：来寄居在长椽下。椽音chuán，椽子","且莫思身外：且不要想身外之事","长近尊前：长在酒杯前。尊同「樽」","憔悴江南倦客：憔悴的江南倦客","急管繁弦：急促的管乐、繁复的弦乐","歌筵畔：歌筵旁","先安簟枕：先安好竹席和枕头。簟音diàn，竹席","容我醉时眠：让我醉时眠"],"m":"风老莺雏，雨肥梅子，午阴嘉树清圆。","r":"按「风老莺雏—雨肥梅子—午阴嘉树—地卑山近—衣润炉烟—人静乌鸢—新绿溅溅—黄芦苦竹—九江船—社燕飘流—寄修椽—莫思身外—长近尊前—憔悴倦客—急管繁弦—安簟枕—醉时眠」背；「鸢」读yuān、「溅溅」读jiānjiān、「椽」读chuán、「簟」读diàn、「垆」同炉、「尊」同樽；以社燕自比、以醉排遣是核心。"},"苏幕遮|周邦彦":{"s":"上片「燎沈香，消溽暑。鸟雀呼晴，侵晓窥檐语。叶上初阳干宿雨，水面清圆，一一风荷举」写焚沉香消溽暑，鸟雀呼晴、侵晓窥檐语，叶上初阳干宿雨、水面清圆、一一风荷举，以「风荷举」写荷叶的挺立，「一一」写出荷叶的层次，是写荷花的千古名句；下片「故乡遥，何日去。家住吴门，久作长安旅。五月渔郎相忆否。小楫轻舟，梦入芙蓉浦」写故乡遥、何日去，家住吴门、久作长安旅，五月渔郎相忆否，小楫轻舟、梦入芙蓉浦，以荷塘景色引发思乡，以「梦入芙蓉浦」写对故乡的思念，全词由景入情、过渡自然，「叶上初阳干宿雨，水面清圆，一一风荷举」成为千古名句。","b":"周邦彦这首《苏幕遮》写夏日荷塘景色与思乡之情，「叶上初阳干宿雨，水面清圆，一一风荷举」是写荷花的千古名句，王国维评为「真能得荷之神理者」。","n":["苏幕遮：词牌名","燎沈香：焚烧沉香。沈同「沉」","消溽暑：消除潮湿的暑气。溽音rù，潮湿","鸟雀呼晴：鸟雀呼唤晴天","侵晓窥檐语：破晓时在屋檐下窥看鸣叫。侵晓，破晓","叶上初阳干宿雨：叶上的初阳晒干了昨夜的雨","水面清圆：水面上的荷叶清圆","一一风荷举：一片一片风中的荷叶挺立。举，挺立","故乡遥，何日去：故乡遥远，何时归去","家住吴门：家住在吴门（苏州）","久作长安旅：长久在长安做客","五月渔郎相忆否：五月的渔郎还记得我吗","小楫轻舟：小桨轻舟","梦入芙蓉浦：梦中进入荷花塘。芙蓉浦，荷花塘"],"m":"叶上初阳干宿雨，水面清圆，一一风荷举。","r":"按「燎沉香—消溽暑—鸟雀呼晴—侵晓窥语—初阳干宿雨—水面清圆—一一风荷举—故乡遥—何日去—家住吴门—久作长安旅—渔郎相忆—小楫轻舟—梦入芙蓉浦」背；「沈」同沉、「溽」读rù；「风荷举」是写荷名句；由景入情是核心。"},"齐天乐|周邦彦":{"s":"上片「绿芜凋尽台城路，殊乡又逢秋晚。暮雨生寒，鸣蛩劝织，深阁时闻裁剪。云窗静掩。叹重拂罗裀，顿疏花簟。尚有𦈌囊，露萤清夜照书卷」写绿芜凋尽台城路、殊乡又逢秋晚，暮雨生寒、鸣蛩劝织、深阁闻裁剪，云窗静掩，重拂罗裀、顿疏花簟，尚有𦈌囊、露萤清夜照书卷，以秋景与物候写羁旅之愁；下片「荆江留滞最久，故人相望处，离思何限。渭水西风，长安乱叶，空忆诗情宛转。凭高眺远。正玉液新𥬠，蟹螯初荐。醉倒山翁，但愁斜照敛」写荆江留滞最久、故人相望、离思何限，渭水西风、长安乱叶、空忆诗情宛转，凭高眺远，玉液新𥬠、蟹螯初荐，醉倒山翁、但愁斜照敛，以故人之思与醉饮排遣，全词用典丰富（车胤囊萤、贾岛秋风、山简醉酒）、格律精严，是周邦彦词的名篇。","b":"周邦彦这首《齐天乐》写在异乡逢秋晚的羁旅之愁与对故人的思念，用典丰富、格律精严，是周邦彦词的名篇。","n":["齐天乐：词牌名","绿芜凋尽台城路：绿草凋尽的台城路（台城，六朝宫城，在南京）","殊乡又逢秋晚：在异乡又逢秋晚","暮雨生寒：暮雨生寒","鸣蛩劝织：蟋蟀鸣叫像劝人织布。蛩音qióng，蟋蟀","深阁时闻裁剪：深阁中不时听到裁剪声","云窗静掩：云窗静掩","重拂罗裀：重拂罗褥。裀音yīn，褥子","顿疏花簟：顿时疏远了花竹席。簟音diàn","𦈌囊：粗布袋。𦈌音shū，粗布","露萤清夜照书卷：露水中的萤火虫在清夜照书卷（车胤囊萤读书典故）","荆江留滞最久：在荆江（今湖北一带）留滞最久","故人相望处：故人相望的地方","离思何限：离思无限","渭水西风：渭水的西风（贾岛「秋风生渭水」）","长安乱叶：长安的乱叶","空忆诗情宛转：空忆诗情宛转","凭高眺远：登高眺远","玉液新𥬠：新酿的美酒。𥬠音chōu，滤酒","蟹螯初荐：蟹螯初上桌。蟹螯，螃蟹的大钳","醉倒山翁：醉倒山翁（山简，晋代人，常醉倒）","但愁斜照敛：只愁夕阳收敛"],"m":"渭水西风，长安乱叶，空忆诗情宛转。","r":"按「绿芜台城—殊乡秋晚—暮雨生寒—鸣蛩劝织—深阁裁剪—云窗静掩—重拂罗裀—顿疏花簟—𦈌囊露萤—荆江留滞—故人离思—渭水西风—长安乱叶—空忆诗情—凭高眺远—玉液新𥬠—蟹螯初荐—醉倒山翁—但愁斜照」背；「蛩」读qióng、「裀」读yīn、「簟」读diàn、「𦈌」读shū、「𥬠」读chōu；用典（囊萤、渭水西风、山简醉酒）；羁旅之愁是核心。"},"72764:少年游|周邦彦":{"s":"上片「并刀如水，吴盐胜雪，纤手破新橙。锦幄初温，兽烟不断，相对坐调笙」写并刀如水、吴盐胜雪、纤手破新橙，锦幄初温、兽烟不断、相对坐调笙，以「破新橙」「调笙」的细节写幽会的温情；下片「低声问向谁行宿，城上已三更。马滑霜浓，不如休去，直是少人行」写低声问今晚到哪里住宿、城上已三更，马滑霜浓、不如休去、只是少人行，以「低声问」的对话写情人的挽留，语言朴素、细节生动，全词以白描手法写幽会的温情，「并刀如水，吴盐胜雪，纤手破新橙」成为名句，是周邦彦词的名篇。","b":"周邦彦这首《少年游》写与情人的幽会，以「并刀如水，吴盐胜雪，纤手破新橙」的细节写温情，是周邦彦词的名篇，传说与宋徽宗、李师师的故事有关。","n":["少年游：词牌名","并刀如水：并州的剪刀如水般锋利。并刀，并州（今山西太原）产的剪刀，以锋利著称","吴盐胜雪：吴地的盐胜过雪（吴盐，吴地产的盐，洁白）","纤手破新橙：纤手剥开新橙","锦幄初温：锦制的帷幕刚温暖。幄音wò，帷幕","兽烟不断：兽形香炉的烟不断","相对坐调笙：相对坐着调笙","低声问向谁行宿：低声问今晚到哪里住宿。谁行，哪里、哪边","城上已三更：城上已三更","马滑霜浓：马滑霜浓","不如休去：不如不要去","直是少人行：只是少人行"],"m":"并刀如水，吴盐胜雪，纤手破新橙。","r":"按「并刀如水—吴盐胜雪—纤手破橙—锦幄初温—兽烟不断—相对调笙—低声问—城上三更—马滑霜浓—不如休去—少人行」背；「幄」读wò；白描与对话是核心特色；传说与宋徽宗李师师有关。"},"解语花|周邦彦":{"s":"上片「风销焰蜡，露浥烘炉。花市光相射。桂华流瓦。纤云散，耿耿素娥欲下。衣裳淡雅。看楚女、纤腰一把。箫鼓喧，人影参差，满路飘香麝」写风销蜡烛、露沾花灯，花市光相射，桂华流瓦、纤云散、素娥欲下，衣裳淡雅、楚女纤腰，箫鼓喧、人影参差、满路飘香麝，以元宵夜景的繁华写节日的热闹；下片「因念都城放夜。望千门如昼，嬉笑游冶。钿车罗帕。相逢处，自有暗尘随马。年光是也。唯只见、旧情衰谢。清漏移，飞盖归来，从舞休歌罢」写因念都城放夜、千门如昼、嬉笑游冶，钿车罗帕、相逢处暗尘随马，年光是也、旧情衰谢，清漏移、飞盖归来、从舞休歌罢，以元宵的繁华反衬旧情的衰谢，全词意境繁华、情感深沉，是咏元宵的名篇。","b":"周邦彦这首《解语花》写元宵节的盛况，以「桂华流瓦」「人影参差」写元宵夜景，是咏元宵的名篇。","n":["解语花：词牌名（周邦彦自度曲）","风销焰蜡：风消蜡烛的焰","露浥烘炉：露沾湿了烘炉（指花灯）。浥音yì，沾湿","花市光相射：花市的灯光相互照射","桂华流瓦：月光流洒在瓦上。桂华，月光（传说月中有桂）","纤云散：纤云散去","耿耿素娥欲下：明亮的嫦娥想下来。素娥，嫦娥","楚女纤腰一把：楚女的纤腰一把（形容腰细）","箫鼓喧：箫鼓喧闹","人影参差：人影参差不齐","满路飘香麝：满路飘香麝香","都城放夜：都城开放夜市（元宵夜开宵禁）","千门如昼：千门如白昼","嬉笑游冶：嬉笑游乐","钿车罗帕：饰金的车、罗帕","相逢处：相逢的地方","自有暗尘随马：自有暗尘随马（苏味道「暗尘随马去」）","年光是也：年光还是这样","旧情衰谢：旧情衰谢","清漏移：清漏移动（指时间流逝）","飞盖归来：飞车归来。盖，车盖，代指车","从舞休歌罢：任舞休歌罢"],"m":"桂华流瓦。纤云散，耿耿素娥欲下。","r":"按「风销焰蜡—露浥烘炉—花市光射—桂华流瓦—纤云散—素娥欲下—衣裳淡雅—楚女纤腰—箫鼓喧—人影参差—满路香麝—都城放夜—千门如昼—嬉笑游冶—钿车罗帕—暗尘随马—年光旧情—清漏飞盖—从舞休歌」背；「浥」读yì；以繁华反衬衰谢是核心。"},"花犯|周邦彦":{"s":"上片「粉墙低，梅花照眼，依然旧风味。露痕轻缀。疑净洗铅华，无限佳丽。去年胜赏曾孤倚。冰盘同宴喜。更可惜，雪中高树，香篝熏素被」写粉墙低、梅花照眼、依然旧风味，露痕轻缀、净洗铅华、无限佳丽，去年胜赏曾孤倚、冰盘同宴喜，更可惜雪中高树、香篝熏素被，以去年赏梅的回忆写梅花的美丽；下片「今年对花最匆匆，相逢似有恨，依依愁悴。吟望久，青苔上、旋看飞坠。相将见、脆丸荐酒，人正在、空江烟浪里。但梦想、一枝潇洒，黄昏斜照水」写今年对花最匆匆、相逢似有恨、依依愁悴，吟望久、青苔上旋看飞坠，相将见脆丸荐酒、人正在空江烟浪里，但梦想一枝潇洒、黄昏斜照水，以今年的匆匆与去年的从容对比，以梅花的飞坠写人生的漂泊，全词时间结构精巧、咏物写情，是咏物词的名篇。","b":"周邦彦这首《花犯》是咏梅词，以梅花的开落写人生的漂泊，「去年」「今年」「相将见」的时间结构是其特色，是咏物词的名篇。","n":["花犯：词牌名（周邦彦自度曲）","粉墙低：粉墙低","梅花照眼：梅花照眼","依然旧风味：依然是旧日的风味","露痕轻缀：露痕轻轻点缀","疑净洗铅华：怀疑是净洗了铅华（铅华，化妆品）","无限佳丽：无限佳丽","去年胜赏曾孤倚：去年赏梅时曾独自倚靠","冰盘同宴喜：冰盘同宴喜（冰盘里的梅子）","雪中高树：雪中的高树","香篝熏素被：香篝熏着素被（以香篝喻梅香、素被喻雪）。篝音gōu，竹笼","今年对花最匆匆：今年对花最匆匆","相逢似有恨：相逢似有恨","依依愁悴：依依愁悴","吟望久：吟诗望久","青苔上、旋看飞坠：青苔上很快看到梅花飞坠","相将见、脆丸荐酒：将看到脆丸（梅子）下酒","人正在、空江烟浪里：人正在空江烟浪里","但梦想、一枝潇洒：只梦想一枝潇洒的梅花","黄昏斜照水：黄昏时斜照在水上"],"m":"今年对花最匆匆，相逢似有恨，依依愁悴。","r":"按「粉墙低—梅花照眼—旧风味—露痕轻缀—净洗铅华—去年胜赏—孤倚冰盘—雪中高树—香篝素被—今年匆匆—相逢有恨—依依愁悴—吟望久—青苔飞坠—脆丸荐酒—空江烟浪—梦想一枝—黄昏照水」背；「篝」读gōu；去年/今年/将来的时间结构是核心特色。"},"六丑|周邦彦":{"s":"上片「正单衣试酒，恨客里、光阴虚掷。愿春暂留，春归如过翼。一去无迹。为问花何在，夜来风雨，葬楚宫倾国。钗钿堕处遗香泽。乱点桃蹊，轻翻柳陌。多情为谁追惜。但蜂媒蝶使，时叩窗隔」写单衣试酒、恨客里光阴虚掷，愿春暂留、春归如飞鸟过、一去无迹，问花何在、夜来风雨葬楚宫倾国，钗钿堕处遗香泽，乱点桃蹊、轻翻柳陌，多情为谁追惜，但蜂媒蝶使时叩窗，以落花的飘零写春归的惋惜；下片「东园岑寂。渐蒙笼暗碧。静绕珍丛底，成叹息。长条故惹行客。似牵衣待话，别情无极。残英小、强簪巾帻。终不似一朵，钗头颤袅，向人敧侧。漂流处、莫趁潮汐。恐断红、尚有相思字，何由见得」写东园岑寂、蒙笼暗碧，静绕花丛成叹息，长条惹行客、似牵衣待话、别情无极，残英小强簪巾帻、终不似钗头颤袅，漂流处莫趁潮汐、恐断红尚有相思字、何由见得，以落花的漂流写相思的无望，全词咏物写情、用典丰富（楚宫倾国、红叶题诗）、格律精严，是周邦彦词的代表作。","b":"周邦彦这首《六丑》是咏落花词，以落花的漂流写人生的漂泊与相思，用典丰富、格律精严，是周邦彦词的代表作，也是宋词中最长的词调之一。","n":["六丑：词牌名（周邦彦自度曲）","正单衣试酒：正是单衣试酒的时候","恨客里、光阴虚掷：恨在客里光阴虚掷","愿春暂留：愿春天暂时留下","春归如过翼：春归如飞鸟过","一去无迹：一去无痕迹","为问花何在：问花在哪里","夜来风雨：夜来风雨","葬楚宫倾国：埋葬了楚宫的倾国美人（喻花）","钗钿堕处遗香泽：钗钿坠落处遗下香泽（喻花落）","乱点桃蹊：乱点在桃树下的小路","轻翻柳陌：轻翻在柳下的小路","多情为谁追惜：多情为谁追惜","但蜂媒蝶使：只有蜂媒蝶使","时叩窗隔：不时叩窗","东园岑寂：东园寂静","渐蒙笼暗碧：渐渐笼罩在暗绿中","静绕珍丛底：静静绕着花丛","成叹息：成叹息","长条故惹行客：长条故意惹行人","似牵衣待话：似牵衣待话","别情无极：别情无限","残英小、强簪巾帻：残花小、勉强插在头巾上。巾帻，头巾","终不似一朵：终究不像一朵","钗头颤袅：在钗头颤动","向人敧侧：向人倾斜","漂流处、莫趁潮汐：漂流处不要趁潮汐","恐断红、尚有相思字：恐怕断红（落花）上还有相思字（红叶题诗典故）","何由见得：怎么能见到呢"],"m":"愿春暂留，春归如过翼。一去无迹。","r":"按「单衣试酒—客里虚掷—愿春暂留—春归过翼—一去无迹—问花何在—夜来风雨—葬楚宫倾国—钗钿遗香—乱点桃蹊—轻翻柳陌—为谁追惜—蜂媒蝶使—叩窗—东园岑寂—蒙笼暗碧—静绕珍丛—成叹息—长条惹客—牵衣待话—别情无极—残英簪巾—不似钗头—漂流莫趁潮—恐断红有字—何由见得」背；「帻」读zé、「敧」读qī；用典（楚宫倾国喻花、红叶题诗）；咏落花写相思是核心。"},"兰陵王|周邦彦":{"s":"第一段「柳阴直。烟里丝丝弄碧。隋堤上、曾见几番，拂水飘绵送行色。登临望故国。谁识。京华倦客。长亭路，年去岁来，应折柔条过千尺」写柳阴直、烟里丝丝弄碧，隋堤上曾见几番拂水飘绵送行色，登临望故国、谁识京华倦客，长亭路年去年来、应折柔条过千尺，以柳写离别；第二段「闲寻旧踪迹。又酒趁哀弦，灯照离席。梨花榆火催寒食。愁一箭风快，半篙波暖，回头迢递便数驿。望人在天北」写闲寻旧踪迹，又酒趁哀弦、灯照离席，梨花榆火催寒食，愁一箭风快、半篙波暖，回头迢递便数驿、望人在天北，写饯别与船行；第三段「凄恻。恨堆积。渐别浦萦回，津堠岑寂。斜阳冉冉春无极。念月榭携手，露桥闻笛。沈思前事，似梦里，泪暗滴」写凄恻恨堆积，别浦萦回、津堠岑寂，斜阳冉冉春无极，念月榭携手、露桥闻笛，沉思前事似梦里、泪暗滴，写别后的思念，全词三段结构、以柳写离、格律精严，是周邦彦词的代表作，「柳阴直，烟里丝丝弄碧」成为名句。","b":"周邦彦这首《兰陵王》是写柳的千古名篇，以柳写离别，「柳阴直，烟里丝丝弄碧」开篇，三段结构（咏柳、饯别、别后），是周邦彦词的代表作，据说宋徽宗因此词召周邦彦回京。","n":["兰陵王：词牌名","柳阴直：柳阴笔直（指隋堤上的柳树）","烟里丝丝弄碧：烟里丝丝柳条弄碧","隋堤上、曾见几番：隋堤上曾见过几番","拂水飘绵送行色：拂水飘绵送行色","登临望故国：登临望故乡","谁识：谁认识","京华倦客：京城的倦客","长亭路，年去岁来：长亭路上年去年来","应折柔条过千尺：应该折过的柔条超过千尺","闲寻旧踪迹：闲寻旧踪迹","又酒趁哀弦：又酒趁着哀弦","灯照离席：灯照离席","梨花榆火催寒食：梨花榆火催寒食（寒食节）","愁一箭风快：愁一箭风快（船行快）","半篙波暖：半篙波暖","回头迢递便数驿：回头迢递便过了数驿","望人在天北：望人在天北","凄恻：凄恻","恨堆积：恨堆积","渐别浦萦回：渐渐别浦萦回","津堠岑寂：渡口的土堡寂静。堠音hòu，土堡","斜阳冉冉春无极：斜阳冉冉春无极","念月榭携手：念月榭携手","露桥闻笛：露桥闻笛","沈思前事：沉思前事。沈同「沉」","似梦里：似梦里","泪暗滴：泪暗滴"],"m":"柳阴直。烟里丝丝弄碧。隋堤上、曾见几番，拂水飘绵送行色。","r":"按「柳阴直—丝丝弄碧—隋堤—拂水飘绵—送行色—望故国—京华倦客—长亭路—折柔条—闲寻旧踪—酒趁哀弦—灯照离席—梨花榆火—催寒食—一箭风快—半篙波暖—回头数驿—望人天北—凄恻恨积—别浦萦回—津堠岑寂—斜阳春无极—月榭携手—露桥闻笛—沉思前事—似梦里—泪暗滴」背；「堠」读hòu、「沈」同沉；三段结构（咏柳/饯别/别后）是核心特色。"},"72792:西河|周邦彦":{"s":"第一段「佳丽地。南朝盛事谁记。山围故国绕清江，髻鬟对起。怒涛寂寞打孤城，风樯遥度天际」写佳丽地、南朝盛事谁记，山围故国绕清江、髻鬟对起，怒涛寂寞打孤城、风樯遥度天际，化用刘禹锡《石头城》诗意；第二段「断崖树，犹倒倚。莫愁艇子曾系。空余旧迹郁苍苍，雾沈半垒。夜深月过女墙来，赏心东望淮水」写断崖树犹倒倚，莫愁艇子曾系，空余旧迹郁苍苍、雾沉半垒，夜深月过女墙来、赏心东望淮水，继续写金陵古迹；第三段「酒旗戏鼓甚处市。想依稀、王谢邻里。燕子不知何世。入寻常、巷陌人家，相对如说兴亡，斜阳里」写酒旗戏鼓甚处市，想依稀王谢邻里，燕子不知何世、入寻常巷陌人家、相对如说兴亡、斜阳里，化用刘禹锡《乌衣巷》诗意，以燕子写兴亡之感，全词化用唐诗、意境苍凉，是宋词中怀古的名篇，「相对如说兴亡，斜阳里」成为名句。","b":"周邦彦这首《西河》是金陵怀古词，化用刘禹锡《石头城》《乌衣巷》的诗意，以「燕子不知何世，入寻常、巷陌人家，相对如说兴亡，斜阳里」写兴亡之感，是宋词中怀古的名篇。","n":["西河：词牌名","佳丽地：佳丽的地方（指金陵，谢朓「江南佳丽地」）","南朝盛事谁记：南朝的盛事谁记得","山围故国绕清江：山围着故国绕着清江（刘禹锡「山围故国周遭在」）","髻鬟对起：发髻般的山峰相对而起","怒涛寂寞打孤城：怒涛寂寞地打着孤城（刘禹锡「潮打空城寂寞回」）","风樯遥度天际：风中的船帆遥度天际","断崖树，犹倒倚：断崖上的树还倒倚着","莫愁艇子曾系：莫愁的小艇曾系在这里","空余旧迹郁苍苍：空余旧迹郁郁苍苍","雾沈半垒：雾沉了半壁堡垒。沈同「沉」","夜深月过女墙来：夜深月过女墙（城墙上的矮墙）来","赏心东望淮水：赏心亭东望淮水（秦淮河）","酒旗戏鼓甚处市：酒旗戏鼓是哪里的街市","想依稀、王谢邻里：想依稀是王谢的邻里（王导、谢安，东晋豪门）","燕子不知何世：燕子不知什么世代","入寻常、巷陌人家：飞入寻常巷陌人家（刘禹锡「旧时王谢前堂燕，飞入寻常百姓家」）","相对如说兴亡：相对如说兴亡","斜阳里：在斜阳里"],"m":"燕子不知何世。入寻常、巷陌人家，相对如说兴亡，斜阳里。","r":"按「佳丽地—南朝盛事—山围故国—髻鬟对起—怒涛打孤城—风樯天际—断崖树—倒倚—莫愁艇子—旧迹苍苍—雾沉半垒—月过女墙—赏心淮水—酒旗戏鼓—王谢邻里—燕子不知世—入寻常巷陌—如说兴亡—斜阳里」背；「沈」同沉；化用刘禹锡《石头城》《乌衣巷》是核心特色。"},"72822:玉楼春|周邦彦":{"s":"上片「桃溪不作从容住。秋藕绝来无续处。当时相候赤栏桥，今日独寻黄叶路」写桃溪不能从容住、秋藕断了无续处，当时相候赤栏桥、今日独寻黄叶路，以「桃溪」「秋藕」的典故与比喻写离别，以「当时」与「今日」对比；下片「烟中列岫青无数。雁背夕阳红欲暮。人如风后入江云，情似雨余黏地絮」写烟中列岫青无数、雁背夕阳红欲暮，人如风后入江云、情似雨后黏地絮，以「风后入江云」写人的飘忽、以「雨余黏地絮」写情的黏着，比喻新奇、对仗工稳，全词意境苍凉、情感深沉，「人如风后入江云，情似雨余黏地絮」成为名句。","b":"周邦彦这首《玉楼春》写离别后的思念，以「人如风后入江云，情似雨余黏地絮」的比喻写情，是周邦彦词的名篇。","n":["玉楼春：词牌名","桃溪不作从容住：桃溪（刘晨阮肇遇仙处）不能从容居住","秋藕绝来无续处：秋藕断了没有续接的地方","当时相候赤栏桥：当时在赤栏桥等候","今日独寻黄叶路：今日独自寻黄叶路","烟中列岫青无数：烟中排列的山峰青无数。岫音xiù，山峰","雁背夕阳红欲暮：雁背的夕阳红欲暮","人如风后入江云：人如风后入江的云（飘忽不定）","情似雨余黏地絮：情如雨后黏地的柳絮（黏着难舍）"],"m":"人如风后入江云，情似雨余黏地絮。","r":"按「桃溪不从容—秋藕无续处—当时赤栏桥—今日黄叶路—烟中列岫—雁背夕阳—人如江云—情似黏絮」背；「岫」读xiù；用典（刘晨阮肇桃溪遇仙）；比喻新奇是核心。"},"夜飞鹊・夜飞鹊慢|周邦彦":{"s":"上片「河桥送人处，凉夜何其。斜月远堕余辉。铜盘烛泪已流尽，霏霏凉露沾衣。相将散离会，探风前津鼓，树杪参旗。华骢会意，纵扬鞭、亦自行迟」写河桥送人处、凉夜如何，斜月堕余辉，铜盘烛泪尽、凉露沾衣，相将散离会、探风前津鼓、树梢参旗，华骝会意、纵扬鞭亦自行迟，以送别之夜的凄凉写离情；下片「迢递路回清野，人语渐无闻，空带愁归。何意重红满地，遗钿不见，斜径都迷。兔葵燕麦，向残阳、欲与人齐。但徘徊班草，欷歔酹酒，极望天西」写迢递路回清野、人语渐无闻、空带愁归，何意重红满地、遗钿不见、斜径都迷，兔葵燕麦向残阳欲与人齐，但徘徊班草、欷歔酹酒、极望天西，以重游故地的荒凉写物是人非，「兔葵燕麦，向残阳、欲与人齐」化用刘禹锡诗意，全词意境苍凉、情感深沉，是周邦彦词的名篇。","b":"周邦彦这首《夜飞鹊》写送别后的重游故地，以「兔葵燕麦，向残阳、欲与人齐」写故地的荒凉，是周邦彦词的名篇。","n":["夜飞鹊：词牌名（周邦彦自度曲）","河桥送人处：河桥送人的地方","凉夜何其：凉夜如何（《诗经》「夜如何其」）","斜月远堕余辉：斜月远远坠落余辉","铜盘烛泪已流尽：铜盘的烛泪已流尽","霏霏凉露沾衣：霏霏凉露沾衣","相将散离会：相将散离会","探风前津鼓：探听风前的渡口更鼓","树杪参旗：树梢上的参星旗星（天将亮）","华骢会意：华骝（骏马）会意","纵扬鞭、亦自行迟：纵然扬鞭也自行迟","迢递路回清野：迢递的路回清野","人语渐无闻：人语渐渐听不到了","空带愁归：空带愁归","何意重红满地：何意重红满地（花又开了）","遗钿不见：遗落的钗钿不见了","斜径都迷：斜径都迷了","兔葵燕麦：兔葵燕麦（刘禹锡「兔葵燕麦，动摇春风」，指荒凉）","向残阳、欲与人齐：向残阳欲与人齐（长得和人一样高）","但徘徊班草：但徘徊在班草（铺草而坐）处","欷歔酹酒：欷歔（叹息）洒酒祭奠。欷歔音xīxū","极望天西：极望天西"],"m":"兔葵燕麦，向残阳、欲与人齐。","r":"按「河桥送人—凉夜何其—斜月余辉—铜盘烛泪—凉露沾衣—散离会—风前津鼓—树梢参旗—华骢会意—扬鞭行迟—迢递路回—人语无闻—空带愁归—重红满地—遗钿不见—斜径都迷—兔葵燕麦—残阳人齐—徘徊班草—欷歔酹酒—极望天西」背；「欷歔」读xīxū；用典（《诗经》夜如何其、刘禹锡兔葵燕麦）；送别与重游对比是核心。"},"62028:点绛唇|姜夔":{"s":"上片「燕雁无心，太湖西畔随云去。数峰清苦。商略黄昏雨」写燕雁无心、太湖西畔随云去，数峰清苦、商量着黄昏的雨，以「清苦」「商略」的拟人手法写山，想象奇特；下片「第四桥边，拟共天随住。今何许。凭栏怀古。残柳参差舞」写第四桥边、拟共天随子同住，今何许、凭栏怀古、残柳参差舞，以陆龟蒙（天随子）的典故写归隐之志，以「残柳参差舞」写怀古的苍凉，全词意境清远、拟人巧妙，「数峰清苦，商略黄昏雨」成为名句，是姜夔词的名篇。","b":"姜夔（南宋词人，「格律派」代表，号白石道人）这首《点绛唇》写在苏州吴江的所见所感，以「数峰清苦，商略黄昏雨」的拟人手法写山，是姜夔词的名篇。","n":["点绛唇：词牌名","燕雁无心：燕雁（北方的雁）无心","太湖西畔随云去：太湖西畔随云去","数峰清苦：几座山峰清苦","商略黄昏雨：商量着黄昏的雨（拟人，山峰像在商量要下雨）","第四桥边：第四桥边（在苏州吴江）","拟共天随住：打算和天随子（陆龟蒙，号天随子，隐居吴江）同住","今何许：如今在哪里","凭栏怀古：凭栏怀古","残柳参差舞：残柳参差不齐地飞舞"],"m":"数峰清苦。商略黄昏雨。","r":"按「燕雁无心—太湖随云—数峰清苦—商略黄昏雨—第四桥—天随住—今何许—凭栏怀古—残柳参差舞」背；用典（陆龟蒙号天随子）；拟人手法（数峰商略雨）是核心特色。"},"62039:鹧鸪天|姜夔":{"s":"上片「肥水东流无尽期。当初不合种相思。梦中未比丹青见，暗里忽惊山鸟啼」写肥水东流无尽期、当初不该种相思，梦中相见不如画像清楚、暗中被山鸟啼惊醒，以「肥水东流」写相思的无尽、以「梦中」写思念的深切；下片「春未绿，鬓先丝。人间别久不成悲。谁教岁岁红莲夜，两处沈吟各自知」写春未绿鬓先丝，人间别久不成悲，谁教年年红莲夜、两地沉吟各自知，以「别久不成悲」写离别的深沉——不是不悲，而是悲到深处已麻木，以「红莲夜」的团圆反衬两地的分离，全词情感深沉、意境凄清，「人间别久不成悲」成为名句，是姜夔词的名篇。","b":"姜夔这首《鹧鸪天》写元宵夜思念旧日情人（在合肥相遇的歌女），以「人间别久不成悲」写离别的深沉，是姜夔词的名篇。","n":["鹧鸪天：词牌名","肥水东流无尽期：肥水（在安徽，姜夔曾在此与情人相遇）东流无尽期","当初不合种相思：当初不该种下相思","梦中未比丹青见：梦中相见不如画像中看得清楚。丹青，画像","暗里忽惊山鸟啼：暗中忽然被山鸟啼惊醒","春未绿，鬓先丝：春还没绿、鬓先白了","人间别久不成悲：人间离别久了就不觉得悲了","谁教岁岁红莲夜：谁让年年红莲夜（灯节，元宵）","两处沈吟各自知：两地沉吟各自知道。沈同「沉」"],"m":"人间别久不成悲。","r":"按「肥水东流—不合种相思—梦中丹青—暗里惊鸟—春未绿—鬓先丝—别久不成悲—岁岁红莲夜—两处沉吟」背；「沈」同沉；「别久不成悲」的反语是核心；合肥情事是背景。"},"齐天乐|姜夔":{"s":"上片「庾郎先自吟愁赋。凄凄更闻私语。露湿铜铺，苔侵石井，都是曾听伊处。哀音似诉。正思妇无眠，起寻机杼。曲曲屏山，夜凉独自甚情绪」写庾信先吟愁赋、凄凄更闻私语（蟋蟀叫），露湿铜铺、苔侵石井、都是曾听它处，哀音似诉，思妇无眠起寻机杼，曲曲屏山、夜凉独自甚情绪，以蟋蟀声写思妇的愁；下片「西窗又吹暗雨。为谁频断续，相和砧杵。候馆迎秋，离宫吊月，别有伤心无数。豳诗漫与。笑篱落呼灯，世间儿女。写入琴丝，一声声更苦」写西窗又吹暗雨，为谁频断续、相和砧杵，候馆迎秋、离宫吊月、别有伤心无数，豳诗漫与，笑篱落呼灯、世间儿女，写入琴丝、一声声更苦，以蟋蟀声写各种人的愁，全词咏物写情、用典丰富（庾信愁赋、《诗经·豳风》）、格律精严，是咏物词的千古名篇。","b":"姜夔这首《齐天乐》是咏蟋蟀词，以蟋蟀的叫声写各种人的愁思，「庾郎先自吟愁赋，凄凄更闻私语」开篇，是咏物词的千古名篇，张炎评为「全章精粹，所咏了然在目，且不留滞于物」。","n":["齐天乐：词牌名","庾郎先自吟愁赋：庾郎（庾信，作《愁赋》）先自吟愁赋","凄凄更闻私语：凄凄地更听到私语（蟋蟀的叫声）","露湿铜铺：露湿了铜铺（门上的铜环底座）","苔侵石井：苔藓侵了石井","都是曾听伊处：都是曾听它（蟋蟀）叫的地方","哀音似诉：哀音似在诉说","正思妇无眠：正是思妇无眠时","起寻机杼：起来找机杼（织布）","曲曲屏山：曲曲的屏山（屏风上的山）","夜凉独自甚情绪：夜凉独自什么情绪","西窗又吹暗雨：西窗又吹暗雨","为谁频断续：为谁频频断续","相和砧杵：和着砧杵声（捣衣声）","候馆迎秋：旅馆迎秋","离宫吊月：离宫（行宫）对月","别有伤心无数：别有伤心无数","豳诗漫与：《诗经·豳风》随意写来（《豳风·七月》有「十月蟋蟀入我床下」）","笑篱落呼灯：笑篱笆边呼灯（儿童捉蟋蟀）","世间儿女：世间的儿女","写入琴丝：写入琴丝（琴曲）","一声声更苦：一声声更苦"],"m":"哀音似诉。正思妇无眠，起寻机杼。","r":"按「庾郎愁赋—凄凄私语—露湿铜铺—苔侵石井—曾听伊处—哀音似诉—思妇无眠—起寻机杼—曲曲屏山—夜凉情绪—西窗暗雨—频断续—相和砧杵—候馆迎秋—离宫吊月—伤心无数—豳诗漫与—篱落呼灯—世间儿女—写入琴丝—一声声苦」背；用典（庾信《愁赋》、《诗经·豳风·七月》蟋蟀）；以蟋蟀声写各种人愁是核心。"},"琵琶仙・自度曲|姜夔":{"s":"上片「双桨来时，有人似、旧曲桃根桃叶。歌扇轻约飞花，蛾眉正奇绝。春渐远、汀洲自绿，更添了、几声啼鴂。十里扬州，三生杜牧，前事休说」写双桨来时、有人像桃根桃叶，歌扇轻约飞花、蛾眉正奇绝，春渐远汀洲自绿、更添几声啼鴂，十里扬州、三生杜牧、前事休说，以看到类似旧情人的女子触发相思；下片「又还是、宫烛分烟，奈愁里、匆匆换时节。都把一襟芳思，与空阶榆荚。千万缕、藏鸦细柳，为玉尊、起舞回雪。想见西出阳关，故人初别」写又还是宫烛分烟、奈愁里匆匆换时节，都把一襟芳思给空阶榆荚，千万缕藏鸦细柳、为玉尊起舞回雪，想见西出阳关、故人初别，以寒食节的景色与典故写离情，全词用典丰富（桃根桃叶、杜牧扬州、韩翃寒食、王维阳关）、意境凄清，是姜夔词的名篇。","b":"姜夔这首《琵琶仙》是在吴兴游历时，看到双桨画船中的女子像旧日情人，触发相思而作，用典丰富（桃根桃叶、杜牧、韩翃、王维），是姜夔词的名篇。","n":["琵琶仙：词牌名（姜夔自度曲）","双桨来时：双桨划来时","有人似、旧曲桃根桃叶：有人像旧曲中的桃根桃叶（桃叶，王献之的爱妾；桃根，桃叶的妹妹）","歌扇轻约飞花：歌扇轻轻拦住飞花","蛾眉正奇绝：蛾眉正奇绝","春渐远、汀洲自绿：春渐远、汀洲自绿","更添了、几声啼鴂：更添了几声啼鴂（杜鹃鸟）。鴂音jué","十里扬州：十里扬州（杜牧「春风十里扬州路」）","三生杜牧：三生杜牧（杜牧的前世今生，指自己像杜牧）","前事休说：前事休说","又还是、宫烛分烟：又还是宫烛分烟（寒食节，韩翃「日暮汉宫传蜡烛」）","奈愁里、匆匆换时节：奈何愁里匆匆换了时节","都把一襟芳思：都把一襟芳思","与空阶榆荚：给空阶的榆荚","千万缕、藏鸦细柳：千万缕藏鸦的细柳","为玉尊、起舞回雪：为玉尊起舞回雪（柳絮如雪）","想见西出阳关：想见西出阳关（王维「西出阳关无故人」）","故人初别：故人初别时"],"m":"十里扬州，三生杜牧，前事休说。","r":"按「双桨来时—似桃根桃叶—歌扇飞花—蛾眉奇绝—春渐远—汀洲绿—啼鴂—十里扬州—三生杜牧—前事休说—宫烛分烟—愁里换节—一襟芳思—空阶榆荚—藏鸦细柳—起舞回雪—西出阳关—故人初别」背；「鴂」读jué；用典（桃根桃叶、杜牧、韩翃寒食、王维阳关）；由类似旧情人的女子触发相思是核心。"},"扬州慢|姜夔":{"s":"上片「淮左名都，竹西佳处，解鞍少驻初程。过春风十里，尽荠麦青青。自胡马窥江去后，废池乔木，犹厌言兵。渐黄昏，清角吹寒，都在空城」写淮左名都、竹西佳处、解鞍少驻，过春风十里、尽荠麦青青，自胡马窥江去后、废池乔木、犹厌言兵，渐黄昏、清角吹寒、都在空城，以扬州昔日的繁华与今日的荒凉对比，以「犹厌言兵」写战争的残酷；下片「杜郎俊赏，算而今，重到须惊。纵豆蔻词工，青楼梦好，难赋深情。二十四桥仍在，波心荡、冷月无声。念桥边红药，年年知为谁生」写杜牧俊赏、算如今重到须惊，纵豆蔻词工、青楼梦好、难赋深情，二十四桥仍在、波心荡冷月无声，念桥边红药、年年知为谁生，以杜牧的典故与二十四桥的冷月写今昔之感，全词用典丰富（杜牧诗句多处）、对比鲜明、情感沉痛，是南宋爱国词的千古名篇，「二十四桥仍在，波心荡、冷月无声」成为千古名句。","b":"姜夔这首《扬州慢》是他22岁时路过扬州，看到扬州在金兵南侵后的荒凉景象而作，是南宋爱国词的千古名篇，「自胡马窥江去后，废池乔木，犹厌言兵」「二十四桥仍在，波心荡、冷月无声」成为千古名句。","n":["扬州慢：词牌名（姜夔自度曲）","淮左名都：淮左（淮南东路）的名都（指扬州）","竹西佳处：竹西亭的佳处（竹西亭在扬州，杜牧「谁知竹西路，歌吹是扬州」）","解鞍少驻初程：解鞍稍停初程","过春风十里：过春风十里（杜牧「春风十里扬州路」）","尽荠麦青青：全是荠麦青青","自胡马窥江去后：自从金兵窥江（指1161年金主完颜亮南侵）去后","废池乔木：废池乔木","犹厌言兵：还厌恶说起战争","渐黄昏：渐渐黄昏","清角吹寒：清角吹寒（号角声吹出寒意）","都在空城：都在空城","杜郎俊赏：杜牧的俊赏（杜牧善于赏玩）","算而今、重到须惊：算如今重到也会吃惊","纵豆蔻词工：纵然豆蔻词工（杜牧「豆蔻梢头二月初」）","青楼梦好：青楼梦好（杜牧「十年一觉扬州梦，赢得青楼薄幸名」）","难赋深情：难赋深情","二十四桥仍在：二十四桥仍在（杜牧「二十四桥明月夜」）","波心荡、冷月无声：波心荡漾、冷月无声","念桥边红药：念桥边的红芍药","年年知为谁生：年年知道为谁开"],"m":"自胡马窥江去后，废池乔木，犹厌言兵。二十四桥仍在，波心荡、冷月无声。","r":"按「淮左名都—竹西佳处—解鞍少驻—春风十里—荠麦青青—胡马窥江—废池乔木—犹厌言兵—黄昏清角—都在空城—杜郎俊赏—重到须惊—豆蔻词工—青楼梦好—难赋深情—二十四桥—波心冷月—桥边红药—年年为谁生」背；用典（杜牧诗句：春风十里、豆蔻、青楼梦、二十四桥、竹西亭）；今昔对比与爱国主题是核心。"},"长亭怨慢|姜夔":{"s":"上片「渐吹尽、枝头香絮。是处人家，绿深门户。远浦萦回，暮帆零乱向何许。阅人多矣，谁得似、长亭树。树若有情时，不会得、青青如此」写渐吹尽柳絮，是处人家绿深门户，远浦萦回、暮帆零乱向何许，阅人多矣、谁得似长亭树，树若有情时、不会青青如此，以长亭树的「青青如此」反衬人的离别之痛；下片「日暮。望高城不见，只见乱山无数。韦郎去也，怎忘得、玉环分付。第一是、早早归来，怕红萼、无人为主。算空有并刀，难翦离愁千缕」写日暮望高城不见、只见乱山无数，韦郎去也、怎忘玉环分付，第一是早早归来、怕红萼无人为主，算空有并刀、难剪离愁千缕，以韦皋玉箫的典故写离别之约，以「并刀难剪离愁」写离愁的深，全词拟人巧妙、用典贴切、情感深沉，「树若有情时，不会得、青青如此」成为名句。","b":"姜夔这首《长亭怨慢》写离别，以「树若有情时，不会得、青青如此」的拟人写树的无情反衬人的有情，用韦皋与玉箫的典故写离别之约，是姜夔词的名篇。","n":["长亭怨慢：词牌名（姜夔自度曲）","渐吹尽、枝头香絮：渐渐吹尽枝头的柳絮","是处人家：到处的人家","绿深门户：绿深的门户","远浦萦回：远浦萦回","暮帆零乱向何许：暮帆零乱向何处","阅人多矣：经历的人多了","谁得似、长亭树：谁能像长亭的树","树若有情时：树如果有情时","不会得、青青如此：不会青青如此（不会这么无情地绿着）","日暮：日暮","望高城不见：望高城不见","只见乱山无数：只见乱山无数","韦郎去也：韦郎（韦皋，与玉箫的爱情故事）去了","怎忘得、玉环分付：怎能忘得了玉环的吩咐（韦皋与玉箫分别时留玉指环约定）","第一是、早早归来：第一是早早归来","怕红萼、无人为主：怕红萼（花，指情人）无人为主","算空有并刀：算空有并州剪刀","难翦离愁千缕：难剪离愁千缕"],"m":"树若有情时，不会得、青青如此。","r":"按「吹尽香絮—绿深门户—远浦萦回—暮帆零乱—阅人多—长亭树—树若有情—不会青青—日暮—望高城—乱山无数—韦郎去—玉环分付—早早归来—红萼无主—空有并刀—难剪离愁」背；「翦」同剪；用典（韦皋与玉箫玉环之约）；拟人（树若有情）是核心特色。"},"淡黄柳|姜夔":{"s":"上片「空城晓月。吹入垂杨陌。马上单衣寒恻恻。看尽鹅黄嫩绿，都是江南旧相识」写空城晓月、吹入垂杨陌，马上单衣寒恻恻，看尽鹅黄嫩绿、都是江南旧相识，以「空城」写合肥的荒凉、以「江南旧相识」写乡愁；下片「正岑寂。明朝又寒食。强携酒、小桥宅，怕梨花落尽成秋色。燕燕飞来，问春何在，唯有池塘自碧」写正岑寂、明朝又寒食，强携酒小桥宅、怕梨花落尽成秋色，燕燕飞来问春何在、唯有池塘自碧，以「怕梨花落尽」写惜春、以「唯有池塘自碧」写春去的空寂，全词意境凄清、情感深沉，「怕梨花落尽成秋色」成为名句，是姜夔词的名篇。","b":"姜夔这首《淡黄柳》写在合肥客居时的春景与乡愁，以「怕梨花落尽成秋色」写惜春之情，是姜夔词的名篇。","n":["淡黄柳：词牌名（姜夔自度曲）","空城晓月：空城的晓月","吹入垂杨陌：吹入垂杨路","马上单衣寒恻恻：马上单衣寒恻恻（寒冷）","看尽鹅黄嫩绿：看尽鹅黄嫩绿（初春的柳色）","都是江南旧相识：都是江南旧相识","正岑寂：正岑寂","明朝又寒食：明天又寒食","强携酒、小桥宅：勉强携酒到小桥宅","怕梨花落尽成秋色：怕梨花落尽成秋色","燕燕飞来：燕子飞来","问春何在：问春在哪里","唯有池塘自碧：只有池塘自碧"],"m":"怕梨花落尽成秋色。","r":"按「空城晓月—垂杨陌—单衣寒恻—鹅黄嫩绿—江南旧识—正岑寂—明朝寒食—强携酒—小桥宅—怕梨花落—成秋色—燕燕飞来—问春何在—池塘自碧」背；合肥客居与乡愁是背景；惜春之情是核心。"},"暗香|姜夔":{"s":"上片「旧时月色。算几番照我，梅边吹笛。唤起玉人，不管清寒与攀摘。何逊而今渐老，都忘却、春风词笔。但怪得、竹外疏花，香冷入瑶席」写旧时月色几番照我梅边吹笛，唤起玉人不顾清寒一同攀摘，何逊而今渐老忘却春风词笔，只怪竹外疏花香冷入瑶席，以回忆与现实对比写梅花的情思；下片「江国。正寂寂。叹寄与路遥，夜雪初积。翠尊易泣。红萼无言耿相忆。长记曾携手处，千树压、西湖寒碧。又片片、吹尽也，几时见得」写江国正寂寂，叹寄梅路遥、夜雪初积，翠尊易泣、红萼无言耿相忆，长记曾携手处千树压西湖寒碧，又片片吹尽、几时见得，以寄梅与西湖千树梅写离情，全词意境清空、用典贴切（何逊咏梅、陆凯寄梅），「旧时月色」开篇，是姜夔词的代表作，与《疏影》并称咏梅双璧。","b":"姜夔这首《暗香》是他咏梅的代表作，与《疏影》并称「暗香疏影」，为咏梅词的千古绝唱，是他应范成大之请而作，范成大赠以青衣小红。","n":["暗香：词牌名（姜夔自度曲，咏梅）","旧时月色：旧日的月色","算几番照我：算几番照过我","梅边吹笛：在梅边吹笛","唤起玉人：唤起美人","不管清寒与攀摘：不顾清寒一同攀摘梅花","何逊而今渐老：何逊（南朝梁诗人，有《咏早梅》诗）如今渐老","都忘却、春风词笔：都忘却了春风般的词笔","但怪得、竹外疏花：只怪竹外稀疏的梅花","香冷入瑶席：冷香飘入瑶席（宴席）","江国：江南水乡","叹寄与路遥：感叹寄梅路途遥远（陆凯寄梅范晔「聊赠一枝春」）","翠尊易泣：翠玉酒杯前容易落泪","红萼无言耿相忆：红花无言、耿耿相忆。耿，心中挂念","千树压、西湖寒碧：千树梅花压着西湖寒碧的水","又片片、吹尽也：又一片片被吹尽了","几时见得：何时能再见"],"m":"旧时月色。算几番照我，梅边吹笛。","r":"按「旧时月色—梅边吹笛—唤起玉人—攀摘—何逊渐老—忘却词笔—竹外疏花—香冷瑶席—江国寂寂—寄与路遥—夜雪初积—翠尊易泣—红萼相忆—携手处—千树西湖—片片吹尽—几时见得」背；用典（何逊咏梅、陆凯寄梅）；清空意境是核心。"},"疏影|姜夔":{"s":"上片「苔枝缀玉。有翠禽小小，枝上同宿。客里相逢，篱角黄昏，无言自倚修竹。昭君不惯胡沙远，但暗忆、江南江北。想佩环、月夜归来，化作此花幽独」写苔枝缀玉、翠禽同宿，客里相逢、篱角黄昏、无言自倚修竹，昭君不惯胡沙远、暗忆江南江北，想佩环月夜归来化作此花幽独，以昭君喻梅、以幽独写梅的品格；下片「犹记深宫旧事，那人正睡里，飞近蛾绿。莫似春风，不管盈盈，早与安排金屋。还教一片随波去，又却怨、玉龙哀曲。等恁时、重觅幽香，已入小窗横幅」写犹记深宫旧事、那人正睡、飞近蛾绿（梅花妆），莫似春风不管盈盈、早安排金屋，还教一片随波去、又怨玉龙哀曲，等那时重觅幽香、已入小窗横幅，用典丰富（寿阳公主梅花妆、金屋藏娇、玉龙吹梅），全词以梅写美人、以美人写家国，意境清空、用典精当，是咏梅词的千古绝唱。","b":"姜夔这首《疏影》与《暗香》并称「暗香疏影」，是咏梅词的千古绝唱，用典丰富（昭君、寿阳公主、金屋藏娇、玉龙吹梅），以梅写家国之思，张炎评为「前无古人，后无来者」。","n":["疏影：词牌名（姜夔自度曲，咏梅）","苔枝缀玉：苔枝（长苔藓的梅枝）上缀着玉（梅花）","翠禽小小：小小的翠鸟（用赵师雄罗浮山遇梅花女神故事，有翠禽啼）","客里相逢：在客中相逢","无言自倚修竹：无言独自倚着修竹（用杜甫「天寒翠袖薄，日暮倚修竹」写美人）","昭君不惯胡沙远：王昭君不习惯胡地风沙的遥远","但暗忆、江南江北：只暗忆江南江北","想佩环、月夜归来：想佩环（昭君的佩环）月夜归来（杜甫「环佩空归月夜魂」）","化作此花幽独：化作这梅花的幽独","深宫旧事：深宫旧事（用宋武帝女寿阳公主梅花落额上成梅花妆故事）","那人正睡里：那人正睡着","飞近蛾绿：飞近蛾绿（梅花妆，蛾绿指眉）","莫似春风：不要像春风","不管盈盈：不管盈盈（梅花的美好）","早与安排金屋：早早安排金屋（金屋藏娇，汉武帝「金屋藏娇」典故）","还教一片随波去：却让一片随波去","又却怨、玉龙哀曲：又怨玉龙（笛）的哀曲（玉龙，笛子；梅花落曲）","等恁时、重觅幽香：等那时重觅幽香","已入小窗横幅：已入小窗的横幅画中"],"m":"昭君不惯胡沙远，但暗忆、江南江北。想佩环、月夜归来，化作此花幽独。","r":"按「苔枝缀玉—翠禽同宿—客里相逢—篱角黄昏—自倚修竹—昭君胡沙—暗忆江南—佩环月夜—化作幽独—深宫旧事—那人睡—飞近蛾绿—莫似春风—安排金屋—一片随波—玉龙哀曲—重觅幽香—小窗横幅」背；用典（赵师雄罗浮遇梅、杜甫佳人、昭君、寿阳公主梅花妆、金屋藏娇、玉龙吹梅落）；以梅写家国之思是核心。"},"惜红衣|姜夔":{"s":"上片「簟枕邀凉，琴书换日，睡余无力。细洒冰泉，并刀破甘碧。墙头唤酒，谁问讯、城南诗客。岑寂。高柳晚蝉，说西风消息」写簟枕邀凉、琴书换日、睡余无力，细洒冰泉、并刀破甘碧，墙头唤酒、谁问讯城南诗客，岑寂，高柳晚蝉说西风消息，以夏日生活的细节写客居的岑寂；下片「虹粱水陌。鱼浪吹香，红衣半狼藉。维舟试望故国。眇天北。可惜渚边沙外，不共美人游历。问甚时同赋，三十六陂秋色」写虹粱水陌、鱼浪吹香、红衣半狼藉，维舟试望故国、眇天北，可惜渚边沙外不共美人游历，问甚时同赋三十六陂秋色，以荷花凋零与望故国写乡愁，全词意境清空、情感深沉，是姜夔词的名篇。","b":"姜夔这首《惜红衣》写在吴兴（今浙江湖州）客居时的夏日景色与乡愁，以「红衣半狼藉」写荷花凋零，是姜夔词的名篇。","n":["惜红衣：词牌名（姜夔自度曲）","簟枕邀凉：竹席枕头邀来清凉。簟音diàn","琴书换日：琴书打发日子","睡余无力：睡后无力","细洒冰泉：细洒冰泉","并刀破甘碧：并州剪刀破开甘碧（瓜）","墙头唤酒：墙头唤酒（杜甫「墙头过酒」）","谁问讯、城南诗客：谁问讯城南诗客（杜甫在城南）","高柳晚蝉：高柳上的晚蝉","说西风消息：说着西风的消息","虹粱水陌：虹粱（桥）水陌","鱼浪吹香：鱼浪吹香","红衣半狼藉：荷花（红衣）半狼藉","维舟试望故国：系船试望故乡","眇天北：遥远在天北","渚边沙外：渚边沙外","不共美人游历：不与美人一同游历","问甚时同赋：问何时同赋","三十六陂秋色：三十六陂（池塘）的秋色"],"m":"高柳晚蝉，说西风消息。","r":"按「簟枕邀凉—琴书换日—睡余无力—细洒冰泉—并刀破甘碧—墙头唤酒—城南诗客—岑寂—高柳晚蝉—西风消息—虹粱水陌—鱼浪吹香—红衣狼藉—维舟望故国—眇天北—渚边沙外—不共美人—同赋—三十六陂秋色」背；「簟」读diàn；用典（杜甫墙头过酒、城南诗客）；客居乡愁是核心。"},"翠楼吟|姜夔":{"s":"上片「月冷龙沙，尘轻虎落，今年汉酺初赐。新翻胡部曲，听毡幕、元戎歌吹。层楼高峙。看栏曲萦红，檐牙飞翠。人姝丽。粉香吹下，夜寒风细」写月冷龙沙、尘轻虎落、今年初赐酺，新翻胡部曲、听毡幕元戎歌吹，层楼高峙、栏曲萦红、檐牙飞翠，人姝丽、粉香吹下、夜寒风细，写安远楼的庆典盛况；下片「此地。宜有词仙，拥素云黄鹤，与君游戏。玉梯凝望久，叹芳草、萋萋千里。天涯情味。仗酒袯清愁，花销英气。西山外。晚来还卷，一帘秋霁」写此地宜有词仙、拥素云黄鹤与君游戏，玉梯凝望久、叹芳草萋萋千里，天涯情味、仗酒袯清愁、花销英气，西山外晚来还卷一帘秋霁，以黄鹤典故与芳草萋萋写天涯漂泊之感，全词意境开阔、用典贴切（崔颢黄鹤楼、《楚辞》芳草），是姜夔词的名篇。","b":"姜夔这首《翠楼吟》是他在武昌参加安远楼落成庆典时所作，写登楼所见与天涯漂泊之感，是姜夔词的名篇。","n":["翠楼吟：词牌名（姜夔自度曲）","月冷龙沙：月冷龙沙（龙沙，泛指塞外）","尘轻虎落：尘轻虎落（虎落，边塞的栅栏）","今年汉酺初赐：今年汉朝（指宋朝）初次赐酺（聚会饮酒）。酺音pú","新翻胡部曲：新翻的胡部乐曲","听毡幕、元戎歌吹：听毡幕中主将的歌吹。元戎，主将","层楼高峙：层楼高峙","栏曲萦红：栏曲萦绕红（栏杆的红）","檐牙飞翠：檐牙飞翠（屋檐的翠）","人姝丽：人美丽","粉香吹下：粉香吹下","夜寒风细：夜寒风细","此地宜有词仙：此地宜有词仙","拥素云黄鹤：拥素云黄鹤（用崔颢「黄鹤一去不复返」）","与君游戏：与君游戏","玉梯凝望久：玉梯凝望久","叹芳草、萋萋千里：叹芳草萋萋千里（用《楚辞》「王孙游兮不归，春草生兮萋萋」）","天涯情味：天涯情味","仗酒袯清愁：仗酒祓除清愁。袯音fú，祓除","花销英气：花销英气","西山外：西山外","晚来还卷：晚来还卷（帘）","一帘秋霁：一帘秋霁（雨后初晴）"],"m":"此地。宜有词仙，拥素云黄鹤，与君游戏。","r":"按「月冷龙沙—尘轻虎落—汉酺初赐—新翻胡曲—毡幕元戎—层楼高峙—栏曲檐牙—人姝丽—粉香—夜寒风细—宜有词仙—素云黄鹤—与君游戏—玉梯凝望—芳草萋萋—天涯情味—酒袯清愁—花销英气—西山外—一帘秋霁」背；「酺」读pú、「袯」读fú；用典（崔颢黄鹤楼、《楚辞》芳草）；天涯漂泊之感是核心。"},"玉楼春|宋祁":{"s":"上片「东城渐觉风光好。縠皱波纹迎客棹。绿杨烟外晓寒轻，红杏枝头春意闹」写东城风光好、波纹迎客棹，绿杨烟外晓寒轻、红杏枝头春意闹，以「闹」字写春天的生机，王国维评为「着一闹字而境界全出」；下片「浮生长恨欢娱少。肯爱千金轻一笑。为君持酒劝斜阳，且向花间留晚照」写浮生长恨欢娱少、肯爱千金轻一笑，为君持酒劝斜阳、且向花间留晚照，以「劝斜阳」「留晚照」写惜春之情，全词色彩明丽、「闹」字传神，是北宋词的名篇，「红杏枝头春意闹」成为千古名句。","b":"宋祁（北宋词人，官至工部尚书）这首《玉楼春》写游春的欢乐与惜春之情，「红杏枝头春意闹」是千古名句，宋祁因此被称为「红杏枝头春意闹尚书」。","n":["玉楼春：词牌名","东城渐觉风光好：东城渐渐觉得风光好","縠皱波纹迎客棹：绉纱般的波纹迎接客船。縠音hú，绉纱；棹音zhào，船桨代指船","绿杨烟外晓寒轻：绿杨烟外晓寒轻","红杏枝头春意闹：红杏枝头春意热闹（「闹」字是千古名句，王国维评为「着一闹字而境界全出」）","浮生长恨欢娱少：浮生常恨欢娱少","肯爱千金轻一笑：怎肯爱惜千金而轻视一笑","为君持酒劝斜阳：为君持酒劝斜阳","且向花间留晚照：且向花间留晚照"],"m":"绿杨烟外晓寒轻，红杏枝头春意闹。","r":"按「东城风光—縠皱波纹—绿杨晓寒—红杏闹—浮生欢娱—千金一笑—持酒劝斜阳—花间留晚照」背；「縠」读hú、「棹」读zhào；「闹」字是诗眼；惜春之情是核心。"},"小重山|岳飞":{"s":"上片「昨夜寒蛩不住鸣。惊回千里梦，已三更。起来独自绕阶行。人悄悄，帘外月胧明」写昨夜寒蛩不住鸣、惊醒千里梦已三更，起来独自绕阶行、人悄悄帘外月胧明，以寒蛩、残月、独行写失眠的苦闷；下片「白首为功名。旧山松竹老，阻归程。欲将心事付瑶琴。知音少，弦断有谁听」写白首为功名、旧山松竹老阻归程，欲将心事付瑶琴、知音少弦断有谁听，以「知音少，弦断有谁听」写抗金壮志难酬、知音难觅的苦闷，全词含蓄深沉、意境苍凉，与《满江红》的豪放形成对比，是南宋爱国词的名篇。","b":"岳飞（南宋抗金名将）这首《小重山》写抗金壮志难酬、知音难觅的苦闷，与他的《满江红》风格不同，以含蓄深沉见长，是南宋爱国词的名篇。","n":["小重山：词牌名","昨夜寒蛩不住鸣：昨夜寒蟋蟀不住鸣叫。蛩音qióng","惊回千里梦：惊醒了千里（杀敌）的梦","已三更：已三更","起来独自绕阶行：起来独自绕阶行","人悄悄：人悄悄","帘外月胧明：帘外月朦胧明亮","白首为功名：白首为功名","旧山松竹老：故乡的山松竹老了","阻归程：阻归程","欲将心事付瑶琴：想将心事付瑶琴","知音少：知音少","弦断有谁听：弦断了有谁听"],"m":"欲将心事付瑶琴。知音少，弦断有谁听。","r":"按「寒蛩不住—惊回千里梦—已三更—独自绕阶—人悄悄—月胧明—白首功名—旧山松竹—阻归程—心事付瑶琴—知音少—弦断谁听」背；「蛩」读qióng；以含蓄写壮志难酬是核心；与《满江红》对读。"},"75578:贺新郎|张元干":{"s":"上片「曳杖危楼去。斗垂天、沧波万顷，月流烟渚。扫尽浮云风不定，未放扁舟夜渡。宿燕落、寒芦深处。怅望关河空吊影，正人间、鼻息鸣鼍鼓。谁伴我，醉中舞」写曳杖危楼、北斗垂天、沧波万顷、月流烟渚，扫尽浮云风不定、未放扁舟夜渡，宿燕落寒芦深处，怅望关河空吊影、人间鼻息鸣鼍鼓，谁伴我醉中舞，以夜景写孤独与壮志；下片「十年一梦扬州路。倚高寒、愁生故国，气吞骄虏。要斩楼兰三尺剑，遗恨琵琶旧语。谩暗涩、铜华尘土。唤取谪仙平章看，过苕溪、尚许垂纶否。风浩荡，欲飞举」写十年一梦扬州路、倚高寒愁生故国气吞骄虏，要斩楼兰三尺剑、遗恨琵琶旧语，谩暗涩铜华尘土，唤取谪仙平章看、过苕溪尚许垂纶否，风浩荡欲飞举，以抗金壮志与对友人的同情写爱国情怀，全词意境苍凉、用典丰富（祖逖闻鸡起舞、楼兰、昭君琵琶、李白谪仙、苕溪垂纶），是南宋爱国词的名篇。","b":"张元干（南宋词人）这首《贺新郎》是他送友人胡铨（因反对秦桧被贬）的词，写抗金壮志与对友人的同情，是南宋爱国词的名篇，与他的《贺新郎·送胡邦衡待制》（「梦绕神州路」）并称。","n":["贺新郎：词牌名","曳杖危楼去：拄杖登上高楼","斗垂天、沧波万顷：北斗垂天、沧波万顷","月流烟渚：月照烟渚","扫尽浮云风不定：扫尽浮云风不定","未放扁舟夜渡：未放扁舟夜渡","宿燕落、寒芦深处：宿燕落在寒芦深处","怅望关河空吊影：怅望关河空吊影","正人间、鼻息鸣鼍鼓：正人间鼻息如鼍鼓（鼍鼓，鳄鱼皮鼓，形容鼾声大）。鼍音tuó","谁伴我，醉中舞：谁伴我醉中舞（用祖逖闻鸡起舞典故）","十年一梦扬州路：十年一梦扬州路（指十年前在扬州的抗金经历）","倚高寒、愁生故国：倚高寒、愁生故国","气吞骄虏：气吞骄虏","要斩楼兰三尺剑：要斩楼兰（敌酋）三尺剑","遗恨琵琶旧语：遗恨琵琶旧语（指和亲屈辱，王昭君琵琶）","谩暗涩、铜华尘土：空让铜剑（铜华）暗涩蒙尘","唤取谪仙平章看：唤取谪仙（李白，指友人）评看","过苕溪、尚许垂纶否：过苕溪还许垂纶（钓鱼，指隐居）否。纶音lún，钓丝","风浩荡，欲飞举：风浩荡、欲飞举"],"m":"要斩楼兰三尺剑，遗恨琵琶旧语。","r":"按「曳杖危楼—斗垂天—沧波万顷—月流烟渚—浮云风—扁舟夜渡—宿燕寒芦—怅望关河—鼻息鼍鼓—谁伴醉舞—十年一梦—愁生故国—气吞骄虏—斩楼兰—琵琶旧语—铜华尘土—谪仙平章—苕溪垂纶—风浩荡—欲飞举」背；「鼍」读tuó、「纶」读lún；用典（闻鸡起舞、楼兰、昭君、李白、垂纶）；爱国情怀是核心。"},"75589:石州慢|张元干":{"s":"上片「寒水依痕，春意渐回，沙际烟阔。溪梅晴照生香，冷芯数枝争发。天涯旧恨，试看几许消魂，长亭门外山重叠。不尽眼中青，是愁来时节」写寒水依痕、春意渐回、沙际烟阔，溪梅晴照生香、冷蕊数枝争发，天涯旧恨、几许消魂，长亭门外山重叠，不尽眼中青是愁来时节，以春景写离愁；下片「情切。画楼深闭，想见东风，暗销肌雪。辜负枕前云雨，尊前花月。心期切处，更有多少凄凉，殷勤留与归时说。到得却相逢，恰经年离别」写情切、画楼深闭、想见东风暗销肌雪，辜负枕前云雨尊前花月，心期切处多少凄凉、殷勤留与归时说，到得却相逢、恰经年离别，以久别重逢的感慨写相思，全词意境凄清、情感深沉，「到得却相逢，恰经年离别」成为名句。","b":"张元干这首《石州慢》写离别后的相思，以「到得却相逢，恰经年离别」写久别重逢的感慨，是婉约词的名篇。","n":["石州慢：词牌名","寒水依痕：寒水依着旧痕","春意渐回：春意渐回","沙际烟阔：沙际烟阔","溪梅晴照生香：溪梅晴照生香","冷芯数枝争发：冷蕊数枝争发。芯同「蕊」","天涯旧恨：天涯旧恨","试看几许消魂：试看几许消魂","长亭门外山重叠：长亭门外山重叠","不尽眼中青：不尽眼中青","是愁来时节：是愁来时节","情切：情切","画楼深闭：画楼深闭","想见东风：想见东风","暗销肌雪：暗销肌雪（肌肤如雪消瘦）","辜负枕前云雨：辜负枕前云雨","尊前花月：尊前花月","心期切处：心期切处","更有多少凄凉：更有多少凄凉","殷勤留与归时说：殷勤留与归时说","到得却相逢：到得却相逢","恰经年离别：恰经年离别"],"m":"到得却相逢，恰经年离别。","r":"按「寒水依痕—春意渐回—沙际烟阔—溪梅生香—冷蕊争发—天涯旧恨—几许消魂—长亭山重—不尽眼中青—愁来时节—情切—画楼深闭—东风销肌—辜负云雨—尊前花月—心期凄凉—留与归说—到得相逢—恰经年离别」背；「芯」同蕊；以春景写离愁是核心。"},"一丛花令・一丛花|张先":{"s":"上片「伤高怀远几时穷。无物似情浓。离愁正引千丝乱，更东陌、飞絮蒙蒙。嘶骑渐遥，征尘不断，何处认郎踪」写伤高怀远几时穷、无物似情浓，离愁引千丝乱、东陌飞絮蒙蒙，嘶骑渐遥、征尘不断、何处认郎踪，以柳丝飞絮写离愁；下片「双鸳池沼水溶溶。南北小桡通。梯横画阁黄昏后，又还是、斜月帘栊。沈恨细思，不如桃杏，犹解嫁东风」写双鸳池沼水溶溶、南北小桡通，梯横画阁黄昏后、又还是斜月帘栊，沉恨细思、不如桃杏犹解嫁东风，以「不如桃杏，犹解嫁东风」写思妇的自怜——人不如桃杏还能嫁给东风，想象奇特、情感深沉，全词意境凄清，「不如桃杏，犹解嫁东风」成为千古名句。","b":"张先（北宋词人，「张三影」）这首《一丛花令》写闺中思妇的离愁，「不如桃杏，犹解嫁东风」是千古名句，欧阳修曾因此戏称张先为「桃杏嫁东风郎中」。","n":["一丛花令：词牌名","伤高怀远几时穷：伤高怀远几时穷尽","无物似情浓：没有什么像情这样浓","离愁正引千丝乱：离愁正引千丝（柳丝）乱","更东陌、飞絮蒙蒙：更东陌飞絮蒙蒙","嘶骑渐遥：嘶鸣的马渐渐远去","征尘不断：征尘不断","何处认郎踪：何处认郎的踪迹","双鸳池沼水溶溶：双鸳池沼水溶溶（水流动的样子）","南北小桡通：南北小船通。桡音ráo，船桨","梯横画阁黄昏后：梯横画阁黄昏后","又还是、斜月帘栊：又还是斜月帘栊","沈恨细思：沉恨细思。沈同「沉」","不如桃杏：不如桃杏","犹解嫁东风：还懂得嫁给东风（桃杏随风飘落，比喻女子不如桃杏还能有所归宿）"],"m":"沈恨细思，不如桃杏，犹解嫁东风。","r":"按「伤高怀远—无物情浓—离愁千丝—飞絮蒙蒙—嘶骑渐遥—征尘不断—何处认郎—双鸳池沼—小桡通—梯横画阁—斜月帘栊—沉恨细思—不如桃杏—犹解嫁东风」背；「桡」读ráo、「沈」同沉；「不如桃杏，犹解嫁东风」是名句；拟人手法是核心。"},"57726:天仙子|张先":{"s":"上片「水调数声持酒听。午醉醒来愁未醒。送春春去几时回，临晚镜。伤流景。往事后期空记省」写持酒听水调、午醉醒来愁未醒，送春春去几时回、临晚镜伤流景、往事后期空记省，以愁写伤春；下片「沙上并禽池上暝。云破月来花弄影。重重帘幕密遮灯，风不定。人初静。明日落红应满径」写沙上并禽池上暝、云破月来花弄影，重重帘幕密遮灯、风不定人初静、明日落红应满径，以「云破月来花弄影」的「弄」字写花的灵动，王国维评为「着一弄字而境界全出」，全词意境凄清、「弄」字传神，是北宋词的名篇，「云破月来花弄影」成为千古名句。","b":"张先这首《天仙子》写伤春之情，「云破月来花弄影」是千古名句，张先因「云破月来花弄影」「娇柔懒起，帘压卷花影」「柳径无人，堕飞絮无影」三句被称为「张三影」。","n":["天仙子：词牌名","水调数声持酒听：持酒听数声《水调》曲","午醉醒来愁未醒：午醉醒来愁未醒","送春春去几时回：送春春去几时回","临晚镜：临晚镜","伤流景：伤流逝的光景","往事后期空记省：往事后期空记省（省音xǐng，记忆）","沙上并禽池上暝：沙上并禽（成对的鸟）池上暝（天黑）","云破月来花弄影：云破月来花弄影（「弄」字是千古名句，张先因此被称「云破月来花弄影郎中」）","重重帘幕密遮灯：重重帘幕密遮灯","风不定：风不定","人初静：人初静","明日落红应满径：明日落红应满径"],"m":"沙上并禽池上暝。云破月来花弄影。","r":"按「水调持酒—午醉愁醒—送春春回—临晚镜—伤流景—往事空记—沙上并禽—池上暝—云破月来—花弄影—帘幕遮灯—风不定—人初静—明日落红」背；「省」读xǐng；「弄」字是诗眼；「张三影」典故是背景。"},"千秋岁|张先":{"s":"上片「数声𫛸鴂。又报芳菲歇。惜春更把残红折。雨轻风色暴，梅子青时节。永丰柳，无人尽日飞花雪」写数声杜鹃、又报芳菲歇，惜春更把残红折，雨轻风色暴、梅子青时节，永丰柳无人尽日飞花雪，以春景写离愁；下片「莫把幺弦拨。怨极弦能说。天不老，情难绝。心似双丝网，中有千千结。夜过也，东窗未白凝残月」写莫把幺弦拨、怨极弦能说，天不老情难绝、心似双丝网中有千千结，夜过也、东窗未白凝残月，以「天不老，情难绝」写爱情的坚贞、以「心似双丝网，中有千千结」写情思的缠绵，全词情感深沉、比喻新奇，「天不老，情难绝。心似双丝网，中有千千结」成为千古名句。","b":"张先这首《千秋岁》写爱情的坚贞，「天不老，情难绝。心似双丝网，中有千千结」是千古名句，是写爱情的名篇。","n":["千秋岁：词牌名","数声𫛸鴂：数声杜鹃。𫛸鴂音tíjué，杜鹃鸟","又报芳菲歇：又报芳菲（花）凋谢","惜春更把残红折：惜春更把残红折","雨轻风色暴：雨轻风色暴","梅子青时节：梅子青时节","永丰柳：永丰柳（白居易「永丰西角荒园里，尽日无人属阿谁」）","无人尽日飞花雪：无人尽日飞柳絮如雪","莫把幺弦拨：莫把幺弦（琵琶第四弦，最细最哀）拨","怨极弦能说：怨极了弦能诉说","天不老，情难绝：天不老、情难绝","心似双丝网：心似双丝网","中有千千结：中有千千结","夜过也：夜过也","东窗未白凝残月：东窗未白凝残月"],"m":"天不老，情难绝。心似双丝网，中有千千结。","r":"按「数声𫛸鴂—芳菲歇—惜春残红—雨轻风暴—梅子青—永丰柳—飞花雪—莫拨幺弦—怨极弦说—天不老—情难绝—心似双丝网—千千结—夜过—东窗残月」背；「𫛸鴂」读tíjué；用典（白居易永丰柳）；「心似双丝网，中有千千结」的比喻是核心。"},"六州歌头|张孝祥":{"s":"上片「长怀望断，关塞莽然平。征尘暗，霜风劲，悄边声。黯销凝。追想当年事，殆天数，非人力，洙泗上，弦歌地，亦膻腥。隔水毡乡，落日牛羊下，区脱纵横。看名王宵猎，骑火一川明。笳鼓悲鸣。遣人惊」写长怀望断关塞、征尘暗霜风劲，追想靖康之变、洙泗弦歌地亦膻腥，隔水毡乡、名王宵猎、笳鼓悲鸣，以中原沦陷的惨状写忠愤；下片「念腰间箭，匣中剑，空埃蠹，竟何成。时易失，心徒壮，岁将零。渺神京。干羽方怀远，静烽燧，且休兵。冠盖使，纷驰骛，若为情。闻道中原遗老，常南望，羽葆霓旌。使行人到此，忠愤气填膺。有泪如倾」写腰间箭匣中剑空埃蠹竟何成，时易失心徒壮岁将零，朝廷干羽怀远静烽燧休兵、使者纷驰骛，闻道中原遗老常南望王师，使行人到此忠愤气填膺有泪如倾，以朝廷主和与中原遗老南望对比写忠愤，全词节奏急促、情感激烈，是南宋爱国词的千古名篇，相传张浚读后为之罢席。","b":"张孝祥（南宋词人）这首《六州歌头》写南宋初年中原沦陷、朝廷主和的忠愤之情，相传是他在建康留守席上作，张浚读后为之罢席，是南宋爱国词的千古名篇。","n":["六州歌头：词牌名","长怀望断：长怀望断","关塞莽然平：关塞莽然平","征尘暗：征尘暗","霜风劲：霜风劲","悄边声：悄边声","黯销凝：黯然销魂凝神","追想当年事：追想当年事（指靖康之变）","殆天数：大概是天数","非人力：非人力","洙泗上：洙泗上（洙水泗水，孔子讲学处，代指中原文化）","弦歌地：弦歌地（礼乐之地）","亦膻腥：也膻腥（被金人玷污）。膻音shān","隔水毡乡：隔水毡乡（金人毡帐之乡）","落日牛羊下：落日牛羊下（用《诗经》「日之夕矣，羊牛下来」）","区脱纵横：区脱纵横（区脱，匈奴筑的土室，此指金人的哨所）。区音ōu","看名王宵猎：看名王（金将）夜猎","骑火一川明：骑兵火把一川明","笳鼓悲鸣：笳鼓悲鸣","遣人惊：使人惊","念腰间箭：念腰间箭","匣中剑：匣中剑","空埃蠹：空被尘埃虫蛀。蠹音dù","竟何成：竟何成","时易失：时易失","心徒壮：心徒壮","岁将零：岁将零（将尽）","渺神京：渺神京（遥远的汴京）","干羽方怀远：干羽方怀远（用文德怀远，指朝廷主和。干羽，盾牌和雉羽，文德的象征）","静烽燧：静烽燧（烽火台安静，指不打仗）","且休兵：且休兵","冠盖使：冠盖使（使者）","纷驰骛：纷纷奔驰。骛音wù","若为情：若为情（何以为情）","闻道中原遗老：闻道中原遗老","常南望：常南望","羽葆霓旌：羽葆霓旌（皇帝的仪仗，指王师）","使行人到此：使行人到此","忠愤气填膺：忠愤气填膺","有泪如倾：有泪如倾"],"m":"闻道中原遗老，常南望，羽葆霓旌。使行人到此，忠愤气填膺。有泪如倾。","r":"按「长怀望断—关塞莽然—征尘暗—霜风劲—悄边声—黯销凝—追想当年—殆天数—洙泗弦歌—亦膻腥—隔水毡乡—落日牛羊—区脱纵横—名王宵猎—骑火一川—笳鼓悲鸣—遣人惊—腰间箭—匣中剑—空埃蠹—竟何成—时易失—心徒壮—岁将零—渺神京—干羽怀远—静烽燧—且休兵—冠盖使—纷驰骛—若为情—中原遗老—常南望—羽葆霓旌—行人到此—忠愤填膺—有泪如倾」背；「膻」读shān、「区」读ōu、「蠹」读dù、「骛」读wù；用典（洙泗弦歌、《诗经》牛羊下来、干羽文德）；忠愤之情是核心；张浚罢席典故是背景。"},"59764:西江月|张孝祥":{"s":"上片「问讯湖边春色，重来又是三年。东风吹我过湖船，杨柳丝丝拂面」写问讯湖边春色、重来又是三年，东风吹我过湖船、杨柳丝丝拂面，以春景写游兴；下片「世路如今已惯，此心到处悠然。寒光庭下水如天，飞起沙鸥一片」写世路如今已惯、此心到处悠然，寒光亭下水如天、飞起沙鸥一片，以「世路已惯，此心悠然」写旷达、以「水如天」「沙鸥飞」写自由，全词意境开阔、心境旷达，是南宋词的名篇。","b":"张孝祥这首《西江月》写游三塔寺（在今江苏丹阳）的所见所感，以「世路如今已惯，此心到处悠然」写旷达的心境，是南宋词的名篇。","n":["西江月：词牌名","问讯湖边春色：问讯湖边春色","重来又是三年：重来又是三年","东风吹我过湖船：东风吹我过湖船","杨柳丝丝拂面：杨柳丝丝拂面","世路如今已惯：世路如今已惯","此心到处悠然：此心到处悠然","寒光庭下水如天：寒光亭下水如天","飞起沙鸥一片：飞起沙鸥一片"],"m":"世路如今已惯，此心到处悠然。","r":"按「问讯春色—重来三年—东风过船—杨柳拂面—世路已惯—此心悠然—寒光水天—沙鸥飞起」背；旷达心境是核心；以景写情是手法。"},"64074:高阳台|张炎":{"s":"上片「接叶巢莺，平波卷絮，断桥斜日归船。能几番游，看花又是明年。东风且伴蔷薇住，到蔷薇、春已堪怜。更凄然。万绿西泠，一抹荒烟」写接叶巢莺、平波卷絮、断桥斜日归船，能几番游、看花又是明年，东风且伴蔷薇住、到蔷薇春已堪怜，更凄然万绿西泠一抹荒烟，以西湖春景写惜春与亡国之思；下片「当年燕子知何处，但苔深韦曲，草暗斜川。见说新愁，如今也到鸥边。无心再续笙歌梦，掩重门、浅醉闲眠。莫开帘。怕见飞花，怕听啼鹃」写当年燕子知何处、但苔深韦曲草暗斜川，见说新愁如今也到鸥边，无心再续笙歌梦、掩重门浅醉闲眠，莫开帘怕见飞花怕听啼鹃，以燕子、苔深、草暗写今昔之感、以「怕见飞花，怕听啼鹃」写亡国之痛，全词意境凄清、用典贴切（刘禹锡燕子、韦曲、斜川、杜鹃啼归），是南宋遗民词的千古名篇。","b":"张炎（南宋末元初词人，「格律派」代表，号玉田）这首《高阳台》写西湖春游的亡国之思，以「莫开帘，怕见飞花，怕听啼鹃」写亡国之痛，是南宋遗民词的千古名篇。","n":["高阳台：词牌名","接叶巢莺：接叶（叶叶相接）巢莺","平波卷絮：平波卷絮","断桥斜日归船：断桥斜日归船","能几番游：能几番游","看花又是明年：看花又是明年","东风且伴蔷薇住：东风且伴蔷薇住","到蔷薇、春已堪怜：到蔷薇春已堪怜","更凄然：更凄然","万绿西泠：万绿西泠（西泠桥，在西湖）","一抹荒烟：一抹荒烟","当年燕子知何处：当年燕子知何处（用刘禹锡「旧时王谢前堂燕」）","但苔深韦曲：但苔深韦曲（韦曲，在长安，代指繁华之地）","草暗斜川：草暗斜川（斜川，在江西，陶渊明游斜川）","见说新愁：见说新愁","如今也到鸥边：如今也到鸥边（鸥鸟本是忘机的，也有了愁）","无心再续笙歌梦：无心再续笙歌梦","掩重门、浅醉闲眠：掩重门浅醉闲眠","莫开帘：莫开帘","怕见飞花：怕见飞花","怕听啼鹃：怕听啼鹃（杜鹃啼声悲，且「不如归去」）"],"m":"当年燕子知何处，但苔深韦曲，草暗斜川。","r":"按「接叶巢莺—平波卷絮—断桥归船—能几番游—看花明年—东风伴蔷薇—春已堪怜—更凄然—万绿西泠—一抹荒烟—当年燕子—苔深韦曲—草暗斜川—新愁到鸥—无心笙歌—掩重门—浅醉闲眠—莫开帘—怕见飞花—怕听啼鹃」背；用典（刘禹锡燕子、韦曲、斜川、杜鹃啼归）；亡国之思是核心。"},"68039:清平乐|张炎":{"s":"上片「候蛩凄断。人语西风岸。月落沙平江似练。望尽芦花无雁」写候蛩凄断、人语西风岸，月落沙平江似练、望尽芦花无雁，以秋景写愁；下片「暗教愁损兰成。可怜夜夜关情。只有一枝梧叶，不知多少秋声」写暗教愁损兰成、可怜夜夜关情，只有一枝梧叶、不知多少秋声，以「一枝梧叶」「多少秋声」写愁的细腻——一枝梧叶就能带来多少秋声，愁思之深尽在其中，全词意境凄清、以小见大，「只有一枝梧叶，不知多少秋声」成为名句。","b":"张炎这首《清平乐》写秋夜的愁思，以「只有一枝梧叶，不知多少秋声」写愁的细腻，是南宋遗民词的名篇。","n":["清平乐：词牌名","候蛩凄断：候蛩（蟋蟀）凄断","人语西风岸：人语西风岸","月落沙平江似练：月落沙平江似练（谢朓「澄江静如练」）","望尽芦花无雁：望尽芦花无雁","暗教愁损兰成：暗教愁损兰成（庾信，小字兰成，作《哀江南赋》，此指自己）","可怜夜夜关情：可怜夜夜关情","只有一枝梧叶：只有一枝梧叶","不知多少秋声：不知多少秋声"],"m":"只有一枝梧叶，不知多少秋声。","r":"按「候蛩凄断—人语西风—月落江练—芦花无雁—愁损兰成—夜夜关情—一枝梧叶—多少秋声」背；用典（庾信小字兰成、谢朓澄江如练）；以小见大是核心。"},"绝句·古木阴中系短篷|志南":{"s":"首两句「古木阴中系短篷，杖藜扶我过桥东」写古木阴中系小船、拄藜杖扶我过桥东，以「系短篷」「杖藜」写春游的闲适；后两句「沾衣欲湿杏花雨，吹面不寒杨柳风」是千古名句——杏花时节的雨沾衣欲湿、杨柳时节的风吹面不寒，以「杏花雨」「杨柳风」写春天的美好，「欲湿」「不寒」二字极炼，全诗意境清新、语言明丽，是写春游的千古名篇，「沾衣欲湿杏花雨，吹面不寒杨柳风」成为千古名句。","b":"志南（南宋诗僧）这首《绝句》写春游的所见所感，「沾衣欲湿杏花雨，吹面不寒杨柳风」是千古名句，朱熹曾跋其诗「清丽有余，格力闲暇，无蔬笋气」。","n":["绝句：诗体名","古木阴中系短篷：古木阴中系短篷（小船）","杖藜扶我过桥东：拄着藜杖扶我过桥东。藜音lí，藜茎做的杖","沾衣欲湿杏花雨：沾衣欲湿的杏花雨（杏花时节的雨）","吹面不寒杨柳风：吹面不寒的杨柳风（杨柳时节的风）"],"m":"沾衣欲湿杏花雨，吹面不寒杨柳风。","r":"四句按「古木系篷—杖藜桥东—杏花雨—杨柳风」背；「藜」读lí；「欲湿」「不寒」是炼字；清新意境是核心。"},"67229:酹江月・念奴娇|文天祥":{"s":"上片「庐山依旧，凄凉处、无限江南风物。空翠晴岚浮汗漫，还障天东半壁。雁过孤峰，猿归危嶂，风急波翻雪。乾坤未老，地灵尚有人杰」写庐山依旧、凄凉处无限江南风物，空翠晴岚浮汗漫还障天东半壁，雁过孤峰猿归危嶂风急波翻雪，乾坤未老地灵尚有人杰，以庐山的雄伟写不屈的气节；下片「堪嗟漂泊孤舟，河倾斗落，客梦催明发。南浦闲云连草树，回首旌旗明灭。三十年来，十年一过，空有星星发。夜深愁听，胡笳吹彻寒月」写堪嗟漂泊孤舟、河倾斗落客梦催明发，南浦闲云连草树回首旌旗明灭，三十年来十年一过空有星星发，夜深愁听胡笳吹彻寒月，以漂泊与胡笳写亡国之痛，全词意境苍凉、气节凛然，「乾坤未老，地灵尚有人杰」成为名句，是南宋爱国词的千古名篇。","b":"文天祥（南宋末民族英雄）这首《酹江月》写他被元军俘虏后押解北上、途经庐山时的所见所感，以「乾坤未老，地灵尚有人杰」写不屈的气节，是南宋爱国词的千古名篇。","n":["酹江月：词牌名，即《念奴娇》","庐山依旧：庐山依旧","凄凉处、无限江南风物：凄凉处无限江南风物","空翠晴岚浮汗漫：空翠晴岚浮汗漫（汗漫，广大无边）。岚音lán，山气","还障天东半壁：还障天东半壁","雁过孤峰：雁过孤峰","猿归危嶂：猿归危嶂","风急波翻雪：风急波翻雪","乾坤未老：乾坤未老","地灵尚有人杰：地灵尚有人杰","堪嗟漂泊孤舟：堪嗟漂泊孤舟","河倾斗落：河倾斗落","客梦催明发：客梦催明发","南浦闲云连草树：南浦闲云连草树","回首旌旗明灭：回首旌旗明灭","三十年来：三十年来","十年一过：十年一过","空有星星发：空有星星发（花白的头发）","夜深愁听：夜深愁听","胡笳吹彻寒月：胡笳吹彻寒月"],"m":"乾坤未老，地灵尚有人杰。","r":"按「庐山依旧—凄凉风物—空翠晴岚—障天半壁—雁过孤峰—猿归危嶂—风急波雪—乾坤未老—地灵人杰—漂泊孤舟—河倾斗落—客梦明发—南浦闲云—回首旌旗—三十年—十年过—星星发—夜深愁听—胡笳寒月」背；「岚」读lán；爱国气节是核心；与《正气歌》对读。"},"正气歌|文天祥":{"s":"全诗分四层：第一层「天地有正气……道义为之根」写正气的本源——天地有正气，下为河岳上为日星，于人曰浩然沛乎塞苍冥，时穷节乃见一一垂丹青，列举齐太史简、晋董狐笔、秦张良椎、汉苏武节、严将军头、嵇侍中血、张睢阳齿、颜常山舌、辽东帽、出师表、渡江楫、击贼笏十二位忠臣义士的事迹，写正气所磅礴凛烈万古存，生死安足论，地维天柱赖以尊，三纲道义为之根；第二层「嗟予遘阳九……百沴自辟易」写自己的遭遇——遭逢阳九、楚囚送穷北，鼎镬甘如饴求之不可得，阴房鬼火春院天黑，牛骥同皂鸡栖凤凰，一朝蒙雾露分作沟中瘠，如此再寒暑百沴自辟易；第三层「嗟哉沮洳场……苍天曷有极」写自己在狱中以正气自守——沮洳场为我安乐国，岂有他缪巧阴阳不能贼，顾此耿耿在仰视浮云白，悠悠我心悲苍天曷有极；第四层「哲人日已远……古道照颜色」写以古人为楷模——哲人日已远典刑在夙昔，风檐展书读古道照颜色。全诗气势磅礴、用典丰富、气节凛然，是中国文学史上最著名的爱国诗篇。","b":"文天祥这首《正气歌》是他被元军俘虏后、囚禁在大都（今北京）时所作，列举历史上十二位忠臣义士的壮烈事迹，抒发自己的浩然正气与不屈气节，是中国文学史上最著名的爱国诗篇之一。","n":["正气歌：诗体名，文天祥作","杂然赋流形：杂然赋予各种形体","下则为河岳：下则为河岳","上则为日星：上则为日星","于人曰浩然：于人叫做浩然之气","沛乎塞苍冥：充沛地充满天地。苍冥，天地","皇路当清夷：国家政治清明太平时。皇路，国家政治；清夷，清明太平","含和吐明庭：含和而立于明庭（朝廷）","时穷节乃见：时运穷困时节操才显现。见同「现」","一一垂丹青：一一垂名丹青（史册）","在齐太史简：齐国太史的竹简（太史兄弟直书「崔杼弑其君」）","在晋董狐笔：晋国董狐的笔（董狐直书「赵盾弑其君」）","在秦张良椎：秦朝张良的铁椎（张良使力士击秦始皇于博浪沙）","在汉苏武节：汉朝苏武的节（苏武持节牧羊十九年不降）","为严将军头：为严将军（严颜，「但有断头将军，无降将军」）的头","为嵇侍中血：为嵇侍中（嵇绍，为保护晋惠帝而死）的血","为张睢阳齿：为张睢阳（张巡，守睢阳，咬牙切齿）的齿","为颜常山舌：为颜常山（颜杲卿，守常山，骂贼被割舌）的舌","或为辽东帽：或为辽东帽（管宁，隐居辽东，戴黑帽）","清操厉冰雪：清操厉如冰雪","或为出师表：或为《出师表》（诸葛亮）","鬼神泣壮烈：鬼神泣其壮烈","或为渡江楫：或为渡江楫（祖逖，中流击楫「不能清中原而复济者，有如大江」）","慷慨吞胡羯：慷慨吞胡羯","或为击贼笏：或为击贼笏（段秀实，以笏击朱泚）","逆竖头破裂：逆竖（叛贼）头破裂","是气所磅礴：这气所磅礴","凛烈万古存：凛烈万古存","当其贯日月：当它贯穿日月","生死安足论：生死哪里值得论","地维赖以立：地维（地的四角）赖以立","天柱赖以尊：天柱赖以尊","三纲实系命：三纲实系命","道义为之根：道义为之根","嗟予遘阳九：嗟我遭逢阳九（厄运）。遘音gòu，遭逢；阳九，厄运","隶也实不力：我（隶，奴仆，自谦）实在不力","楚囚缨其冠：楚囚（被俘的人）戴着冠（用钟仪「南冠而絷」典故）","传车送穷北：传车送到穷北","鼎镬甘如饴：鼎镬（酷刑）甘如饴（糖）。镬音huò","求之不可得：求之不可得","阴房阗鬼火：阴房阗（寂静）鬼火。阗音tián","春院閟天黑：春院閟（关闭）天黑。閟音bì","牛骥同一皂：牛和骥（千里马）同一皂（马槽）","鸡栖凤凰食：鸡栖凤凰食（凤凰和鸡一样吃食）","一朝蒙雾露：一旦蒙雾露（生病）","分作沟中瘠：分（理应）作沟中瘠（沟中的枯骨）。瘠音zí，枯骨","如此再寒暑：如此过了两年（再寒暑，两年）","百沴自辟易：百沴（各种灾疫）自辟易（退避）。沴音lì","嗟哉沮洳场：嗟哉沮洳场（低湿的地方）。沮洳音jùrù","为我安乐国：为我安乐国","岂有他缪巧：岂有他缪巧（计谋）。缪同「谬」","阴阳不能贼：阴阳（寒暑）不能贼（害）","顾此耿耿在：顾此耿耿（忠心）在","仰视浮云白：仰视浮云白","悠悠我心悲：悠悠我心悲","苍天曷有极：苍天曷（何）有极","哲人日已远：哲人日已远","典刑在夙昔：典刑（楷模）在夙昔（从前）","风檐展书读：风檐展书读","古道照颜色：古道照颜色"],"m":"天地有正气，杂然赋流形。下则为河岳，上则为日星。于人曰浩然，沛乎塞苍冥。","r":"按「正气本源—十二义士—正气磅礴—自身遭遇—狱中自守—古人楷模」背；生僻字多：遘gòu、镬huò、阗tián、閟bì、瘠zí、沴lì、沮洳jùrù；十二位义士典故是核心；浩然正气是全诗主题。"},"58522:鹧鸪天|晏几道":{"s":"上片「彩袖殷勤捧玉钟。当年拼却醉颜红。舞低杨柳楼心月，歌尽桃花扇影风」写彩袖殷勤捧玉钟、当年拼却醉颜红，舞低杨柳楼心月、歌尽桃花扇影风，以「舞低」「歌尽」写当年的欢乐；下片「从别后，忆相逢。几回魂梦与君同。今宵剩把银釭照，犹恐相逢是梦中」写从别后忆相逢、几回魂梦与君同，今宵剩把银釭照、犹恐相逢是梦中，以「犹恐相逢是梦中」写久别重逢的惊喜与不敢置信，全词今昔对比、情感深沉，「舞低杨柳楼心月，歌尽桃花扇影风」「今宵剩把银釭照，犹恐相逢是梦中」成为千古名句，是婉约词的千古名篇。","b":"晏几道（北宋词人，晏殊第七子，号小山）这首《鹧鸪天》写与歌女的久别重逢，「舞低杨柳楼心月，歌尽桃花扇影风」「今宵剩把银釭照，犹恐相逢是梦中」是千古名句，是婉约词的千古名篇。","n":["鹧鸪天：词牌名","彩袖殷勤捧玉钟：彩袖（歌女）殷勤捧玉钟（酒杯）","当年拼却醉颜红：当年拼却醉颜红。拼音pīn，不顾","舞低杨柳楼心月：舞低杨柳楼心月（舞到月亮西沉）","歌尽桃花扇影风：歌尽桃花扇影风（歌到扇影风停）","从别后：从别后","忆相逢：忆相逢","几回魂梦与君同：几回魂梦与君同","今宵剩把银釭照：今宵尽把银釭（灯）照。釭音gāng，灯","犹恐相逢是梦中：犹恐相逢是梦中"],"m":"舞低杨柳楼心月，歌尽桃花扇影风。今宵剩把银釭照，犹恐相逢是梦中。","r":"按「彩袖捧钟—拼却醉红—舞低楼月—歌尽扇风—从别后—忆相逢—魂梦与同—银釭照—相逢梦中」背；「釭」读gāng；今昔对比是核心；「犹恐相逢是梦中」是名句。"},"58541:生查子|晏几道":{"s":"上片「金鞭美少年，去跃青骢马。牵系玉楼人，绣被春寒夜」写金鞭美少年去跃青骢马，牵系玉楼人、绣被春寒夜，以少年的远游写女子的思念；下片「消息未归来，寒食梨花谢。无处说相思，背面秋千下」写消息未归来、寒食梨花谢，无处说相思、背面秋千下，以「背面秋千下」的细节写相思的无言——无处诉说，只能背对着人在秋千下默默思念，细节生动、情感深沉，全词意境凄清，「无处说相思，背面秋千下」成为名句。","b":"晏几道这首《生查子》写闺中女子思念远游的少年，以「背面秋千下」写相思的无言，是婉约词的名篇。","n":["生查子：词牌名","金鞭美少年：金鞭美少年","去跃青骢马：去跃青骢马（青白色的马）。骢音cōng","牵系玉楼人：牵系玉楼人（楼上的女子）","绣被春寒夜：绣被春寒夜","消息未归来：消息未归来","寒食梨花谢：寒食梨花谢","无处说相思：无处说相思","背面秋千下：背面秋千下"],"m":"无处说相思，背面秋千下。","r":"按「金鞭少年—跃青骢马—牵系玉楼—绣被春寒—消息未归—寒食花谢—无处说相思—背面秋千」背；「骢」读cōng；「背面秋千下」的细节是核心。"},"58561:清平乐|晏几道":{"s":"上片「留人不住。醉解兰舟去。一棹碧涛春水路，过尽晓莺啼处」写留人不住、醉解兰舟去，一棹碧涛春水路、过尽晓莺啼处，以留人不住写离别的无奈；下片「渡头杨柳青青。枝枝叶叶离情。此后锦书休寄，画楼云雨无凭」写渡头杨柳青青、枝枝叶叶离情，此后锦书休寄、画楼云雨无凭，以「锦书休寄」「云雨无凭」写失恋的决绝——既然靠不住，就不要再寄信了，决绝中含痛苦，全词意境凄清、情感深沉，「此后锦书休寄，画楼云雨无凭」成为名句。","b":"晏几道这首《清平乐》写送别后的决绝，以「此后锦书休寄，画楼云雨无凭」写失恋的痛苦，是婉约词的名篇。","n":["清平乐：词牌名","留人不住：留人不住","醉解兰舟去：醉解兰舟（木兰舟）去","一棹碧涛春水路：一棹碧涛春水路","过尽晓莺啼处：过尽晓莺啼处","渡头杨柳青青：渡头杨柳青青","枝枝叶叶离情：枝枝叶叶离情","此后锦书休寄：此后锦书（情书）休寄","画楼云雨无凭：画楼云雨无凭（靠不住）"],"m":"此后锦书休寄，画楼云雨无凭。","r":"按「留人不住—醉解兰舟—一棹碧涛—过尽晓莺—渡头杨柳—枝叶离情—锦书休寄—云雨无凭」背；决绝中含痛苦是核心；以杨柳写离情是手法。"},"58616:阮郎归|晏几道":{"s":"上片「旧香残粉似当初。人情恨不如。一春犹有数行书。秋来书更疏」写旧香残粉似当初、人情恨不如，一春犹有数行书、秋来书更疏，以物是人非写相思；下片「衾凤冷，枕鸳孤。愁肠待酒舒。梦魂纵有也成虚。那堪和梦无」写衾凤冷枕鸳孤、愁肠待酒舒，梦魂纵有也成虚、那堪和梦无，以「和梦无」写相思的极致——连梦都没有，比梦中相见更痛苦，全词意境凄清、情感深沉，「梦魂纵有也成虚，那堪和梦无」成为名句。","b":"晏几道这首《阮郎归》写闺中女子的相思，以「梦魂纵有也成虚，那堪和梦无」写相思的深沉，是婉约词的名篇。","n":["阮郎归：词牌名","旧香残粉似当初：旧香残粉似当初","人情恨不如：人情恨不如","一春犹有数行书：一春犹有数行书","秋来书更疏：秋来书更疏","衾凤冷：衾凤（绣凤的被子）冷。衾音qīn","枕鸳孤：枕鸳（绣鸳的枕头）孤","愁肠待酒舒：愁肠待酒舒","梦魂纵有也成虚：梦魂纵有也成虚","那堪和梦无：那堪和梦无（连梦都没有）"],"m":"梦魂纵有也成虚，那堪和梦无。","r":"按「旧香残粉—人情不如—春有数行—秋来书疏—衾凤冷—枕鸳孤—愁肠待酒—梦魂成虚—那堪和梦无」背；「衾」读qīn；「和梦无」的递进是核心。"},"58683:少年游|晏几道":{"s":"上片「离多最是，东西流水，终解两相逢。浅情终似，行云无定，犹到梦魂中」写离多最是东西流水、终解两相逢，浅情终似行云无定、犹到梦魂中，以流水、行云反衬——流水还能相逢、行云还能到梦；下片「可怜人意，薄于云水，佳会更难重。细想从来，断肠多处，不与者番同」写可怜人意薄于云水、佳会更难重，细想从来断肠多处、不与者番同，以「人意薄于云水」写人情的淡薄——人还不如云和水，以「不与者番同」写这次离别最断肠，全词层层递进、情感深沉，「可怜人意，薄于云水」成为名句。","b":"晏几道这首《少年游》写离别的痛苦，以「人意薄于云水」写人情的淡薄，是婉约词的名篇。","n":["少年游：词牌名","离多最是：离多最是","东西流水：东西流水","终解两相逢：终解两相逢（流水东西流去还能相逢）","浅情终似：浅情终似","行云无定：行云无定","犹到梦魂中：犹到梦魂中（行云还能到梦中）","可怜人意：可怜人意","薄于云水：薄于云水（人的情意比云和水还薄）","佳会更难重：佳会更难重","细想从来：细想从来","断肠多处：断肠多处","不与者番同：不与者番（这次）同。者同「这」"],"m":"可怜人意，薄于云水，佳会更难重。","r":"按「离多最是—东西流水—终解相逢—浅情终似—行云无定—犹到梦魂—可怜人意—薄于云水—佳会难重—细想从来—断肠多处—不与者番同」背；「者」同这；以云水反衬人意是核心。"},"思远人|晏几道":{"s":"上片「红叶黄花秋意晚，千里念行客。飞云过尽，归鸿无信，何处寄书得」写红叶黄花秋意晚、千里念行客，飞云过尽归鸿无信、何处寄书得，以秋景写相思；下片「泪弹不尽临窗滴。就砚旋研墨。渐写到别来，此情深处，红笺为无色」写泪弹不尽临窗滴、就砚旋研墨，渐写到别来此情深处、红笺为无色，以「泪滴研墨」「红笺无色」的细节写情之深——眼泪滴到砚台里研墨，写到情深处红笺都被泪浸湿褪色，想象奇特、细节生动，全词意境凄清、情感深沉，「红笺为无色」成为千古名句。","b":"晏几道这首《思远人》写闺中女子思念远人、写信寄情，以「红笺为无色」写泪之多、情之深，是婉约词的千古名篇。","n":["思远人：词牌名（晏几道自度曲）","红叶黄花秋意晚：红叶黄花秋意晚","千里念行客：千里念行客","飞云过尽：飞云过尽","归鸿无信：归鸿无信","何处寄书得：何处寄书得","泪弹不尽临窗滴：泪弹不尽临窗滴","就砚旋研墨：就砚台随即研墨","渐写到别来：渐写到别来","此情深处：此情深处","红笺为无色：红笺（红纸）为无色（被泪浸湿褪色）"],"m":"渐写到别来，此情深处，红笺为无色。","r":"按「红叶黄花—秋意晚—千里念客—飞云过尽—归鸿无信—何处寄书—泪弹不尽—临窗滴—就砚研墨—写到别来—此情深处—红笺无色」背；「泪滴研墨」「红笺无色」的细节是核心。"},"57824:浣溪沙|晏殊":{"s":"上片「一曲新词酒一杯。去年天气旧亭台。夕阳西下几时回」写一曲新词酒一杯、去年天气旧亭台，夕阳西下几时回，以新词美酒与旧亭台对比写时光流逝；下片「无可奈何花落去，似曾相识燕归来。小园香径独徘徊」写无可奈何花落去、似曾相识燕归来，小园香径独徘徊，以「花落去」「燕归来」写春去春来、时光流逝，「无可奈何」与「似曾相识」对比，蕴含深刻的人生哲理，全词意境清丽、哲理深沉，「无可奈何花落去，似曾相识燕归来」成为千古名句，是婉约词的千古名篇。","b":"晏殊（北宋词人，官至宰相，「大晏」）这首《浣溪沙》写伤春惜时之情，「无可奈何花落去，似曾相识燕归来」是千古名句，是婉约词的千古名篇。","n":["浣溪沙：词牌名","一曲新词酒一杯：一曲新词酒一杯","去年天气旧亭台：去年天气旧亭台","夕阳西下几时回：夕阳西下几时回","无可奈何花落去：无可奈何花落去","似曾相识燕归来：似曾相识燕归来","小园香径独徘徊：小园香径独徘徊"],"m":"无可奈何花落去，似曾相识燕归来。","r":"按「一曲新词—酒一杯—去年天气—旧亭台—夕阳西下—几时回—无可奈何—花落去—似曾相识—燕归来—小园香径—独徘徊」背；「无可奈何」与「似曾相识」的对比是核心；人生哲理是主题。"},"57838:鹊踏枝・蝶恋花|晏殊":{"s":"上片「槛菊愁烟兰泣露。罗幕轻寒，燕子双飞去。明月不谙离恨苦，斜光到晓穿朱户」写槛菊愁烟兰泣露、罗幕轻寒燕子双飞，明月不谙离恨苦、斜光到晓穿朱户，以菊愁兰泣、燕双飞写思妇的孤独；下片「昨夜西风凋碧树。独上高楼，望尽天涯路。欲寄彩笺兼尺素，山长水阔知何处」写昨夜西风凋碧树、独上高楼望尽天涯路，欲寄彩笺兼尺素、山长水阔知何处，以「独上高楼，望尽天涯路」写思妇的执着与迷茫，意境开阔、情感深沉，「昨夜西风凋碧树，独上高楼，望尽天涯路」成为千古名句，王国维列为人生三境界之第一境界。","b":"晏殊这首《蝶恋花》写闺中思妇的离愁，「昨夜西风凋碧树，独上高楼，望尽天涯路」是千古名句，王国维在《人间词话》中将其列为「古今之成大事业、大学问者」的第一境界。","n":["鹊踏枝：词牌名，即《蝶恋花》","槛菊愁烟兰泣露：栏外菊花愁于烟、兰花泣于露","罗幕轻寒：罗幕轻寒","燕子双飞去：燕子双飞去","明月不谙离恨苦：明月不谙（熟悉）离恨苦。谙音ān","斜光到晓穿朱户：斜光到晓穿朱户","昨夜西风凋碧树：昨夜西风凋碧树","独上高楼：独上高楼","望尽天涯路：望尽天涯路","欲寄彩笺兼尺素：欲寄彩笺（彩色信纸）兼尺素（书信）","山长水阔知何处：山长水阔知何处"],"m":"昨夜西风凋碧树。独上高楼，望尽天涯路。","r":"按「槛菊愁烟—兰泣露—罗幕轻寒—燕子双飞—明月不谙—斜光穿户—昨夜西风—凋碧树—独上高楼—望尽天涯—欲寄彩笺—兼尺素—山长水阔—知何处」背；「谙」读ān；王国维三境界第一境界是背景；意境开阔是核心。"},"57848:清平乐|晏殊":{"s":"上片「红笺小字。说尽平生意。鸿雁在云鱼在水。惆怅此情难寄」写红笺小字说尽平生意，鸿雁在云鱼在水、惆怅此情难寄，以雁鱼传书的典故写信难寄；下片「斜阳独倚西楼。遥山恰对帘钩。人面不知何处，绿波依旧东流」写斜阳独倚西楼、遥山恰对帘钩，人面不知何处、绿波依旧东流，以「人面不知何处，绿波依旧东流」写物是人非——人不知去了哪里，只有绿波依旧东流，用崔护典故，全词意境清丽、情感深沉，「人面不知何处，绿波依旧东流」成为名句。","b":"晏殊这首《清平乐》写思念情人的惆怅，以「人面不知何处，绿波依旧东流」写物是人非，是婉约词的名篇。","n":["清平乐：词牌名","红笺小字：红笺小字","说尽平生意：说尽平生意","鸿雁在云鱼在水：鸿雁在云鱼在水（雁足传书、鱼腹藏书的典故）","惆怅此情难寄：惆怅此情难寄","斜阳独倚西楼：斜阳独倚西楼","遥山恰对帘钩：遥山恰对帘钩","人面不知何处：人面不知何处（用崔护「人面不知何处去，桃花依旧笑春风」）","绿波依旧东流：绿波依旧东流"],"m":"人面不知何处，绿波依旧东流。","r":"按「红笺小字—说尽平生意—鸿雁在云—鱼在水—惆怅难寄—斜阳独倚—遥山帘钩—人面不知—绿波东流」背；用典（雁足传书、鱼腹藏书、崔护人面桃花）；物是人非是核心。"},"57856:采桑子|晏殊":{"s":"上片「时光只解催人老。不信多情。长恨离亭。泪滴春衫酒易醒」写时光只解催人老、不信多情，长恨离亭、泪滴春衫酒易醒，以时光催人写离情；下片「梧桐昨夜西风急。淡月胧明。好梦频惊。何处高楼雁一声」写梧桐昨夜西风急、淡月胧明，好梦频惊、何处高楼雁一声，以「雁一声」写惊梦后的凄凉——一声雁叫惊醒好梦，不知从何处高楼传来，以声写情，全词意境凄清、情感深沉，「时光只解催人老」成为名句。","b":"晏殊这首《采桑子》写时光流逝与离情，以「何处高楼雁一声」写惊梦后的凄凉，是婉约词的名篇。","n":["采桑子：词牌名","时光只解催人老：时光只解催人老","不信多情：不信多情","长恨离亭：长恨离亭","泪滴春衫酒易醒：泪滴春衫酒易醒","梧桐昨夜西风急：梧桐昨夜西风急","淡月胧明：淡月胧明","好梦频惊：好梦频惊","何处高楼雁一声：何处高楼雁一声"],"m":"时光只解催人老，不信多情。","r":"按「时光催人—不信多情—长恨离亭—泪滴春衫—酒易醒—梧桐西风—淡月胧明—好梦频惊—高楼雁一声」背；以雁声写情是核心；时光流逝是主题。"},"57870:木兰花・玉楼春|晏殊":{"s":"上片「东风昨夜回梁苑。日脚依稀添一线。旋开杨柳绿蛾眉，暗拆海棠红粉面」写东风昨夜回梁苑、日脚添一线，旋开杨柳绿蛾眉、暗拆海棠红粉面，以柳叶如蛾眉、海棠如粉面写初春的美好；下片「无情一去云中雁。有意归来梁上燕。有情无意且休论，莫向酒杯容易散」写无情一去云中雁、有意归来梁上燕，有情无意且休论、莫向酒杯容易散，以雁去燕来写春的来去、以「莫向酒杯容易散」写惜春之情，全词色彩明丽、对仗工稳，「无情一去云中雁，有意归来梁上燕」成为名句。","b":"晏殊这首《玉楼春》写初春景色与惜春之情，以「无情一去云中雁，有意归来梁上燕」写春的来去，是婉约词的名篇。","n":["木兰花：词牌名，即《玉楼春》","东风昨夜回梁苑：东风昨夜回梁苑（梁苑，汉梁孝王的兔园，此指园林）","日脚依稀添一线：日脚依稀添一线（冬至后日长一线）","旋开杨柳绿蛾眉：旋开杨柳绿蛾眉（柳叶如蛾眉）","暗拆海棠红粉面：暗拆海棠红粉面（海棠如红粉面）","无情一去云中雁：无情一去云中雁","有意归来梁上燕：有意归来梁上燕","有情无意且休论：有情无意且休论","莫向酒杯容易散：莫向酒杯容易散"],"m":"无情一去云中雁，有意归来梁上燕。","r":"按「东风回苑—日脚添线—杨柳蛾眉—海棠粉面—云中雁去—梁上燕来—有情无意—莫散酒杯」背；以雁去燕来写春来去是核心；惜春之情是主题。"},"57883:诉衷情|晏殊":{"s":"上片「芙蓉金菊斗馨香。天气欲重阳。远村秋色如画，红树间疏黄」写芙蓉金菊斗馨香、天气欲重阳，远村秋色如画、红树间疏黄，以秋色写重阳前的景色；下片「流水淡，碧天长。路茫茫。凭高目断，鸿雁来时，无限思量」写流水淡碧天长路茫茫，凭高目断、鸿雁来时无限思量，以「凭高目断」「鸿雁来时」写思乡——登高望远，大雁飞来时引起无限思量，全词意境开阔、情感深沉，「凭高目断，鸿雁来时，无限思量」成为名句。","b":"晏殊这首《诉衷情》写重阳前的秋色与思乡之情，以「凭高目断，鸿雁来时，无限思量」写秋思，是婉约词的名篇。","n":["诉衷情：词牌名","芙蓉金菊斗馨香：芙蓉金菊斗馨香","天气欲重阳：天气欲重阳","远村秋色如画：远村秋色如画","红树间疏黄：红树间疏黄","流水淡：流水淡","碧天长：碧天长","路茫茫：路茫茫","凭高目断：凭高目断","鸿雁来时：鸿雁来时","无限思量：无限思量"],"m":"凭高目断，鸿雁来时，无限思量。","r":"按「芙蓉金菊—斗馨香—天气重阳—远村秋色—红树疏黄—流水淡—碧天长—路茫茫—凭高目断—鸿雁来时—无限思量」背；以鸿雁写思乡是核心；秋色如画是特点。"},"73999:鹧鸪天|朱敦儒":{"s":"上片「我是清都山水郎。天教懒慢带疏狂。曾批给露支风敕，累奏留云借月章」写我是清都山水郎、天教懒慢带疏狂，曾批给露支风敕、累奏留云借月章，以「清都山水郎」的自称写疏狂；下片「诗万首，酒千觞。几曾着眼看侯王。玉楼金阙慵归去，且插梅花醉洛阳」写诗万首酒千觞、几曾着眼看侯王，玉楼金阙慵归去、且插梅花醉洛阳，以「几曾着眼看侯王」写对功名的蔑视、以「插梅花醉洛阳」写疏狂，全词气势豪迈、语言明快，「诗万首，酒千觞，几曾着眼看侯王」成为千古名句。","b":"朱敦儒（南宋词人，号岩壑）这首《鹧鸪天》写自己的疏狂与对功名的蔑视，「诗万首，酒千觞，几曾着眼看侯王」是千古名句，是南宋词的名篇。","n":["鹧鸪天：词牌名","我是清都山水郎：我是清都（天宫）山水郎（管理山水的官）","天教懒慢带疏狂：天教懒慢带疏狂","曾批给露支风敕：曾批给露支风的敕令（管理风雨的命令）。敕音chì","累奏留云借月章：屡次上奏留云借月的奏章","诗万首：诗万首","酒千觞：酒千觞。觞音shāng，酒杯","几曾着眼看侯王：几曾着眼看侯王","玉楼金阙慵归去：玉楼金阙（天宫）慵（懒）归去","且插梅花醉洛阳：且插梅花醉洛阳"],"m":"诗万首，酒千觞，几曾着眼看侯王。","r":"按「清都山水郎—天教疏狂—给露支风—留云借月—诗万首—酒千觞—几曾看侯王—玉楼慵归—插梅醉洛阳」背；「敕」读chì、「觞」读shāng；疏狂与蔑视功名是核心。"},"74074:好事近|朱敦儒":{"s":"上片「摇首出红尘。醒醉更无时节。活计绿蓑青笠，惯披霜冲雪」写摇首出红尘、醒醉无时节，活计绿蓑青笠、惯披霜冲雪，以渔父生活写自由；下片「晚来风定钓丝闲。上下是新月。千里水天一色，看孤鸿明灭」写晚来风定钓丝闲、上下是新月，千里水天一色、看孤鸿明灭，以「水天一色」「孤鸿明灭」写自由的境界，全词意境开阔、语言明快，「千里水天一色，看孤鸿明灭」成为名句。","b":"朱敦儒这首《好事近》写渔父的隐居生活，以「千里水天一色，看孤鸿明灭」写自由的境界，是南宋词的名篇。","n":["好事近：词牌名","摇首出红尘：摇首出红尘（尘世）","醒醉更无时节：醒醉更无时节","活计绿蓑青笠：活计是绿蓑青笠（蓑衣斗笠）","惯披霜冲雪：惯披霜冲雪","晚来风定钓丝闲：晚来风定钓丝闲","上下是新月：上下是新月","千里水天一色：千里水天一色","看孤鸿明灭：看孤鸿明灭（忽明忽暗）"],"m":"千里水天一色，看孤鸿明灭。","r":"按「摇首红尘—醒醉无节—绿蓑青笠—披霜冲雪—风定钓闲—上下新月—水天一色—孤鸿明灭」背；自由境界是核心；以景写情是手法。"},"74094:西江月|朱敦儒":{"s":"上片「日日深杯酒满。朝朝小圃花开。自歌自舞自开怀。且喜无拘无碍」写日日深杯酒满、朝朝小圃花开，自歌自舞自开怀、且喜无拘无碍，以隐居生活写快乐；下片「青史几番春梦。黄泉多少奇才。不须计较与安排。领取而今现在」写青史几番春梦、黄泉多少奇才，不须计较与安排、领取而今现在，以「青史春梦」「黄泉奇才」写人生短暂、以「领取而今现在」写及时行乐，全词语言明快、哲理深沉，「领取而今现在」成为名句。","b":"朱敦儒这首《西江月》写隐居生活的旷达，以「领取而今现在」写及时行乐的人生态度，是南宋词的名篇。","n":["西江月：词牌名","日日深杯酒满：日日深杯酒满","朝朝小圃花开：朝朝小圃花开","自歌自舞自开怀：自歌自舞自开怀","且喜无拘无碍：且喜无拘无碍","青史几番春梦：青史几番春梦","黄泉多少奇才：黄泉多少奇才","不须计较与安排：不须计较与安排","领取而今现在：领取而今现在"],"m":"不须计较与安排，领取而今现在。","r":"按「深杯酒满—小圃花开—自歌自舞—无拘无碍—青史春梦—黄泉奇才—不须计较—领取现在」背；旷达人生态度是核心；哲理深沉是特点。"},"74177:相见欢|朱敦儒":{"s":"上片「金陵城上西楼。倚清秋。万里夕阳垂地、大江流」写金陵城上西楼、倚清秋，万里夕阳垂地大江流，以夕阳大江写亡国的苍凉；下片「中原乱。簪缨散。几时收。试倩悲风吹泪、过扬州」写中原乱、簪缨散、几时收，试倩悲风吹泪过扬州，以「中原乱，簪缨散，几时收」写亡国之痛与收复之望、以「悲风吹泪过扬州」写对中原的思念，全词意境苍凉、情感激烈，「中原乱，簪缨散，几时收」成为千古名句，是南宋爱国词的名篇。","b":"朱敦儒这首《相见欢》写登金陵城楼所见与亡国之痛，「中原乱，簪缨散，几时收」是千古名句，是南宋爱国词的名篇。","n":["相见欢：词牌名","金陵城上西楼：金陵城上西楼","倚清秋：倚清秋","万里夕阳垂地、大江流：万里夕阳垂地大江流","中原乱：中原乱（靖康之变）","簪缨散：簪缨（官员）散","几时收：几时收（收复）","试倩悲风吹泪、过扬州：试请悲风吹泪过扬州。倩音qìng，请"],"r":"按「金陵西楼—倚清秋—万里夕阳—大江流—中原乱—簪缨散—几时收—倩悲风—吹泪过扬州」背；「倩」读qìng；亡国之痛是核心；与岳飞《满江红》对读。"},"卜算子|李之仪":{"s":"上片「我住长江头，君住长江尾。日日思君不见君，共饮长江水」写我住长江头、君住长江尾，日日思君不见君、共饮长江水，以长江水为喻写两地相思——虽然相隔千里，但共饮一江水；下片「此水几时休，此恨何时已。只愿君心似我心，定不负相思意」写此水几时休、此恨何时已，只愿君心似我心、定不负相思意，以江水无尽写相思无尽、以「君心似我心」写对爱情的坚贞，全词语言朴素、比喻巧妙、情感深沉，「我住长江头，君住长江尾」成为千古名句，是婉约词的千古名篇。","b":"李之仪（北宋词人）这首《卜算子》写女子对情人的相思，以长江水为喻，「我住长江头，君住长江尾。日日思君不见君，共饮长江水」是千古名句，是婉约词的千古名篇。","n":["卜算子：词牌名","我住长江头：我住长江头","君住长江尾：君住长江尾","日日思君不见君：日日思君不见君","共饮长江水：共饮长江水","此水几时休：此水几时休","此恨何时已：此恨何时已","只愿君心似我心：只愿君心似我心","定不负相思意：定不负相思意"],"m":"我住长江头，君住长江尾。日日思君不见君，共饮长江水。","r":"按「我住江头—君住江尾—日日思君—不见君—共饮江水—此水几时休—此恨何时已—君心似我心—不负相思」背；以长江水为喻是核心；民歌风格是特点。"},"孤雁儿・御街行|李清照":{"s":"上片「藤床纸帐朝眠起。说不尽、无佳思。沈香断续玉炉寒，伴我情怀如水。笛里三弄，梅心惊破，多少春情意」写藤床纸帐朝眠起、说不尽无佳思，沉香断续玉炉寒、伴我情怀如水，笛里三弄梅心惊破、多少春情意，以独居生活写孤独；下片「小风疏雨萧萧地。又催下、千行泪。吹箫人去玉楼空，肠断与谁同倚。一枝折得，人间天上，没个人堪寄」写小风疏雨萧萧、又催下千行泪，吹箫人去玉楼空、肠断与谁同倚，一枝折得人间天上、没个人堪寄，以「吹箫人去」写丈夫去世、以「没个人堪寄」写悼亡之痛——折了梅花却无人可寄，全词意境凄清、情感深沉，「吹箫人去玉楼空，肠断与谁同倚」成为名句，是婉约词的千古名篇。","b":"李清照（南宋女词人，号易安居士）这首《孤雁儿》是她丈夫赵明诚去世后所作，写悼亡之情，「吹箫人去玉楼空，肠断与谁同倚」是名句，是婉约词的千古名篇。","n":["孤雁儿：词牌名，即《御街行》","藤床纸帐朝眠起：藤床纸帐朝眠起","说不尽、无佳思：说不尽无佳思","沈香断续玉炉寒：沉香断续玉炉寒。沈同「沉」","伴我情怀如水：伴我情怀如水","笛里三弄：笛里三弄（《梅花三弄》笛曲）","梅心惊破：梅心惊破","多少春情意：多少春情意","小风疏雨萧萧地：小风疏雨萧萧地","又催下、千行泪：又催下千行泪","吹箫人去玉楼空：吹箫人去玉楼空（用萧史弄玉吹箫引凤典故，指丈夫去世）","肠断与谁同倚：肠断与谁同倚","一枝折得：一枝折得（折梅）","人间天上：人间天上","没个人堪寄：没个人堪寄（无人可寄）"],"m":"吹箫人去玉楼空，肠断与谁同倚。","r":"按「藤床纸帐—朝眠起—无佳思—沉香断续—玉炉寒—情怀如水—笛里三弄—梅心惊破—春情意—小风疏雨—千行泪—吹箫人去—玉楼空—肠断谁倚—一枝折得—人间天上—无人堪寄」背；「沈」同沉；用典（萧史弄玉吹箫、陆凯寄梅）；悼亡之情是核心。"},"75026:渔家傲|李清照":{"s":"上片「雪里已知春信至。寒梅点缀琼枝腻。香脸半开娇旖旎。当庭际。玉人浴出新妆洗」写雪里已知春信至、寒梅点缀琼枝腻，香脸半开娇旖旎、当庭际玉人浴出新妆洗，以「玉人浴出」比喻梅花的美丽；下片「造化可能偏有意。故教明月玲珑地。共赏金尊沈绿蚁。莫辞醉。此花不与群花比」写造化可能偏有意、故教明月玲珑地，共赏金尊沉绿蚁、莫辞醉，此花不与群花比，以「此花不与群花比」写梅的高洁，全词色彩明丽、比喻巧妙，「此花不与群花比」成为名句。","b":"李清照这首《渔家傲》写寒梅的美丽与高洁，以「此花不与群花比」写梅的品格，是咏梅词的名篇。","n":["渔家傲：词牌名","雪里已知春信至：雪里已知春信至","寒梅点缀琼枝腻：寒梅点缀琼枝（如玉的枝）腻（细腻）","香脸半开娇旖旎：香脸半开娇旖旎（柔美）。旖旎音yǐnǐ","当庭际：当庭际","玉人浴出新妆洗：玉人浴出新妆洗","造化可能偏有意：造化可能偏有意","故教明月玲珑地：故教明月玲珑地","共赏金尊沈绿蚁：共赏金尊沉绿蚁（酒面上的泡沫，代指酒）。沈同「沉」","莫辞醉：莫辞醉","此花不与群花比：此花不与群花比"],"m":"此花不与群花比。","r":"按「雪里春信—寒梅琼枝—香脸半开—娇旖旎—当庭际—玉人浴出—造化有意—明月玲珑—金尊绿蚁—莫辞醉—此花不与群花比」背；「旖旎」读yǐnǐ、「沈」同沉；以玉人喻梅是核心；高洁品格是主题。"},"75031:如梦令|李清照":{"s":"全词「常记溪亭日暮。沈醉不知归路。兴尽晚回舟，误入藕花深处。争渡。争渡。惊起一滩鸥鹭」写常记溪亭日暮、沉醉不知归路，兴尽晚回舟、误入藕花深处，争渡争渡、惊起一滩鸥鹭，以「误入藕花深处」「争渡」「惊起鸥鹭」写郊游的欢乐与少女的天真，全词语言明快、画面生动、情感欢乐，「争渡，争渡，惊起一滩鸥鹭」成为千古名句，是婉约词的千古名篇，也是李清照早期词的代表作。","b":"李清照这首《如梦令》是她少女时代的作品，写一次郊游的欢乐经历，「争渡，争渡，惊起一滩鸥鹭」是千古名句，是婉约词的千古名篇。","n":["如梦令：词牌名","常记溪亭日暮：常记溪亭日暮","沈醉不知归路：沉醉不知归路。沈同「沉」","兴尽晚回舟：兴尽晚回舟","误入藕花深处：误入藕花深处","争渡：争渡（怎么渡出去，一说「怎渡」）","争渡：争渡","惊起一滩鸥鹭：惊起一滩鸥鹭"],"m":"争渡。争渡。惊起一滩鸥鹭。","r":"按「常记溪亭—日暮—沉醉归路—兴尽回舟—误入藕花—争渡—争渡—惊起鸥鹭」背；「沈」同沉；少女天真与郊游欢乐是核心；画面生动是特点。"},"75034:菩萨蛮|李清照":{"s":"上片「风柔日薄春犹早。夹衫乍著心情好。睡起觉微寒。梅花鬓上残」写风柔日薄春犹早、夹衫乍著心情好，睡起觉微寒、梅花鬓上残，以早春景色写南渡后的生活；下片「故乡何处是。忘了除非醉。沈水卧时烧。香消酒未消」写故乡何处是、忘了除非醉，沉水卧时烧、香消酒未消，以「忘了除非醉」写思乡之深——只有喝醉了才能忘记故乡，以「香消酒未消」写酒醒后的痛苦，全词意境凄清、情感深沉，「故乡何处是，忘了除非醉」成为千古名句，是婉约词的千古名篇。","b":"李清照这首《菩萨蛮》是她南渡后所作，写思乡之情，「故乡何处是，忘了除非醉」是千古名句，是婉约词的千古名篇。","n":["菩萨蛮：词牌名","风柔日薄春犹早：风柔日薄春犹早","夹衫乍著心情好：夹衫乍著（刚穿上）心情好。著同「着」","睡起觉微寒：睡起觉微寒","梅花鬓上残：梅花鬓上残","故乡何处是：故乡何处是","忘了除非醉：忘了除非醉","沈水卧时烧：沉水（沉香）卧时烧。沈同「沉」","香消酒未消：香消酒未消"],"m":"故乡何处是，忘了除非醉。","r":"按「风柔日薄—春犹早—夹衫乍著—心情好—睡起微寒—梅花鬓残—故乡何处—忘了除非醉—沉水卧烧—香消酒未消」背；「著」同着、「沈」同沉；思乡之情是核心；「忘了除非醉」是名句。"},"凤凰台上忆吹箫|李清照":{"s":"上片「香冷金猊，被翻红浪，起来人未梳头。任宝奁闲掩，日上帘钩。生怕闲愁暗恨，多少事、欲说还休。今年瘦，非干病酒，不是悲秋」写香冷金猊、被翻红浪、起来未梳头，任宝奁闲掩日上帘钩，生怕闲愁暗恨、多少事欲说还休，今年瘦非干病酒不是悲秋，以「欲说还休」「非干病酒，不是悲秋」写离情的深沉——瘦了不是因为醉酒也不是因为悲秋，而是因为离别；下片「明朝，这回去也，千万遍阳关，也即难留。念武陵春晚，云锁重楼。记取楼前绿水，应念我、终日凝眸。凝眸处，从今更数，几段新愁」写明朝这回去也、千万遍阳关也难留，念武陵春晚云锁重楼，记取楼前绿水应念我终日凝眸，凝眸处从今更数几段新愁，以「千万遍阳关也难留」写离别的无奈、以「终日凝眸」写思念，全词意境凄清、情感深沉，「今年瘦，非干病酒，不是悲秋」「多少事、欲说还休」成为千古名句，是婉约词的千古名篇。","b":"李清照这首《凤凰台上忆吹箫》是她与丈夫赵明诚离别时所作，写离情，「今年瘦，非干病酒，不是悲秋」「多少事、欲说还休」是千古名句，是婉约词的千古名篇。","n":["凤凰台上忆吹箫：词牌名","香冷金猊：香冷金猊（狮形香炉）。猊音ní","被翻红浪：被翻红浪（红被乱翻如浪）","起来人未梳头：起来人未梳头","任宝奁闲掩：任宝奁（梳妆匣）闲掩。奁音lián","日上帘钩：日上帘钩","生怕闲愁暗恨：生怕闲愁暗恨","多少事、欲说还休：多少事欲说还休","今年瘦：今年瘦","非干病酒：非干病酒（不是因为醉酒）","不是悲秋：不是悲秋","明朝：明朝","这回去也：这回去也","千万遍阳关：千万遍阳关（《阳关三叠》送别曲）","也即难留：也即难留","念武陵春晚：念武陵春晚（武陵，陶渊明《桃花源记》，此指与丈夫的美好时光）","云锁重楼：云锁重楼","记取楼前绿水：记取楼前绿水","应念我、终日凝眸：应念我终日凝眸","凝眸处：凝眸处","从今更数：从今更数","几段新愁：几段新愁"],"m":"今年瘦，非干病酒，不是悲秋。","r":"按「香冷金猊—被翻红浪—起来未梳—宝奁闲掩—日上帘钩—闲愁暗恨—欲说还休—今年瘦—非干病酒—不是悲秋—明朝归去—千万遍阳关—难留—武陵春晚—云锁重楼—楼前绿水—终日凝眸—从今更数—几段新愁」背；「猊」读ní、「奁」读lián；用典（萧史弄玉吹箫、阳关三叠、武陵桃花源）；「非干病酒，不是悲秋」是名句。"},"一剪梅・一翦梅|李清照":{"s":"上片「红藕香残玉簟秋。轻解罗裳，独上兰舟。雪中谁寄锦书来，雁字回时，月满西楼」写红藕香残玉簟秋、轻解罗裳独上兰舟，雪中谁寄锦书来、雁字回时月满西楼，以秋景写相思；下片「花自飘零水自流。一种相思，两处闲愁。此情无计可消除，才下眉头，却上心头」写花自飘零水自流、一种相思两处闲愁，此情无计可消除、才下眉头却上心头，以「才下眉头，却上心头」写相思的无法排遣——刚从眉头消失，又涌上心头，全词意境凄清、情感深沉，「此情无计可消除，才下眉头，却上心头」成为千古名句，是婉约词的千古名篇。","b":"李清照这首《一剪梅》是她与丈夫赵明诚离别后所作，写相思之情，「此情无计可消除，才下眉头，却上心头」是千古名句，是婉约词的千古名篇。","n":["一剪梅：词牌名","红藕香残玉簟秋：红藕香残玉簟（竹席）秋。簟音diàn","轻解罗裳：轻解罗裳","独上兰舟：独上兰舟","雪中谁寄锦书来：雪中谁寄锦书来（雁足传书）","雁字回时：雁字回时","月满西楼：月满西楼","花自飘零水自流：花自飘零水自流","一种相思：一种相思","两处闲愁：两处闲愁","此情无计可消除：此情无计可消除","才下眉头：才下眉头","却上心头：却上心头"],"m":"此情无计可消除，才下眉头，却上心头。","r":"按「红藕香残—玉簟秋—轻解罗裳—独上兰舟—谁寄锦书—雁字回时—月满西楼—花自飘零—水自流—一种相思—两处闲愁—无计消除—才下眉头—却上心头」背；「簟」读diàn；用典（雁足传书）；「才下眉头，却上心头」是名句。"},"75043:鹧鸪天|李清照":{"s":"上片「寒日萧萧上锁窗。梧桐应恨夜来霜。酒阑更喜团茶苦，梦断偏宜瑞脑香」写寒日萧萧上锁窗、梧桐应恨夜来霜，酒阑更喜团茶苦、梦断偏宜瑞脑香，以秋景写凄凉；下片「秋已尽，日犹长。仲宣怀远更凄凉。不如随分尊前醉，莫负东篱菊蕊黄」写秋已尽日犹长、仲宣怀远更凄凉，不如随分尊前醉、莫负东篱菊蕊黄，以王粲登楼怀远写思乡、以「尊前醉」「莫负菊蕊」写借酒排遣，全词意境凄清、用典贴切（王粲登楼、陶渊明东篱），「仲宣怀远更凄凉」成为名句。","b":"李清照这首《鹧鸪天》写秋日的凄凉与借酒排遣，以「仲宣怀远更凄凉」写思乡，是婉约词的名篇。","n":["鹧鸪天：词牌名","寒日萧萧上锁窗：寒日萧萧上锁窗","梧桐应恨夜来霜：梧桐应恨夜来霜","酒阑更喜团茶苦：酒阑更喜团茶苦","梦断偏宜瑞脑香：梦断偏宜瑞脑（香料）香","秋已尽：秋已尽","日犹长：日犹长","仲宣怀远更凄凉：仲宣（王粲，字仲宣，作《登楼赋》怀远）怀远更凄凉","不如随分尊前醉：不如随分（随缘）尊前醉","莫负东篱菊蕊黄：莫负东篱（陶渊明「采菊东篱下」）菊蕊黄"],"m":"仲宣怀远更凄凉。","r":"按「寒日萧萧—上锁窗—梧桐恨霜—酒阑团茶—梦断瑞脑—秋已尽—日犹长—仲宣怀远—随分尊醉—莫负东篱」背；用典（王粲登楼、陶渊明东篱）；思乡与借酒排遣是核心。"},"醉花阴|李清照":{"s":"上片「薄雾浓云愁永昼。瑞脑消金兽。佳节又重阳，玉枕纱厨，半夜凉初透」写薄雾浓云愁永昼、瑞脑消金兽，佳节又重阳、玉枕纱厨半夜凉初透，以重阳景色写相思；下片「东篱把洒黄昏后，有暗香盈袖。莫道不消魂，帘卷西风，人似黄花瘦」写东篱把酒黄昏后、有暗香盈袖，莫道不消魂、帘卷西风人似黄花瘦，以「人似黄花瘦」写相思之深——人比黄花还瘦，比喻新奇、情感深沉，全词意境凄清、比喻巧妙，「莫道不消魂，帘卷西风，人似黄花瘦」成为千古名句，是婉约词的千古名篇。","b":"李清照这首《醉花阴》是她重阳节思念丈夫赵明诚所作，「莫道不消魂，帘卷西风，人似黄花瘦」是千古名句，是婉约词的千古名篇，传说赵明诚读后自愧不如。","n":["醉花阴：词牌名","薄雾浓云愁永昼：薄雾浓云愁永昼（漫长的白天）","瑞脑消金兽：瑞脑在金兽（兽形香炉）中烧尽","佳节又重阳：佳节又重阳","玉枕纱厨：玉枕纱厨（纱帐）","半夜凉初透：半夜凉初透","东篱把洒黄昏后：东篱把酒黄昏后（陶渊明「采菊东篱下」）","有暗香盈袖：有暗香盈袖","莫道不消魂：莫道不消魂","帘卷西风：帘卷西风","人似黄花瘦：人似黄花瘦"],"m":"莫道不消魂，帘卷西风，人似黄花瘦。","r":"按「薄雾浓云—愁永昼—瑞脑金兽—佳节重阳—玉枕纱厨—半夜凉透—东篱把酒—黄昏后—暗香盈袖—莫道消魂—帘卷西风—人似黄花瘦」背；用典（陶渊明东篱把酒）；「人似黄花瘦」的比喻是核心。"},"添字丑奴儿・采桑子|李清照":{"s":"上片「窗前谁种芭蕉树。阴满中庭。阴满中庭。叶叶心心，舒卷有余情」写窗前谁种芭蕉树、阴满中庭，叶叶心心舒卷有余情，以芭蕉写愁；下片「伤心枕上三更雨。点滴霖霪。点滴霖霪。愁损北人，不惯起来听」写伤心枕上三更雨、点滴霖霪，愁损北人不惯起来听，以「三更雨」「点滴霖霪」写雨的绵密、以「愁损北人」写南渡后的思乡——北方人不习惯听这南方的芭蕉雨，全词意境凄清、情感深沉，「愁损北人，不惯起来听」成为名句。","b":"李清照这首《添字丑奴儿》是她南渡后所作，写听雨的愁思，以「愁损北人，不惯起来听」写南渡后的思乡，是婉约词的名篇。","n":["添字丑奴儿：词牌名，即《采桑子》","窗前谁种芭蕉树：窗前谁种芭蕉树","阴满中庭：阴满中庭","阴满中庭：阴满中庭","叶叶心心：叶叶心心","舒卷有余情：舒卷有余情","伤心枕上三更雨：伤心枕上三更雨","点滴霖霪：点滴霖霪（连绵不断）。霖霪línyín","点滴霖霪：点滴霖霪","愁损北人：愁损北人（南渡的北方人，李清照自指）","不惯起来听：不惯起来听"],"m":"伤心枕上三更雨，点滴霖霪。","r":"按「谁种芭蕉—阴满中庭—叶叶心心—舒卷余情—伤心枕上—三更雨—点滴霖霪—愁损北人—不惯起来听」背；「霖霪」读línyín；南渡思乡是核心；以雨写愁是手法。"},"永遇乐|李清照":{"s":"上片「落日熔金，暮云合璧，人在何处。染柳烟浓，吹梅笛怨，春意知几许。元宵佳节，融和天气，次第岂无风雨。来相召、香车宝马，谢他酒朋诗侣」写落日熔金暮云合璧、人在何处，染柳烟浓吹梅笛怨、春意知几许，元宵佳节融和天气、次第岂无风雨，来相召香车宝马、谢他酒朋诗侣，以元宵景色写南渡后的孤独；下片「中州盛日，闺门多暇，记得偏重三五。铺翠冠儿，拈金雪柳，簇带争济楚。如今憔悴，风鬟霜鬓，怕见夜间出去。不如向、帘儿底下，听人笑语」写中州盛日闺门多暇、记得偏重三五，铺翠冠儿拈金雪柳簇带争济楚，如今憔悴风鬟霜鬓怕见夜间出去，不如向帘儿底下听人笑语，以汴京全盛时的元宵欢乐与如今的憔悴对比写亡国之痛，全词今昔对比、情感深沉，「不如向、帘儿底下，听人笑语」成为千古名句，是婉约词的千古名篇。","b":"李清照这首《永遇乐》是她南渡后元宵节所作，写今昔对比的亡国之痛，「不如向、帘儿底下，听人笑语」是千古名句，是婉约词的千古名篇，刘辰翁曾和其韵。","n":["永遇乐：词牌名","落日熔金：落日熔金（落日像熔化的金子）","暮云合璧：暮云合璧（暮云像合拢的玉璧）","人在何处：人在何处","染柳烟浓：染柳烟浓","吹梅笛怨：吹梅笛怨（《梅花落》笛曲哀怨）","春意知几许：春意知几许","元宵佳节：元宵佳节","融和天气：融和天气","次第岂无风雨：次第岂无风雨（接着难道没有风雨吗）","来相召、香车宝马：来相召香车宝马","谢他酒朋诗侣：谢他酒朋诗侣","中州盛日：中州盛日（汴京全盛时）","闺门多暇：闺门多暇","记得偏重三五：记得偏重三五（正月十五元宵节）","铺翠冠儿：铺翠冠儿（饰翠羽的帽子）","拈金雪柳：拈金雪柳（金线的雪柳，元宵节饰物）","簇带争济楚：簇带争济楚（打扮得整齐漂亮）","如今憔悴：如今憔悴","风鬟霜鬓：风鬟霜鬓（头发散乱斑白）","怕见夜间出去：怕见夜间出去","不如向、帘儿底下：不如向帘儿底下","听人笑语：听人笑语"],"m":"如今憔悴，风鬟霜鬓，怕见夜间出去。不如向、帘儿底下，听人笑语。","r":"按「落日熔金—暮云合璧—人在何处—染柳烟浓—吹梅笛怨—春意几许—元宵佳节—融和天气—岂无风雨—香车宝马—谢酒朋诗侣—中州盛日—闺门多暇—偏重三五—铺翠冠儿—拈金雪柳—簇带济楚—如今憔悴—风鬟霜鬓—怕见出去—帘儿底下—听人笑语」背；用典（《梅花落》笛曲）；今昔对比是核心；亡国之痛是主题。"},"点绛唇|李清照":{"s":"上片「寂寞深闺。柔肠一寸愁千缕。惜春春去。几点催花雨」写寂寞深闺、柔肠一寸愁千缕，惜春春去、几点催花雨，以「一寸愁千缕」写愁之深；下片「倚遍阑干。只是无情绪。人何处。连天衰草。望断归来路」写倚遍阑干、只是无情绪，人何处、连天衰草望断归来路，以「倚遍阑干」「望断归来路」写相思的执着，全词意境凄清、情感深沉，「柔肠一寸愁千缕」成为名句。","b":"李清照这首《点绛唇》是她早期作品，写闺中女子的相思，以「柔肠一寸愁千缕」写愁之深，是婉约词的名篇。","n":["点绛唇：词牌名","寂寞深闺：寂寞深闺","柔肠一寸愁千缕：柔肠一寸愁千缕","惜春春去：惜春春去","几点催花雨：几点催花雨","倚遍阑干：倚遍阑干","只是无情绪：只是无情绪","人何处：人何处","连天衰草：连天衰草","望断归来路：望断归来路"],"m":"柔肠一寸愁千缕。","r":"按「寂寞深闺—柔肠愁缕—惜春春去—催花雨—倚遍阑干—无情绪—人何处—连天衰草—望断归路」背；「一寸愁千缕」的夸张是核心；闺怨是主题。"},"75481:忆王孙|李重元":{"s":"全词「萋萋芳草忆王孙。柳外楼高空断魂。杜宇声声不忍闻。欲黄昏。雨打梨花深闭门」写萋萋芳草忆王孙、柳外楼高空断魂，杜宇声声不忍闻，欲黄昏雨打梨花深闭门，以芳草、柳外楼、杜宇、雨打梨花写春愁，「雨打梨花深闭门」的画面凄清动人，全词意境凄清、用典贴切（《楚辞》王孙芳草、杜鹃啼归），「雨打梨花深闭门」成为千古名句，是婉约词的千古名篇。","b":"李重元（北宋词人）这首《忆王孙》写闺中女子思念远人，以「雨打梨花深闭门」写春愁，是婉约词的千古名篇，「忆王孙」四首（春词、夏词、秋词、冬词）以此首最著名。","n":["忆王孙：词牌名","萋萋芳草忆王孙：萋萋芳草忆王孙（用《楚辞》「王孙游兮不归，春草生兮萋萋」）","柳外楼高空断魂：柳外楼高空断魂","杜宇声声不忍闻：杜宇（杜鹃）声声不忍闻","欲黄昏：欲黄昏","雨打梨花深闭门：雨打梨花深闭门"],"m":"欲黄昏。雨打梨花深闭门。","r":"按「萋萋芳草—忆王孙—柳外楼—空断魂—杜宇声声—不忍闻—欲黄昏—雨打梨花—深闭门」背；用典（《楚辞》王孙芳草、杜鹃啼归）；「雨打梨花深闭门」的画面是核心。"},"宿新市徐公店|杨万里":{"s":"首两句「篱落疏疏一径深，树头新绿未成阴」写篱笆稀疏小路深远、树头新绿未成阴，以乡村景色写环境；后两句「儿童急走追黄蝶，飞入菜花无处寻」是千古名句——儿童急跑追黄蝶、黄蝶飞入菜花无处寻，以「急走」「追」写儿童的天真、以「飞入菜花无处寻」写黄蝶与菜花同色的巧妙，画面生动、情趣盎然，全诗语言明快、充满生活气息，「儿童急走追黄蝶，飞入菜花无处寻」成为千古名句。","b":"杨万里（南宋诗人，「诚斋体」）这首《宿新市徐公店》写乡村儿童追蝶的情景，「儿童急走追黄蝶，飞入菜花无处寻」是千古名句，是南宋七绝的名篇。","n":["宿新市徐公店：住宿在新市徐公店","篱落疏疏一径深：篱笆稀疏一条小路深远","树头新绿未成阴：树头新绿未成阴（树荫）","儿童急走追黄蝶：儿童急跑追黄蝶","飞入菜花无处寻：飞入菜花无处寻"],"m":"儿童急走追黄蝶，飞入菜花无处寻。","r":"四句按「篱落疏疏—一径深—树头新绿—未成阴—儿童急走—追黄蝶—飞入菜花—无处寻」背；「急走」「追」的细节是核心；儿童天真是主题。"},"点绛唇|林逋":{"s":"上片「金谷年年。乱生春色谁为主。余花落处。满地和烟雨」写金谷年年乱生春色谁为主、余花落处满地和烟雨，以金谷园的春草写繁华不再；下片「又是离歌。一阕长亭暮。王孙去。萋萋无数。南北东西路」写又是离歌一阕长亭暮，王孙去萋萋无数南北东西路，以「萋萋无数，南北东西路」写春草的无边与离情的无尽——春草长满了南北东西的路，王孙却不知去了哪里，全词意境凄清、用典贴切（金谷园、《楚辞》王孙芳草），「萋萋无数，南北东西路」成为名句。","b":"林逋（北宋诗人，隐居西湖孤山，「梅妻鹤子」）这首《点绛唇》写春草与离别，以「萋萋无数，南北东西路」写离情，是婉约词的名篇。","n":["点绛唇：词牌名","金谷年年：金谷（金谷园，晋石崇的园林，此指繁华之地）年年","乱生春色谁为主：乱生春色谁为主","余花落处：余花落处","满地和烟雨：满地和烟雨","又是离歌：又是离歌","一阕长亭暮：一阕长亭暮","王孙去：王孙去（用《楚辞》「王孙游兮不归」）","萋萋无数：萋萋无数","南北东西路：南北东西路"],"m":"王孙去。萋萋无数，南北东西路。","r":"按「金谷年年—春色谁主—余花落处—满地烟雨—又是离歌—长亭暮—王孙去—萋萋无数—南北东西路」背；用典（金谷园、《楚辞》王孙芳草）；以春草写离情是核心。"},"雨霖铃|柳永":{"s":"上片「寒蝉凄切。对长亭晚，骤雨初歇。都门帐饮无绪，留恋处、兰舟催发。执手相看泪眼，竟无语凝噎。念去去、千里烟波，暮霭沈沈楚天阔」写寒蝉凄切对长亭晚骤雨初歇，都门帐饮无绪留恋处兰舟催发，执手相看泪眼竟无语凝噎，念去去千里烟波暮霭沉沉楚天阔，以离别场景写离情；下片「多情自古伤离别。更那堪、冷落清秋节。今宵酒醒何处，杨柳岸、晓风残月。此去经年，应是良辰、好景虚设。便纵有、千种风情，更与何人说」写多情自古伤离别更那堪冷落清秋节，今宵酒醒何处杨柳岸晓风残月，此去经年应是良辰好景虚设，便纵有千种风情更与何人说，以「杨柳岸晓风残月」写酒醒后的凄凉、以「更与何人说」写离别的痛苦，全词意境凄清、情感深沉，「今宵酒醒何处，杨柳岸、晓风残月」成为千古名句，是婉约词的千古名篇。","b":"柳永（北宋词人，「婉约派」代表，「奉旨填词柳三变」）这首《雨霖铃》写离别之情，「今宵酒醒何处，杨柳岸、晓风残月」是千古名句，是婉约词的千古名篇，也是柳永的代表作。","n":["雨霖铃：词牌名","寒蝉凄切：寒蝉凄切","对长亭晚：对长亭晚","骤雨初歇：骤雨初歇","都门帐饮无绪：都门帐饮无绪（在京城门外设帐饯行，没有情绪）","留恋处、兰舟催发：留恋处兰舟催发","执手相看泪眼：执手相看泪眼","竟无语凝噎：竟无语凝噎（哽咽说不出话）。噎音yē","念去去、千里烟波：念去去千里烟波","暮霭沈沈楚天阔：暮霭沉沉楚天阔。沈同「沉」","多情自古伤离别：多情自古伤离别","更那堪、冷落清秋节：更那堪冷落清秋节","今宵酒醒何处：今宵酒醒何处","杨柳岸、晓风残月：杨柳岸晓风残月","此去经年：此去经年","应是良辰、好景虚设：应是良辰好景虚设","便纵有、千种风情：便纵有千种风情","更与何人说：更与何人说"],"m":"今宵酒醒何处，杨柳岸、晓风残月。","r":"按「寒蝉凄切—长亭晚—骤雨初歇—都门帐饮—无绪—留恋兰舟—催发—执手泪眼—无语凝噎—千里烟波—暮霭楚天—多情伤别—冷落清秋—今宵酒醒—杨柳岸—晓风残月—此去经年—良辰虚设—千种风情—更与何人说」背；「噎」读yē、「沈」同沉；「杨柳岸晓风残月」是名句；离别之情是核心。"},"迷仙引|柳永":{"s":"上片「才过笄年，初绾云鬟，便学歌舞。席上尊前，王孙随分相许。算等闲、酬一笑，便千金慵觑。常祗恐、容易蕣华偷换，光阴虚度」写才过笄年初绾云鬟便学歌舞，席上尊前王孙随分相许，算等闲酬一笑便千金慵觑，常只恐容易蕣华偷换光阴虚度，以歌女的生活写对青春虚度的忧虑；下片「已受君恩顾，好与花为主。万里丹霄，何妨携手同归去。永弃却、烟花伴侣。免教人见妾，朝云暮雨」写已受君恩顾好与花为主，万里丹霄何妨携手同归去，永弃却烟花伴侣，免教人见妾朝云暮雨，以「携手同归去」「永弃却烟花伴侣」写对从良的渴望，全词语言朴素、情感真挚，是柳永写歌女心理的名篇，「万里丹霄，何妨携手同归去」成为名句。","b":"柳永这首《迷仙引》写歌女希望从良、与情人携手归去的心愿，以「万里丹霄，何妨携手同归去」写对自由的渴望，是婉约词的名篇。","n":["迷仙引：词牌名","才过笄年：才过笄年（十五岁，女子成年）。笄音jī","初绾云鬟：初绾云鬟（盘起发髻）","便学歌舞：便学歌舞","席上尊前：席上尊前","王孙随分相许：王孙随分相许（随意答应）","算等闲、酬一笑：算等闲酬一笑（平常一笑）","便千金慵觑：便千金慵觑（懒得看）","常祗恐、容易蕣华偷换：常只恐容易蕣华（木槿花，朝开暮落，喻青春）偷换。祗同「只」；蕣音shùn","光阴虚度：光阴虚度","已受君恩顾：已受君恩顾","好与花为主：好与花为主","万里丹霄：万里丹霄","何妨携手同归去：何妨携手同归去","永弃却、烟花伴侣：永弃却烟花伴侣","免教人见妾：免教人见妾","朝云暮雨：朝云暮雨（用宋玉《高唐赋》巫山神女「旦为朝云，暮为行雨」，指妓女生活）"],"m":"万里丹霄，何妨携手同归去。","r":"按「才过笄年—初绾云鬟—便学歌舞—席上尊前—王孙相许—等闲一笑—千金慵觑—常恐蕣华—光阴虚度—已受恩顾—与花为主—万里丹霄—携手同归—永弃烟花—免教人见—朝云暮雨」背；「笄」读jī、「祗」同只、「蕣」读shùn；用典（巫山神女朝云暮雨）；歌女从良的渴望是核心。"},"57498:凤栖梧・蝶恋花|柳永":{"s":"上片「帘下清歌帘外宴。虽爱新声，不见如花面。牙板数敲珠一串，梁尘暗落琉璃盏」写帘下清歌帘外宴，虽爱新声不见如花面，牙板数敲珠一串、梁尘暗落琉璃盏，以「珠一串」「梁尘落」写歌声之美；下片「桐树花深孤凤怨。渐遏遥天，不放行云散。坐上少年听不惯。玉山未倒肠先断」写桐树花深孤凤怨，渐遏遥天不放行云散，坐上少年听不惯、玉山未倒肠先断，以「响遏行云」写歌声之高、以「肠先断」写歌声的感染力，全词用典丰富（珠串歌声、梁尘落、响遏行云、玉山倾倒）、意境凄清，「玉山未倒肠先断」成为名句。","b":"柳永这首《凤栖梧》写歌女的歌声之美与动人，以「玉山未倒肠先断」写歌声的感染力，是婉约词的名篇。","n":["凤栖梧：词牌名，即《蝶恋花》","帘下清歌帘外宴：帘下清歌帘外宴","虽爱新声：虽爱新声","不见如花面：不见如花面","牙板数敲珠一串：牙板（拍板）数敲珠一串（歌声如珠串）","梁尘暗落琉璃盏：梁尘暗落琉璃盏（用「歌声绕梁，尘落」典故）","桐树花深孤凤怨：桐树花深孤凤怨","渐遏遥天：渐遏遥天（响遏行云）","不放行云散：不放行云散","坐上少年听不惯：坐上少年听不惯","玉山未倒肠先断：玉山未倒（未醉）肠先断（玉山，指身体，「玉山倾倒」指醉倒）"],"m":"坐上少年听不惯。玉山未倒肠先断。","r":"按「帘下清歌—帘外宴—爱新声—不见花面—牙板珠串—梁尘落盏—桐花孤凤—遏遥天—行云散—少年听不惯—玉山未倒—肠先断」背；用典（珠串歌声、梁尘落、响遏行云、玉山倾倒）；歌声的感染力是核心。"},"57631:鹤冲天|柳永":{"s":"上片「黄金榜上。偶失龙头望。明代暂遗贤，如何向。未遂风云便，争不恣狂荡。何须论得丧。才子词人，自是白衣卿相」写黄金榜上偶失龙头望，明代暂遗贤如何向，未遂风云便争不恣狂荡，何须论得丧，才子词人自是白衣卿相，以「白衣卿相」写对功名的蔑视；下片「烟花巷陌，依约丹青屏障。幸有意中人，堪寻访。且恁偎红翠，风流事、平生畅。青春都一饷。忍把浮名，换了浅斟低唱」写烟花巷陌依约丹青屏障，幸有意中人堪寻访，且恁偎红翠风流事平生畅，青春都一饷，忍把浮名换了浅斟低唱，以「忍把浮名，换了浅斟低唱」写对自由生活的向往，全词语言明快、情感激烈，「忍把浮名，换了浅斟低唱」成为千古名句，是柳永的代表作。","b":"柳永这首《鹤冲天》是他科举落第后所作，写对功名的蔑视与对自由生活的向往，「忍把浮名，换了浅斟低唱」是千古名句，传说宋仁宗因此批「且去浅斟低唱，何要浮名」，柳永遂自称「奉旨填词柳三变」。","n":["鹤冲天：词牌名","黄金榜上：黄金榜上（科举金榜）","偶失龙头望：偶失龙头望（状元）","明代暂遗贤：明代（圣明时代）暂遗贤（遗落贤才）","如何向：如何向（怎么办）","未遂风云便：未遂风云便（未得志）","争不恣狂荡：争不恣狂荡（怎不恣意狂荡）","何须论得丧：何须论得丧（得失）","才子词人：才子词人","自是白衣卿相：自是白衣卿相（平民卿相）","烟花巷陌：烟花巷陌（歌妓聚居处）","依约丹青屏障：依约丹青屏障（画屏）","幸有意中人：幸有意中人","堪寻访：堪寻访","且恁偎红翠：且恁偎红翠（依偎歌女）","风流事、平生畅：风流事平生畅","青春都一饷：青春都一饷（片刻）。饷同「晌」","忍把浮名：忍把浮名","换了浅斟低唱：换了浅斟低唱"],"m":"忍把浮名，换了浅斟低唱。","r":"按「黄金榜—失龙头—明代遗贤—如何向—未遂风云—恣狂荡—何须得丧—才子词人—白衣卿相—烟花巷陌—丹青屏障—意中人—堪寻访—偎红翠—平生畅—青春一饷—忍把浮名—浅斟低唱」背；「饷」同晌；「白衣卿相」「忍把浮名换浅斟低唱」是名句；宋仁宗「且去填词」典故是背景。"},"朝中措|欧阳修":{"s":"上片「平山阑槛倚晴空。山色有无中。手种堂前垂柳，别来几度春风」写平山堂栏杆倚晴空、山色有无中，手种堂前垂柳、别来几度春风，以平山堂景色写对扬州的怀念；下片「文章太守，挥毫万字，一饮千钟。行乐直须年少，尊前看取衰翁」写文章太守挥毫万字一饮千钟，行乐直须年少、尊前看取衰翁，以「文章太守」写自己的豪情、以「衰翁」写岁月的感慨，全词意境开阔、语言明快，「文章太守，挥毫万字，一饮千钟」成为千古名句。","b":"欧阳修（北宋文学家，「唐宋八大家」之一）这首《朝中措》是他送友人刘敞（字原父）出守扬州时所作，写平山堂的景色与自己的感慨，「文章太守，挥毫万字，一饮千钟」是千古名句。","n":["朝中措：词牌名","平山阑槛倚晴空：平山堂（欧阳修在扬州建的堂）的栏杆倚晴空","山色有无中：山色有无中（用王维「江流天地外，山色有无中」）","手种堂前垂柳：手种堂前垂柳","别来几度春风：别来几度春风","文章太守：文章太守（欧阳修自称）","挥毫万字：挥毫万字","一饮千钟：一饮千钟","行乐直须年少：行乐直须年少","尊前看取衰翁：尊前看取衰翁（欧阳修自指）"],"m":"文章太守，挥毫万字，一饮千钟。","r":"按「平山阑槛—倚晴空—山色有无—手种垂柳—几度春风—文章太守—挥毫万字—一饮千钟—行乐年少—尊前衰翁」背；用典（王维山色有无中）；「文章太守」是名句；豪放与感慨并存是特点。"},"58004:诉衷情|欧阳修":{"s":"上片「清晨帘幕卷轻霜。呵手试梅妆。都缘自有离恨，故画作远山长」写清晨帘幕卷轻霜、呵手试梅妆，都缘自有离恨、故画作远山长，以「画作远山长」写离恨——把眉画得像远山一样长，暗示离恨之长；下片「思往事，惜流芳。易成伤。拟歌先敛，欲笑还颦。最断人肠」写思往事惜流芳易成伤，拟歌先敛欲笑还颦最断人肠，以「拟歌先敛，欲笑还颦」写女子的矛盾心理——想唱歌却先收敛、想笑却还皱眉，全词意境凄清、细节生动，「拟歌先敛，欲笑还颦，最断人肠」成为名句。","b":"欧阳修这首《诉衷情》写闺中女子的离恨，以「拟歌先敛，欲笑还颦，最断人肠」写女子的矛盾心理，是婉约词的名篇。","n":["诉衷情：词牌名","清晨帘幕卷轻霜：清晨帘幕卷轻霜","呵手试梅妆：呵手试梅妆（梅花妆，寿阳公主故事）","都缘自有离恨：都缘自有离恨","故画作远山长：故画作远山长（把眉画得像远山一样长，写离恨）","思往事：思往事","惜流芳：惜流芳（流逝的美好时光）","易成伤：易成伤","拟歌先敛：拟歌先敛（想唱歌先收敛表情）","欲笑还颦：欲笑还颦（想笑还皱眉）。颦音pín","最断人肠：最断人肠"],"m":"拟歌先敛，欲笑还颦，最断人肠。","r":"按「清晨帘幕—卷轻霜—呵手梅妆—都缘离恨—画作远山—思往事—惜流芳—易成伤—拟歌先敛—欲笑还颦—最断人肠」背；「颦」读pín；用典（寿阳公主梅花妆、远山眉）；「画作远山长」的暗示是核心。"},"58111:临江仙|欧阳修":{"s":"上片「柳外轻雷池上雨，雨声滴碎荷声。小楼西角断虹明。阑干倚处，待得月华生」写柳外轻雷池上雨、雨声滴碎荷声，小楼西角断虹明，阑干倚处待得月华生，以雨后景色写闺中等待；下片「燕子飞来窥画栋，玉钩垂下帘旌。凉波不动簟纹平。水精双枕，傍有堕钗横」写燕子飞来窥画栋、玉钩垂下帘旌，凉波不动簟纹平，水精双枕傍有堕钗横，以「堕钗横」的细节写闺中女子的慵懒，全词意境清丽、细节生动，「燕子飞来窥画栋，玉钩垂下帘旌」成为名句。","b":"欧阳修这首《临江仙》写夏日雨后的闺中情景，以「燕子飞来窥画栋，玉钩垂下帘旌」写环境的清幽，是婉约词的名篇。","n":["临江仙：词牌名","柳外轻雷池上雨：柳外轻雷池上雨","雨声滴碎荷声：雨声滴碎荷声","小楼西角断虹明：小楼西角断虹明","阑干倚处：阑干倚处","待得月华生：待得月华（月光）生","燕子飞来窥画栋：燕子飞来窥画栋","玉钩垂下帘旌：玉钩垂下帘旌（帘幕）。旌音jīng","凉波不动簟纹平：凉波不动簟纹（竹席纹）平。簟音diàn","水精双枕：水精（水晶）双枕","傍有堕钗横：傍有堕钗横"],"m":"燕子飞来窥画栋，玉钩垂下帘旌。","r":"按「柳外轻雷—池上雨—滴碎荷声—断虹明—阑干倚—待月华—燕子窥栋—玉钩帘旌—凉波簟纹—水精双枕—堕钗横」背；「簟」读diàn、「旌」读jīng；「堕钗横」的细节是核心。"},"58114:浪淘沙|欧阳修":{"s":"上片「把酒祝东风。且共从容。垂杨紫陌洛城东。总是当时携手处，游遍芳丛」写把酒祝东风且共从容，垂杨紫陌洛城东，总是当时携手处游遍芳丛，以洛阳春色写相聚的欢乐；下片「聚散苦匆匆。此恨无穷。今年花胜去年红。可惜明年花更好，知与谁同」写聚散苦匆匆此恨无穷，今年花胜去年红，可惜明年花更好知与谁同，以「今年花胜去年红」「明年花更好」的递进写聚散无常——花一年比一年好，却不知明年与谁同赏，全词意境清丽、哲理深沉，「今年花胜去年红。可惜明年花更好，知与谁同」成为千古名句。","b":"欧阳修这首《浪淘沙》写与友人在洛阳相聚又离别的感慨，「今年花胜去年红。可惜明年花更好，知与谁同」是千古名句，是婉约词的千古名篇。","n":["浪淘沙：词牌名","把酒祝东风：把酒祝东风（祝，向东风祝祷）","且共从容：且共从容（且与东风一同从容赏春）","垂杨紫陌洛城东：垂杨紫陌洛城东（紫陌，帝都的道路）","总是当时携手处：总是当时携手处","游遍芳丛：游遍芳丛","聚散苦匆匆：聚散苦匆匆","此恨无穷：此恨无穷","今年花胜去年红：今年花胜去年红","可惜明年花更好：可惜明年花更好","知与谁同：知与谁同"],"m":"今年花胜去年红。可惜明年花更好，知与谁同。","r":"按「把酒祝东风—且共从容—垂杨紫陌—洛城东—携手处—游遍芳丛—聚散匆匆—此恨无穷—今年花红—明年花好—知与谁同」背；「祝」是向东风祝祷；花的递进与聚散无常是核心。"},"58127:浣溪沙|欧阳修":{"s":"上片「堤上游人逐画船。拍堤春水四垂天。绿杨楼外出秋千」写堤上游人逐画船、拍堤春水四垂天，绿杨楼外出秋千，以「出秋千」的「出」字写秋千的灵动，王国维评为「着一出字而境界全出」；下片「白发戴花君莫笑，六幺催拍盏频传。人生何处似尊前」写白发戴花君莫笑、六幺催拍盏频传，人生何处似尊前，以「白发戴花」写旷达、以「人生何处似尊前」写及时行乐，全词意境明丽、情感旷达，「绿杨楼外出秋千」成为名句。","b":"欧阳修这首《浣溪沙》写颍州西湖春游的欢乐，「绿杨楼外出秋千」是名句，「人生何处似尊前」写及时行乐，是婉约词的名篇。","n":["浣溪沙：词牌名","堤上游人逐画船：堤上游人逐画船","拍堤春水四垂天：拍堤春水四垂天（天幕四垂）","绿杨楼外出秋千：绿杨楼外出秋千","白发戴花君莫笑：白发戴花君莫笑","六幺催拍盏频传：六幺（曲调名）催拍盏频传。幺音yāo","人生何处似尊前：人生何处似尊前（酒杯前）"],"m":"绿杨楼外出秋千。","r":"按「游人逐船—拍堤春水—四垂天—绿杨楼—出秋千—白发戴花—君莫笑—六幺催拍—盏频传—人生尊前」背；「幺」读yāo；「出」字是炼字；旷达及时行乐是核心。"},"卖油翁|欧阳修":{"s":"全文分三层：第一层写陈尧咨善射自矜，卖油翁释担而立、睨之、但微颔之，以卖油翁的冷淡反衬陈尧咨的自矜；第二层写陈尧咨质问卖油翁，卖油翁以「无他，但手熟尔」回答，陈尧咨忿然，卖油翁当场演示酌油——以钱覆葫芦口、徐以杓酌油沥之、自钱孔入而钱不湿，以实际行动证明「手熟」的道理；第三层写卖油翁「我亦无他，惟手熟尔」，陈尧咨笑而遣之，以「熟能生巧」的道理作结。全文叙事简洁、对话生动、寓意深刻，「无他，但手熟尔」成为千古名句，是寓言式散文的典范。","b":"欧阳修这篇《卖油翁》通过陈尧咨善射与卖油翁酌油的故事，说明「熟能生巧」的道理，是中国古代寓言式散文的千古名篇。","n":["卖油翁：篇名，欧阳修作","陈康肃公：陈尧咨，谥号康肃，北宋官员，善射","善射：擅长射箭","当世无双：当世无双","自矜：自夸。矜音jīn","家圃：家里的园子。圃音pǔ","释担：放下担子","睨之：斜着眼看他。睨音nì","久而不去：久久不离开","发矢十中八九：射箭十中八九","但微颔之：只是微微点头。颔音hàn，点头","汝亦知射乎：你也懂射箭吗","无他，但手熟尔：没有别的，只是手熟罢了。尔同「耳」","忿然：气愤的样子。忿音fèn","尔安敢轻吾射：你怎么敢轻视我的射箭","以我酌油知之：凭我倒油知道这个道理","乃取一葫芦置于地：于是拿一个葫芦放在地上","以钱覆其口：用铜钱盖住葫芦口","徐以杓酌油沥之：慢慢地用勺子倒油沥入葫芦。杓同「勺」","自钱孔入：从钱孔中进入","而钱不湿：而钱不湿","我亦无他，惟手熟尔：我也没有别的，只是手熟罢了","笑而遣之：笑着打发他走了"],"m":"我亦无他，惟手熟尔。","r":"按「陈尧咨善射自矜—卖油翁睨之微颔—陈质问—卖油翁答手熟—陈忿然—卖油翁演示酌油—钱不湿—我亦无他惟手熟—陈笑遣之」背；「矜」读jīn、「圃」读pǔ、「睨」读nì、「颔」读hàn、「忿」读fèn；「尔」同耳、「杓」同勺；「熟能生巧」是核心寓意。"},"桂枝香|王安石":{"s":"上片「登临送目。正故国晚秋，天气初肃。千里澄江似练，翠峰如簇。归帆去棹残阳里，背西风、酒旗斜矗。彩舟云淡，星河鹭起，画图难足」写登临送目、故国晚秋、天气初肃，千里澄江似练翠峰如簇，归帆去棹残阳里背西风酒旗斜矗，彩舟云淡星河鹭起画图难足，以金陵壮丽景色写登临；下片「念往昔、繁华竞逐。叹门外楼头，悲恨相续。千古凭高，对此漫嗟荣辱。六朝旧事随流水，但寒烟、芳草凝绿。至今商女，时时犹唱，后庭遗曲」写念往昔繁华竞逐、叹门外楼头悲恨相续，千古凭高对此漫嗟荣辱，六朝旧事随流水但寒烟芳草凝绿，至今商女时时犹唱后庭遗曲，以六朝兴亡写怀古、以「后庭遗曲」写对现实的隐忧，全词意境壮阔、用典贴切、寓意深刻，「至今商女，时时犹唱，后庭遗曲」成为千古名句，是豪放词的千古名篇。","b":"王安石这首《桂枝香》写金陵怀古，「至今商女，时时犹唱，后庭遗曲」是千古名句，是豪放词的千古名篇，杨慎评为「金陵怀古诸词，惟介甫最为绝唱」。","n":["桂枝香：词牌名","登临送目：登临送目（登高远望）","正故国晚秋：正故国（金陵）晚秋","天气初肃：天气初肃（肃杀）","千里澄江似练：千里澄江似练（白绢）。用谢朓「澄江静如练」","翠峰如簇：翠峰如簇（簇拥）。簇音cù","归帆去棹残阳里：归帆去棹残阳里。棹音zhào","背西风、酒旗斜矗：背西风酒旗斜矗。矗音chù，竖立","彩舟云淡：彩舟云淡","星河鹭起：星河（银河，此指长江）鹭起","画图难足：画图难足（难以画尽）","念往昔、繁华竞逐：念往昔繁华竞逐","叹门外楼头：叹门外楼头（用陈后主「门外韩擒虎，楼头张丽华」典故，隋兵已到门外，陈后主还在楼头与张丽华享乐）","悲恨相续：悲恨相续","千古凭高：千古凭高","对此漫嗟荣辱：对此漫嗟荣辱（空叹荣辱）","六朝旧事随流水：六朝旧事随流水","但寒烟、芳草凝绿：但寒烟芳草凝绿","至今商女：至今商女（歌女）","时时犹唱：时时犹唱","后庭遗曲：后庭遗曲（《玉树后庭花》，陈后主作，亡国之音）。用杜牧「商女不知亡国恨，隔江犹唱后庭花」"],"m":"至今商女，时时犹唱，后庭遗曲。","r":"按「登临送目—故国晚秋—天气初肃—澄江似练—翠峰如簇—归帆残阳—酒旗斜矗—彩舟云淡—星河鹭起—画图难足—念往昔—繁华竞逐—门外楼头—悲恨相续—千古凭高—漫嗟荣辱—六朝旧事—寒烟芳草—至今商女—犹唱后庭」背；「簇」读cù、「棹」读zhào、「矗」读chù；用典（谢朓澄江、陈后主门外楼头、杜牧商女后庭花）；怀古讽今是核心。"},"梅花|王安石":{"s":"首两句「墙角数枝梅，凌寒独自开」写墙角几枝梅、冒着严寒独自开放，以「凌寒」「独自」写梅的坚韧；后两句「遥知不是雪，为有暗香来」是千古名句——远远知道不是雪，因为有暗香飘来，以「暗香」写梅的品格，以雪衬梅、以香辨梅，全诗语言朴素、意境清幽，「遥知不是雪，为有暗香来」成为千古名句，是咏梅诗的千古名篇。","b":"王安石这首《梅花》写梅花在严寒中独自开放，以「暗香」写梅的品格，是咏梅诗的千古名篇。","n":["梅花：诗题","墙角数枝梅：墙角几枝梅","凌寒独自开：冒着严寒独自开放","遥知不是雪：远远知道不是雪","为有暗香来：因为有暗香飘来"],"m":"遥知不是雪，为有暗香来。","r":"四句按「墙角数枝—凌寒独开—遥知非雪—为有暗香」背；以雪衬梅、以香辨梅是核心；梅的坚韧品格是主题。"},"明妃曲·其一|王安石":{"s":"全诗分四层：第一层「明妃初出汉宫时……尚得君王不自持」写明妃初出汉宫时的美貌——春风一面花含露，低回顾影无颜色，尚得君王不自持，以「不自持」写昭君之美；第二层「归来却怪丹青手……当时枉杀毛延寿」写汉元帝归来却怪画师毛延寿，入眼平生几曾有，意态由来画不成，当时枉杀毛延寿，以「意态由来画不成」翻案——昭君的风度神态是画不出来的，杀毛延寿是冤枉的，这是千古新意；第三层「一去心知更不归……只有年年鸿雁飞」写昭君一去心知更不归，可怜着尽汉宫衣，寄声欲问塞南事，只有年年鸿雁飞，以「着尽汉宫衣」「鸿雁飞」写昭君的思乡；第四层「家人万里传消息……人生失意无南北」写家人万里传消息，好在毡城莫相忆，君不见咫尺长门闭阿娇，人生失意无南北，以陈皇后阿娇被废长门宫的典故说明——人生失意不分南北，即使在汉朝也有失意，深化了主题。全诗立意新颖、议论精辟、情感深沉，「意态由来画不成，当时枉杀毛延寿」「人生失意无南北」成为千古名句，是咏史诗的千古名篇。","b":"王安石这首《明妃曲》写王昭君出塞的故事，「意态由来画不成，当时枉杀毛延寿」「人生失意无南北」是千古名句，是咏史诗的千古名篇，在当时引起很大反响，欧阳修、司马光、梅尧臣等都有和作。","n":["明妃曲：诗题，明妃即王昭君","明妃初出汉宫时：明妃初出汉宫时","春风一面花含露：春风一面花含露（面容如春风中含露的花）","低回顾影无颜色：低回顾影无颜色（低头回看，面容失色）","尚得君王不自持：尚且使君王不能自持（指汉元帝见昭君美貌后悔）","归来却怪丹青手：归来却怪丹青手（画师毛延寿）","入眼平生几曾有：入眼平生几曾有（平生从未见过如此美貌）","意态由来画不成：意态（风度神态）从来画不成","当时枉杀毛延寿：当时枉杀毛延寿","一去心知更不归：一去心知更不归","可怜着尽汉宫衣：可怜穿尽了汉宫衣（思念汉朝）","寄声欲问塞南事：寄声欲问塞南（汉朝）事","只有年年鸿雁飞：只有年年鸿雁飞","家人万里传消息：家人万里传消息","好在毡城莫相忆：好在毡城（匈奴）莫相忆","君不见咫尺长门闭阿娇：君不见咫尺长门（长门宫）闭阿娇（陈皇后，被汉武帝废居长门宫）","人生失意无南北：人生失意无南北（无论南北都有失意）"],"m":"意态由来画不成，当时枉杀毛延寿。人生失意无南北。","r":"按「明妃出汉宫—花含露—低回顾影—君王不自持—怪丹青手—几曾有—意态画不成—枉杀毛延寿—一去不归—着尽汉宫衣—问塞南事—鸿雁飞—家人传消息—毡城莫相忆—长门闭阿娇—人生失意无南北」背；「意态由来画不成」的翻案是核心；阿娇长门典故是深化主题；与欧阳修等人的和作对读。"},"江上|王安石":{"s":"首两句「江水漾西风，江花脱晚红」写江水在西风中荡漾、江花脱落晚红，以秋景写离情；后两句「离情被横笛，吹过乱山东」是名句——离情被横笛声吹过乱山东，以「离情被横笛吹过」的拟人写离情的悠远，想象奇特，全诗意境凄清、想象奇特，「离情被横笛，吹过乱山东」成为名句。","b":"王安石这首《江上》写江上秋风中的离情，以「离情被横笛，吹过乱山东」写离情的悠远，是七绝的名篇。","n":["江上：诗题","江水漾西风：江水在西风中荡漾","江花脱晚红：江花脱落了晚红（晚开的红花）","离情被横笛：离情被横笛（笛声）","吹过乱山东：吹过乱山东"],"m":"离情被横笛，吹过乱山东。","r":"四句按「江水漾西风—江花脱晚红—离情被横笛—吹过乱山东」背；拟人手法（离情被吹过）是核心；秋景写离情是手法。"},"游褒禅山记|王安石":{"s":"全文分五段：第一段写褒禅山的得名与华山洞的位置，通过仆碑考证「花山」的读音，提出「音谬」的问题；第二段写游前洞与后洞的经过——前洞平旷游者众，后洞窈然入之愈深其进愈难而其见愈奇，因「火且尽」而随怠者出，后悔「不得极夫游之乐」；第三段写由此引发的议论——「夷以近则游者众，险以远则至者少」，「世之奇伟瑰怪非常之观常在于险远」，提出「志、力、物」三者的关系：非有志者不能至，有志矣力不足亦不能至，有志与力而无物以相之亦不能至；「尽吾志也而不能至者，可以无悔矣」；第四段写由仆碑引发的议论——「悲夫古书之不存，后世之谬其传而莫能名者」，提出「学者不可以不深思而慎取之也」；第五段记同游四人与写作时间。全文叙议结合、逻辑严密、寓意深刻，「世之奇伟瑰怪非常之观常在于险远」「尽吾志也而不能至者，可以无悔矣」「深思而慎取」成为千古名句，是游记散文的典范。","b":"王安石这篇《游褒禅山记》是他任舒州通判时所作，通过游褒禅山的经历，阐述「志、力、物」三者的关系和「深思而慎取」的治学态度，是中国古代游记散文的千古名篇。","n":["游褒禅山记：篇名，王安石作","褒禅山：在今安徽含山北","浮图慧褒：和尚慧褒。浮图，和尚","始舍于其址：开始在山脚下建屋居住","卒葬之：死后葬在那里","以故其后名之曰褒禅：因此后来称它为褒禅山","慧空禅院：慧空禅院（寺庙）","庐冢：庐舍和坟墓","华山洞：华山洞","华山之阳：华山的南面。阳，山南水北为阳","碑仆道：石碑倒在路上。仆音pū","其文漫灭：碑文模糊磨灭","独其为文犹可识：只有其中的文字还可辨认","曰花山：叫「花山」","今言华如华实之华者：现在把「华」读成「华实」的「华」","盖音谬也：大概是读音错了","前洞：前洞","有泉侧出：有泉水从旁边流出","窈然：幽暗深远的样子。窈音yǎo","拥火以入：拿着火把进去","有怠而欲出者：有懈怠想出去的人","不出，火且尽：不出去，火把将要烧完了","不能十一：不到十分之一","则或咎其欲出者：就有人责怪那个想出去的人。咎音jiù","悔其随之：后悔自己跟着他出来","不得极夫游之乐：不能极尽游洞的乐趣","夷以近：平坦而近","险以远：险峻而远","瑰怪：瑰丽怪异","非常之观：不寻常的景象","非有志者不能至：不是有志气的人不能到达","不随以止：不跟着别人停止","无物以相之：没有外物帮助他。相音xiàng，帮助","力足以至焉：力量足以到达那里","于人为可讥：在别人看来是可以讥笑的","在己为有悔：在自己看来是有悔恨的","尽吾志也而不能至者：尽了我的志向却不能到达的","可以无悔矣：可以没有悔恨了","其孰能讥之乎：谁能讥笑他呢","仆碑：倒了的石碑","悲夫古书之不存：可悲古书不存","后世之谬其传而莫能名者：后世以讹传讹而不能说明白的","何可胜道也哉：哪里说得完呢","深思而慎取：深入思考而谨慎选取","四人者：四个人","庐陵萧君圭君玉：庐陵萧君圭字君玉","长乐王回深父：长乐王回字深父","余弟安国平父：我弟弟王安国字平父","安上纯父：王安上字纯父","至和元年七月某日：至和元年（1054）七月某日","临川王某记：临川王某（王安石）记"],"m":"世之奇伟、瑰怪，非常之观，常在于险远，而人之所罕至焉，故非有志者不能至也。尽吾志也而不能至者，可以无悔矣，其孰能讥之乎？","r":"按「褒禅山得名—华山洞位置—仆碑考音谬—游前洞后洞—火尽随出—悔不得极游—议论：夷近险远—奇伟在险远—志力物三者关系—尽吾志无悔—仆碑议论：古书不存—谬传莫能名—深思慎取—同游四人—写作时间」背；生僻字：仆pū、窈yǎo、咎jiù、相xiàng；「志力物」三者关系是核心；「深思慎取」是治学态度。"},"67446:水龙吟|王沂孙":{"s":"上片「晓霜初著青林，望中故国凄凉早。萧萧渐积，纷纷犹坠，门荒径悄。渭水风生，洞庭波起，几番秋杪。想重崖半没，千峰尽出，山中路、无人到」写晓霜初著青林、望中故国凄凉早，萧萧渐积纷纷犹坠门荒径悄，渭水风生洞庭波起几番秋杪，想重崖半没千峰尽出山中路无人到，以落叶写故国凄凉；下片「前度题红杳杳。溯宫沟、暗流空绕。啼螀未歇，飞鸿欲过，此时怀抱。乱影翻窗，碎声敲砌，愁人多少。望吾庐甚处，只应今夜，满庭谁扫」写前度题红杳杳、溯宫沟暗流空绕，啼螀未歇飞鸿欲过此时怀抱，乱影翻窗碎声敲砌愁人多少，望吾庐甚处只应今夜满庭谁扫，以「题红」「宫沟」写故宫之思、以「满庭谁扫」写亡国后的荒凉，全词意境凄清、用典贴切（红叶题诗、渭水秋风、洞庭波起），是南宋遗民词的名篇。","b":"王沂孙（南宋末元初词人，「格律派」代表，号碧山）这首《水龙吟》写落叶，以落叶写亡国之思，是南宋遗民词的名篇，与他的《齐天乐·蝉》《眉妩·新月》并称。","n":["水龙吟：词牌名","晓霜初著青林：晓霜初著（附着）青林","望中故国凄凉早：望中故国凄凉早","萧萧渐积：萧萧渐积（落叶）","纷纷犹坠：纷纷犹坠","门荒径悄：门荒径悄","渭水风生：渭水风生（用贾岛「秋风生渭水」）","洞庭波起：洞庭波起（用屈原「洞庭波兮木叶下」）","几番秋杪：几番秋杪（秋末）。杪音miǎo","想重崖半没：想重崖半没","千峰尽出：千峰尽出","山中路、无人到：山中路无人到","前度题红杳杳：前度题红（红叶题诗典故）杳杳","溯宫沟、暗流空绕：溯宫沟暗流空绕","啼螀未歇：啼螀（寒蝉）未歇。螀音jiāng","飞鸿欲过：飞鸿欲过","此时怀抱：此时怀抱","乱影翻窗：乱影翻窗","碎声敲砌：碎声敲砌（台阶）","愁人多少：愁人多少","望吾庐甚处：望吾庐甚处（我的家在哪里）","只应今夜：只应今夜","满庭谁扫：满庭谁扫（落叶谁扫）"],"m":"望吾庐甚处，只应今夜，满庭谁扫。","r":"按「晓霜青林—故国凄凉—萧萧渐积—纷纷犹坠—门荒径悄—渭水风生—洞庭波起—几番秋杪—重崖半没—千峰尽出—山路无人—题红杳杳—宫沟暗流—啼螀未歇—飞鸿欲过—此时怀抱—乱影翻窗—碎声敲砌—愁人多少—望吾庐—今夜—满庭谁扫」背；「杪」读miǎo、「螀」读jiāng；用典（红叶题诗、贾岛渭水、屈原洞庭）；落叶写亡国之思是核心。"},"67452:齐天乐|王沂孙":{"s":"上片「碧痕初化池塘草，荧荧野光相趁。扇薄星流，盘明露滴，零落秋原飞磷。练裳暗近。记穿柳生凉，度荷分暝。误我残编，翠囊空叹梦无准」写碧痕初化池塘草、荧荧野光相趁，扇薄星流盘明露滴零落秋原飞磷，练裳暗近，记穿柳生凉度荷分暝，误我残编翠囊空叹梦无准，以萤火虫的光写秋夜的凄凉；下片「楼阴时过数点，倚阑人未睡，曾赋幽恨。汉苑飘苔，秦陵坠叶，千古凄凉不尽。何人为省。但隔水余晖，傍林残影。已觉萧疏，更堪秋夜永」写楼阴时过数点、倚阑人未睡曾赋幽恨，汉苑飘苔秦陵坠叶千古凄凉不尽，何人为省，但隔水余晖傍林残影，已觉萧疏更堪秋夜永，以「汉苑飘苔，秦陵坠叶」写千古兴亡、以「秋夜永」写亡国之痛，全词意境凄清、用典贴切（车胤囊萤），是南宋遗民词的名篇。","b":"王沂孙这首《齐天乐》写萤火虫，以萤写亡国之思，是南宋遗民词的名篇，与他的《水龙吟·落叶》《眉妩·新月》并称。","n":["齐天乐：词牌名","碧痕初化池塘草：碧痕初化池塘草（萤火虫的碧光初化池塘草）","荧荧野光相趁：荧荧野光相趁（追逐）","扇薄星流：扇薄星流（萤光如星流）","盘明露滴：盘明露滴（露滴如盘明）","零落秋原飞磷：零落秋原飞磷（磷火）","练裳暗近：练裳暗近（白裳暗中靠近）","记穿柳生凉：记穿柳生凉","度荷分暝：度荷分暝（穿过荷塘分开暮色）","误我残编：误我残编（耽误我读书）","翠囊空叹梦无准：翠囊（车胤囊萤读书的袋子）空叹梦无准","楼阴时过数点：楼阴时过数点","倚阑人未睡：倚阑人未睡","曾赋幽恨：曾赋幽恨","汉苑飘苔：汉苑飘苔","秦陵坠叶：秦陵坠叶","千古凄凉不尽：千古凄凉不尽","何人为省：何人为省（知晓）","但隔水余晖：但隔水余晖","傍林残影：傍林残影","已觉萧疏：已觉萧疏","更堪秋夜永：更堪秋夜永（秋夜漫长）"],"m":"汉苑飘苔，秦陵坠叶，千古凄凉不尽。","r":"按「碧痕化草—荧荧野光—扇薄星流—盘明露滴—秋原飞磷—练裳暗近—穿柳生凉—度荷分暝—误我残编—翠囊空叹—楼阴数点—倚阑未睡—曾赋幽恨—汉苑飘苔—秦陵坠叶—千古凄凉—何人为省—隔水余晖—傍林残影—已觉萧疏—更堪秋夜永」背；用典（车胤囊萤）；萤写亡国之思是核心；「汉苑秦陵」的兴亡之感是核心。"},"八六子|秦观":{"s":"上片「倚危亭。恨如芳草，萋萋刬尽还生。念柳外青骢别后，水边红袂分时，怆然暗惊」写倚危亭、恨如芳草萋萋刬尽还生，念柳外青骢别后水边红袂分时怆然暗惊，以「恨如芳草，刬尽还生」写离恨的绵绵不绝；下片「无端天与娉婷。夜月一帘幽梦，春风十里柔情。怎奈向、欢娱渐随流水，素弦声断，翠绡香减，那堪片片飞花弄晚，蒙蒙残雨笼晴。正销凝。黄鹂又啼数声」写无端天与娉婷、夜月一帘幽梦春风十里柔情，怎奈欢娱渐随流水素弦声断翠绡香减，那堪片片飞花弄晚蒙蒙残雨笼晴，正销凝黄鹂又啼数声，以「欢娱渐随流水」写欢乐的消逝、以「黄鹂又啼数声」写愁思的不断，全词意境凄清、比喻巧妙、情感深沉，「恨如芳草，萋萋刬尽还生」成为千古名句，是婉约词的千古名篇。","b":"秦观（北宋词人，「婉约派」代表，「苏门四学士」之一）这首《八六子》写离别后的相思，「恨如芳草，萋萋刬尽还生」是千古名句，是婉约词的千古名篇。","n":["八六子：词牌名","倚危亭：倚危亭（高亭）","恨如芳草：恨如芳草","萋萋刬尽还生：萋萋刬（铲）尽还生。刬音chǎn，同「铲」","念柳外青骢别后：念柳外青骢（青白色马）别后。骢音cōng","水边红袂分时：水边红袂（红袖，指女子）分时。袂音mèi","怆然暗惊：怆然暗惊。怆音chuàng","无端天与娉婷：无端天与娉婷（美貌）。娉婷音pīngtíng","夜月一帘幽梦：夜月一帘幽梦","春风十里柔情：春风十里柔情（用杜牧「春风十里扬州路」）","怎奈向、欢娱渐随流水：怎奈向欢娱渐随流水","素弦声断：素弦声断","翠绡香减：翠绡（绿纱）香减。绡音xiāo","那堪片片飞花弄晚：那堪片片飞花弄晚","蒙蒙残雨笼晴：蒙蒙残雨笼晴","正销凝：正销凝（销魂凝神）","黄鹂又啼数声：黄鹂又啼数声"],"m":"恨如芳草，萋萋刬尽还生。","r":"按「倚危亭—恨如芳草—刬尽还生—柳外青骢—水边红袂—怆然暗惊—天与娉婷—夜月幽梦—春风柔情—欢娱流水—素弦声断—翠绡香减—飞花弄晚—残雨笼晴—正销凝—黄鹂啼声」背；「刬」读chǎn、「骢」读cōng、「袂」读mèi、「怆」读chuàng、「娉婷」读pīngtíng、「绡」读xiāo；用典（杜牧春风十里）；「恨如芳草」的比喻是核心。"},"72097:江城子|秦观":{"s":"上片「西城杨柳弄春柔。动离忧。泪难收。犹记多情，曾为系归舟。碧野朱桥当日事，人不见，水空流」写西城杨柳弄春柔、动离忧泪难收，犹记多情曾为系归舟，碧野朱桥当日事人不见水空流，以杨柳写离忧、以「人不见水空流」写物是人非；下片「韶华不为少年留。恨悠悠。几时休。飞絮落花时候、一登楼。便做春江都是泪，流不尽，许多愁」写韶华不为少年留恨悠悠几时休，飞絮落花时候一登楼，便做春江都是泪流不尽许多愁，以「便做春江都是泪，流不尽，许多愁」的夸张写愁之多，全词意境凄清、夸张巧妙、情感深沉，「便做春江都是泪，流不尽，许多愁」成为千古名句，是婉约词的千古名篇。","b":"秦观这首《江城子》写离别后的愁思，「便做春江都是泪，流不尽，许多愁」是千古名句，是婉约词的千古名篇。","n":["江城子：词牌名","西城杨柳弄春柔：西城杨柳弄春柔","动离忧：动离忧","泪难收：泪难收","犹记多情：犹记多情","曾为系归舟：曾为系归舟","碧野朱桥当日事：碧野朱桥当日事","人不见：人不见","水空流：水空流","韶华不为少年留：韶华（美好时光）不为少年留","恨悠悠：恨悠悠","几时休：几时休","飞絮落花时候、一登楼：飞絮落花时候一登楼","便做春江都是泪：便做春江都是泪","流不尽：流不尽","许多愁：许多愁"],"m":"便做春江都是泪，流不尽，许多愁。","r":"按「西城杨柳—弄春柔—动离忧—泪难收—犹记多情—系归舟—碧野朱桥—人不见—水空流—韶华不留—恨悠悠—几时休—飞絮落花—一登楼—春江都是泪—流不尽—许多愁」背；「便做春江都是泪」的夸张是核心；韶华易逝与离愁是主题。"},"减字木兰花|秦观":{"s":"上片「天涯旧恨。独自凄凉人不问。欲见回肠。断尽金炉小篆香」写天涯旧恨、独自凄凉人不问，欲见回肠断尽金炉小篆香，以「小篆香断尽」喻愁肠的断尽；下片「黛峨长敛。任是春风吹不展。困倚危楼。过尽飞鸿字字愁」写黛峨长敛、任是春风吹不展，困倚危楼过尽飞鸿字字愁，以「春风吹不展」写愁眉之紧、以「飞鸿字字愁」写雁阵如字字字是愁，全词意境凄清、比喻巧妙、情感深沉，「黛峨长敛，任是春风吹不展」「过尽飞鸿字字愁」成为名句。","b":"秦观这首《减字木兰花》写闺中女子的愁思，「黛峨长敛，任是春风吹不展」「过尽飞鸿字字愁」是名句，是婉约词的名篇。","n":["减字木兰花：词牌名","天涯旧恨：天涯旧恨","独自凄凉人不问：独自凄凉人不问","欲见回肠：欲见回肠（愁肠）","断尽金炉小篆香：断尽金炉小篆香（盘香，喻愁肠）","黛峨长敛：黛峨（蛾眉）长敛。黛音dài","任是春风吹不展：任是春风吹不展","困倚危楼：困倚危楼","过尽飞鸿字字愁：过尽飞鸿字字愁（雁阵如字，字字是愁）"],"m":"黛峨长敛，任是春风吹不展。","r":"按「天涯旧恨—独自凄凉—人不问—欲见回肠—断尽篆香—黛峨长敛—春风不展—困倚危楼—过尽飞鸿—字字愁」背；「黛」读dài；「小篆香」喻愁肠、「飞鸿字字愁」是核心比喻。"},"72106:画堂春|秦观":{"s":"上片「落红铺尽水平池。弄晴小雨霏霏。杏园憔悴杜鹃啼。无奈春归」写落红铺尽水平池、弄晴小雨霏霏，杏园憔悴杜鹃啼无奈春归，以春景写伤春；下片「柳外画楼独上。凭阑手拈花枝。放花无语对斜晖。此恨谁知」写柳外画楼独上、凭阑手拈花枝，放花无语对斜晖此恨谁知，以「手拈花枝」「放花无语」的细节写女子的愁思，全词意境凄清、细节生动、情感深沉，「放花无语对斜晖」成为名句。","b":"秦观这首《画堂春》写伤春之情，「放花无语对斜晖」是名句，是婉约词的名篇。","n":["画堂春：词牌名","落红铺尽水平池：落红铺尽水平池","弄晴小雨霏霏：弄晴小雨霏霏","杏园憔悴杜鹃啼：杏园憔悴杜鹃啼","无奈春归：无奈春归","柳外画楼独上：柳外画楼独上","凭阑手拈花枝：凭阑手拈（捏）花枝。拈音niān","放花无语对斜晖：放花无语对斜晖","此恨谁知：此恨谁知"],"m":"放花无语对斜晖。","r":"按「落红铺池—小雨霏霏—杏园憔悴—杜鹃啼—无奈春归—柳外画楼—独上—凭阑拈花—放花无语—对斜晖—此恨谁知」背；「拈」读niān；「放花无语对斜晖」的细节是核心；伤春是主题。"},"千秋岁|秦观":{"s":"上片「水边沙外。城郭春寒退。花影乱，莺声碎。飘零疏酒盏，离别宽衣带。人不见，碧云暮合空相对」写水边沙外城郭春寒退，花影乱莺声碎，飘零疏酒盏离别宽衣带，人不见碧云暮合空相对，以春景写被贬后的飘零；下片「忆昔西池会。鹓鹭同飞盖。携手处，今谁在。日边清梦断，镜里朱颜改。春去也，飞红万点愁如海」写忆昔西池会鹓鹭同飞盖，携手处今谁在，日边清梦断镜里朱颜改，春去也飞红万点愁如海，以「西池会」的回忆与「今谁在」的现实对比、以「飞红万点愁如海」的夸张写愁之深，全词意境凄清、对比鲜明、情感深沉，「春去也，飞红万点愁如海」成为千古名句，是婉约词的千古名篇。","b":"秦观这首《千秋岁》是他被贬处州时所作，写对昔日友人的思念与被贬的痛苦，「春去也，飞红万点愁如海」是千古名句，是婉约词的千古名篇。","n":["千秋岁：词牌名","水边沙外：水边沙外","城郭春寒退：城郭春寒退","花影乱：花影乱","莺声碎：莺声碎","飘零疏酒盏：飘零疏酒盏（疏远了酒杯）","离别宽衣带：离别宽衣带（人瘦了衣带宽松，用「衣带渐宽」意）","人不见：人不见","碧云暮合空相对：碧云暮合空相对","忆昔西池会：忆昔西池会（西池，汴京金明池，秦观曾与友人游此）","鹓鹭同飞盖：鹓鹭同飞盖（鹓鹭，指朝官；飞盖，飞驰的车盖）。鹓音yuān","携手处：携手处","今谁在：今谁在","日边清梦断：日边清梦断（皇帝身边的清梦断了，指被贬）","镜里朱颜改：镜里朱颜改","春去也：春去也","飞红万点愁如海：飞红万点愁如海"],"m":"春去也，飞红万点愁如海。","r":"按「水边沙外—春寒退—花影乱—莺声碎—飘零疏酒—离别宽带—人不见—碧云空对—忆昔西池—鹓鹭飞盖—携手处—今谁在—日边梦断—朱颜改—春去也—飞红万点—愁如海」背；「鹓」读yuān；用典（衣带渐宽、西池会）；「飞红万点愁如海」的夸张是核心；被贬之痛是主题。"},"72116:浣溪沙|秦观":{"s":"上片「漠漠轻寒上小楼。晓阴无赖似穷秋。淡烟流水画屏幽」写漠漠轻寒上小楼、晓阴无赖似穷秋，淡烟流水画屏幽，以轻寒、晓阴、画屏写环境的清幽；下片「自在飞花轻似梦。无边丝雨细如愁。宝帘闲挂小银钩」写自在飞花轻似梦、无边丝雨细如愁，宝帘闲挂小银钩，以「飞花轻似梦」「丝雨细如愁」的比喻写愁的轻盈与绵密，比喻新奇、对仗工稳，全词意境清丽、比喻巧妙、情感深沉，「自在飞花轻似梦，无边丝雨细如愁」成为千古名句，是婉约词的千古名篇。","b":"秦观这首《浣溪沙》写春愁，「自在飞花轻似梦，无边丝雨细如愁」是千古名句，是婉约词的千古名篇，梁启超评为「奇语」。","n":["浣溪沙：词牌名","漠漠轻寒上小楼：漠漠轻寒上小楼","晓阴无赖似穷秋：晓阴无赖似穷秋（深秋）","淡烟流水画屏幽：淡烟流水画屏幽","自在飞花轻似梦：自在飞花轻似梦","无边丝雨细如愁：无边丝雨细如愁","宝帘闲挂小银钩：宝帘闲挂小银钩"],"m":"自在飞花轻似梦，无边丝雨细如愁。","r":"按「漠漠轻寒—上小楼—晓阴无赖—似穷秋—淡烟流水—画屏幽—自在飞花—轻似梦—无边丝雨—细如愁—宝帘闲挂—小银钩」背；「飞花轻似梦」「丝雨细如愁」的比喻是核心；清丽意境是特点。"},"好事近|秦观":{"s":"上片「春路雨添花。花动一山春色。行到小溪深处，有黄鹂千百」写春路雨添花、花动一山春色，行到小溪深处有黄鹂千百，以春景写梦中的欢乐；下片「飞云当面化龙蛇。夭矫转空碧。醉卧古藤阴下，了不知南北」写飞云当面化龙蛇、夭矫转空碧，醉卧古藤阴下了不知南北，以「醉卧古藤阴下，了不知南北」写梦中的旷达与忘却，全词意境明丽、想象奇特、情感旷达，「醉卧古藤阴下，了不知南北」成为名句，后来秦观死于藤州，被认为是谶语。","b":"秦观这首《好事近》是他被贬处州时梦中所作，写梦中春游的欢乐，「醉卧古藤阴下，了不知南北」是名句，后来秦观死于藤州（今广西藤县），人们认为此词是谶语，是婉约词的名篇。","n":["好事近：词牌名","春路雨添花：春路雨添花","花动一山春色：花动一山春色","行到小溪深处：行到小溪深处","有黄鹂千百：有黄鹂千百","飞云当面化龙蛇：飞云当面化龙蛇（云的形状如龙蛇）","夭矫转空碧：夭矫（屈伸的样子）转空碧。夭矫音yāojiǎo","醉卧古藤阴下：醉卧古藤阴下","了不知南北：了（完全）不知南北"],"m":"醉卧古藤阴下，了不知南北。","r":"按「春路雨添花—花动春色—小溪深处—黄鹂千百—飞云化龙—夭矫空碧—醉卧古藤—了不知南北」背；「夭矫」读yāojiǎo；「了」是完全；梦中春游与谶语是背景；旷达忘却是核心。"},"春日偶成|程颢":{"s":"首两句「云淡风轻近午天，傍花随柳过前川」写云淡风轻近午天、傍花随柳过前川，以春景写郊游的快乐；后两句「时人不识余心乐，将谓偷闲学少年」是名句——时人不认识我心中的快乐，以为我偷闲学少年游乐，以「时人不识」写理学家的「孔颜乐处」——不是少年的游乐，而是理学家的「天理之乐」，全诗意境明丽、哲理深沉，「时人不识余心乐，将谓偷闲学少年」成为名句。","b":"程颢（北宋理学家，「二程」之一）这首《春日偶成》写春日郊游的快乐，「时人不识余心乐，将谓偷闲学少年」是名句，是理学家诗的名篇。","n":["春日偶成：诗题，程颢作","云淡风轻近午天：云淡风轻近午天（中午）","傍花随柳过前川：傍花随柳过前川（前面的河流）","时人不识余心乐：时人不识余心乐","将谓偷闲学少年：将谓偷闲学少年（以为我偷闲学少年游乐）"],"m":"时人不识余心乐，将谓偷闲学少年。","r":"四句按「云淡风轻—近午天—傍花随柳—过前川—时人不识—余心乐—将谓偷闲—学少年」背；「孔颜乐处」的理学家之乐是核心；与一般的游乐诗不同。"},"六国论|苏洵":{"s":"全文分五段：第一段提出中心论点——「六国破灭，非兵不利，战不善，弊在赂秦」，并分两层：赂秦而力亏是破灭之道，不赂者以赂者丧（失强援不能独完）；第二段论证「赂秦而力亏」——秦以攻取之外小则获邑大则得城，较秦之所得与战胜而得者其实百倍，诸侯之所亡与战败而亡者其实亦百倍，故秦之所大欲诸侯之所大患固不在战；思厥先祖父暴霜露斩荆棘以有尺寸之地，子孙视之不甚惜举以予人如弃草芥，今日割五城明日割十城然后得一夕安寝，起视四境而秦兵又至；然则诸侯之地有限暴秦之欲无厌，奉之弥繁侵之愈急，故不战而强弱胜负已判矣，至于颠覆理固宜然；引古人云「以地事秦犹抱薪救火，薪不尽火不灭」；第三段论证「不赂者以赂者丧」——齐人未尝赂秦终继五国迁灭，因为与嬴而不助五国，五国既丧齐亦不免；燕赵之君始有远略能守其土义不赂秦，故燕虽小国而后亡斯用兵之效；至丹以荆卿为计始速祸，赵尝五战于秦二败三胜，后秦击赵者再李牧连却之，洎牧以谗诛邯郸为郡，惜其用武而不终；且燕赵处秦革灭殆尽之际可谓智力孤危，战败而亡诚不得已；向使三国各爱其地齐人勿附于秦刺客不行良将犹在，则胜负之数存亡之理当与秦相较或未易量；第四段总结教训——以赂秦之地封天下之谋臣，以事秦之心礼天下之奇才，并力西向则吾恐秦人食之不得下咽；悲夫有如此之势而为秦人积威之所劫，日削月割以趋于亡，为国者无使为积威之所劫哉；第五段借古讽今——夫六国与秦皆诸侯其势弱于秦而犹有可以不赂而胜之之势，苟以天下之大下而从六国破亡之故事，是又在六国下矣。全文论证严密、对比鲜明、气势充沛、借古讽今，「弊在赂秦」「以地事秦犹抱薪救火」「为国者无使为积威之所劫」成为千古名句，是论说文的典范。","b":"苏洵（北宋散文家，「唐宋八大家」之一，苏轼之父）这篇《六国论》通过分析六国灭亡的原因在于「赂秦」，借古讽今，告诫北宋统治者不要重蹈覆辙，是中国古代论说文的千古名篇。","n":["六国论：篇名，苏洵作","六国破灭：六国破灭","非兵不利：不是兵器不锋利","战不善：仗打得不好","弊在赂秦：弊病在于贿赂秦国","赂秦而力亏：贿赂秦国而力量亏损","破灭之道也：是破灭的道路","或曰：有人说","六国互丧：六国相继灭亡","率赂秦耶：都是因为贿赂秦国吗。率音shuài，全都","不赂者以赂者丧：不贿赂的因为贿赂的而灭亡","盖失强援：大概因为失去了强大的援助","不能独完：不能独自保全","秦以攻取之外：秦国除了用战争夺取之外","小则获邑：小的就获得邑镇","大则得城：大的就获得城池","较秦之所得：比较秦国所得到的","其实百倍：它实际（数量）是百倍","诸侯之所亡：诸侯所失去的","其实亦百倍：它实际也是百倍","则秦之所大欲：那么秦国最大的欲望","诸侯之所大患：诸侯最大的祸患","固不在战矣：本来就不在于战争了","思厥先祖父：想想他们的先人祖父。厥音jué，其","暴霜露：冒着霜露。暴音pù，同「曝」","斩荆棘：斩断荆棘","以有尺寸之地：才有了尺寸之地","子孙视之不甚惜：子孙看待它不很爱惜","举以予人：拿来送给别人","如弃草芥：像抛弃草芥一样","今日割五城：今天割让五城","明日割十城：明天割让十城","然后得一夕安寝：然后得到一夜的安睡","起视四境：起来看看四周边境","而秦兵又至矣：而秦兵又到了","然则诸侯之地有限：既然这样那么诸侯的土地有限","暴秦之欲无厌：强暴的秦国的欲望没有满足。厌同「餍」，满足","奉之弥繁：奉送它越频繁。弥音mí，更加","侵之愈急：侵犯它越急迫","故不战而强弱胜负已判矣：所以不打仗而强弱胜负已经判定了","至于颠覆：到了灭亡","理固宜然：道理本来应该这样","古人云：古人说","以地事秦：用土地侍奉秦国","犹抱薪救火：就像抱着柴草救火","薪不尽：柴草不烧完","火不灭：火不会灭","此言得之：这话说对了","齐人未尝赂秦：齐人不曾贿赂秦国","终继五国迁灭：最终跟着五国灭亡","何哉：为什么呢","与嬴而不助五国也：亲附秦国而不帮助五国。与，亲附；嬴，秦王姓嬴，代指秦国","五国既丧：五国已经灭亡","齐亦不免矣：齐国也免不了了","燕赵之君：燕赵的国君","始有远略：开始有长远的谋略","能守其土：能守住他们的土地","义不赂秦：坚持正义不贿赂秦国","是故燕虽小国而后亡：所以燕国虽然是小国却后灭亡","斯用兵之效也：这是用兵的效果","至丹以荆卿为计：到了燕太子丹用荆轲（刺秦王）作为计策","始速祸焉：才招致了祸患。速，招致","赵尝五战于秦：赵国曾经与秦国打了五次仗","二败而三胜：两次失败三次胜利","后秦击赵者再：后来秦国两次攻打赵国","李牧连却之：李牧接连击退了它","洎牧以谗诛：等到李牧因为谗言被杀。洎音jì，等到","邯郸为郡：邯郸成为（秦国的）郡","惜其用武而不终也：可惜它用武力而不能坚持到底","且燕赵处秦革灭殆尽之际：况且燕赵处在秦国消灭（各国）将近完了的时候","可谓智力孤危：可以说智谋力量孤危","战败而亡：战败而灭亡","诚不得已：实在是不得已","向使三国各爱其地：假使三国（韩魏楚）各自爱惜他们的土地","齐人勿附于秦：齐人不要亲附秦国","刺客不行：刺客（荆轲）不去行刺","良将犹在：良将（李牧）还在","则胜负之数：那么胜负的命运。数音shù，命运","存亡之理：存亡的道理","当与秦相较：应当与秦国相比较","或未易量：或许还不容易估量","呜呼：唉","以赂秦之地封天下之谋臣：用贿赂秦国的土地分封天下的谋臣","以事秦之心礼天下之奇才：用侍奉秦国的心礼遇天下的奇才","并力西向：合力向西（对付秦国）","则吾恐秦人食之不得下咽也：那么我恐怕秦国人吃饭也咽不下去","悲夫：可悲啊","有如此之势：有这样的形势","而为秦人积威之所劫：却被秦国人积久的威势所胁迫。劫，胁迫","日削月割：天天割地月月割地","以趋于亡：以至于走向灭亡","为国者无使为积威之所劫哉：治理国家的人不要被积久的威势所胁迫啊","夫六国与秦皆诸侯：六国和秦国都是诸侯","其势弱于秦：他们的势力比秦国弱","而犹有可以不赂而胜之之势：却还有可以不贿赂而战胜它的形势","苟以天下之大：如果凭着天下的广大","下而从六国破亡之故事：降低身份追随六国灭亡的旧事（前例）","是又在六国下矣：这又在六国之下了"],"m":"六国破灭，非兵不利，战不善，弊在赂秦。以地事秦，犹抱薪救火，薪不尽，火不灭。","r":"按「提出论点：弊在赂秦—赂秦力亏—不赂者以赂者丧—论证赂秦：秦所得百倍—先祖父暴霜露—子孙弃草芥—今日割明日割—秦兵又至—地有限欲无厌—奉弥繁侵愈急—抱薪救火—论证不赂者：齐与嬴不助五国—燕赵义不赂秦—燕用荆轲速祸—赵李牧被诛—智力孤危—向使假设—总结教训：赂地封谋臣—事秦心礼奇才—并力西向—为积威所劫—为国者无使—借古讽今：天下之大—从六国故事—又在六国下」背；生僻字：率shuài、厥jué、暴pù、弥mí、厌同餍、与嬴、洎jì、数shù；借古讽今（讽北宋赂辽夏）是核心；「弊在赂秦」是中心论点。"},"58896:定风波|苏轼":{"s":"上片「莫听穿林打叶声。何妨吟啸且徐行。竹杖芒鞋轻胜马。谁怕。一蓑烟雨任平生」写莫听穿林打叶声、何妨吟啸且徐行，竹杖芒鞋轻胜马谁怕一蓑烟雨任平生，以「一蓑烟雨任平生」写面对风雨的旷达；下片「料峭春风吹酒醒。微冷。山头斜照却相迎。回首向来潇洒处。归去。也无风雨也无晴」写料峭春风吹酒醒微冷、山头斜照却相迎，回首向来潇洒处归去也无风雨也无晴，以「也无风雨也无晴」写宠辱不惊的人生态度——风雨和晴天都无所谓，全词意境旷达、哲理深沉、情感豪迈，「一蓑烟雨任平生」「也无风雨也无晴」成为千古名句，是豪放词的千古名篇。","b":"苏轼这首《定风波》是他被贬黄州时所作，写途中遇雨的经历，表达「也无风雨也无晴」的旷达人生态度，是豪放词的千古名篇。","n":["定风波：词牌名","莫听穿林打叶声：不要听穿林打叶的声音","何妨吟啸且徐行：何妨吟诗长啸且慢慢走","竹杖芒鞋轻胜马：竹杖草鞋轻胜过马。芒鞋，草鞋","谁怕：谁怕","一蓑烟雨任平生：一蓑烟雨任平生（任凭一生风雨）","料峭春风吹酒醒：微寒的春风吹酒醒。料峭，微寒","微冷：微冷","山头斜照却相迎：山头斜照却相迎","回首向来潇洒处：回首刚才走过的地方（潇洒处，指遇雨的地方）","归去：归去","也无风雨也无晴：也没有风雨也没有晴天（指宠辱不惊）"],"m":"竹杖芒鞋轻胜马。谁怕。一蓑烟雨任平生。回首向来潇洒处。归去。也无风雨也无晴。","r":"按「莫听打叶—何妨吟啸—且徐行—竹杖芒鞋—轻胜马—谁怕—一蓑烟雨—任平生—料峭春风—吹酒醒—微冷—山头斜照—却相迎—回首向来—潇洒处—归去—也无风雨—也无晴」背；「芒鞋」是草鞋、「料峭」是微寒；旷达人生态度是核心；「也无风雨也无晴」是哲理。"},"58965:江神子・江城子|苏轼":{"s":"上片「十年生死两茫茫。不思量。自难忘。千里孤坟，无处话凄凉。纵使相逢应不识，尘满面，鬓如霜」写十年生死两茫茫、不思量自难忘，千里孤坟无处话凄凉，纵使相逢应不识尘满面鬓如霜，以「十年生死」「千里孤坟」写时间与空间的阻隔、以「尘满面鬓如霜」写自己的衰老；下片「夜来幽梦忽还乡。小轩窗。正梳妆。相顾无言，惟有泪千行。料得年年断肠处，明月夜，短松冈」写夜来幽梦忽还乡、小轩窗正梳妆，相顾无言惟有泪千行，料得年年断肠处明月夜短松冈，以梦中相见写思念、以「相顾无言惟有泪千行」写悲痛、以「明月夜短松冈」写永恒的思念，全词意境凄清、情感深沉、真挚动人，「十年生死两茫茫」「相顾无言，惟有泪千行」成为千古名句，是悼亡词的千古绝唱。","b":"苏轼这首《江城子》是他悼念亡妻王弗所作，是中国文学史上最著名的悼亡词，「十年生死两茫茫」「相顾无言，惟有泪千行」是千古名句，是婉约词的千古名篇。","n":["江神子：词牌名，即《江城子》","十年生死两茫茫：十年生死两茫茫（苏轼妻王弗去世十年）","不思量：不思量","自难忘：自难忘","千里孤坟：千里孤坟（王弗葬在四川彭山，苏轼在山东密州，相隔千里）","无处话凄凉：无处话凄凉","纵使相逢应不识：纵使相逢应不识","尘满面：尘满面","鬓如霜：鬓如霜","夜来幽梦忽还乡：夜来幽梦忽还乡","小轩窗：小轩窗","正梳妆：正梳妆","相顾无言：相顾无言","惟有泪千行：惟有泪千行","料得年年断肠处：料得年年断肠处","明月夜：明月夜","短松冈：短松冈（王弗墓地）"],"m":"十年生死两茫茫。不思量。自难忘。相顾无言，惟有泪千行。","r":"按「十年生死—两茫茫—不思量—自难忘—千里孤坟—无处话凄凉—纵使相逢—应不识—尘满面—鬓如霜—夜来幽梦—忽还乡—小轩窗—正梳妆—相顾无言—惟有泪千行—料得年年—断肠处—明月夜—短松冈」背；悼亡主题是核心；王弗是苏轼第一任妻子；「相顾无言惟有泪千行」是名句。"},"58966:蝶恋花|苏轼":{"s":"上片「花褪残红青杏小。燕子飞时，绿水人家绕。枝上柳绵吹又少。天涯何处无芳草」写花褪残红青杏小、燕子飞时绿水人家绕，枝上柳绵吹又少天涯何处无芳草，以暮春景色写伤春；下片「墙里秋千墙外道。墙外行人，墙里佳人笑。笑渐不闻声渐悄。多情却被无情恼」写墙里秋千墙外道、墙外行人墙里佳人笑，笑渐不闻声渐悄多情却被无情恼，以「墙里墙外」的场景写多情被无情恼，全词意境清丽、情感深沉、哲理巧妙，「天涯何处无芳草」「多情却被无情恼」成为千古名句，是婉约词的千古名篇。","b":"苏轼这首《蝶恋花》写暮春景色与多情被无情恼的感慨，「天涯何处无芳草」「多情却被无情恼」是千古名句，是婉约词的千古名篇。","n":["蝶恋花：词牌名","花褪残红青杏小：花褪残红青杏小","燕子飞时：燕子飞时","绿水人家绕：绿水人家绕","枝上柳绵吹又少：枝上柳绵吹又少","天涯何处无芳草：天涯何处无芳草","墙里秋千墙外道：墙里秋千墙外道","墙外行人：墙外行人","墙里佳人笑：墙里佳人笑","笑渐不闻声渐悄：笑渐不闻声渐悄","多情却被无情恼：多情却被无情恼"],"m":"枝上柳绵吹又少。天涯何处无芳草。笑渐不闻声渐悄。多情却被无情恼。","r":"按「花褪残红—青杏小—燕子飞时—绿水人家—枝上柳绵—吹又少—天涯何处—无芳草—墙里秋千—墙外道—墙外行人—墙里佳人—笑渐不闻—声渐悄—多情却被—无情恼」背；「天涯何处无芳草」是名句；「多情却被无情恼」是哲理；墙里墙外的场景是核心。"},"59058:浣溪沙|苏轼":{"s":"上片「山下兰芽短浸溪。松间沙路净无泥。萧萧暮雨子规啼」写山下兰芽短浸溪、松间沙路净无泥，萧萧暮雨子规啼，以暮春景色写环境的清幽；下片「谁道人生无再少。门前流水尚能西。休将白发唱黄鸡」写谁道人生无再少、门前流水尚能西，休将白发唱黄鸡，以「流水尚能西」的反常现象说明人生可以「再少」、以「休将白发唱黄鸡」反用白居易典故写不要感叹时光流逝，全词意境清丽、哲理深沉、情感旷达，「谁道人生无再少，门前流水尚能西」成为千古名句，是豪放词的千古名篇。","b":"苏轼这首《浣溪沙》是他被贬黄州时游蕲水清泉寺所作，写暮春景色与「人生无再少」的旷达，「谁道人生无再少，门前流水尚能西」是千古名句，是豪放词的千古名篇。","n":["浣溪沙：词牌名","山下兰芽短浸溪：山下兰芽短浸溪","松间沙路净无泥：松间沙路净无泥","萧萧暮雨子规啼：萧萧暮雨子规（杜鹃）啼","谁道人生无再少：谁道人生无再少","门前流水尚能西：门前流水尚能西（溪水向西流，反「百川东到海」意）","休将白发唱黄鸡：休将白发唱黄鸡（不要因白发而感叹时光流逝，用白居易「黄鸡催晓」「白日催年」意，反其意而用之）"],"m":"谁道人生无再少，门前流水尚能西。休将白发唱黄鸡。","r":"按「山下兰芽—短浸溪—松间沙路—净无泥—萧萧暮雨—子规啼—谁道人生—无再少—门前流水—尚能西—休将白发—唱黄鸡」背；用典（白居易黄鸡催晓，反用）；「流水尚能西」的哲理是核心；旷达人生态度是主题。"},"和子由渑池怀旧|苏轼":{"s":"首联「人生到处知何似，应似飞鸿踏雪泥」以「飞鸿踏雪泥」比喻人生的行踪不定，成为千古名句，「雪泥鸿爪」成为成语；颔联「泥上偶然留指爪，鸿飞那复计东西」承接比喻——泥上偶然留下指爪，鸿雁飞走哪还计较东西，写人生的偶然与无常；颈联「老僧已死成新塔，坏壁无由见旧题」回到渑池的具体往事——老僧奉闲已死建成新塔，坏壁上当年的旧题已看不到，以具体人事写人生无常；尾联「往日崎岖还记否，路长人困蹇驴嘶」回忆当年路过渑池的艰辛——路长人困跛驴嘶，以回忆作结，全诗比喻新奇、哲理深沉、情感真挚，「人生到处知何似，应似飞鸿踏雪泥」成为千古名句，「雪泥鸿爪」成为成语。","b":"苏轼这首《和子由渑池怀旧》是他早年所作，写对人生无常的感慨，「人生到处知何似，应似飞鸿踏雪泥」是千古名句，「雪泥鸿爪」成为成语，是七律的千古名篇。","n":["和子由渑池怀旧：诗题，和弟弟苏辙（字子由）的《渑池怀旧》","人生到处知何似：人生到处知何似","应似飞鸿踏雪泥：应似飞鸿踏雪泥","泥上偶然留指爪：泥上偶然留指爪","鸿飞那复计东西：鸿飞那复计东西","老僧已死成新塔：老僧已死成新塔（渑池寺中老僧奉闲已死，建了新塔）","坏壁无由见旧题：坏壁无由见旧题（当年题在壁上的诗已看不到了）","往日崎岖还记否：往日崎岖还记否","路长人困蹇驴嘶：路长人困蹇驴（跛脚驴）嘶。蹇音jiǎn"],"m":"人生到处知何似，应似飞鸿踏雪泥。泥上偶然留指爪，鸿飞那复计东西。","r":"按「人生到处—知何似—应似飞鸿—踏雪泥—泥上偶然—留指爪—鸿飞那复—计东西—老僧已死—成新塔—坏壁无由—见旧题—往日崎岖—还记否—路长人困—蹇驴嘶」背；「蹇」读jiǎn；「雪泥鸿爪」的比喻是核心；人生无常的哲理是主题；与苏辙《渑池怀旧》对读。"},"东栏梨花|苏轼":{"s":"首两句「梨花淡白柳深青，柳絮飞时花满城」写梨花淡白柳深青、柳絮飞时花满城，以梨花与柳絮对比写春景；后两句「惆怅东栏一株雪，人生看得几清明」是名句——惆怅东栏一株梨花如雪，人生能看到几个清明呢，以「几清明」的反问写人生短暂、春光易逝，全诗意境清丽、情感深沉、哲理巧妙，「人生看得几清明」成为名句。","b":"苏轼这首《东栏梨花》写梨花与人生感慨，「人生看得几清明」是名句，是七绝的名篇。","n":["东栏梨花：诗题","梨花淡白柳深青：梨花淡白柳深青","柳絮飞时花满城：柳絮飞时花满城","惆怅东栏一株雪：惆怅东栏一株雪（指梨花）","人生看得几清明：人生看得几清明（几个清明时节）"],"m":"惆怅东栏一株雪，人生看得几清明。","r":"四句按「梨花淡白—柳深青—柳絮飞时—花满城—惆怅东栏—一株雪—人生看得—几清明」背；「一株雪」喻梨花；「人生看得几清明」的反问是核心；人生短暂是主题。"},"海棠|苏轼":{"s":"首两句「东风袅袅泛崇光，香雾空蒙月转廊」写东风袅袅泛崇光、香雾空蒙月转廊，以东风、香雾、月光写海棠的美丽；后两句「只恐夜深花睡去，故烧高烛照红妆」是千古名句——只恐夜深花睡去，所以烧高烛照红妆，以「花睡去」的拟人写对花的珍爱、以「烧高烛照红妆」写赏花的痴情，全诗意境清丽、拟人巧妙、情感真挚，「只恐夜深花睡去，故烧高烛照红妆」成为千古名句。","b":"苏轼这首《海棠》写深夜赏花，以「只恐夜深花睡去，故烧高烛照红妆」写对花的珍爱，是七绝的千古名篇。","n":["海棠：诗题","东风袅袅泛崇光：东风袅袅（轻柔）泛崇光（流动的光泽）。袅袅音niǎo","香雾空蒙月转廊：香雾空蒙月转廊（回廊）","只恐夜深花睡去：只恐夜深花睡去","故烧高烛照红妆：所以烧高烛照红妆（指海棠花）"],"m":"只恐夜深花睡去，故烧高烛照红妆。","r":"四句按「东风袅袅—泛崇光—香雾空蒙—月转廊—只恐夜深—花睡去—故烧高烛—照红妆」背；「袅袅」读niǎo；「花睡去」的拟人是核心；对花的珍爱是主题。"},"春宵|苏轼":{"s":"首两句「春宵一刻值千金，花有清香月有阴」写春宵一刻值千金、花有清香月有阴，以「一刻值千金」写春夜的珍贵，成为千古成语；后两句「歌管楼台声细细，秋千院落夜沉沉」写歌管楼台声细细、秋千院落夜沉沉，以「声细细」「夜沉沉」写春夜的幽静，全诗意境清丽、语言明快、哲理深沉，「春宵一刻值千金」成为千古成语。","b":"苏轼这首《春宵》写春夜的美好，「春宵一刻值千金」成为千古成语，是七绝的名篇。","n":["春宵：诗题","春宵一刻值千金：春宵一刻值千金（成语出处）","花有清香月有阴：花有清香月有阴（阴影）","歌管楼台声细细：歌管楼台声细细","秋千院落夜沉沉：秋千院落夜沉沉"],"m":"春宵一刻值千金，花有清香月有阴。","r":"四句按「春宵一刻—值千金—花有清香—月有阴—歌管楼台—声细细—秋千院落—夜沉沉」背；「春宵一刻值千金」是成语出处；春夜珍贵是主题。"},"石钟山记|苏轼":{"s":"全文分三段：第一段提出质疑——《水经》云彭蠡之口有石钟山，郦道元以为下临深潭微风鼓浪水石相搏声如洪钟，人常疑之（以钟磬置水中虽大风浪不能鸣）；唐李渤访遗踪得双石扣而聆之南声函胡北音清越桴止响腾余韵徐歇自以为得之，余尤疑之（石之铿然有声者所在皆是也，而此独以钟名何哉）；第二段写实地考察——元丰七年六月丁丑余自齐安舟行适临汝，长子迈赴饶之德兴尉，送之至湖口因得观所谓石钟；寺僧使小童持斧于乱石间择其一二扣之硿硿焉，余固笑而不信；至莫夜月明独与迈乘小舟至绝壁下，大石侧立千尺如猛兽奇鬼森然欲搏人，山上栖鹘闻人声惊起磔磔云霄间，又有若老人咳且笑于山谷中者或曰此鹳鹤也；余方心动欲还而大声发于水上噌吰如钟鼓不绝舟人大恐；徐而察之则山下皆石穴罅不知其浅深微波入焉涵澹澎湃而为此也；舟回至两山间将入港口有大石当中流可坐百人空中而多窍与风水相吞吐有窾坎镗鞳之声与向之噌吰者相应如乐作焉；因笑谓迈曰「汝识之乎？噌吰者周景王之无射也，窾坎镗鞳者魏庄子之歌钟也，古之人不余欺也」；第三段写议论——事不目见耳闻而臆断其有无可乎？郦元之所见闻殆与余同而言之不详；士大夫终不肯以小舟夜泊绝壁之下故莫能知；渔工水师虽知而不能言，此世所以不传也；而陋者乃以斧斤考击而求之自以为得其实；余是以记之，盖叹郦元之简而笑李渤之陋也。全文叙议结合、考察细致、议论精辟，「事不目见耳闻，而臆断其有无，可乎」「古之人不余欺也」成为千古名句，是游记散文的典范。","b":"苏轼这篇《石钟山记》是他由黄州移任汝州、送儿子苏迈赴德兴尉任时游石钟山所作，通过实地考察探明石钟山命名的原因，提出「事不目见耳闻，而臆断其有无，可乎」的治学态度，是中国古代游记散文的千古名篇。","n":["石钟山记：篇名，苏轼作","《水经》云：《水经》说","彭蠡之口有石钟山焉：彭蠡（鄱阳湖）口有石钟山","郦元以为下临深潭：郦元（郦道元）认为下临深潭","微风鼓浪：微风鼓浪（鼓动波浪）","水石相搏：水石相搏（撞击）","声如洪钟：声如洪钟","是说也：这个说法","人常疑之：人们常常怀疑它","今以钟磬置水中：现在把钟磬放在水中","虽大风浪不能鸣也：即使大风浪也不能使它鸣响","而况石乎：更何况石头呢","至唐李渤始访其遗踪：到唐李渤才寻访它的遗迹","得双石于潭上：在潭上得到两块石头","扣而聆之：敲而听它。扣同「叩」，敲击；聆音líng，听","南声函胡：南边的声音函胡（模糊）","北音清越：北边的声音清越（清脆高扬）","桴止响腾：鼓槌停止声音还在腾响。桴音fú，鼓槌","余韵徐歇：余韵慢慢停歇","自以为得之矣：自以为得到了（石钟山命名的原因）","然是说也：然而这个说法","余尤疑之：我更加怀疑它","石之铿然有声者：石头铿然（金石声）有声的","所在皆是也：到处都是这样","而此独以钟名：而这里独以钟命名","何哉：为什么呢","元丰七年六月丁丑：元丰七年（1084）六月丁丑日","余自齐安舟行适临汝：我从齐安（今湖北黄冈）坐船到临汝（今河南临汝）","而长子迈将赴饶之德兴尉：而大儿子苏迈将去饶州德兴县做县尉","送之至湖口：送他到湖口（今江西湖口）","因得观所谓石钟者：因而得以观看所谓石钟山","寺僧使小童持斧：寺僧让小童拿着斧头","于乱石间择其一二扣之：在乱石间选一两块敲它","硿硿焉：硿硿地响。硿音kōng","余固笑而不信也：我本来笑着不相信","至莫夜月明：到了暮夜（夜晚）月明。莫同「暮」","独与迈乘小舟：独与苏迈乘小舟","至绝壁下：到绝壁下","大石侧立千尺：大石侧立千尺","如猛兽奇鬼：如猛兽奇鬼","森然欲搏人：森然（阴森的样子）想要扑人","而山上栖鹘：而山上栖鹘（隼类猛禽）。鹘音hú","闻人声而惊起：听到人声而惊起","磔磔云霄间：磔磔（鸟鸣声）在云霄间。磔音zhé","又有若老人咳且笑于山谷中者：又有像老人咳嗽且笑在山谷中的","或曰此鹳鹤也：有人说这是鹳鹤。鹳音guàn","余方心动欲还：我正心惊想要回去","而大声发于水上：而大声发于水上","噌吰如钟鼓不绝：噌吰（钟声）如钟鼓不绝。噌吰音chēnghóng","舟人大恐：船夫非常害怕","徐而察之：慢慢观察它","则山下皆石穴罅：则山下都是石穴裂缝。罅音xià，裂缝","不知其浅深：不知它的浅深","微波入焉：微波进入其中","涵澹澎湃而为此也：涵澹（水波动荡）澎湃（波浪相激）而发出这个声音。涵澹音hándàn","舟回至两山间：船回到两山间","将入港口：将要进入港口","有大石当中流：有大石挡在中流","可坐百人：可坐百人","空中而多窍：中间空而多窍（孔）","与风水相吞吐：与风水相吞吐","有窾坎镗鞳之声：有窾坎镗鞳（钟鼓声）之声。窾坎镗鞳音kuǎnkǎntāngtà","与向之噌吰者相应：与刚才的噌吰声相应和","如乐作焉：如音乐演奏一样","因笑谓迈曰：于是笑着对苏迈说","汝识之乎：你知道吗。识音zhì，同「志」，记住","噌吰者：噌吰的声音","周景王之无射也：是周景王的无射钟（无射，钟名，音wúyì）","窾坎镗鞳者：窾坎镗鞳的声音","魏庄子之歌钟也：是魏庄子（魏绛）的歌钟","古之人不余欺也：古人没有欺骗我啊（不余欺，不欺余）","事不目见耳闻：事情不目见耳闻","而臆断其有无：而主观判断它的有无","可乎：可以吗","郦元之所见闻：郦道元的所见所闻","殆与余同：大概与我相同","而言之不详：而说得不详细","士大夫终不肯以小舟夜泊绝壁之下：士大夫终究不肯以小舟夜泊绝壁之下","故莫能知：所以不能知道","而渔工水师虽知而不能言：而渔工水师虽然知道却不能说出来","此世所以不传也：这是世上所以不流传的原因","而陋者乃以斧斤考击而求之：而浅陋的人竟以斧头敲击来寻求它","自以为得其实：自以为得到了它的实际","余是以记之：我因此记下它","盖叹郦元之简：大概感叹郦道元的简略","而笑李渤之陋也：而嘲笑李渤的浅陋"],"m":"事不目见耳闻，而臆断其有无，可乎？古之人不余欺也。","r":"按「提出质疑：郦道元说—人常疑之—李渤说—余尤疑之—实地考察：元丰七年—送苏迈—至湖口—寺僧扣石—余不信—莫夜乘小舟—至绝壁—大石猛兽—栖鹘惊起—鹳鹤咳笑—余心动欲还—大声噌吰—舟人大恐—徐察石穴罅—微波入—涵澹澎湃—舟回两山间—大石当中流—空中多窍—风水吞吐—窾坎镗鞳—如乐作—笑谓迈—古之人不余欺—议论：事不目见耳闻—臆断可乎—郦元简—士大夫不肯夜泊—渔工不能言—陋者斧击—叹郦元之简—笑李渤之陋」背；生僻字：聆líng、桴fú、铿kēng、莫同暮、鹘hú、磔zhé、鹳guàn、噌吰chēnghóng、罅xià、涵澹hándàn、窾坎镗鞳kuǎnkǎntāngtà、识zhì、无射wúyì；「事不目见耳闻不可臆断」是核心；实地考察的治学态度是主题。"},"后赤壁赋|苏轼":{"s":"全文分四段：第一段写游前准备——是岁十月之望步自雪堂将归于临皋，二客从予过黄泥之坂，霜露既降木叶尽脱，人影在地仰见明月，顾而乐之行歌相答；已而叹曰有客无酒有酒无肴月白风清如此良夜何；客曰今者薄暮举网得鱼巨口细鳞状如松江之鲈顾安所得酒乎；归而谋诸妇，妇曰我有斗酒藏之久矣以待子不时之需；第二段写游赤壁——于是携酒与鱼复游于赤壁之下，江流有声断岸千尺，山高月小水落石出，曾日月之几何而江山不可复识矣；第三段写登山——予乃摄衣而上，履巉岩披蒙茸踞虎豹登虬龙，攀栖鹘之危巢俯冯夷之幽宫，盖二客不能从焉；划然长啸草木震动山鸣谷应风起水涌，予亦悄然而悲肃然而恐凛乎其不可留也；反而登舟放乎中流听其所止而休焉；第四段写孤鹤与梦境——时夜将半四顾寂寥，适有孤鹤横江东来翅如车轮玄裳缟衣戛然长鸣掠予舟而西也；须臾客去予亦就睡，梦一道士羽衣蹁跹过临皋之下揖予而言曰赤壁之游乐乎；问其姓名俯而不答，呜呼噫嘻我知之矣畴昔之夜飞鸣而过我者非子也邪；道士顾笑余亦惊悟，开户视之不见其处。全文写景如画、叙事生动、梦境奇幻、哲理深沉，「山高月小，水落石出」成为千古名句，与《前赤壁赋》并称赋体散文的双璧。","b":"苏轼这篇《后赤壁赋》是他被贬黄州时所作，是《前赤壁赋》的姊妹篇，写十月十五日游赤壁的经历，以孤鹤与道士的梦境写超脱旷达的人生态度，是中国古代赋体散文的千古名篇。","n":["后赤壁赋：篇名，苏轼作","是岁十月之望：这年十月十五日（望，农历十五）","步自雪堂：从雪堂（苏轼在黄州建的堂）步行","将归于临皋：将回到临皋（苏轼在黄州的居所）","二客从予过黄泥之坂：两位客人跟我过黄泥坂（山坡）。坂音bǎn","霜露既降：霜露已经降下","木叶尽脱：树叶全部脱落","人影在地：人影在地","仰见明月：仰见明月","顾而乐之：顾而乐之","行歌相答：边走边唱互相唱和","已而叹曰：过了一会儿叹道","有客无酒：有客无酒","有酒无肴：有酒无菜。肴音yáo，菜","月白风清：月白风清","如此良夜何：如此良夜怎么办呢","客曰：客人说","今者薄暮：刚才傍晚","举网得鱼：举网得鱼","巨口细鳞：巨口细鳞","状如松江之鲈：形状像松江的鲈鱼","顾安所得酒乎：但哪里能得到酒呢","归而谋诸妇：回去跟妻子商量","妇曰：妻子说","我有斗酒：我有一斗酒","藏之久矣：藏了很久了","以待子不时之需：以等待你不时的需要","于是携酒与鱼：于是携酒与鱼","复游于赤壁之下：又游于赤壁之下","江流有声：江流有声","断岸千尺：断岸千尺","山高月小：山高月小","水落石出：水落石出","曾日月之几何：才过了多少日子（距前次游赤壁）","而江山不可复识矣：而江山不可再认识了（变化太大）","予乃摄衣而上：我于是提起衣服上山","履巉岩：踏险峻的岩石。巉音chán","披蒙茸：拨开茂密的野草。蒙茸音méngróng","踞虎豹：蹲在虎豹（形状像虎豹的石头）上","登虬龙：登上虬龙（形状像虬龙的树木）。虬音qiú","攀栖鹘之危巢：攀栖鹘（猛禽）的高巢。鹘音hú","俯冯夷之幽宫：俯视冯夷（水神）的幽宫。冯夷音píngyí","盖二客不能从焉：大概两位客人不能跟从我了","划然长啸：划然（长啸声）长啸","草木震动：草木震动","山鸣谷应：山鸣谷应","风起水涌：风起水涌","予亦悄然而悲：我也悄然而悲","肃然而恐：肃然而恐","凛乎其不可留也：凛然（恐惧的样子）不可久留了","反而登舟：反而登舟","放乎中流：放（船）到中流","听其所止而休焉：听它停在哪里就休息在哪里","时夜将半：时夜将半","四顾寂寥：四顾寂寥","适有孤鹤：恰好有孤鹤","横江东来：横江东来","翅如车轮：翅如车轮","玄裳缟衣：玄裳（黑裙）缟衣（白衣）。玄，黑色；缟音gǎo，白色","戛然长鸣：戛然（鹤鸣声）长鸣。戛音jiá","掠予舟而西也：掠过我的船向西去了","须臾客去：过了一会儿客人离去","予亦就睡：我也去睡","梦一道士：梦见一个道士","羽衣蹁跹：羽衣（道士穿的鸟羽衣）蹁跹（轻盈飞舞）。蹁跹音piánxiān","过临皋之下：过临皋之下","揖予而言曰：向我作揖说道","赤壁之游乐乎：赤壁之游乐吗","问其姓名：问他姓名","俯而不答：俯而不答","呜呼噫嘻：呜呼噫嘻（感叹词）","我知之矣：我知道了","畴昔之夜：昨夜","飞鸣而过我者：飞鸣而过我的","非子也邪：不是你吗","道士顾笑：道士回头笑","余亦惊悟：我也惊醒","开户视之：开门看他","不见其处：不见他的去处"],"m":"山高月小，水落石出。","r":"按「游前准备：十月望—雪堂归临皋—过黄泥坂—霜露木叶—人影明月—行歌相答—叹无酒肴—客举网得鱼—如松江鲈—妇有斗酒—藏之久矣—游赤壁：携酒与鱼—复游赤壁—江流有声—断岸千尺—山高月小—水落石出—江山不可复识—登山：摄衣而上—履巉岩—披蒙茸—踞虎豹—登虬龙—攀鹘巢—俯冯夷—二客不能从—划然长啸—草木震动—山鸣谷应—风起水涌—悄然而悲—肃然而恐—凛乎不可留—反而登舟—放乎中流—听其所止—孤鹤梦境：夜将半—四顾寂寥—孤鹤东来—翅如车轮—玄裳缟衣—戛然长鸣—掠舟而西—客去就睡—梦道士—羽衣蹁跹—过临皋—揖予—赤壁乐乎—问姓名—俯不答—我知之矣—飞鸣过我—非子也邪—道士顾笑—余亦惊悟—开户视之—不见其处」背；生僻字：坂bǎn、肴yáo、巉chán、蒙茸méngróng、虬qiú、鹘hú、冯夷píngyí、缟gǎo、戛jiá、蹁跹piánxiān；「山高月小水落石出」是名句；孤鹤道士的梦境写超脱旷达是核心；与《前赤壁赋》对读。"},"苏幕遮|范仲淹":{"s":"上片「碧云天。黄叶地。秋色连波，波上寒烟翠。山映斜阳天接水。芳草无情，更在斜阳外」写碧云天黄叶地、秋色连波波上寒烟翠，山映斜阳天接水、芳草无情更在斜阳外，以秋景写思乡；下片「黯乡魂。追旅思。夜夜除非，好梦留人睡。明月楼高休独倚。酒入愁肠，化作相思泪」写黯乡魂追旅思、夜夜除非好梦留人睡，明月楼高休独倚、酒入愁肠化作相思泪，以「酒入愁肠化作相思泪」的夸张写思乡之深，全词意境开阔、情感深沉、夸张巧妙，「碧云天，黄叶地」「酒入愁肠，化作相思泪」成为千古名句，是婉约词的千古名篇。","b":"范仲淹（北宋政治家、文学家）这首《苏幕遮》写秋日思乡之情，「碧云天，黄叶地」「酒入愁肠，化作相思泪」是千古名句，是婉约词的千古名篇。","n":["苏幕遮：词牌名","碧云天：碧云天","黄叶地：黄叶地","秋色连波：秋色连波","波上寒烟翠：波上寒烟翠","山映斜阳天接水：山映斜阳天接水","芳草无情：芳草无情","更在斜阳外：更在斜阳外","黯乡魂：黯乡魂（思乡的灵魂黯然）","追旅思：追旅思（羁旅的愁思）","夜夜除非：夜夜除非","好梦留人睡：好梦留人睡","明月楼高休独倚：明月楼高休独倚","酒入愁肠：酒入愁肠","化作相思泪：化作相思泪"],"m":"碧云天，黄叶地。秋色连波，波上寒烟翠。酒入愁肠，化作相思泪。","r":"按「碧云天—黄叶地—秋色连波—寒烟翠—山映斜阳—天接水—芳草无情—斜阳外—黯乡魂—追旅思—夜夜除非—好梦留睡—明月楼高—休独倚—酒入愁肠—化作相思泪」背；「碧云天黄叶地」是名句；「酒入愁肠化作相思泪」的夸张是核心；思乡是主题。"},"渔家傲|范仲淹":{"s":"上片「塞下秋来风景异。衡阳雁去无留意。四面边声连角起。千嶂里。长烟落日孤城闭」写塞下秋来风景异、衡阳雁去无留意，四面边声连角起，千嶂里长烟落日孤城闭，以边塞秋景写环境的荒凉；下片「浊酒一杯家万里。燕然未勒归无计。羌管悠悠霜满地。人不寐。将军白发征夫泪」写浊酒一杯家万里、燕然未勒归无计，羌管悠悠霜满地，人不寐将军白发征夫泪，以「家万里」与「燕然未勒」的矛盾写将士的思乡与报国、以「将军白发征夫泪」写将士的悲苦，全词意境苍凉、情感深沉、刚健豪放，「将军白发征夫泪」成为千古名句，是豪放词的千古名篇，开宋代豪放词之先声。","b":"范仲淹这首《渔家傲》是他任陕西经略副使、镇守西北边疆时所作，写边塞将士的思乡与报国之情，「将军白发征夫泪」是千古名句，是豪放词的千古名篇，开宋代豪放词之先声。","n":["渔家傲：词牌名","塞下秋来风景异：塞下秋来风景异","衡阳雁去无留意：衡阳雁去无留意（雁去衡阳，毫无留恋之意）","四面边声连角起：四面边声（边塞的声音）连角（号角）起","千嶂里：千嶂（像屏障的山峰）里","长烟落日孤城闭：长烟落日孤城闭","浊酒一杯家万里：浊酒一杯家万里","燕然未勒归无计：燕然未勒归无计（燕然，山名，东汉窦宪追北单于登燕然山刻石纪功；勒，刻石。指没有建立功业不能回去）","羌管悠悠霜满地：羌管（羌笛）悠悠霜满地","人不寐：人不寐（睡不着）","将军白发征夫泪：将军白发征夫泪"],"m":"浊酒一杯家万里，燕然未勒归无计。羌管悠悠霜满地。人不寐。将军白发征夫泪。","r":"按「塞下秋来—风景异—衡阳雁去—无留意—四面边声—连角起—千嶂里—长烟落日—孤城闭—浊酒一杯—家万里—燕然未勒—归无计—羌管悠悠—霜满地—人不寐—将军白发—征夫泪」背；用典（窦宪燕然勒石）；思乡与报国的矛盾是核心；开豪放词先声是地位。"},"67825:贺新郎|蒋捷":{"s":"上片「渺渺啼鸦了。亘鱼天、寒生峭屿，五湖秋晓。竹几一灯人做梦，嘶马谁行古道。起搔首、窥星多少。月有微黄篱无影，挂牵牛、数朵青花小。秋太淡，添红枣」写渺渺啼鸦了、亘鱼天寒生峭屿五湖秋晓，竹几一灯人做梦嘶马谁行古道，起搔首窥星多少，月有微黄篱无影挂牵牛数朵青花小，秋太淡添红枣，以秋景写愁思；下片「愁痕倚赖西风扫。被西风、翻催鬓鬒，与秋俱老。旧院隔霜帘不卷，金粉屏边醉倒。计无此、中年怀抱。万里江南吹箫恨，恨参差、白雁横天杪。烟未敛，楚山杳」写愁痕倚赖西风扫、被西风翻催鬓鬒与秋俱老，旧院隔霜帘不卷金粉屏边醉倒计无此中年怀抱，万里江南吹箫恨恨参差白雁横天杪，烟未敛楚山杳，以「吹箫恨」（伍子胥典故）写亡国之痛、以「白雁横天杪」写愁思的辽远，全词意境凄清、用典贴切（伍子胥吹箫）、情感深沉，是南宋遗民词的名篇。","b":"蒋捷（南宋末元初词人，号竹山）这首《贺新郎》写秋日的愁思与亡国之痛，「万里江南吹箫恨」写亡国之痛，是南宋遗民词的名篇，与他的《虞美人·听雨》《一剪梅·舟过吴江》并称。","n":["贺新郎：词牌名","渺渺啼鸦了：渺渺啼鸦了（停）","亘鱼天、寒生峭屿：亘（横贯）鱼天寒生峭屿。亘音gèn","五湖秋晓：五湖（太湖）秋晓","竹几一灯人做梦：竹几一灯人做梦","嘶马谁行古道：嘶马谁行古道","起搔首、窥星多少：起搔首窥星多少","月有微黄篱无影：月有微黄篱无影","挂牵牛、数朵青花小：挂牵牛数朵青花小","秋太淡：秋太淡","添红枣：添红枣","愁痕倚赖西风扫：愁痕倚赖西风扫","被西风、翻催鬓鬒：被西风翻催鬓鬒（鬓发）。鬒音zhěn，黑发","与秋俱老：与秋俱老","旧院隔霜帘不卷：旧院隔霜帘不卷","金粉屏边醉倒：金粉屏边醉倒","计无此、中年怀抱：计无此中年怀抱","万里江南吹箫恨：万里江南吹箫恨（用伍子胥吹箫乞食典故）","恨参差、白雁横天杪：恨参差白雁横天杪（天末）。杪音miǎo","烟未敛：烟未敛","楚山杳：楚山杳（遥远）"],"m":"万里江南吹箫恨，恨参差、白雁横天杪。","r":"按「啼鸦了—亘鱼天—寒生峭屿—五湖秋晓—竹几一灯—人做梦—嘶马古道—起搔首—窥星多少—月微黄—篱无影—挂牵牛—青花小—秋太淡—添红枣—愁痕西风—翻催鬓鬒—与秋俱老—旧院隔霜—帘不卷—金粉屏边—醉倒—中年怀抱—万里江南—吹箫恨—白雁横天—烟未敛—楚山杳」背；「亘」读gèn、「鬒」读zhěn、「杪」读miǎo；用典（伍子胥吹箫乞食）；亡国之痛是核心。"},"67832:女冠子|蒋捷":{"s":"上片「蕙花香也。雪晴池馆如画。春风飞到，宝钗楼上，一片笙箫，琉璃光射。而今灯漫挂。不是暗尘明月，那时元夜」写蕙花香、雪晴池馆如画，春风飞到宝钗楼上一片笙箫琉璃光射，而今灯漫挂不是暗尘明月那时元夜，以元宵的今昔对比写亡国之痛；下片「况年来、心懒意怯，羞与蛾儿争要。江城人悄初更打。问繁华谁解，再向天公借。剔残红灺。但梦里隐隐，钿车罗帕。吴笺银粉砑。待把旧家风景，写成闲话。笑绿鬟邻女，倚窗犹唱，夕阳西下」写况年来心懒意怯羞与蛾儿争要，江城人悄初更打，问繁华谁解再向天公借，剔残红灺但梦里隐隐钿车罗帕，吴笺银粉砑待把旧家风景写成闲话，笑绿鬟邻女倚窗犹唱夕阳西下，以「邻女犹唱夕阳西下」写对故国的思念——邻女还在唱从前的歌曲，而故国已亡，全词今昔对比、用典贴切、情感深沉，「笑绿鬟邻女，倚窗犹唱，夕阳西下」成为名句，是南宋遗民词的名篇。","b":"蒋捷这首《女冠子》写元宵节的今昔对比，以「笑绿鬟邻女，倚窗犹唱，夕阳西下」写亡国之痛，是南宋遗民词的名篇。","n":["女冠子：词牌名","蕙花香也：蕙花香也","雪晴池馆如画：雪晴池馆如画","春风飞到：春风飞到","宝钗楼上：宝钗楼上","一片笙箫：一片笙箫","琉璃光射：琉璃光射","而今灯漫挂：而今灯漫挂（随便挂）","不是暗尘明月：不是暗尘明月（指从前元宵节的热闹）","那时元夜：那时元夜（元宵节）","况年来、心懒意怯：况年来心懒意怯","羞与蛾儿争要：羞与蛾儿（元宵节的饰物）争要","江城人悄初更打：江城人悄初更打","问繁华谁解：问繁华谁解","再向天公借：再向天公借","剔残红灺：剔残红灺（残烛）。灺音xiè，蜡烛的余烬","但梦里隐隐：但梦里隐隐","钿车罗帕：钿车罗帕（饰金的车、罗帕）","吴笺银粉砑：吴笺银粉砑（压光的银粉纸）。砑音yà，碾磨","待把旧家风景：待把旧家风景","写成闲话：写成闲话","笑绿鬟邻女：笑绿鬟邻女","倚窗犹唱：倚窗犹唱","夕阳西下：夕阳西下（指从前的歌曲）"],"m":"笑绿鬟邻女，倚窗犹唱，夕阳西下。","r":"按「蕙花香—雪晴池馆—春风飞到—宝钗楼—笙箫—琉璃光射—而今灯漫挂—不是暗尘—那时元夜—年来心懒—意怯—羞与蛾儿—争要—江城人悄—初更打—繁华谁解—向天公借—剔残红灺—梦里隐隐—钿车罗帕—吴笺银粉—砑—旧家风景—写成闲话—笑绿鬟—邻女—倚窗犹唱—夕阳西下」背；「灺」读xiè、「砑」读yà；今昔对比是核心；「邻女犹唱夕阳西下」写亡国之痛是核心。"},"虞美人·听雨|蒋捷":{"s":"全词以「听雨」为线索，分三个阶段：上片「少年听雨歌楼上。红烛昏罗帐。壮年听雨客舟中。江阔云低、断雁叫西风」写少年时在歌楼上听雨、红烛昏罗帐——欢乐奢靡；壮年时在客舟中听雨、江阔云低断雁叫西风——漂泊孤独；下片「而今听雨僧庐下。鬓已星星也。悲欢离合总无情。一任阶前、点滴到天明」写而今在僧庐下听雨、鬓已星星——亡国后的孤苦；悲欢离合总无情，一任阶前点滴到天明——对人生的彻悟与无奈。全词以「听雨」贯穿一生，三个场景三种心境，对比鲜明、情感深沉、语言精炼，「少年听雨歌楼上，红烛昏罗帐。壮年听雨客舟中，江阔云低、断雁叫西风。而今听雨僧庐下，鬓已星星也」成为千古名句，是南宋遗民词的千古名篇。","b":"蒋捷这首《虞美人·听雨》以「听雨」为线索，写少年、壮年、晚年三个阶段的人生经历，表达亡国后的深沉感慨，是南宋遗民词的千古名篇，「少年听雨歌楼上，红烛昏罗帐。壮年听雨客舟中，江阔云低、断雁叫西风。而今听雨僧庐下，鬓已星星也」成为千古名句。","n":["虞美人·听雨：词牌名+题目","少年听雨歌楼上：少年听雨歌楼上","红烛昏罗帐：红烛昏罗帐","壮年听雨客舟中：壮年听雨客舟中","江阔云低、断雁叫西风：江阔云低断雁叫西风","而今听雨僧庐下：而今听雨僧庐下","鬓已星星也：鬓已星星也（花白）","悲欢离合总无情：悲欢离合总无情","一任阶前、点滴到天明：一任阶前点滴到天明"]},"六州歌头|贺铸":{"s":"上片「少年侠气，交结五都雄。肝胆洞。毛发耸。立谈中。死生同。一诺千金重。推翘勇。衿豪踪。轻盖拥。聊飞鞚。斗城东。轰饮酒炉，春色浮寒瓮。吸海垂虹。闲呼鹰嗾犬，白羽摘雕弓。狡穴俄空。乐匆匆」写少年侠气交结五都雄，肝胆洞毛发耸立谈中死生同一诺千金重，推翘勇衿豪踪轻盖拥聊飞鞚斗城东，轰饮酒炉春色浮寒瓮吸海垂虹，闲呼鹰嗾犬白羽摘雕弓狡穴俄空乐匆匆，以少年的豪侠生活写欢乐；下片「似黄粱梦。辞丹凤。明月共。漾孤篷。官冗从。怀倥偬。落尘笼。薄书从。鹖弁如云众。共粗用。忽奇功。笳鼓动。渔阳弄。思悲翁。不请长缨，系取天娇种。剑吼西风。恨登山临水，手寄七弦桐。目送归鸿」写似黄粱梦辞丹凤明月共漾孤篷，官冗从怀倥偬落尘笼薄书从，鹖弁如云众共粗用忽奇功，笳鼓动渔阳弄思悲翁，不请长缨系取天娇种剑吼西风，恨登山临水手寄七弦桐目送归鸿，以中年的失意与壮志难酬写悲慨，全词气势磅礴、对比鲜明、情感深沉，「不请长缨，系取天娇种。剑吼西风」成为名句，是豪放词的千古名篇。","b":"贺铸（北宋词人，号庆湖遗老）这首《六州歌头》写少年的豪侠生活与中年的失意，以「剑吼西风」写壮志难酬，是豪放词的千古名篇，夏敬观评为「雄姿壮采，不可一世」。","n":["六州歌头：词牌名","少年侠气：少年侠气","交结五都雄：交结五都（五大都市）的英雄","肝胆洞：肝胆洞（肝胆相照、坦诚）","毛发耸：毛发耸（激昂）","立谈中：立谈中（站着谈话之间）","死生同：死生同（同生共死）","一诺千金重：一诺千金重（承诺重如千金）","推翘勇：推翘勇（推崇杰出的勇士）","衿豪踪：衿豪踪（衣襟上带着豪杰的踪迹）","轻盖拥：轻盖拥（轻车簇拥）","聊飞鞚：聊飞鞚（姑且飞马）。鞚音kòng，马笼头，代指马","斗城东：斗城东（汴京城东）","轰饮酒炉：轰饮酒炉（在酒垆豪饮）","春色浮寒瓮：春色浮寒瓮（酒瓮中浮着春色）","吸海垂虹：吸海垂虹（像垂虹吸海一样豪饮）","闲呼鹰嗾犬：闲呼鹰嗾犬（嗾，使唤狗的声音，此指嗾使）。嗾音sǒu","白羽摘雕弓：白羽摘雕弓（从雕弓上取箭）","狡穴俄空：狡穴俄空（狡兔的巢穴很快空了）","乐匆匆：乐匆匆（欢乐匆匆）","似黄粱梦：似黄粱梦（像黄粱一梦）","辞丹凤：辞丹凤（辞别京城。丹凤，丹凤楼，代指京城）","明月共：明月共（与明月相伴）","漾孤篷：漾孤篷（飘荡孤舟）","官冗从：官冗从（做闲散的随从官）。冗音rǒng","怀倥偬：怀倥偬（心怀事情繁忙）。倥偬音kǒngzǒng","落尘笼：落尘笼（落入尘世的牢笼）","薄书从：薄书从（簿书文书相从）","鹖弁如云众：鹖弁如云众（武官如云之多。鹖弁音hébiàn，武官的帽子）","共粗用：共粗用（都做粗用）","忽奇功：忽奇功（忽然建立奇功）","笳鼓动：笳鼓动（笳鼓响起，指战事起）","渔阳弄：渔阳弄（渔阳鼙鼓，指安禄山叛乱，此指金兵入侵）","思悲翁：思悲翁（思念悲翁，古乐府曲名）","不请长缨：不请长缨（不请求长绳，指不请缨杀敌）","系取天娇种：系取天娇种（捆绑天骄，指匈奴，此指金人）","剑吼西风：剑吼西风（剑在西风中吼叫）","恨登山临水：恨登山临水","手寄七弦桐：手寄七弦桐（手寄七弦琴。桐，代指琴）","目送归鸿：目送归鸿"],"m":"不请长缨，系取天娇种。剑吼西风。","r":"按「少年侠气—交结五都—肝胆洞—毛发耸—立谈中—死生同—一诺千金—推翘勇—衿豪踪—轻盖拥—飞鞚—斗城东—轰饮酒炉—春色寒瓮—吸海垂虹—呼鹰嗾犬—白羽雕弓—狡穴俄空—乐匆匆—似黄粱梦—辞丹凤—明月共—漾孤篷—官冗从—怀倥偬—落尘笼—薄书从—鹖弁如云—共粗用—忽奇功—笳鼓动—渔阳弄—思悲翁—不请长缨—系取天骄—剑吼西风—恨登山临水—手寄七弦—目送归鸿」背；「鞚」读kòng、「嗾」读sǒu、「冗」读rǒng、「倥偬」读kǒngzǒng、「鹖弁」读hébiàn；用典（黄粱梦、请缨、渔阳鼙鼓、七弦琴）；少年豪侠与中年失意的对比是核心；「剑吼西风」是名句。"},"石州引・石州慢|贺铸":{"s":"上片「薄雨初寒。斜照弄晴。春意空阔。长亭柳色缠黄。远客一枝先折。烟横水际。映带几点归鸦。东风销尽龙沙雪。还记初关来。恰而今时节」写薄雨初寒斜照弄晴春意空阔，长亭柳色缠黄远客一枝先折，烟横水际映带几点归鸦东风销尽龙沙雪，还记初关来恰而今时节，以春景写离别；下片「将发。画楼芳酒。红泪清歌。顿成清别。已是经年。杳杳音尘多绝。欲知方寸。共有几许清愁。芭蕉不展丁香结。枉望断天涯。两厌厌风月」写将发画楼芳酒红泪清歌顿成清别，已是经年杳杳音尘多绝，欲知方寸共有几许清愁芭蕉不展丁香结，枉望断天涯两厌厌风月，以「芭蕉不展丁香结」化用李商隐诗句写愁、以「两厌厌风月」写两人的相思，全词意境凄清、用典贴切、情感深沉，「芭蕉不展丁香结」成为名句。","b":"贺铸这首《石州引》写离别后的相思，「芭蕉不展丁香结」化用李商隐诗句，是婉约词的名篇。","n":["石州引：词牌名，即《石州慢》","薄雨初寒：薄雨初寒","斜照弄晴：斜照弄晴","春意空阔：春意空阔","长亭柳色缠黄：长亭柳色缠黄（嫩黄）","远客一枝先折：远客一枝先折","烟横水际：烟横水际","映带几点归鸦：映带几点归鸦","东风销尽龙沙雪：东风销尽龙沙（边塞）雪","还记初关来：还记初关来（刚出关时）","恰而今时节：恰而今时节","将发：将发","画楼芳酒：画楼芳酒","红泪清歌：红泪清歌","顿成清别：顿成清别","已是经年：已是经年","杳杳音尘多绝：杳杳音尘多绝","欲知方寸：欲知方寸（心）","共有几许清愁：共有几许清愁","芭蕉不展丁香结：芭蕉不展丁香结（用李商隐「芭蕉不展丁香结，同向春风各自愁」）","枉望断天涯：枉望断天涯","两厌厌风月：两厌厌风月（两人都厌厌风月）"],"m":"芭蕉不展丁香结。枉望断天涯，两厌厌风月。","r":"按「薄雨初寒—斜照弄晴—春意空阔—长亭柳色—缠黄—远客一枝—先折—烟横水际—几点归鸦—东风龙沙—还记初关—而今时节—将发—画楼芳酒—红泪清歌—顿成清别—已是经年—杳杳音尘—欲知方寸—几许清愁—芭蕉不展—丁香结—枉望断天涯—两厌厌风月」背；用典（李商隐芭蕉不展丁香结）；离别相思是核心。"},"半死桐・鹧鸪天|贺铸":{"s":"上片「重过阊门万事非。同来何事不同归。梧桐半死清霜后，头白鸳鸯失伴飞」写重过阊门万事非、同来何事不同归，梧桐半死清霜后头白鸳鸯失伴飞，以「梧桐半死」「鸳鸯失伴」比喻丧偶；下片「原上草。露初晞。旧栖新垅两依依。空床卧听南窗雨，谁复挑灯夜补衣」写原上草露初晞、旧栖新垅两依依，空床卧听南窗雨谁复挑灯夜补衣，以「挑灯夜补衣」的细节写对妻子的思念——再也没有人挑灯夜里补衣服了，细节生动、情感真挚，全词意境凄清、比喻巧妙、细节生动、情感深沉，「空床卧听南窗雨，谁复挑灯夜补衣」成为千古名句，是悼亡词的千古名篇。","b":"贺铸这首《半死桐》是他悼念亡妻赵氏所作，是中国文学史上著名的悼亡词，与苏轼《江城子·十年生死两茫茫》并称，「空床卧听南窗雨，谁复挑灯夜补衣」是千古名句。","n":["半死桐：词牌名，即《鹧鸪天》","重过阊门万事非：重过阊门（苏州西门）万事非","同来何事不同归：同来何事不同归（为什么同来却不能同归，指妻子去世）","梧桐半死清霜后：梧桐半死清霜后（用枚乘「梧桐半死」喻丧偶）","头白鸳鸯失伴飞：头白鸳鸯失伴飞","原上草：原上草","露初晞：露初晞（露水刚干。晞音xī，干）","旧栖新垅两依依：旧栖（旧居）新垅（新坟）两依依。垅同「垄」，坟","空床卧听南窗雨：空床卧听南窗雨","谁复挑灯夜补衣：谁复挑灯夜补衣（谁还会挑灯夜里补衣服呢，指妻子）"],"m":"梧桐半死清霜后，头白鸳鸯失伴飞。空床卧听南窗雨，谁复挑灯夜补衣。","r":"按「重过阊门—万事非—同来何事—不同归—梧桐半死—清霜后—头白鸳鸯—失伴飞—原上草—露初晞—旧栖新垅—两依依—空床卧听—南窗雨—谁复挑灯—夜补衣」背；「晞」读xī、「垅」同垄；用典（枚乘梧桐半死）；「挑灯夜补衣」的细节是核心；与苏轼《江城子》并称悼亡双璧。"},"横塘路・青玉案|贺铸":{"s":"上片「凌波不过横塘路。但目送、芳尘去。锦瑟华年谁与度。月桥花院，琐窗朱户。只有春知处」写凌波不过横塘路但目送芳尘去，锦瑟华年谁与度，月桥花院琐窗朱户只有春知处，以美人的离去写思念；下片「飞云冉冉蘅皋暮。彩笔新题断肠句。若问闲情都几许。一川烟草，满城风絮。梅子黄时雨」写飞云冉冉蘅皋暮彩笔新题断肠句，若问闲情都几许——一川烟草、满城风絮、梅子黄时雨，以三种景物（烟草、风絮、梅雨）比喻闲愁的多、乱、绵长，比喻新奇、对仗工稳，全词意境清丽、比喻巧妙、情感深沉，「若问闲情都几许。一川烟草，满城风絮。梅子黄时雨」成为千古名句，贺铸因此被称为「贺梅子」，是婉约词的千古名篇。","b":"贺铸这首《横塘路》写对美人的思念与闲愁，「若问闲情都几许。一川烟草，满城风絮。梅子黄时雨」是千古名句，以三种景物比喻闲愁，是婉约词的千古名篇，贺铸因此被称为「贺梅子」。","n":["横塘路：词牌名，即《青玉案》","凌波不过横塘路：凌波不过横塘路（凌波，形容女子步态轻盈，用曹植「凌波微步」）","但目送、芳尘去：但目送芳尘去（芳尘，美人的踪迹）","锦瑟华年谁与度：锦瑟华年谁与度（美好的青春年华与谁度过。用李商隐「锦瑟无端五十弦」）","月桥花院：月桥花院","琐窗朱户：琐窗朱户（雕花窗、红漆门）","只有春知处：只有春知处","飞云冉冉蘅皋暮：飞云冉冉蘅皋暮（蘅皋，长着杜蘅的水边高地。蘅音héng）","彩笔新题断肠句：彩笔新题断肠句（彩笔，用江淹「彩笔」典故，指文才）","若问闲情都几许：若问闲情都几许","一川烟草：一川烟草","满城风絮：满城风絮","梅子黄时雨：梅子黄时雨"],"m":"若问闲情都几许。一川烟草，满城风絮。梅子黄时雨。","r":"按「凌波不过—横塘路—但目送—芳尘去—锦瑟华年—谁与度—月桥花院—琐窗朱户—只有春知—飞云冉冉—蘅皋暮—彩笔新题—断肠句—若问闲情—都几许—一川烟草—满城风絮—梅子黄时雨」背；「蘅」读héng；用典（曹植凌波微步、李商隐锦瑟、江淹彩笔）；「一川烟草满城风絮梅子黄时雨」的三重比喻是核心；「贺梅子」的称号是背景。"},"燕山亭|赵佶":{"s":"上片「裁翦冰绡。打叠数重，冷淡燕脂匀注。新样靓妆，艳溢香融，羞杀蕊珠宫女。易得凋零，更多少、无情风雨。愁苦。闲院落凄凉，几番春暮」写杏花的美丽——裁剪冰绡打叠数重冷淡胭脂匀注，新样靓妆艳溢香融羞杀蕊珠宫女；又写杏花的凋零——易得凋零更多少无情风雨，闲院落凄凉几番春暮，以杏花的美丽与凋零比喻自己的命运；下片「凭寄离恨重重。这双燕，何曾会人言语。天遥地远，万水千山，知他故宫何处。怎不思量，除梦里、有时会去。无据。和梦也、有时不做」写凭寄离恨重重这双燕何曾会人言语，天遥地远万水千山知他故宫何处，怎不思量除梦里有时会去，无据和梦也有时不做，以「故宫何处」写亡国之痛、以「和梦也有时不做」写绝望——连梦都做不成了，全词意境凄清、比喻巧妙、情感深沉、字字血泪，「怎不思量，除梦里、有时会去。无据。和梦也、有时不做」成为千古名句，是婉约词的千古名篇，王国维评为「以血书者」。","b":"赵佶（宋徽宗，北宋末代皇帝）这首《燕山亭》是他被金兵俘虏北行时所作，写杏花与亡国之痛，「怎不思量，除梦里、有时会去。无据。和梦也、有时不做」是千古名句，是婉约词的千古名篇，王国维评为「以血书者」。","n":["燕山亭：词牌名","裁翦冰绡：裁剪冰绡（洁白的薄绸，喻花瓣）。翦同「剪」","打叠数重：打叠数重（叠了几层）","冷淡燕脂匀注：冷淡燕脂（胭脂）匀注（均匀涂抹）。燕同「胭」","新样靓妆：新样靓妆（新颖的妆扮）。靓音jìng","艳溢香融：艳溢香融（艳丽四溢、香气融合）","羞杀蕊珠宫女：羞杀蕊珠宫女（蕊珠宫，道教天上宫殿）","易得凋零：易得凋零","更多少、无情风雨：更多少无情风雨","愁苦：愁苦","闲院落凄凉：闲院落凄凉","几番春暮：几番春暮","凭寄离恨重重：凭寄离恨重重（凭谁寄离恨重重）","这双燕：这双燕","何曾会人言语：何曾会人言语（哪里懂人的言语）","天遥地远：天遥地远","万水千山：万水千山","知他故宫何处：知他故宫何处","怎不思量：怎不思量","除梦里、有时会去：除梦里有时会去","无据：无据（没有凭据）","和梦也、有时不做：和梦也有时不做（连梦也有时不做）"],"m":"怎不思量，除梦里、有时会去。无据。和梦也、有时不做。","r":"按「裁翦冰绡—打叠数重—冷淡燕脂—匀注—新样靓妆—艳溢香融—羞杀蕊珠—易得凋零—无情风雨—愁苦—闲院落—凄凉—几番春暮—凭寄离恨—这双燕—何曾会人—天遥地远—万水千山—故宫何处—怎不思量—除梦里—有时会去—无据—和梦也—有时不做」背；「翦」同剪、「燕」同胭、「靓」读jìng；以杏花喻命运是核心；「和梦也有时不做」的绝望是核心；宋徽宗被俘虏北行是背景；王国维「以血书者」的评价是地位。"},"60483:摸鱼儿|辛弃疾":{"s":"上片「更能消、几番风雨。匆匆春又归去。惜春长恨花开早，何况落红无数。春且住。见说道、天涯芳草迷归路。怨春不语。算只有殷勤，画檐珠网，尽日惹飞絮」写更能消几番风雨匆匆春又归去，惜春长恨花开早何况落红无数，春且住见说道天涯芳草迷归路，怨春不语算只有殷勤画檐珠网尽日惹飞絮，以暮春景色写对国事的忧虑——春天（国势）经受不住几番风雨；下片「长门事，准拟佳期又误。蛾眉曾有人妒。千金纵买相如赋，脉脉此情谁诉。君莫舞。君不见、玉环飞燕皆尘土。闲愁最苦。休去倚危楼，斜阳正在，烟柳断肠处」写长门事准拟佳期又误蛾眉曾有人妒，千金纵买相如赋脉脉此情谁诉，君莫舞君不见玉环飞燕皆尘土，闲愁最苦休去倚危楼斜阳正在烟柳断肠处，以「长门事」「蛾眉曾有人妒」写自己的不被重用、以「玉环飞燕皆尘土」警告当权者、以「斜阳正在烟柳断肠处」写对国事的忧虑——国势如斜阳西下，全词意境苍凉、用典丰富、寓意深刻、情感深沉，「君莫舞。君不见、玉环飞燕皆尘土」「斜阳正在，烟柳断肠处」成为千古名句，是豪放词的千古名篇。","b":"辛弃疾这首《摸鱼儿》是他任湖北转运副使时所作，写暮春景色与对国事的忧虑，以「玉环飞燕皆尘土」警告当权者，以「斜阳正在烟柳断肠处」写对国事的忧虑，是豪放词的千古名篇，梁启超评为「回肠荡气，至于此极，前无古人，后无来者」。","n":["摸鱼儿：词牌名","更能消、几番风雨：还能经受几番风雨","匆匆春又归去：匆匆春又归去","惜春长恨花开早：惜春长恨花开早","何况落红无数：何况落红无数","春且住：春且住（春天暂且停住）","见说道、天涯芳草迷归路：听说天涯芳草迷归路（春归路被芳草遮住了）","怨春不语：怨春不语","算只有殷勤：算只有殷勤","画檐珠网：画檐珠网（画檐下的蛛网）","尽日惹飞絮：尽日惹飞絮（整天沾惹飞絮）","长门事：长门事（陈皇后被废居长门宫，司马相如作《长门赋》）","准拟佳期又误：准拟佳期又误（约定的佳期又耽误了）","蛾眉曾有人妒：蛾眉曾有人妒（美女曾被人嫉妒，用屈原「众女嫉余之蛾眉兮」）","千金纵买相如赋：千金纵买相如赋（纵然用千金买司马相如的赋）","脉脉此情谁诉：脉脉此情谁诉（含情脉脉此情向谁诉说）","君莫舞：君莫舞（你不要得意）","君不见、玉环飞燕皆尘土：君不见玉环（杨贵妃）飞燕（赵飞燕）皆尘土","闲愁最苦：闲愁最苦","休去倚危楼：休去倚危楼（不要靠高楼）","斜阳正在：斜阳正在","烟柳断肠处：烟柳断肠处"],"m":"君莫舞。君不见、玉环飞燕皆尘土。闲愁最苦。休去倚危楼，斜阳正在，烟柳断肠处。","r":"按「更能消—几番风雨—春又归去—惜春—花开早—落红无数—春且住—天涯芳草—迷归路—怨春不语—画檐珠网—惹飞絮—长门事—佳期又误—蛾眉曾妒—千金买赋—此情谁诉—君莫舞—玉环飞燕—皆尘土—闲愁最苦—休倚危楼—斜阳正在—烟柳断肠」背；用典（长门赋、屈原蛾眉、玉环飞燕）；以暮春写国事是核心；「斜阳烟柳断肠处」的隐喻是核心；梁启超的评价是地位。"},"60485:沁园春|辛弃疾":{"s":"上片「三径初成。鹤怨猿惊，稼轩未来。甚云山自许，平生意气，衣冠人笑，抵死尘埃。意倦须还，身闲贵早，岂为莼羹鲈鲙哉。秋江上，看惊弦雁避，骇浪船回」写三径初成鹤怨猿惊稼轩未来，甚云山自许平生意气衣冠人笑抵死尘埃，意倦须还身闲贵早岂为莼羹鲈脍哉，秋江上看惊弦雁避骇浪船回，以「三径」「莼羹鲈脍」写归隐之志、以「惊弦雁避骇浪船回」写官场的险恶；下片「东冈更葺茅斋。好都把轩窗临水开。要小舟行钓，先应种柳，疏篱护竹，莫碍观梅。秋菊堪餐，春兰可佩，留待先生手自栽。沈吟久，怕君恩未许，此意徘徊」写东冈更葺茅斋好都把轩窗临水开，要小舟行钓先应种柳疏篱护竹莫碍观梅，秋菊堪餐春兰可佩留待先生手自栽，沈吟久怕君恩未许此意徘徊，以「秋菊堪餐春兰可佩」用屈原典故写高洁、以「怕君恩未许此意徘徊」写归隐与忠君的矛盾，全词用典丰富、意境开阔、情感深沉，「秋菊堪餐，春兰可佩」成为名句。","b":"辛弃疾这首《沁园春》是他带湖新居将成时所作，写归隐之志与对君恩的矛盾，「秋菊堪餐，春兰可佩」用屈原典故，是豪放词的名篇。","n":["沁园春：词牌名","三径初成：三径初成（三径，用蒋诩「三径」典故，指归隐后的家园）","鹤怨猿惊：鹤怨猿惊（鹤猿都抱怨惊讶，指归隐）","稼轩未来：稼轩未来（辛弃疾号稼轩，自己还未来）","甚云山自许：甚云山自许（为什么以云山自许）","平生意气：平生意气","衣冠人笑：衣冠人笑（被官场人嘲笑）","抵死尘埃：抵死尘埃（终究在尘世中）","意倦须还：意倦须还（心意疲倦了必须归去）","身闲贵早：身闲贵早（身闲贵在早）","岂为莼羹鲈鲙哉：岂为莼羹鲈鲙哉（难道是为了莼羹鲈脍吗，用张翰「莼羹鲈脍」典故，指归隐）。鲙同「脍」","秋江上：秋江上","看惊弦雁避：看惊弦雁避（惊弓之雁躲避）","骇浪船回：骇浪船回（骇浪中船转回）","东冈更葺茅斋：东冈更葺茅斋（东冈再盖茅屋）。葺音qì，修补","好都把轩窗临水开：好都把轩窗临水开","要小舟行钓：要小舟行钓","先应种柳：先应种柳","疏篱护竹：疏篱护竹","莫碍观梅：莫碍观梅","秋菊堪餐：秋菊堪餐（可以吃，用屈原「夕餐秋菊之落英」）","春兰可佩：春兰可佩（可以佩戴，用屈原「纫秋兰以为佩」）","留待先生手自栽：留待先生手自栽","沈吟久：沈吟久（沉吟久）。沈同「沉」","怕君恩未许：怕君恩未许（怕皇帝不允许）","此意徘徊：此意徘徊（这个心意徘徊不定）"],"m":"秋菊堪餐，春兰可佩，留待先生手自栽。","r":"按「三径初成—鹤怨猿惊—稼轩未来—云山自许—平生意气—衣冠人笑—抵死尘埃—意倦须还—身闲贵早—岂为莼羹—鲈鲙—秋江上—惊弦雁避—骇浪船回—东冈葺茅—轩窗临水—小舟行钓—先应种柳—疏篱护竹—莫碍观梅—秋菊堪餐—春兰可佩—留待先生—手自栽—沈吟久—怕君恩—未许—此意徘徊」背；「葺」读qì、「鲙」同脍、「沈」同沉；用典（蒋诩三径、张翰莼羹鲈脍、屈原秋菊春兰）；归隐与忠君的矛盾是核心。"},"60489:水龙吟|辛弃疾":{"s":"上片「楚天千里清秋。水随天去秋无际。遥岑远目，献愁供恨，玉簪螺髻。落日楼头，断鸿声里，江南游子。把吴钩看了，栏干拍遍，无人会、登临意」写楚天千里清秋水随天去秋无际，遥岑远目献愁供恨玉簪螺髻，落日楼头断鸿声里江南游子，把吴钩看了栏干拍遍无人会登临意，以「把吴钩看了栏干拍遍」的动作写壮志难酬的悲愤、以「无人会登临意」写不被理解的孤独；下片「休说鲈鱼堪鲙。尽西风、季鹰归未。求田问舍，怕应羞见，刘郎才气。可惜流年，忧愁风雨，树犹如此。倩何人，唤取盈盈翠袖，揾英雄泪」写休说鲈鱼堪鲙尽西风季鹰归未，求田问舍怕应羞见刘郎才气，可惜流年忧愁风雨树犹如此，倩何人唤取盈盈翠袖揾英雄泪，以「鲈鱼堪鲙」「求田问舍」两个典故写自己不愿归隐、不谋私利，以「树犹如此」写时光流逝，以「揾英雄泪」写壮志难酬的悲愤，全词意境苍凉、用典丰富、动作生动、情感深沉，「把吴钩看了，栏干拍遍，无人会、登临意」「倩何人，唤取盈盈翠袖，揾英雄泪」成为千古名句，是豪放词的千古名篇。","b":"辛弃疾这首《水龙吟》是他任建康通判时所作，写登临建康赏心亭所见与壮志难酬的悲愤，「把吴钩看了，栏干拍遍，无人会、登临意」「倩何人，唤取盈盈翠袖，揾英雄泪」是千古名句，是豪放词的千古名篇。","n":["水龙吟：词牌名","楚天千里清秋：楚天千里清秋","水随天去秋无际：水随天去秋无际","遥岑远目：遥岑远目（眺望远山）。岑音cén，小山","献愁供恨：献愁供恨（远山好像在献愁供恨）","玉簪螺髻：玉簪螺髻（像玉簪和螺髻，比喻山的形状）。髻音jì","落日楼头：落日楼头","断鸿声里：断鸿声里（孤雁的叫声里）","江南游子：江南游子（辛弃疾自指，他是北方人，流落江南）","把吴钩看了：把吴钩看了（吴钩，古代吴地出产的弯刀，代指武器）","栏干拍遍：栏干拍遍","无人会、登临意：无人会登临意（没有人理解登临的心意）","休说鲈鱼堪鲙：休说鲈鱼堪鲙（不要说鲈鱼可以做脍，用张翰「莼羹鲈脍」典故，指归隐）。鲙同「脍」","尽西风、季鹰归未：尽西风季鹰归未（西风吹尽了，张翰（字季鹰）回来了没有）","求田问舍：求田问舍（买田置屋，用许汜典故，指只顾个人利益）","怕应羞见：怕应羞见","刘郎才气：刘郎才气（刘备的才气，指有大志的人）","可惜流年：可惜流年（可惜时光流逝）","忧愁风雨：忧愁风雨（忧愁国家的风雨飘摇）","树犹如此：树犹如此（用桓温「木犹如此，人何以堪」典故，指时光流逝）","倩何人：倩何人（请什么人）。倩音qìng，请","唤取盈盈翠袖：唤取盈盈翠袖（唤取美丽的女子，翠袖代指女子）","揾英雄泪：揾英雄泪（擦英雄的眼泪）。揾音wèn，擦"],"m":"把吴钩看了，栏干拍遍，无人会、登临意。倩何人，唤取盈盈翠袖，揾英雄泪。","r":"按「楚天清秋—水随天去—秋无际—遥岑远目—献愁供恨—玉簪螺髻—落日楼头—断鸿声里—江南游子—把吴钩看—栏干拍遍—无人会—登临意—休说鲈鱼—堪鲙—尽西风—季鹰归未—求田问舍—怕应羞见—刘郎才气—可惜流年—忧愁风雨—树犹如此—倩何人—唤取翠袖—揾英雄泪」背；「岑」读cén、「髻」读jì、「鲙」同脍、「倩」读qìng、「揾」读wèn；用典（张翰莼羹鲈脍、许汜求田问舍、刘备、桓温树犹如此）；「把吴钩看了栏干拍遍」的动作是核心；壮志难酬是主题。"},"60544:临江仙|辛弃疾":{"s":"上片「老去惜花心已懒。爱梅犹绕江村。一枝先破玉溪春。更无花态度，全有雪精神」写老去惜花心已懒爱梅犹绕江村，一枝先破玉溪春，更无花态度全有雪精神，以「更无花态度全有雪精神」写梅花的高洁——没有花的媚态，全有雪的精神；下片「剩向空山餐秀色。为渠著句清新。竹根流水带溪云。醉中浑不记，归路月黄昏」写剩向空山餐秀色为渠著句清新，竹根流水带溪云，醉中浑不记归路月黄昏，以「醉中浑不记归路月黄昏」写赏梅的沉醉，全词意境清丽、品格高洁、情感深沉，「更无花态度，全有雪精神」成为名句。","b":"辛弃疾这首《临江仙》写梅花的品格，「更无花态度，全有雪精神」是名句，是辛弃疾婉约词的名篇。","n":["临江仙：词牌名","老去惜花心已懒：老去惜花心已懒","爱梅犹绕江村：爱梅犹绕江村","一枝先破玉溪春：一枝先破玉溪春（玉溪的春天先被一枝梅花打破）","更无花态度：更无花态度（没有花的媚态）","全有雪精神：全有雪精神（全有雪的精神）","剩向空山餐秀色：剩向空山餐秀色（只向空山欣赏秀色）","为渠著句清新：为渠著句清新（为它写清新的诗句。渠，它）","竹根流水带溪云：竹根流水带溪云","醉中浑不记：醉中浑不记（醉中全不记得）","归路月黄昏：归路月黄昏"],"m":"更无花态度，全有雪精神。","r":"按「老去惜花—心已懒—爱梅犹绕—江村—一枝先破—玉溪春—更无花—态度—全有雪—精神—剩向空山—餐秀色—为渠著句—清新—竹根流水—带溪云—醉中浑不记—归路月黄昏」背；「更无花态度全有雪精神」是核心；梅花的高洁品格是主题。"},"60548:菩萨蛮|辛弃疾":{"s":"上片「郁孤台下清江水。中间多少行人泪。西北是长安。可怜无数山」写郁孤台下清江水中间多少行人泪，西北是长安可怜无数山，以「行人泪」写中原沦陷的痛苦、以「可怜无数山」写视线被山遮住、望不到中原；下片「青山遮不住。毕竟江流去。江晚正愁予。山深闻鹧鸪」写青山遮不住毕竟江流去，江晚正愁予山深闻鹧鸪，以「青山遮不住毕竟东流去」写恢复中原的愿望不可阻挡、以「闻鹧鸪」暗指恢复之事行不得的矛盾，全词意境苍凉、比喻巧妙、情感深沉、寓意深刻，「青山遮不住，毕竟东流去」成为千古名句，是豪放词的千古名篇。","b":"辛弃疾这首《菩萨蛮》是他任江西提点刑狱时路过造口所作，写对中原的思念与恢复中原的愿望，「青山遮不住，毕竟东流去」是千古名句，是豪放词的千古名篇。","n":["菩萨蛮：词牌名","郁孤台下清江水：郁孤台下清江水（郁孤台，在今江西赣州）","中间多少行人泪：中间多少行人泪","西北是长安：西北是长安（长安，代指北宋都城汴京，指中原）","可怜无数山：可怜无数山（可惜被无数山遮住）","青山遮不住：青山遮不住","毕竟江流去：毕竟江流去（毕竟江水向东流去）","江晚正愁予：江晚正愁予（江边傍晚正使我忧愁。予，我）","山深闻鹧鸪：山深闻鹧鸪（山深听到鹧鸪叫，鹧鸪叫声似「行不得也哥哥」，暗指恢复中原之事行不得）"],"m":"青山遮不住，毕竟江流去。","r":"按「郁孤台下—清江水—中间多少—行人泪—西北是—长安—可怜无数—山—青山遮不住—毕竟江流—去—江晚正愁—予—山深闻—鹧鸪」背；用典（长安代指中原、鹧鸪「行不得也哥哥」）；「青山遮不住毕竟东流去」的比喻是核心；恢复中原的愿望与矛盾是主题。"},"青玉案|辛弃疾":{"s":"上片「东风夜放花千树。更吹落、星如雨。宝马雕车香满路。凤箫声动，玉壶光转，一夜鱼龙舞」写东风夜放花千树更吹落星如雨，宝马雕车香满路，凤箫声动玉壶光转一夜鱼龙舞，以夸张的手法写元宵节的盛况——花灯如千树花开、烟花如星雨、宝马雕车、凤箫玉壶、鱼龙百舞；下片「蛾儿雪柳黄金缕。笑语盈盈暗香去。众里寻他千百度。蓦然回首，那人却在，灯火阑珊处」写蛾儿雪柳黄金缕笑语盈盈暗香去，众里寻他千百度蓦然回首那人却在灯火阑珊处，以「众里寻他千百度」写追寻的执着、以「蓦然回首那人却在灯火阑珊处」写发现的惊喜——在灯火稀疏的地方找到了意中人，全词意境开阔、夸张巧妙、情感深沉、哲理深刻，「众里寻他千百度。蓦然回首，那人却在，灯火阑珊处」成为千古名句，王国维列为人生三境界之第三境界（最高境界），是豪放词的千古名篇。","b":"辛弃疾这首《青玉案》写元宵节的盛况与对意中人的追寻，「众里寻他千百度。蓦然回首，那人却在，灯火阑珊处」是千古名句，王国维在《人间词话》中将其列为「古今之成大事业、大学问者」的第三境界（最高境界），是豪放词的千古名篇。","n":["青玉案：词牌名","东风夜放花千树：东风夜放花千树（东风夜里吹放了千树花，指花灯）","更吹落、星如雨：更吹落星如雨（更吹落星星如雨，指烟花）","宝马雕车香满路：宝马雕车香满路","凤箫声动：凤箫声动（箫声响起）","玉壶光转：玉壶光转（玉壶般的月亮光影移动，或指白玉灯）","一夜鱼龙舞：一夜鱼龙舞（鱼龙灯舞动，指百戏）","蛾儿雪柳黄金缕：蛾儿雪柳黄金缕（元宵节妇女的饰物）","笑语盈盈暗香去：笑语盈盈暗香去（笑语盈盈、带着暗香离去）","众里寻他千百度：众里寻他千百度（在人群里找了她千百次）","蓦然回首：蓦然回首（忽然回头）","那人却在：那人却在","灯火阑珊处：灯火阑珊处（灯火稀疏的地方。阑珊，稀疏、将尽）"],"m":"众里寻他千百度。蓦然回首，那人却在，灯火阑珊处。","r":"按「东风夜放—花千树—更吹落—星如雨—宝马雕车—香满路—凤箫声动—玉壶光转—一夜鱼龙—舞—蛾儿雪柳—黄金缕—笑语盈盈—暗香去—众里寻他—千百度—蓦然回首—那人却在—灯火阑珊—处」背；「阑珊」是稀疏将尽；元宵节盛况的夸张是核心；「众里寻他千百度蓦然回首那人却在灯火阑珊处」是名句；王国维三境界第三境界是地位。"},"阮郎归|辛弃疾":{"s":"上片「山前风雨欲黄昏。山头来去雪。鹧鸪声里数家村。潇湘逢故人」写山前风雨欲黄昏山头来去雪，鹧鸪声里数家村潇湘逢故人，以潇湘的风雨鹧鸪写环境的荒凉；下片「挥羽扇。整纶巾。少年鞍马尘。如今憔悴赋招魂。儒冠多误身」写挥羽扇整纶巾少年鞍马尘，如今憔悴赋招魂儒冠多误身，以「挥羽扇整纶巾」用诸葛亮典故写少年的英雄气概、以「如今憔悴赋招魂儒冠多误身」写如今的憔悴与失意——儒生的帽子多误了自身，用杜甫典故，全词今昔对比、用典贴切、情感深沉，「如今憔悴赋招魂。儒冠多误身」成为名句。","b":"辛弃疾这首《阮郎归》写在潇湘遇到老朋友，回忆少年的鞍马生活与如今的憔悴，「儒冠多误身」用杜甫典故，是豪放词的名篇。","n":["阮郎归：词牌名","山前风雨欲黄昏：山前风雨欲黄昏","山头来去雪：山头来去雪（山头雪来来去去）","鹧鸪声里数家村：鹧鸪声里数家村（鹧鸪声里有几个村庄）","潇湘逢故人：潇湘逢故人（在潇湘遇到老朋友）","挥羽扇：挥羽扇（挥羽扇，用诸葛亮「羽扇纶巾」典故）","整纶巾：整纶巾（整理纶巾。纶巾，青丝带头巾，诸葛亮所戴。纶音guān）","少年鞍马尘：少年鞍马尘（少年时在鞍马风尘中）","如今憔悴赋招魂：如今憔悴赋招魂（如今憔悴，赋《招魂》（屈原作品，指招回魂魄））","儒冠多误身：儒冠多误身（儒生的帽子多误了自身，用杜甫「纨绔不饿死，儒冠多误身」）"],"m":"如今憔悴赋招魂。儒冠多误身。","r":"按「山前风雨—欲黄昏—山头来去—雪—鹧鸪声里—数家村—潇湘逢—故人—挥羽扇—整纶巾—少年鞍马—尘—如今憔悴—赋招魂—儒冠多—误身」背；「纶」读guān；用典（诸葛亮羽扇纶巾、屈原招魂、杜甫儒冠多误身）；今昔对比是核心；壮志难酬是主题。"},"60579:清平乐|辛弃疾":{"s":"上片「茅檐低小。溪上青青草。醉里蛮音相媚好。白发谁家翁媪」写茅檐低小溪上青青草，醉里蛮音相媚好白发谁家翁媪，以茅檐、青草、翁媪写农村环境的清幽与老夫妻的温馨；下片「大儿锄豆溪东。中儿正织鸡笼。最喜小儿亡赖。溪头卧剥莲蓬」写大儿锄豆溪东中儿正织鸡笼，最喜小儿亡赖溪头卧剥莲蓬，以三个儿子的不同活动写农村生活的生动——大儿子勤劳、二儿子手巧、小儿子顽皮，全词意境清新、语言朴素、细节生动、情感真挚，「最喜小儿亡赖，溪头卧剥莲蓬」成为千古名句，是宋词中最著名的农村词，是婉约词的千古名篇。","b":"辛弃疾这首《清平乐》写江西上饶农村的一个五口之家的生活，是宋词中最著名的农村词，「最喜小儿亡赖，溪头卧剥莲蓬」是千古名句，是婉约词的千古名篇。","n":["清平乐：词牌名","茅檐低小：茅檐低小（茅屋的屋檐又低又小）","溪上青青草：溪上青青草","醉里蛮音相媚好：醉里蛮音相媚好（醉里用吴地方言互相逗趣。蛮音，库文作「蛮音」，通行本作「吴音」）","白发谁家翁媪：白发谁家翁媪（谁家的白发老翁老妇。媪音ǎo，老妇）","大儿锄豆溪东：大儿锄豆溪东（大儿子在溪东锄豆田）","中儿正织鸡笼：中儿正织鸡笼（二儿子正在织鸡笼）","最喜小儿亡赖：最喜小儿亡赖（最喜爱小儿子的顽皮。亡赖同「无赖」，此指顽皮可爱）","溪头卧剥莲蓬：溪头卧剥莲蓬（在溪头躺着剥莲蓬）"],"m":"最喜小儿亡赖，溪头卧剥莲蓬。","r":"按「茅檐低小—溪上青青—草—醉里蛮音—相媚好—白发谁家—翁媪—大儿锄豆—溪东—中儿正织—鸡笼—最喜小儿—亡赖—溪头卧剥—莲蓬」背；「媪」读ǎo、「亡赖」同无赖（顽皮）；库文作「蛮音」，通行本作「吴音」，以库文为准；农村生活的生动是核心；小儿的顽皮是名句。"},"60620:最高楼|辛弃疾":{"s":"上片「吾衰矣。须富贵何时。富贵是危机。暂忘设醴抽身去，未曾得米弃官归。穆先生。陶县令。是吾师」写吾衰矣须富贵何时富贵是危机，暂忘设醴抽身去未曾得米弃官归，穆先生陶县令是吾师，以「富贵是危机」写对富贵的蔑视、以穆生和陶渊明两个典故写归隐之志；下片「待葺个、园儿名佚老。更作个、亭儿名亦好。闲饮酒，醉吟诗。千年田换八百主，一人口插几张匙。休休休，更说甚，是和非」写待葺个园儿名佚老更作个亭儿名亦好，闲饮酒醉吟诗，千年田换八百主一人口插几张匙，休休休更说甚是和非，以「千年田换八百主一人口插几张匙」写世事无常、贪多无益，以「休休休更说甚是和非」写归隐后的旷达，全词用典丰富、语言明快、哲理深刻、情感旷达，「千年田换八百主，一人口插几张匙」成为名句。","b":"辛弃疾这首《最高楼》是他被弹劾罢官、归隐瓢泉时所作，写归隐之志与对富贵的蔑视，「千年田换八百主，一人口插几张匙」是名句，是豪放词的名篇。","n":["最高楼：词牌名","吾衰矣：吾衰矣（我衰老了，用孔子「甚矣吾衰也」）","须富贵何时：须富贵何时（要富贵到什么时候呢，用杨恽「人生行乐耳，须富贵何时」）","富贵是危机：富贵是危机（富贵是危机四伏的）","暂忘设醴抽身去：暂忘设醴抽身去（暂时忘记设醴（酒）抽身离去，用楚元王与穆生典故——穆生因楚王忘设醴而知其怠，抽身离去）。醴音lǐ，甜酒","未曾得米弃官归：未曾得米弃官归（未曾得到米就弃官归去，用陶渊明「不为五斗米折腰」典故）","穆先生：穆先生（穆生）","陶县令：陶县令（陶渊明，曾任彭泽令）","是吾师：是吾师","待葺个、园儿名佚老：待葺个园儿名佚老（待修个园子名叫佚老。葺音qì，修补；佚老，安乐养老）","更作个、亭儿名亦好：更作个亭儿名亦好（再建个亭子名叫亦好）","闲饮酒：闲饮酒","醉吟诗：醉吟诗","千年田换八百主：千年田换八百主（千年的田地换了八百个主人，指世事无常）","一人口插几张匙：一人口插几张匙（一张嘴插几把匙，指贪多无益）","休休休：休休休（算了吧）","更说甚：更说甚（还说什么呢）","是和非：是和非（是与非）"],"m":"千年田换八百主，一人口插几张匙。","r":"按「吾衰矣—须富贵—何时—富贵是—危机—暂忘设醴—抽身去—未曾得米—弃官归—穆先生—陶县令—是吾师—待葺园—名佚老—更作亭—名亦好—闲饮酒—醉吟诗—千年田—八百主—一人口—几张匙—休休休—更说甚—是和非」背；「醴」读lǐ、「葺」读qì；用典（孔子吾衰、杨恽须富贵何时、穆生设醴、陶渊明不为五斗米折腰）；「千年田换八百主一人口插几张匙」的哲理是核心；归隐旷达是主题。"},"鹧鸪天|辛弃疾":{"s":"上片「陌上柔条初破芽。东邻蚕种已生些。平冈细草鸣黄犊，斜日寒林点暮鸦」写陌上柔条初破芽东邻蚕种已生些，平冈细草鸣黄犊斜日寒林点暮鸦，以柔条、蚕种、黄犊、暮鸦写农村初春的生机；下片「山远近。路横斜。青旗沽酒有人家。城中桃李愁风雨，春在溪头野荠花」写山远近路横斜青旗沽酒有人家，城中桃李愁风雨春在溪头野荠花，以「城中桃李愁风雨春在溪头野荠花」的对比写——城中的桃李虽娇贵却忧愁风雨，而溪头的野荠花虽平凡却充满春意，以平凡的野花写春天的真正所在，全词意境清新、对比鲜明、哲理深刻、情感真挚，「城中桃李愁风雨，春在溪头野荠花」成为千古名句，是婉约词的千古名篇。","b":"辛弃疾这首《鹧鸪天》写农村的初春景色，「城中桃李愁风雨，春在溪头野荠花」是千古名句，以城中桃李与溪头野荠对比，是婉约词的千古名篇。","n":["鹧鸪天：词牌名","陌上柔条初破芽：陌上柔条初破芽（田间小路上柔嫩的枝条刚发芽。库文作「柔条」，通行本作「柔桑」；库文作「初破芽」，通行本作「破嫩芽」）","东邻蚕种已生些：东邻蚕种已生些（东邻的蚕种已经孵化了一些。些音suō，句末语气词）","平冈细草鸣黄犊：平冈细草鸣黄犊（平缓的山冈上细草中黄牛犊在叫。犊音dú，小牛）","斜日寒林点暮鸦：斜日寒林点暮鸦（斜日寒林中点缀着暮鸦）","山远近：山远近（山有远有近）","路横斜：路横斜（路有横有斜）","青旗沽酒有人家：青旗沽酒有人家（青旗卖酒的地方有人家）","城中桃李愁风雨：城中桃李愁风雨（城中的桃李忧愁风雨）","春在溪头野荠花：春在溪头野荠花（春天在溪头的野荠花中。库文作「野荠花」，通行本作「荠菜花」）"],"m":"城中桃李愁风雨，春在溪头野荠花。","r":"按「陌上柔条—初破芽—东邻蚕种—已生些—平冈细草—鸣黄犊—斜日寒林—点暮鸦—山远近—路横斜—青旗沽酒—有人家—城中桃李—愁风雨—春在溪头—野荠花」背；「些」读suō、「犊」读dú；库文作「柔条」「初破芽」「野荠花」，通行本作「柔桑」「破嫩芽」「荠菜花」，以库文为准；城中桃李与溪头野荠的对比是核心；平凡中见春意是哲理。"},"60737:贺新郎|辛弃疾":{"s":"上片「甚矣吾衰矣。怅平生、交游零落，只今余几。白发空垂三千丈，一笑人间万事。问何物、能令公喜。我见青山多妩媚，料青山、见我应如是。情与貌，略相似」写甚矣吾衰矣怅平生交游零落只今余几，白发空垂三千丈一笑人间万事，问何物能令公喜，我见青山多妩媚料青山见我应如是情与貌略相似，以「我见青山多妩媚料青山见我应如是」写对青山的喜爱与物我两忘；下片「一尊搔首东窗里。想渊明、停云诗就，此时风味。江左沈酣求名者，岂识浊醪妙理。回首叫、云飞风起。不恨古人吾不见，恨古人、不见吾狂耳。知我者，二三子」写一尊搔首东窗里想渊明停云诗就此时风味，江左沈酣求名者岂识浊醪妙理，回首叫云飞风起，不恨古人吾不见恨古人不见吾狂耳，知我者二三子，以陶渊明《停云》写思友、以「浊醪妙理」写饮酒的妙处、以「不恨古人吾不见恨古人不见吾狂耳」写狂放的人生态度，全词用典丰富、意境开阔、狂放不羁、情感深沉，「我见青山多妩媚，料青山、见我应如是」「不恨古人吾不见，恨古人、不见吾狂耳」成为千古名句，是豪放词的千古名篇。","b":"辛弃疾这首《贺新郎》是他归隐瓢泉时所作，写对青山的喜爱与狂放的人生态度，「我见青山多妩媚，料青山、见我应如是」「不恨古人吾不见，恨古人、不见吾狂耳」是千古名句，是豪放词的千古名篇。","n":["贺新郎：词牌名","甚矣吾衰矣：甚矣吾衰矣（我衰老得太厉害了，用孔子「甚矣吾衰也」）","怅平生、交游零落：怅平生交游零落（惆怅平生交游零落）","只今余几：只今余几（如今还剩几个）","白发空垂三千丈：白发空垂三千丈（白发空垂了三千丈，用李白「白发三千丈」）","一笑人间万事：一笑人间万事（对人间万事一笑置之）","问何物、能令公喜：问何物能令公喜（问什么东西能让您高兴呢，用「能令公喜」典故）","我见青山多妩媚：我见青山多妩媚（我看青山多妩媚。妩媚，姿态美好）","料青山、见我应如是：料青山见我应如是（料想青山看我也应该是这样）","情与貌：情与貌（情感与外貌）","略相似：略相似（大略相似）","一尊搔首东窗里：一尊搔首东窗里（一杯酒搔首在东窗里）","想渊明、停云诗就：想渊明停云诗就（想陶渊明《停云》诗写成。《停云》，陶渊明作品，思亲友）","此时风味：此时风味（这时的风味）","江左沈酣求名者：江左沈酣求名者（江东那些沉湎于求名的人。沈同「沉」）","岂识浊醪妙理：岂识浊醪妙理（哪里懂得浊酒的妙理。醪音láo，浊酒）","回首叫、云飞风起：回首叫云飞风起（回首大叫云飞风起，用刘邦「大风起兮云飞扬」）","不恨古人吾不见：不恨古人吾不见（不恨古人我见不到）","恨古人、不见吾狂耳：恨古人不见吾狂耳（恨古人见不到我的狂放）","知我者：知我者（了解我的人）","二三子：二三子（两三个，用孔子「二三子」典故，指少数朋友）"],"m":"我见青山多妩媚，料青山、见我应如是。不恨古人吾不见，恨古人、不见吾狂耳。","r":"按「甚矣吾衰—交游零落—只今余几—白发三千—一笑人间—问何物—能令公喜—我见青山—多妩媚—料青山—见我应如是—情与貌—略相似—一尊搔首—东窗里—想渊明—停云诗就—此时风味—江左沈酣—求名者—岂识浊醪—妙理—回首叫—云飞风起—不恨古人—吾不见—恨古人—不见吾狂—知我者—二三子」背；「醪」读láo、「沈」同沉；用典（孔子甚矣吾衰、李白白发三千丈、能令公喜、陶渊明停云、刘邦大风歌、孔子二三子）；「我见青山多妩媚料青山见我应如是」的物我两忘是核心；「不恨古人吾不见恨古人不见吾狂耳」的狂放是核心。"},"粉蝶儿|辛弃疾":{"s":"上片「昨日春如，十三女儿学绣。一枝枝、不教花瘦。甚无情，便下得，雨僝风僽。向园林、铺作地衣红绉」写昨日春如十三女儿学绣一枝枝不教花瘦，甚无情便下得雨僝风僽向园林铺作地衣红绉，以「十三女儿学绣」比喻春的繁盛——像十三岁女儿学刺绣一样，一枝枝都绣得饱满；下片「而今春似，轻薄荡子难久。记前时、送春归后。把春波，都酿作，一江春酎。约清愁、杨柳岸边相候」写而今春似轻薄荡子难久记前时送春归后，把春波都酿作一江春酎约清愁杨柳岸边相候，以「轻薄荡子难久」比喻春的短暂——像轻薄的浪子一样难以长久，全词比喻新奇、语言明快、情感深沉，「昨日春如，十三女儿学绣」「而今春似轻薄荡子难久」成为名句。","b":"辛弃疾这首《粉蝶儿》写春天的来去，以「昨日春如十三女儿学绣」「而今春似轻薄荡子难久」两个新奇的比喻写春的盛与衰，是婉约词的名篇。","n":["粉蝶儿：词牌名","昨日春如：昨日春如（昨天春天像）","十三女儿学绣：十三女儿学绣（十三岁的女儿学刺绣）","一枝枝、不教花瘦：一枝枝不教花瘦（一枝枝都不让花瘦，指花开得饱满）","甚无情：甚无情（太无情了）","便下得：便下得（就忍心）","雨僝风僽：雨僝风僽（雨折磨风折磨。僝僽音chánzhòu，折磨）","向园林、铺作地衣红绉：向园林铺作地衣红绉（在园林里铺成红色绉纹的地毯。绉音zhòu，绉纹）","而今春似：而今春似（如今春天像）","轻薄荡子难久：轻薄荡子难久（轻薄的浪子难以长久）","记前时、送春归后：记前时送春归后（记得以前送春归去后）","把春波：把春波（把春天的水波）","都酿作：都酿作（都酿成）","一江春酎：一江春酎（一江春酒。酎音zhòu，醇酒）","约清愁、杨柳岸边相候：约清愁杨柳岸边相候（约清愁在杨柳岸边相候）"],"m":"昨日春如，十三女儿学绣。一枝枝、不教花瘦。","r":"按「昨日春如—十三女儿—学绣—一枝枝—不教花瘦—甚无情—便下得—雨僝风僽—向园林—铺作地衣—红绉—而今春似—轻薄荡子—难久—记前时—送春归后—把春波—都酿作—一江春酎—约清愁—杨柳岸边—相候」背；「僝僽」读chánzhòu、「绉」读zhòu、「酎」读zhòu；「十三女儿学绣」「轻薄荡子难久」两个新奇比喻是核心；春的盛与衰是主题。"},"60769:汉宫春|辛弃疾":{"s":"上片「春已归来。看美人头上，袅袅春幡。无端风雨，未肯收尽余寒。年时燕子，料今宵、梦到西园。浑未办、黄柑荐酒，更传青韭堆盘」写春已归来看美人头上袅袅春幡，无端风雨未肯收尽余寒，年时燕子料今宵梦到西园，浑未办黄柑荐酒更传青韭堆盘，以立春的习俗写春的归来；下片「却笑东风从此，便薰梅染柳，更没些闲。闲时又来镜里，转变朱颜。清愁不断，问何人、会解连环。生怕见、花开花落，朝来塞雁先还」写却笑东风从此便薰梅染柳更没些闲，闲时又来镜里转变朱颜，清愁不断问何人会解连环，生怕见花开花落朝来塞雁先还，以「东风薰梅染柳」写春的忙碌、以「镜里转变朱颜」写时光流逝使人衰老、以「解连环」写愁的难解、以「塞雁先还」写自己不能归，全词用典丰富、意境清丽、情感深沉，「却笑东风从此，便薰梅染柳，更没些闲。闲时又来镜里，转变朱颜」成为名句。","b":"辛弃疾这首《汉宫春》写立春的景色与对时光流逝的感慨，「却笑东风从此，便薰梅染柳，更没些闲。闲时又来镜里，转变朱颜」是名句，是婉约词的名篇。","n":["汉宫春：词牌名","春已归来：春已归来","看美人头上：看美人头上","袅袅春幡：袅袅春幡（美人头上戴着袅袅的春幡。春幡，立春时戴的彩幡）","无端风雨：无端风雨（无缘无故的风雨）","未肯收尽余寒：未肯收尽余寒（不肯收尽残余的寒气）","年时燕子：年时燕子（去年的燕子）","料今宵、梦到西园：料今宵梦到西园（料想今晚梦到西园）","浑未办、黄柑荐酒：浑未办黄柑荐酒（全没准备黄柑荐酒。黄柑荐酒，立春时的习俗）","更传青韭堆盘：更传青韭堆盘（更传上青韭堆盘。青韭堆盘，立春时的习俗）","却笑东风从此：却笑东风从此（却笑东风从此）","便薰梅染柳：便薰梅染柳（就熏梅染柳，使梅香柳绿）","更没些闲：更没些闲（更没有一点空闲）","闲时又来镜里：闲时又来镜里（空闲时又来到镜里）","转变朱颜：转变朱颜（改变红润的容颜，指使人衰老）","清愁不断：清愁不断","问何人、会解连环：问何人会解连环（问什么人能解连环，用「解连环」典故，指难解的愁）","生怕见、花开花落：生怕见花开花落（生怕看见花开花落）","朝来塞雁先还：朝来塞雁先还（早晨塞雁先回来了）"],"m":"却笑东风从此，便薰梅染柳，更没些闲。闲时又来镜里，转变朱颜。","r":"按「春已归来—美人头上—袅袅春幡—无端风雨—未肯收尽—余寒—年时燕子—梦到西园—浑未办—黄柑荐酒—更传青韭—堆盘—却笑东风—从此—便薰梅染柳—更没些闲—闲时又来—镜里—转变朱颜—清愁不断—问何人—会解连环—生怕见—花开花落—朝来塞雁—先还」背；用典（解连环）；立春习俗是背景；「东风薰梅染柳转变朱颜」的拟人是核心；时光流逝是主题。"},"60815:太常引|辛弃疾":{"s":"上片「一轮秋影转金波。飞镜又重磨。把酒问姮娥。被白发、欺人奈何」写一轮秋影转金波飞镜又重磨，把酒问姮娥被白发欺人奈何，以「把酒问姮娥被白发欺人奈何」写对时光流逝的感慨；下片「乘风好去。长空万里。直下看山河。斫去桂婆娑。人道是、清光更多」写乘风好去长空万里直下看山河，斫去桂婆娑人道是清光更多，以「乘风好去长空万里直下看山河」写对祖国山河的热爱、以「斫去桂婆娑清光更多」用杜甫典故暗指要扫除朝廷中的奸邪、使国家政治清明，全词想象奇特、用典贴切、意境开阔、寓意深刻，「斫去桂婆娑，人道是、清光更多」成为千古名句，是豪放词的千古名篇。","b":"辛弃疾这首《太常引》是他中秋夜所作，写对月的遐想与对国事的忧虑，「斫去桂婆娑，人道是、清光更多」用杜甫典故，暗指要扫除朝廷中的奸邪，是豪放词的千古名篇。","n":["太常引：词牌名","一轮秋影转金波：一轮秋影转金波（一轮秋月的影子转动着金色的光波）","飞镜又重磨：飞镜又重磨（飞镜（月亮）又重新磨过）","把酒问姮娥：把酒问姮娥（拿着酒问嫦娥。姮娥音héng'é，嫦娥）","被白发、欺人奈何：被白发欺人奈何（被白发欺负人怎么办呢）","乘风好去：乘风好去（乘风好去）","长空万里：长空万里","直下看山河：直下看山河（直下看山河）","斫去桂婆娑：斫去桂婆娑（砍去婆娑的桂树。斫音zhuó，砍；婆娑，枝叶扶疏的样子）","人道是、清光更多：人道是清光更多（人们说这样清光更多。用杜甫「斫却月中桂，清光应更多」）"],"m":"斫去桂婆娑，人道是、清光更多。","r":"按「一轮秋影—转金波—飞镜又重—磨—把酒问—姮娥—被白发—欺人奈何—乘风好去—长空万里—直下看—山河—斫去桂—婆娑—人道是—清光更多」背；「姮娥」读héng'é、「斫」读zhuó；用典（杜甫斫却月中桂清光应更多）；「斫去桂婆娑清光更多」的隐喻是核心；扫除奸邪、政治清明是寓意。"},"60882:祝英台近|辛弃疾":{"s":"上片「水纵横。山远近。拄杖占千顷。老眼羞将，水底看山影。试教水动山摇，吾生堪笑，似此个、青山无定」写水纵横山远近拄杖占千顷，老眼羞将水底看山影，试教水动山摇吾生堪笑似此个青山无定，以「水动山摇」写山水的变幻、以「青山无定」比喻人生的无定；下片「一瓢饮。人问翁爱飞泉，来寻个中静。绕屋生喧，怎做静中境。我眠君且归休。维摩方丈，待天女、散花时问」写一瓢饮人问翁爱飞泉来寻个中静，绕屋生喧怎做静中境，我眠君且归休维摩方丈待天女散花时问，以「一瓢饮」用颜回典故写安贫乐道、以「维摩方丈天女散花」用佛典写禅意，全词用典丰富、意境清幽、哲理深刻、情感旷达，「我眠君且归休。维摩方丈，待天女、散花时问」成为名句。","b":"辛弃疾这首《祝英台近》写归隐后的山水之乐与对静的追求，用颜回、维摩诘典故，是婉约词的名篇。","n":["祝英台近：词牌名","水纵横：水纵横","山远近：山远近","拄杖占千顷：拄杖占千顷（拄杖占据千顷山水）","老眼羞将：老眼羞将（老眼羞于将）","水底看山影：水底看山影（在水底看山影）","试教水动山摇：试教水动山摇（试让水动山摇）","吾生堪笑：吾生堪笑（我的一生可笑）","似此个、青山无定：似此个青山无定（像这个青山一样无定）","一瓢饮：一瓢饮（一瓢水的饮食，用颜回「一箪食一瓢饮」典故，指安贫乐道）","人问翁爱飞泉：人问翁爱飞泉（人问老翁为什么喜爱飞泉）","来寻个中静：来寻个中静（来寻找其中的静）","绕屋生喧：绕屋生喧（绕屋生出喧闹）","怎做静中境：怎做静中境（怎么能做到静中的境界呢）","我眠君且归休：我眠君且归休（我睡了您暂且回去休息吧）","维摩方丈：维摩方丈（维摩诘的方丈室，用维摩诘「方丈」典故，指小室）","待天女、散花时问：待天女散花时问（等天女散花时再问。天女散花，维摩诘经中天女散花考验菩萨）"],"m":"我眠君且归休。维摩方丈，待天女、散花时问。","r":"按「水纵横—山远近—拄杖占—千顷—老眼羞将—水底看—山影—试教水动—山摇—吾生堪笑—似此个—青山无定—一瓢饮—人问翁—爱飞泉—来寻个中—静—绕屋生喧—怎做静中—境—我眠君且—归休—维摩方丈—待天女—散花时问」背；用典（颜回一箪食一瓢饮、维摩诘方丈、天女散花）；山水变幻与人生无定是核心；归隐禅意是主题。"},"71649:踏莎行|辛弃疾":{"s":"上片「夜月楼台，秋香院宇。笑吟吟地人来去。是谁秋到便凄凉，当年宋玉悲如许」写夜月楼台秋香院宇，笑吟吟地人来去，是谁秋到便凄凉当年宋玉悲如许，以宋玉悲秋的典故写秋日的凄凉；下片「随分杯盘，等闲歌舞。问他有甚堪悲处。思量却也有悲时，重阳节近多风雨」写随分杯盘等闲歌舞，问他有甚堪悲处，思量却也有悲时重阳节近多风雨，以「重阳节近多风雨」暗喻国事的风雨飘摇——表面写重阳近了多风雨，实则写国家命运的风雨飘摇，全词意境清丽、用典贴切、寓意深刻，「思量却也有悲时，重阳节近多风雨」成为名句。","b":"辛弃疾这首《踏莎行》写秋日的感慨，以「重阳节近多风雨」暗喻国事的风雨飘摇，是婉约词中寓含悲愤的名篇。","n":["踏莎行：词牌名","夜月楼台：夜月楼台","秋香院宇：秋香院宇","笑吟吟地人来去：笑吟吟地人来去","是谁秋到便凄凉：是谁秋到便凄凉","当年宋玉悲如许：当年宋玉悲如许（宋玉，战国楚辞赋家，作《九辩》悲秋）","随分杯盘：随分杯盘（随分，随便）","等闲歌舞：等闲歌舞（等闲，平常）","问他有甚堪悲处：问他有甚堪悲处","思量却也有悲时：思量却也有悲时","重阳节近多风雨：重阳节近多风雨"],"m":"思量却也有悲时，重阳节近多风雨。","r":"按「夜月楼台—秋香院宇—笑吟吟—人来去—秋到凄凉—宋玉悲秋—随分杯盘—等闲歌舞—有甚堪悲—思量悲时—重阳近—多风雨」背；用典（宋玉《九辩》悲秋）；「重阳节近多风雨」的隐喻是核心；悲愤寓于婉约是特点。"},"71672:南乡子|辛弃疾":{"s":"上片「何处望神州。满眼风光北固楼。千古兴亡多少事，悠悠。不尽长江衮衮流」写何处望神州满眼风光北固楼，千古兴亡多少事悠悠不尽长江衮衮流，以长江滚滚东流写千古兴亡的感慨；下片「年少万兜鍪。坐断东南战未休。天下英雄谁敌手。曹刘。生子当如孙仲谋」写年少万兜鍪坐断东南战未休，天下英雄谁敌手曹刘，生子当如孙仲谋，以孙权年少时统率大军、占据东南、征战不休的英雄气概，讽刺南宋朝廷的苟且偷安——「生子当如孙仲谋」用曹操的话，既是对孙权的赞美，也是对南宋统治者的鞭挞，全词意境壮阔、用典贴切、借古讽今、情感豪迈，「生子当如孙仲谋」成为千古名句，是豪放词的千古名篇。","b":"辛弃疾这首《南乡子》是他任镇江知府时登北固亭所作，借古讽今，以孙权的英雄气概讽刺南宋朝廷的苟且偷安，「生子当如孙仲谋」是千古名句，是豪放词的千古名篇。","n":["南乡子：词牌名","何处望神州：何处望神州（神州，中原）","满眼风光北固楼：满眼风光北固楼（北固楼，在今江苏镇江北固山）","千古兴亡多少事：千古兴亡多少事","悠悠：悠悠（漫长无尽）","不尽长江衮衮流：不尽长江衮衮流（衮衮，滚滚，连续不断）","年少万兜鍪：年少万兜鍪（兜鍪，头盔，代指士兵。指孙权年少时统率大军。鍪音móu）","坐断东南战未休：坐断东南战未休（坐断，占据）","天下英雄谁敌手：天下英雄谁敌手","曹刘：曹刘（曹操、刘备）","生子当如孙仲谋：生子当如孙仲谋（孙仲谋，孙权字仲谋。用曹操「生子当如孙仲谋」语）"],"m":"千古兴亡多少事，悠悠。不尽长江衮衮流。天下英雄谁敌手。曹刘。生子当如孙仲谋。","r":"按「何处望神州—北固楼—千古兴亡—多少事—悠悠—不尽长江—衮衮流—年少万兜鍪—坐断东南—战未休—天下英雄—谁敌手—曹刘—生子当如—孙仲谋」背；「鍪」读móu、「衮衮」同滚滚；用典（曹操「生子当如孙仲谋」、孙权据东南）；借古讽今是核心；孙权的英雄气概与南宋的苟且偷安对比是主题。"}};
